 * Prototyp-Schlüssel sind in keiner Tiefe fachliche Konfiguration. Iterative
 * Prüfung begrenzt Tiefe (64) und Objektzahl (100000), ohne den Stack zu erschöpfen.
 * Keine Persistenz/States; ungültige Daten werden dem aufrufenden API als Fehler gemeldet.
 */
function nwAssertSafeConfigObject(value) {
  const pending = [{ value, depth: 0 }];
  let count = 0;
  while (pending.length) {
    const item = pending.pop();
    if (!item.value || typeof item.value !== 'object') continue;
    if (item.depth > 64 || ++count > 100000) throw new Error('Konfiguration zu tief oder zu umfangreich.');
    for (const [key, child] of Object.entries(item.value)) {
      if (['__proto__', 'prototype', 'constructor'].includes(key)) throw new Error('Unsicherer Konfigurationsschlüssel.');
      if (child && typeof child === 'object') pending.push({ value: child, depth: item.depth + 1 });
    }
