    if (name === 'energyWalletOperator') return snapshot.grants.includes('wallet') && snapshot.grants.includes('billing');
    if (/^(?:energyWallet|energyLedger)/.test(name)) return snapshot.grants.includes('wallet');
    if (['billingExport','solarChargeBilling'].includes(name)) return snapshot.grants.includes('billing');
    return snapshot.grants.includes('energy');
  }

  _nwIsFeatureLicensed(feature) {
    return this._nwFeatureInSnapshot(this._nwRuntimeLicenseSnapshot(), feature);
  }

  _nwLicenseAllowsAppId(appId) {
    if (['mesh', 'microgrid', 'meshMicrogrid'].includes(String(appId))) {
      const snapshot = this._nwRuntimeLicenseSnapshot();
      return snapshot.ok && (snapshot.grants.includes('microgridSlave') || snapshot.grants.includes('microgridMaster'));
    }
    return this._nwIsFeatureLicensed(this._nwLicenseAppFeature(appId));
  }

  _nwLicenseMaxWallboxes() {
    return this._nwRuntimeLicenseSnapshot().maxWallboxes;
  }

  _nwLicenseMaxStorages() {
    return this._nwRuntimeLicenseSnapshot().maxStorages;
  }

  _nwValidateStorageFarmLicense(config) {
    // Every configured row occupies a slot, including disabled rows. Never trim
    // existing mappings on downgrade; reject new saves/imports with a clear error.
    const rows = config && config.storageFarm && config.storageFarm.storages;
    const configuredStorages = this._nwNormalizeStorageFarmRows(rows).length;
    const maxStorages = this._nwLicenseMaxStorages();
    if (configuredStorages <= maxStorages) return { ok: true, maxStorages, configuredStorages };
    const label = this._nwCurrentLicenseEdition() === 'hems' ? 'Home' : (maxStorages > 0 ? 'Pro' : 'Keine gültige Lizenz');
    return {
      ok: false, error: 'storage_farm_license_limit', maxStorages, configuredStorages,
      message: `${label}: maximal ${maxStorages} Speichersysteme. Konfiguriert: ${configuredStorages}. Bitte die Speicherzuordnung anpassen.`,
    };
  }

  /**
   * Ablauf und Zusammenhang: Bereitet die Feature-/Limitinformationen für das App-Center auf. Dieser begrenzte Antwortpfad ersetzt für Installer den Zugriff auf vollständige Lizenzinformationen samt Schlüssel/UUID.
   */
  _nwBuildLicenseFeatureInfo() {
    // One fresh immutable public view prevents stale-valid -> Pro fallback on revocation.
    const info = centralLicenseSnapshot(this._bridge);
    this._nwLicenseInfo = info;
    this._nwLicenseOk = info.ok;
    const valid = info.ok;
    const edition = info.edition;
    const features = Object.fromEntries(Object.keys(this._nwLicenseFeaturesForEdition(edition))
      .map(feature => [feature, this._nwFeatureInSnapshot(info, feature)]));
    const editionLabel = (nwFeatureFlagsService && typeof nwFeatureFlagsService.editionLabel === 'function') ? nwFeatureFlagsService.editionLabel(edition) : (edition === 'eos' ? 'Pro' : (edition === 'hems' ? 'Home' : 'Keine Lizenz'));
    const storagePowerProfile = (nwFeatureFlagsService && typeof nwFeatureFlagsService.storagePerformanceProfile === 'function')
      ? nwFeatureFlagsService.storagePerformanceProfile(edition, 0)
      : {
          edition,
          id: edition === 'eos' ? 'pro' : (edition === 'hems' ? 'home' : 'none'),
          label: edition === 'eos' ? 'Pro' : (edition === 'hems' ? 'Home' : 'Keine Lizenz'),
          maxCommandW: edition === 'hems' ? 50000 : 0,
          unrestricted: edition === 'eos',
          industrial: edition === 'eos',
        };
    return {
      valid,
      type: String(info.type || (valid ? 'full' : 'none')),
      edition,
      editionLabel,
      message: String(info.msg || (valid ? `${editionLabel} Lizenz gültig` : '')),
      expiresAt: Number(info.expiresAt || 0),
      daysRemaining: Number(info.daysRemaining || 0),
      maxWallboxes: info.maxWallboxes,
      maxStorages: info.maxStorages,
      storagePowerProfile,
      maxStoragePowerW: Number(storagePowerProfile.maxCommandW || 0),
      features,
      hemsIncludedApps: (nwFeatureFlagsService && typeof nwFeatureFlagsService.homeIncludedApps === 'function') ? nwFeatureFlagsService.homeIncludedApps() : ['charging', 'storage', 'storagefarm', 'thermal', 'heatingrod', 'threshold', 'relay', 'grid', 'aiAdvisor', 'tariff', 'para14a', 'energyWallet'],
      homeIncludedApps: (nwFeatureFlagsService && typeof nwFeatureFlagsService.homeIncludedApps === 'function') ? nwFeatureFlagsService.homeIncludedApps() : ['charging', 'storage', 'storagefarm', 'thermal', 'heatingrod', 'threshold', 'relay', 'grid', 'aiAdvisor', 'tariff', 'para14a', 'energyWallet'],
      eosFullAccess: edition === 'eos',
      proFullAccess: edition === 'eos'
    };
  }

  _nwApplyLicenseLimitsToEmsApps(emsApps) {
    const out = (emsApps && typeof emsApps === 'object') ? this.nwDeepMerge ? this.nwDeepMerge({}, emsApps) : JSON.parse(JSON.stringify(emsApps)) : { schemaVersion: 1, apps: {} };
    out.schemaVersion = out.schemaVersion || 1;
    out.apps = (out.apps && typeof out.apps === 'object') ? out.apps : {};
    for (const appId of Object.keys(out.apps)) {
      // Netzlimits ist ein Sicherheitskern und darf auch bei abgelaufener, noch
      // nicht aktivierter oder vorübergehend nicht lesbarer Lizenz niemals aus
      // der Runtime entfernt werden. Nur Komfort-/Funktionsmodule werden lizenziert.
      if (appId === 'grid') {
        out.apps[appId] = Object.assign({}, out.apps[appId] || {}, {
          installed: true,
          enabled: true,
          licenseBlocked: false,
          requiredLicense: 'Kernschutz',
        });
      } else if (!this._nwLicenseAllowsAppId(appId)) {
        out.apps[appId] = Object.assign({}, out.apps[appId] || {}, { installed: false, enabled: false, licenseBlocked: true, requiredLicense: 'Pro' });
      } else {
        out.apps[appId] = Object.assign({}, out.apps[appId] || {}, { licenseBlocked: false, requiredLicense: this._nwCurrentLicenseEdition() === 'hems' ? 'Home' : 'Pro' });
      }
    }
    return out;
  }

  _nwApplyLicenseLimitsToInstallerPatch(patch) {
    const p = (patch && typeof patch === 'object') ? patch : {};
    try {
      if (p.emsApps && typeof p.emsApps === 'object') {
        p.emsApps = this._nwApplyLicenseLimitsToEmsApps(p.emsApps);
      }
    } catch (_e) {}
    try {
      const maxWb = this._nwLicenseMaxWallboxes();
      if (maxWb > 0 && p.settingsConfig && typeof p.settingsConfig === 'object') {
        const rawCount = Number(p.settingsConfig.evcsCount);
        const count = Number.isFinite(rawCount) ? Math.max(0, Math.min(maxWb, Math.round(rawCount))) : 0;
        p.settingsConfig.evcsCount = count;
        if (Array.isArray(p.settingsConfig.evcsList)) p.settingsConfig.evcsList = p.settingsConfig.evcsList.slice(0, count);
        if (Array.isArray(p.settingsConfig.stationGroups)) {
          p.settingsConfig.stationGroups = p.settingsConfig.stationGroups.map((g) => {
            const row = (g && typeof g === 'object') ? Object.assign({}, g) : {};
            if (Array.isArray(row.members)) row.members = row.members.filter((x) => Number(x) >= 1 && Number(x) <= count);
            if (Array.isArray(row.connectors)) row.connectors = row.connectors.filter((x) => Number(x) >= 1 && Number(x) <= count);
            return row;
          });
        }
      }
    } catch (_e) {}
    try {
      const edition = this._nwCurrentLicenseEdition();
      const profile = (nwFeatureFlagsService && typeof nwFeatureFlagsService.storagePerformanceProfile === 'function')
        ? nwFeatureFlagsService.storagePerformanceProfile(edition, p.storage && p.storage.ratedPowerW)
        : { id: edition === 'hems' ? 'home' : 'pro', maxCommandW: edition === 'hems' ? 50000 : 0 };
      const hardLimitW = Math.max(0, Number(profile.maxCommandW || 0));
      if (p.storage && typeof p.storage === 'object') {
        const normalizePositiveW = (value) => {
          const n = Number(value);
          if (!Number.isFinite(n) || n <= 0) return value;
          return Math.round(hardLimitW > 0 ? Math.min(n, hardLimitW) : n);
        };
        // Optionale, nicht gesetzte Grenzen bleiben abwesend. Ein leeres Speicher-
        // Objekt darf durch die Lizenznormalisierung keine undefined-Eigenschaften
        // erhalten, die einen späteren Geräteplan ungültig machen; 0/null bleiben exakt erhalten.
        for (const key of ['ratedPowerW', 'maxChargeW', 'maxDischargeW', 'selfMaxChargeW', 'selfMaxDischargeW', 'lskMaxChargeW', 'lskMaxDischargeW']) {
          const value = Reflect.get(p.storage, key);
          if (value === undefined) Reflect.deleteProperty(p.storage, key);
          else Reflect.set(p.storage, key, normalizePositiveW(value));
        }
      }
      // Home: Auch Farm-Zeilen behalten die bestehende Leistungsgrenze.
      // Der finale gemeinsame Speicherbefehl wird zusätzlich zentral begrenzt.
      if (hardLimitW > 0 && p.storageFarm && typeof p.storageFarm === 'object' && Array.isArray(p.storageFarm.storages)) {
        p.storageFarm.storages = p.storageFarm.storages.map((entry) => {
          const row = entry && typeof entry === 'object' ? Object.assign({}, entry) : {};
          for (const key of ['maxChargeW', 'maxDischargeW']) {
            const n = Number(row[key]);
            if (Number.isFinite(n) && n > hardLimitW) row[key] = hardLimitW;
          }
          return row;
        });
      }
    } catch (_e) {}
    return p;
  }
