  /**
   * Deep merge helper used for App‑Center config patches.
   *
   * Notes:
   * - Arrays are replaced (not concatenated).
   * - Objects are merged recursively.
   * - Primitive values overwrite.
   */
  /**
   * Code-Teil: nwDeepMerge
   * Zweck: Kapselt einen lokalen Verarbeitungsschritt, damit Aufrufer nicht direkt in Detaildaten eingreifen.
   * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
   * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
   */
  nwDeepMerge(target, patch, validated = false) {
    if (!validated) nwAssertSafeConfigObject(patch);
    if (patch === undefined) return target;
    if (patch === null) return null;

    // Replace arrays wholesale (but clone for safety)
    if (Array.isArray(patch)) {
      return patch.map((v) => {
        if (v && typeof v === 'object') {
          return this.nwDeepMerge(Array.isArray(v) ? [] : {}, v, true);
        }
        return v;
      });
    }

    // Primitives overwrite
    if (typeof patch !== 'object') {
      return patch;
    }

    // Ensure target is an object
    if (!target || typeof target !== 'object' || Array.isArray(target)) {
      target = {};
    }

    for (const [k, v] of Object.entries(patch)) {
      if (v && typeof v === 'object') {
        const previous = Object.prototype.hasOwnProperty.call(target, k) ? target[k] : undefined;
        target[k] = this.nwDeepMerge(previous, v, true);
      } else {
        target[k] = v;
      }
    }

    return target;
  }
