      peak:        ['peak', 'peakShaving', 'peakshaving'],
      storagefarm: ['storagefarm', 'storageFarm', 'storage_farm'],
      heatingrod:  ['heatingrod', 'heatingRod', 'heating_rod', 'heizstab'],
      ai:          ['ai', 'ki', 'aiOptimization', 'kiOptimization', 'energyAdvisor'],
