      }

      // Mandatory apps cannot be uninstalled/disabled
      if (a.mandatory) {
        installed = true;
        enabled = true;
      }

      // Safety: a non-installed app must never be enabled
      if (!installed) enabled = false;

      out.apps[a.id] = {
        installed: !!installed,
        enabled: !!enabled,
      };
    }

