  /**
   * Load persisted App‑Center configuration patch from `installer.configJson`.
   *
   * Why states?
   * Saving into system.adapter.<instance>.native triggers an ioBroker instance
   * restart, which broke the frontend "Speichern" flow (Failed to fetch, SSE drop).
   */
  /**
   * Installer-only MultiUse policy marker.
   *
   * Ab 0.8.138 werden die MultiUse-Zonen nicht mehr in `storage.*` kopiert.
   * Alle abhängigen Module lesen installerConfig.storageMultiUse über denselben
   * Policy-Resolver. Dadurch können deaktivierte MultiUse-Werte keine versteckte
   * 20-%-SoC-Sperre oder alte NVP-Parameter in der normalen Speicherregelung
   * hinterlassen.
   */
  /**
   * Code-Teil: nwApplyStorageMultiUsePolicy
   * Zweck: Verarbeitet Speicherwerte; signed DP, Split-DPs und Fallbacks müssen konsistent bleiben.
   * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
   * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
   */
  nwApplyStorageMultiUsePolicy(nativeObj) {
    try {
      if (!nativeObj || typeof nativeObj !== 'object') return nativeObj;

      nativeObj.storage = (nativeObj.storage && typeof nativeObj.storage === 'object' && !Array.isArray(nativeObj.storage))
        ? nativeObj.storage
        : {};
      const st = nativeObj.storage;
      const ic = (nativeObj.installerConfig && typeof nativeObj.installerConfig === 'object' && !Array.isArray(nativeObj.installerConfig))
        ? nativeObj.installerConfig
        : null;
      const mu = (ic && ic.storageMultiUse && typeof ic.storageMultiUse === 'object' && !Array.isArray(ic.storageMultiUse))
        ? ic.storageMultiUse
        : null;
      const active = !!(nativeObj.enableMultiUse === true && mu && mu.enabled === true);
      const multiUseWasApplied = st.multiUsePolicyApplied === true
        || st.multiUsePolicyApplied === 1
        || String(st.multiUsePolicyApplied || '').trim().toLowerCase() === 'true';

      const finiteOrNull = (value) => {
        if (value === null || value === undefined || value === '') return null;
        const n = Number(value);
        return Number.isFinite(n) ? n : null;
      };
      const clampNumber = (value, min, max, fallback) => {
        const n = finiteOrNull(value);
        return Math.min(max, Math.max(min, n === null ? fallback : n));
      };

      // Beim ersten Aktivieren einer neuen MultiUse-Policy wird die bis dahin
      // eigenstaendige Speicher-Policy einmal separat gesichert. Ab dann darf
      // MultiUse seine Werte nicht mehr in storage.self*/reserve*/lsk* spiegeln.
      // Alte Installationen tragen bereits `multiUsePolicyApplied=true`; deren
      // storage.self*-Werte koennen deshalb historisch gespiegelt sein und werden
      // bewusst nicht nachtraeglich als Standalone-Wahrheit uebernommen.
      if (active && !multiUseWasApplied) {
        // Die normale Speicher-App besitzt im AppCenter keine eigene SoC-Zonen-
        // Konfiguration. Deshalb werden historisch vermischte storage.selfMin/
        // selfMax-Werte nicht als Standalone-Wahrheit konserviert. Standalone
        // startet nach dem Abschalten von MultiUse sicher bei 10..100 %.
        if (st.standaloneSelfDischargeEnabled === undefined) st.standaloneSelfDischargeEnabled = true;
        if (st.standaloneSelfMinSocPct === undefined) st.standaloneSelfMinSocPct = 10;
        if (st.standaloneSelfMaxSocPct === undefined) st.standaloneSelfMaxSocPct = 100;
        // Zielimport und Deadband sind dagegen echte, sichtbare Tuningwerte der
        // normalen NVP-Regelung und werden getrennt bewahrt.
        if (st.standaloneSelfTargetGridImportW === undefined) {
          st.standaloneSelfTargetGridImportW = clampNumber(st.selfTargetGridImportW, 0, 1000000, 50);
        }
        if (st.standaloneSelfImportThresholdW === undefined) {
          st.standaloneSelfImportThresholdW = clampNumber(st.selfImportThresholdW, 0, 1000000, 20);
        }
      }

      st.multiUsePolicyActive = active;
      st.multiUsePolicySource = active
        ? 'installerConfig.storageMultiUse'
        : (mu ? 'standalone-storage-policy;inactive-multiuse-ignored' : 'standalone-storage-policy');
      if (active || multiUseWasApplied) st.multiUsePolicyVersion = 2;
      if (active) st.multiUsePolicyApplied = true;

      return nativeObj;
    } catch (e) {
      try {
        this.log && this.log.warn && this.log.warn(`[multiuse] Failed to prepare storage MultiUse policy: ${e?.message || e}`);
      } catch (_e) {
        // ignore
      }
      return nativeObj;
    }
  }
  /**
   * Code-Teil: loadInstallerConfigFromState
   * Zweck: Lädt Daten aus API, States oder Konfiguration.
   * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
   * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
   */
  /** Prüft aktuelle Objektverträge; Messfrische entscheidet ausschließlich der Regeltick. */
  /** Partnerrechte folgen der jeweiligen aktiven App und der aktuellen Lizenz. */
  _nwPartnerAppActive(appId) {
    if (this._nwMeshAppSaveInProgress || this._nwLicenseOk !== true) return false;
    const localId = appId === 'directMarketing' ? 'grid' : appId;
    const app = this.config?.emsApps?.apps?.[localId];
    return app?.installed === true && app?.enabled === true && this._nwLicenseAllowsAppId(localId);
  }

  /** Startet genau einen ausgehenden Partnerkanal. Der strikte Runtimebaustein
   * prüft Credentials, Journal, DNS/TLS und Positivlisten; hier werden nur die
   * vorhandenen lokalen Adapterdienste verbunden, niemals Fremddaten geschrieben. */
  async _nwStartPartnerRuntime() {
    this._partnerRuntime?.stop();
    this._partnerRuntime = new PartnerRuntime({
      getRoot: () => this.config || {},
      isAppActive: (appId) => this._nwPartnerAppActive(appId),
      controlAvailable: () => this._nwIsEmsReady() && this._nwPartnerAppActive('arbitrage'),
      isResourceAvailable: (resourceId) => {
        const availability = this._nwPartnerResourceAvailability?.[resourceId];
        const now = Date.now();
        return resourceId !== 'farm' && availability?.available === true && typeof availability.ts === 'number' && Number.isFinite(availability.ts) && availability.ts <= now && now - availability.ts <= 15000;
      },
      dataDirectory: require('@iobroker/adapter-core').getAbsoluteInstanceDataDir(this),
      readState: (id) => this.stateCache?.[id] || null,
      readTelemetry: (resourceId) => this._nwPartnerStorageTelemetry?.[resourceId] || null,
    });
    this._nwGetPartnerStorageRequest = (resourceId) => this._partnerRuntime?.getCurrentRequest(resourceId) || null;
    try { await this._partnerRuntime.refresh(); }
    catch (_partnerStartError) { this.log.warn('Partnerkanal bleibt gesperrt: Initialisierung fehlgeschlagen.'); }
  }

  async _nwValidateDynamicGridConfig(raw = this.config && this.config.dynamicGridConnection, rootConfig = this.config || {}) {
    const validation = await validateDynamicGridCandidate(this, raw, rootConfig);
    if (rootConfig === this.config && raw === rootConfig.dynamicGridConnection) {
      this._nwDynamicGridValidation = { configFingerprint: dynamicGridSignature(rootConfig), validation };
      this._nwDynamicGridGeneralMeasurement = validation.generalMeasurement || null;
    }
    return validation;
  }

  async _nwValidateNvpTopology(raw = this.config && this.config.nvpTopology) {
    // Native Konfiguration und wiederhergestellte States durchlaufen denselben
    // Alias-/Gerätecheck wie HTTP-Saves. Ungültiges active bleibt ausdrücklich
    // ungültig; es wird nicht in statisch oder eine frische Messung umgedeutet.
    const validation = await validateNvpCandidate(this, raw, this.config || {});
    if (raw === (this.config && this.config.nvpTopology)) {
      this._nwNvpTopologyValidation = { configFingerprint: JSON.stringify(raw), validation };
    }
    return validation;
  }

  async loadInstallerConfigFromState() {
    const preservedMode = this.namespace !== this.hostNamespace && /^nexowatt-ui\.\d+$/.test(this.namespace);
    const previous = { config: this.config, native: this._nwNativeConfigBase, patch: this._nwInstallerConfigPatch, rawPatch: this._nwInstallerConfigRawPatch };
    try {
      const baseNative = (this.config && typeof this.config === 'object') ? this.config : {};
      // Kunden-Navigation: Admin-native Schalter dürfen nicht durch alte Installer-Patches
      // übersteuert werden. Wir merken uns deshalb den nativen Stand vor der
      // App-Center-/Installer-Hydration; /config nutzt diesen Snapshot für optionale
      // Kundenunterseiten wie SmartHome.
      try { this._nwNativeConfigBase = this._nwDeepClone ? (this._nwDeepClone(baseNative) || {}) : JSON.parse(JSON.stringify(baseNative || {})); } catch (_eNativeSnap) { this._nwNativeConfigBase = baseNative || {}; }

      let patch = {};
      let needPersist = false;
      let source = 'state';

      const preserved = preservedMode
        ? (this._nwPreservedUiStates || await readPreservedUiStates(this, this.namespace, this._owner.config.eosUiMigration?.requiredStates))
        : null;
      const st = preserved ? (preserved.values['installer.configJson'] === null ? null : { val: JSON.stringify(preserved.values['installer.configJson']) })
        : await this.getStateAsync('installer.configJson');
      // Ein vorhandener Kundenstand ist maßgeblich, auch {} und bewusst leere
      // Geräte-/DP-Listen. Ein größeres/älteres Backup darf ihn nie ersetzen.
      if (st !== null && st !== undefined) {
        patch = parseInstallerConfigState(st);
      } else {
        // Nur ein bestätigter fehlender State erlaubt Erstinitialisierung/Recovery.
        // Lesefehler und beschädigte vorhandene Daten verlassen diesen Pfad vor Writes.
        needPersist = true;
        if (!preservedMode) {
          const backup = await this.nwReadUserdataBackup({ strict: true });
          if (backup && backup.configPatch && backup.instance === this.instance) {
            patch = parseInstallerConfigState({ val: JSON.stringify(backup.configPatch) });
            source = 'userdata';
          }
        }
      }

      // Neue Laufzeitfelder werden ausschließlich im Speicher ergänzt. Ein normales
      // Update/Neustart schreibt keine normalisierte Fassung über vorhandene Kundendaten.
      patch = restoreInfluxHistoryConfig(patch, this._nwHistorySecretCodec());
      const norm = this.nwNormalizeInstallerPatch(patch, baseNative);
      patch = norm.patch;

      this._nwInstallerConfigPatch = patch;
      // Roh-Patch separat merken: Sichtbarkeitsentscheidungen sollen nicht durch
      // automatisch aus Legacy-Flags normalisierte App-Zustände verfälscht werden.
      try { this._nwInstallerConfigRawPatch = this._nwDeepClone ? (this._nwDeepClone(patch) || {}) : JSON.parse(JSON.stringify(patch || {})); } catch (_eRawPatchSnap) { this._nwInstallerConfigRawPatch = patch || {}; }

      // Apply patch as installer SoT (replace installer-managed sections)
      this.config = this.nwApplyInstallerPatchToRuntimeConfig(baseNative, patch);
      this._nwConfigureHistory();
      try { await this._nwValidateNvpTopology(); }
      catch (_nvpError) { this._nwNvpTopologyValidation = { configFingerprint: JSON.stringify(this.config.nvpTopology), validation: { valid: false, errors: [{ code: 'NVP_SOURCE_VALIDATION_FAILED', message: 'NVP-Quellenprüfung fehlgeschlagen.' }] } }; }

      // Native App-Verträge und Aliasidentitäten stehen vor jedem EMS-Writer fest.
      try { await this._nwValidateDynamicGridConfig(); }
      catch (_dynamicError) { this._nwDynamicGridValidation = { validation: { valid: false, errors: [{ code: 'DYNAMIC_GRID_SOURCE_VALIDATION_FAILED', message: 'Objektprüfung fehlgeschlagen.' }] } }; }

      // Nur Erstinitialisierung bzw. fehlenden State sichern, nie bestehende Konfiguration.
      if (needPersist) {
        if (await this.persistInstallerConfigToState(patch) === false) throw new Error('EOS_UI_CONFIG_WRITE_FAILED');

        // Keep userdata backup in sync (best-effort)
        try {
          await this.nwWriteUserdataBackup(patch, source === 'userdata' ? 'restore-userdata' : 'normalize');
        } catch (_e5) {}
      }

    } catch (e) {
      this.config = previous.config;
      this._nwNativeConfigBase = previous.native;
      this._nwInstallerConfigPatch = previous.patch;
      this._nwInstallerConfigRawPatch = previous.rawPatch;
      this.log.warn('loadInstallerConfigFromState failed: EOS_UI_CONFIG_LOAD_FAILED; saved configuration unchanged');
      if (preservedMode || /^EOS_UI_(CONFIG_(INVALID|WRITE_FAILED)|BACKUP_READ_FAILED)$/.test(String(e?.message || ''))) throw e;
      throw new Error('EOS_UI_CONFIG_LOAD_FAILED');
    }
  }
