   * Gesamtpatch eine inzwischen bestätigte NVP-Konfigurationsversion überschreibt. */
  _nwBeginInstallerConfigMutation() {
    if (this._nwMeshAppSaveInProgress || this._meshCoordinator?.saving) return null;
    const token = {};
    this._nwMeshAppSaveInProgress = token;
    this._nwDynamicGridSaveInFlight = true;
    // Alte Freigaben dürfen während einer Konfigurationsmutation nicht wirken.
    this._partnerRuntime?.stop();
    return token;
