    let evcsCount = Math.max(0, Math.min(200, Math.round(Number(native.chargersCount ?? native.chargerCount ?? native.evcsCount ?? 0) || 0)));

    // Prefer runtime state if available (supports dynamic changes in sim adapter)
    try {
      const stCount = await this.getForeignStateAsync(`${inst}.evcs.count`).catch(() => null);
      const n = (stCount && stCount.val !== undefined && stCount.val !== null) ? Number(stCount.val) : NaN;
      if (Number.isFinite(n) && n >= 0) {
        evcsCount = Math.max(0, Math.min(200, Math.round(n)));
      }
    } catch (_e) {}

    // Try to read per-charger max power from meta states (fallback to 11kW)
    let evcsMaxPowerKwSum = 0;
    const evcsList = [];
    /**
     * Code-Teil: pad2
     * Zweck: Kapselt einen lokalen Verarbeitungsschritt, damit Aufrufer nicht direkt in Detaildaten eingreifen.
     * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
     * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
     */
    const pad2 = (n) => String(n).padStart(2, '0');

    for (let i = 1; i <= evcsCount; i++) {
      const cid = `c${pad2(i)}`;
      let type = 'ac';
      let maxKw = 11;

      try {
        const stType = await this.getForeignStateAsync(`${inst}.evcs.${cid}.meta.type`);
        if (stType && typeof stType.val === 'string' && stType.val.trim()) type = stType.val.trim().toLowerCase();
      } catch (_e) {}

      try {
        const stMax = await this.getForeignStateAsync(`${inst}.evcs.${cid}.meta.max_kw`);
        const v = stMax && stMax.val !== undefined ? Number(stMax.val) : NaN;
        if (Number.isFinite(v) && v > 0) maxKw = v;
      } catch (_e) {}

      const chargerType = (type === 'dc') ? 'DC' : 'AC';
      const maxPowerW = Math.round(maxKw * 1000);
      evcsMaxPowerKwSum += maxKw;

      evcsList.push({
        enabled: true,
        name: `SIM ${cid.toUpperCase()}`,
        stationKey: '',
        chargerType,
        maxPowerW,
        stationMaxPowerW: maxPowerW,
        phaseCount: 3,
        voltageV: 230,
        controlPreference: 'powerW',

        // Mapping (Sim Adapter)
        powerId: `${inst}.evcs.${cid}.meas.power_kw`,
        energyTotalId: `${inst}.evcs.${cid}.meas.energy_kwh`,
        statusId: `${inst}.evcs.${cid}.meas.status`,
        vehicleSocId: `${inst}.evcs.${cid}.vehicle.soc_pct`,

        // Write control: limit (kW) + enable
        setPowerWId: `${inst}.evcs.${cid}.ctrl.limit_kw`,
        enableWriteId: `${inst}.evcs.${cid}.ctrl.enabled`,

        // Optional: show as "active" when plugged
        activeId: `${inst}.evcs.${cid}.ctrl.plugged`,
      });
    }

    // Storage specs
    const storageMaxChKw = Number(native.storageMaxChargeKw || native.storageMaxChKw || native.storageMaxCharge || native.storageMaxPowerKw || 5);
    const storageMaxDisKw = Number(native.storageMaxDischargeKw || native.storageMaxDisKw || native.storageMaxDischarge || native.storageMaxPowerKw || 5);

    const patch = {
      // Ensure the key apps are enabled for testing
      enableChargingManagement: true,
      enableStorageControl: true,

      // Base energy flow mapping (App-Center "Zuordnung")
      datapoints: {
        // IMPORTANT: actively clear existing mappings that would otherwise mix
        // real hardware datapoints with simulation (basePatch merge behaviour).
        gridBuyPower: '',
        gridSellPower: '',
        gridPointPower: `${inst}.grid.power_kw`,

        pvPower: `${inst}.pv.power_kw`,
        productionTotal: '',

        // Optional producers/consumers for flow visualization (can be used by apps)
        producer1Power: `${inst}.chp.power_kw`,
        producer2Power: `${inst}.generator.power_kw`,
        producer3Power: '',
        producer4Power: '',
        producer5Power: '',

        consumer1Power: `${inst}.heatpump.power_kw`,
        consumer2Power: '',
        consumer3Power: '',
        consumer4Power: '',
        consumer5Power: '',

        // Let the flow engine derive building consumption from balance
        consumptionTotal: '',
        consumptionEvcs: '',

        // Storage: use signed batteryPower; clear separate charge/discharge mapping
        storageChargePower: '',
        storageDischargePower: '',
        batteryPower: `${inst}.storage.power_kw`,
        storageSoc: `${inst}.storage.soc_pct`,

        // Dynamic tariff
        priceCurrent: `${inst}.tariff.price_ct_per_kwh`,
        priceAverage: '',
        // NOTE: tarif-vis.js supports numeric arrays as hourly curve for simulation
        priceTodayJson: `${inst}.tariff.price_next_24h_json`,
        priceTomorrowJson: '',

        // Optional forecasts (not provided by sim adapter)
        pvForecastTodayJson: '',
        pvForecastTomorrowJson: '',
      },

      // EVCS mapping (App-Center)
      settingsConfig: {
        evcsCount,
        evcsMaxPowerKw: Math.round(evcsMaxPowerKwSum * 100) / 100,
        evcsList,
      },

      // Storage mapping for the Storage-Control module
      storage: {
        controlMode: 'targetPower',
        ratedPowerW: Math.round(Math.max(storageMaxChKw, storageMaxDisKw) * 1000),
        datapoints: {
          socObjectId: `${inst}.storage.soc_pct`,
          batteryPowerObjectId: `${inst}.storage.power_kw`,
          targetPowerObjectId: `${inst}.storage.ctrl.power_set_kw`,
          maxChargeObjectId: `${inst}.storage.max_charge_kw`,
          maxDischargeObjectId: `${inst}.storage.max_discharge_kw`,
        },
      },

      // Installer meta (shown in installer overview)
      installerConfig: {
        chargepoints: evcsCount,
        storageCount: 1,
        storagePower: Math.round(Math.max(storageMaxChKw, storageMaxDisKw) * 1000),
      },
    };

    return { patch, meta: { simInstanceId: inst, evcsCount, evcsMaxPowerKwSum, storageMaxChKw, storageMaxDisKw } };
  }
  /**
   * Code-Teil: nwSimEnable
   * Zweck: Kapselt einen lokalen Verarbeitungsschritt, damit Aufrufer nicht direkt in Detaildaten eingreifen.
   * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
   * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
   */
  async nwSimEnable(simInstanceId, restartEmsFn) {
    const mutationToken = this._nwBeginInstallerConfigMutation();
    if (!mutationToken) throw createPublicHttpError(409, 'INSTALLER_CONFIG_BUSY', 'Konfiguration wird bereits gespeichert.');
    try {
      // Safety: do not overwrite an existing backup (would make restore impossible).
      try {
        const st = await this.getStateAsync('simulation.backupConfigJson');
        const raw = st && st.val;
        if (typeof raw === 'string' && raw.trim()) {
          throw createPublicHttpError(500, 'SIMULATION_BACKUP_EXISTS', 'Simulation backup already exists. Please disable simulation (restore) before enabling again.');
        }
      } catch (e) {
        // If the check itself failed, proceed; if it threw our guard error, rethrow.
        if (safeConfigurationFailure(e).body.error === 'SIMULATION_BACKUP_EXISTS') throw e;
      }

      const instances = await this.nwSimListInstances();
      const inst = String(simInstanceId || '').trim() || await this.nwSimPickDefaultInstance(instances);
      if (!inst) throw createPublicHttpError(500, 'SIMULATION_INSTANCE_NOT_FOUND', 'nexowatt-sim instance not found');
      // Auto-enable sim instance if it is currently disabled (so datapoints/states are created).
      let simPrevEnabled = true;
      try {
        const simInstObj = await this.getForeignObjectAsync(`system.adapter.${inst}`).catch(() => null);
        simPrevEnabled = !!(simInstObj && simInstObj.common && simInstObj.common.enabled);
        if (!simPrevEnabled) {
          await this.nwSimSetInstanceEnabled(inst, true);
          await this.nwSimWaitAlive(inst, 8000);
        }
      } catch (_e) {}

      // Backup relevant VIS runtime settings so simulation can be started/stopped reproducibly.
      const backupSettings = { settings: {}, simInstance: { instanceId: inst, prevEnabled: simPrevEnabled } };
      for (const k of ['dynamicTariff','tariffMode','storagePower']) {
        try {
          const stK = await this.getStateAsync(`settings.${k}`).catch(() => null);
          backupSettings.settings[k] = (stK && stK.val !== undefined) ? stK.val : null;
        } catch (_e) {
          backupSettings.settings[k] = null;
        }
      }
      const backupSettingsJson = JSON.stringify(backupSettings);

      // Backup current App-Center patch so we can restore after simulation.
      const basePatch = (this._nwInstallerConfigPatch && typeof this._nwInstallerConfigPatch === 'object') ? this._nwInstallerConfigPatch : {};
      const backupJson = JSON.stringify(protectInfluxHistoryConfig(basePatch, this._nwHistorySecretCodec()));
      const backupWritten = await this.nwSimWriteStatus({
        active: false,
        instanceId: inst,
        backupConfigJson: backupJson,
        backupSettingsJson: backupSettingsJson,
        lastAction: 'backup',
        lastError: '',
      });
      if (backupWritten === false) throw new Error('credential-state-write-failed');

      // Build + apply simulation patch
      const built = await this.nwSimBuildPatch(inst);
      let mergedPatch = this.nwDeepMerge(this.nwDeepMerge({}, basePatch), built.patch);
      mergedPatch = this.nwApplyEmsAppsToLegacyFlags(mergedPatch);
      try {
        const norm = this.nwNormalizeInstallerPatch(mergedPatch, this.config || {});
        mergedPatch = (norm && norm.patch) ? norm.patch : mergedPatch;
      } catch (_e) {}

      if (await this.persistInstallerConfigToState(mergedPatch) === false) throw new Error('Simulationskonfiguration konnte nicht gespeichert werden.');
      this._nwInstallerConfigPatch = mergedPatch;
      this.config = (this.config && typeof this.config === 'object') ? this.config : {};
      this.config = this.nwApplyInstallerPatchToRuntimeConfig(this.config, mergedPatch);

      // Sync runtime states + subscriptions
      try { await this.syncInstallerConfigToStates(); } catch (_e) {}
      try { await this.syncSettingsToStates(); } catch (_e) {}
      try { await this.syncSettingsConfigToStates(); } catch (_e) {}
      try { await this.ensureEvcsStates(); } catch (_e) {}
      try { await this.ensureRfidStates(); } catch (_e) {}
      try { await this.subscribeEvcsMappedStates(); } catch (_e) {}
      try {
        if (typeof this.subscribeConfiguredStates === 'function') await this.subscribeConfiguredStates();
      } catch (_e) {}

      // Apply sensible defaults for simulation runs (can be changed later in VIS settings).
      // This ensures that Tarif-/Speicher-Logik is active without requiring manual UI steps.
      try {
        const storagePowerW = Math.round(Math.max(
          Number(built && built.meta && built.meta.storageMaxChKw) || 0,
          Number(built && built.meta && built.meta.storageMaxDisKw) || 0
        ) * 1000);

        await this.setStateAsync('settings.dynamicTariff', { val: true, ack: true });
        await this.setStateAsync('settings.tariffMode', { val: 2, ack: true }); // 2 = Auto/Forecast

        if (Number.isFinite(storagePowerW) && storagePowerW > 0) {
          await this.setStateAsync('settings.storagePower', { val: storagePowerW, ack: true });
        }
      } catch (_e) {}

      // Restart EMS engine (best-effort)
      try {
        if (typeof restartEmsFn === 'function') await restartEmsFn();
        else await this.initEmsEngine(true);
      } catch (_e) {}

      await this.nwSimWriteStatus({
        active: true,
        instanceId: inst,
        lastAction: 'enabled',
        lastError: '',
      });

      return { ok: true, instanceId: inst, meta: built.meta };
    } finally { this._nwEndInstallerConfigMutation(mutationToken); }
  }
  /**
   * Code-Teil: nwSimDisable
   * Zweck: Kapselt einen lokalen Verarbeitungsschritt, damit Aufrufer nicht direkt in Detaildaten eingreifen.
   * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
   * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
   */
  async nwSimDisable(restartEmsFn) {
    const mutationToken = this._nwBeginInstallerConfigMutation();
    if (!mutationToken) throw createPublicHttpError(409, 'INSTALLER_CONFIG_BUSY', 'Konfiguration wird bereits gespeichert.');
    try {
      const backupPatch = await this.nwSimReadBackupPatchFromState();
      if (!backupPatch) throw createPublicHttpError(500, 'SIMULATION_BACKUP_NOT_FOUND', 'no simulation backup found');

      // Apply backup patch (replace) and restart EMS
      let mergedPatch = this.nwDeepMerge({}, backupPatch);
      mergedPatch = this.nwApplyEmsAppsToLegacyFlags(mergedPatch);
      try {
        const norm = this.nwNormalizeInstallerPatch(mergedPatch, this.config || {});
        mergedPatch = (norm && norm.patch) ? norm.patch : mergedPatch;
      } catch (_e) {}

      if (await this.persistInstallerConfigToState(mergedPatch) === false) throw new Error('Simulationskonfiguration konnte nicht gespeichert werden.');
      this._nwInstallerConfigPatch = mergedPatch;
      this.config = (this.config && typeof this.config === 'object') ? this.config : {};
      this.config = this.nwApplyInstallerPatchToRuntimeConfig(this.config, mergedPatch);

      // Sync runtime states + subscriptions
      try { await this.syncInstallerConfigToStates(); } catch (_e) {}
      try { await this.syncSettingsToStates(); } catch (_e) {}
      try { await this.syncSettingsConfigToStates(); } catch (_e) {}
      try { await this.ensureEvcsStates(); } catch (_e) {}
      try { await this.ensureRfidStates(); } catch (_e) {}
      try { await this.subscribeEvcsMappedStates(); } catch (_e) {}
      try {
        if (typeof this.subscribeConfiguredStates === 'function') await this.subscribeConfiguredStates();
      } catch (_e) {}

      // Restart EMS engine (best-effort)
      try {
        if (typeof restartEmsFn === 'function') await restartEmsFn();
        else await this.initEmsEngine(true);
      } catch (_e) {}

      // Restore VIS settings + sim instance enabled state (best-effort)
      try {
        const backupSettings = await this.nwSimReadBackupSettingsFromState();
        if (backupSettings && typeof backupSettings === 'object') {
          const s = backupSettings.settings && typeof backupSettings.settings === 'object' ? backupSettings.settings : {};
          for (const k of Object.keys(s)) {
            const v = s[k];
            if (v === null || v === undefined) continue;
            try {
              await this.setStateAsync(`settings.${k}`, { val: v, ack: true });
            } catch (_e) {}
          }

          const simMeta = backupSettings.simInstance && typeof backupSettings.simInstance === 'object' ? backupSettings.simInstance : null;
          const prevEnabled = simMeta && simMeta.prevEnabled;
          const instId = simMeta && simMeta.instanceId ? String(simMeta.instanceId) : '';
          if (instId && prevEnabled === false) {
            await this.nwSimSetInstanceEnabled(instId, false);
          }
        }
      } catch (_e) {}

      // Clear backup after successful restore
      await this.nwSimWriteStatus({
        active: false,
        backupConfigJson: null,
        backupSettingsJson: null,
        lastAction: 'disabled (restored backup)',
        lastError: '',
      });

      return { ok: true };
    } finally { this._nwEndInstallerConfigMutation(mutationToken); }
  }
  /**
   * Normalisiert die frei zugeordneten Einzel-Speicher-DPs aus aktuellen und
   * älteren Installer-Strukturen. Die aktuelle storage.datapoints-Struktur hat
   * immer Vorrang; Fallbacks werden nur für leere Felder übernommen.
   */
  _nwNormalizeStorageDatapointsConfig(storageIn, _globalDatapointsIn) {
    // `storage.datapoints` ist die persistierte, manuelle Quelle. Das allgemeine
    // Energiefluss-Mapping wird ausschließlich zur Laufzeit in der EMS-Bridge
    // ergänzt und darf hier niemals in den Installer-Patch zurückfließen.
    return nwNormalizeStorageDatapointsConfig(storageIn);
  }

  // Speicherfarm (mehrere Speichersysteme als Pool/Gruppe)
  /**
   * Normalisiert eine manuell im AppCenter zugeordnete Speicherfarm-Zeile.
   *
   * Die aktuellen Feldnamen bleiben immer führend. Ältere Installer-/Runtime-
   * Spiegel werden ausschließlich als Fallback gelesen, damit die TS-Umstellung
   * bestehende freie ioBroker-DP-Zuordnungen nicht entkoppelt. Es findet bewusst
   * keine Hersteller- oder Objektpfad-Erkennung statt.
   */
  _nwNormalizeStorageFarmRow(row, index = 0) {
    const r = row && typeof row === 'object' && !Array.isArray(row) ? row : {};
    const nested = [
      r,
      (r.datapoints && typeof r.datapoints === 'object') ? r.datapoints : null,
      (r.dp && typeof r.dp === 'object') ? r.dp : null,
      (r.mapping && typeof r.mapping === 'object') ? r.mapping : null,
    ].filter(Boolean);
    const textFrom = (...keys) => {
      // Feldname vor Container: Ein heutiges kanonisches Feld gewinnt auch dann,
      // wenn ein alter Alias noch parallel in einer anderen Migrationsebene liegt.
      for (const key of keys) {
        for (const root of nested) {
          const value = root[key];
          if (value === undefined || value === null) continue;
          const text = String(value).trim();
          if (text) return text;
        }
      }
      return '';
    };
    const numberOrNull = (...keys) => {
      for (const key of keys) {
        for (const root of nested) {
          const value = root[key];
          if (value === undefined || value === null) continue;
          let raw = String(value).trim();
          if (!raw) continue;
          if (raw.includes(',') && raw.includes('.')) {
            raw = raw.lastIndexOf(',') > raw.lastIndexOf('.')
              ? raw.replace(/\./g, '').replace(/,/g, '.')
              : raw.replace(/,/g, '');
          } else if (raw.includes(',')) {
            raw = raw.replace(/,/g, '.');
          }
          const n = Number(raw);
          if (Number.isFinite(n)) return n;
        }
      }
      return null;
    };
    const boolFrom = (fallback, ...keys) => {
      for (const key of keys) {
        for (const root of nested) {
          if (!Object.prototype.hasOwnProperty.call(root, key)) continue;
          const value = root[key];
          if (typeof value === 'boolean') return value;
          if (value === 1 || value === '1' || String(value).trim().toLowerCase() === 'true') return true;
          if (value === 0 || value === '0' || String(value).trim().toLowerCase() === 'false') return false;
        }
      }
      return fallback;
    };

    const couplingRaw = textFrom('coupling', 'storageCoupling').toLowerCase();
    const coupling = couplingRaw === 'dc' ? 'dc' : (couplingRaw === 'ac' ? 'ac' : '');
    const vendorRaw = textFrom('vendorProfile', 'storageVendorProfile', 'profile', 'manufacturerProfile').toLowerCase();
    const vendorProfile = ['fenecon', 'openems', 'fems', 'fenecon-openems'].includes(vendorRaw)
      ? 'fenecon-openems'
      : (['sungrow', 'sungrow-ess', 'sungrow-hybrid'].includes(vendorRaw)
        ? 'sungrow-hybrid'
        : (['e3dc', 'e3/dc', 'e3dc-rscp'].includes(vendorRaw) ? 'e3dc-rscp' : (vendorRaw || 'generic')));
    const feneconControlModeRaw = textFrom('feneconControlMode', 'feneconHybridControlMode', 'controlModeMode').toLowerCase();
    const feneconControlMode = ['fems-grid', 'fems', 'fems-nvp', 'native', 'grid-target'].includes(feneconControlModeRaw)
      ? 'fems-grid'
      : (['direct-ess', 'direct', 'ess', 'direct-power'].includes(feneconControlModeRaw) ? 'direct-ess' : 'auto');
    const normalized = {
      ...r,
      enabled: boolFrom(true, 'enabled', 'active'),
      name: textFrom('name', 'label', 'title') || `Speicher ${Math.max(1, Number(index) + 1)}`,
      coupling,
      vendorProfile,
      feneconControlMode,
      // Messwerte
      socId: textFrom('socId', 'socObjectId', 'socDp', 'storageSocId', 'storageSoc'),
      batteryFlowPowerId: textFrom('batteryFlowPowerId'),
      signedPowerId: textFrom('signedPowerId', 'batteryPowerObjectId', 'signedPowerDp', 'powerObjectId', 'powerId', 'batteryPower'),
      chargePowerId: textFrom('chargePowerId', 'batteryChargePowerObjectId', 'chargePowerDp', 'chargeDp', 'storageChargePower'),
      dischargePowerId: textFrom('dischargePowerId', 'batteryDischargePowerObjectId', 'dischargePowerDp', 'dischargeDp', 'storageDischargePower'),
      pvPowerId: textFrom('pvPowerId', 'pvPowerObjectId', 'pvPowerDp', 'storagePvPowerId'),
      invertSignedPowerSign: boolFrom(false, 'invertSignedPowerSign', 'batteryPowerInvert', 'invertPowerSign'),
      invertChargeSign: boolFrom(false, 'invertChargeSign', 'batteryChargePowerInvert'),
      invertDischargeSign: boolFrom(false, 'invertDischargeSign', 'batteryDischargePowerInvert'),
      // Schreibziele
      setSignedPowerId: textFrom('setSignedPowerId', 'targetPowerObjectId', 'targetPowerId', 'setSignedPowerDp', 'powerSetpointId', 'setpointId', 'setPowerId'),
      setChargePowerId: textFrom('setChargePowerId', 'targetChargePowerObjectId', 'targetChargePowerId', 'setChargePowerDp', 'chargeSetpointId'),
      setDischargePowerId: textFrom('setDischargePowerId', 'targetDischargePowerObjectId', 'targetDischargePowerId', 'setDischargePowerDp', 'dischargeSetpointId'),
      invertSetSignedPowerSign: boolFrom(false, 'invertSetSignedPowerSign', 'targetPowerInvert', 'invertSetpointSign'),
      // FENECON/OpenEMS-Hybrid: nativer FEMS-NVP-Master oder direkte ESS-Rückmeldungen.
      feneconGridSetpointId: textFrom('feneconGridSetpointId', 'feneconGridSetpointObjectId', 'femsGridSetpointId', 'femsGridSetpointObjectId'),
      feneconEssActualPowerId: textFrom('feneconEssActualPowerId', 'feneconEssActualPowerObjectId', 'feneconActivePowerId'),
      feneconNvpPowerId: textFrom('feneconNvpPowerId', 'feneconNvpPowerObjectId', 'feneconGridPowerId', 'feneconNapPowerId'),
      feneconConsumptionTotalId: textFrom('feneconConsumptionTotalId', 'feneconConsumptionTotalObjectId', 'feneconLoadTotalId', 'feneconConsumptionPowerId', 'feneconLoadPowerId'),
      feneconMinPowerId: textFrom('feneconMinPowerId', 'feneconMinPowerObjectId', 'feneconMinimumPowerId'),
      feneconMaxPowerId: textFrom('feneconMaxPowerId', 'feneconMaxPowerObjectId', 'feneconMaximumPowerId'),
      feneconActualSetpointId: textFrom('feneconActualSetpointId', 'feneconActualSetpointObjectId', 'feneconSetpointReadbackId'),
      feneconPvDcId: textFrom('feneconPvDcId', 'feneconPvDcObjectId', 'feneconProductionDcId'),
      feneconPvAcId: textFrom('feneconPvAcId', 'feneconPvAcObjectId', 'feneconProductionAcId'),
      feneconPvTotalId: textFrom('feneconPvTotalId', 'feneconPvTotalObjectId', 'feneconProductionTotalId'),
      feneconPvPassthroughThresholdW: numberOrNull('feneconPvPassthroughThresholdW', 'feneconPvOnThresholdW'),
      feneconPvReleaseThresholdW: numberOrNull('feneconPvReleaseThresholdW', 'feneconPvOffThresholdW'),
      feneconPvPassthroughDelaySec: numberOrNull('feneconPvPassthroughDelaySec', 'feneconPvOnDelaySec'),
      feneconPvReleaseDelaySec: numberOrNull('feneconPvReleaseDelaySec', 'feneconPvOffDelaySec'),
      feneconApiTimeoutSec: numberOrNull('feneconApiTimeoutSec', 'apiTimeoutSec'),
      // Grenzen / optionale Signale
      maxChargeW: numberOrNull('maxChargeW', 'maxChargePowerW'),
      maxDischargeW: numberOrNull('maxDischargeW', 'maxDischargePowerW'),
      allowedChargePowerId: textFrom('allowedChargePowerId'),
      allowedDischargePowerId: textFrom('allowedDischargePowerId'),
      availableId: textFrom('availableId', 'availableObjectId', 'availableDp', 'availabilityId'),
      faultId: textFrom('faultId', 'faultObjectId', 'faultDp', 'errorId'),
      chargeAllowedId: textFrom('chargeAllowedId', 'chargeAllowedObjectId', 'chargeAllowedDp', 'chargeEnableId'),
      dischargeAllowedId: textFrom('dischargeAllowedId', 'dischargeAllowedObjectId', 'dischargeAllowedDp', 'dischargeEnableId'),
      capacityKWh: numberOrNull('capacityKWh', 'capacityKwh', 'batteryCapacityKWh'),
      group: textFrom('group', 'groupName'),
    };

    // RC36-Migration: In einigen Zwischenständen wurde der direkte ESS-Sollwert
    // (SetActivePowerEquals / 706 / aliases.ctrl.powerSetpointW) irrtümlich im
    // FEMS-NVP-Zielfeld gespeichert. Auto und Direkte-ESS übernehmen diesen Wert
    // als signed Sollwert und leeren die native Rolle. Ein Netzleistungs-Messwert
    // wird ebenfalls aus der Schreibrolle entfernt. Explizites FEMS-NVP bleibt
    // streng und verlangt weiterhin einen echten SetGridActivePower-Aktor.
    const nativeTargetId = String(normalized.feneconGridSetpointId || '').trim();
    const nativeIsDirectEss = nwIsLikelyDirectEssSetpointObjectId(nativeTargetId)
