      /**
       * Code-Teil: getState
       * Zweck: Kapselt einen lokalen Verarbeitungsschritt, damit Aufrufer nicht direkt in Detaildaten eingreifen.
       * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
       * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
       */
      const getState = async (id) => {
        const sid = String(id || '').trim();
        if (!sid) return null;
        if (_stCache.has(sid)) return _stCache.get(sid);
        const st = await this.getForeignStateAsync(sid).catch(() => null);
        _stCache.set(sid, st);
        return st;
      };
      /**
       * Code-Teil: toBool
       * Zweck: Kapselt einen lokalen Verarbeitungsschritt, damit Aufrufer nicht direkt in Detaildaten eingreifen.
       * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
       * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
       */
      const toBool = (v) => {
        if (v === null || v === undefined) return null;
        if (typeof v === 'boolean') return v;
        if (typeof v === 'number') return v !== 0;
        const s = String(v).trim().toLowerCase();
        if (!s) return null;
        if (['true', '1', 'on', 'yes', 'y'].includes(s)) return true;
        if (['false', '0', 'off', 'no', 'n'].includes(s)) return false;
        return null;
      };

      // If datapoints come from nexowatt-devices, we can infer a stable device base path
      // and use its connected/offline signals for status.
      /**
       * Code-Teil: inferDeviceBases
       * Zweck: Kapselt einen lokalen Verarbeitungsschritt, damit Aufrufer nicht direkt in Detaildaten eingreifen.
       * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
       * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
       */
      const inferDeviceBases = (id) => {
        const sid = String(id || '').trim();
        if (!sid) return [];

        // Support both: "...devices.X.aliases...." and direct "...devices.X...."
        const mAlias = sid.match(/^(nexowatt-devices\.\d+\.devices\.[^.]+\.aliases)(?:\.|$)/);
        if (mAlias) {
          const aliasBase = mAlias[1];
          const rootBase = aliasBase.replace(/\.aliases$/, '');
          return [aliasBase, rootBase];
        }

        const mRoot = sid.match(/^(nexowatt-devices\.\d+\.devices\.[^.]+)(?:\.|$)/);
        if (mRoot) {
          const rootBase = mRoot[1];
          return [`${rootBase}.aliases`, rootBase];
        }

        return [];
      };

      // Robust number parsing (some adapters deliver strings like "4,62 kW")
      /**
       * Code-Teil: parseNum
       * Zweck: Parst Rohdaten in ein sicheres internes Format.
       * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
       * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
       */
      const parseNum = (val) => {
        try {
          if (val === null || val === undefined) return NaN;
          if (typeof val === 'number') return val;
          if (typeof val === 'boolean') return NaN;
          if (typeof val === 'string') {
            let s = val.trim();
            if (!s) return NaN;

            // Extract first number-like token
            const m = s.match(/[-+]?\d[\d.,]*([eE][-+]?\d+)?/);
            if (!m) return NaN;
            let num = m[0];

            const hasDot = num.includes('.');
            const hasComma = num.includes(',');

            if (hasDot && hasComma) {
              // Determine decimal separator by last occurrence
              if (num.lastIndexOf(',') > num.lastIndexOf('.')) {
                // comma decimal, dots thousands
                num = num.replace(/\./g, '').replace(',', '.');
              } else {
                // dot decimal, commas thousands
                num = num.replace(/,/g, '');
              }
            } else if (hasComma && !hasDot) {
              // comma decimal
              num = num.replace(',', '.');
            } else if (hasDot) {
              // multiple dots -> thousands separators
              const parts = num.split('.');
              if (parts.length > 2) {
                const dec = parts.pop();
                num = parts.join('') + '.' + dec;
              }
            }

            const n = parseFloat(num);
            return Number.isFinite(n) ? n : NaN;
          }
          return NaN;
        } catch (_e) {
          return NaN;
        }
      };

      // Cache units of datapoints (for kW → W conversion, etc.)
      const _unitCache = this._nwDpUnitCache || (this._nwDpUnitCache = new Map());
      /**
       * Code-Teil: getUnit
       * Zweck: Kapselt einen lokalen Verarbeitungsschritt, damit Aufrufer nicht direkt in Detaildaten eingreifen.
       * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
       * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
       */
      const getUnit = async (id) => {
        const sid = String(id || '').trim();
        if (!sid) return '';
        if (_unitCache.has(sid)) return _unitCache.get(sid) || '';

        let unit = '';
        try {
          const obj = await this.getForeignObjectAsync(sid);
          unit = (obj && obj.common && obj.common.unit !== undefined && obj.common.unit !== null) ? String(obj.common.unit) : '';
        } catch (_e) {
          unit = '';
        }
        _unitCache.set(sid, unit);
        return unit;
      };
      /**
       * Code-Teil: scalePowerToW
       * Zweck: Kapselt einen lokalen Verarbeitungsschritt, damit Aufrufer nicht direkt in Detaildaten eingreifen.
       * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
       * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
       */
      const scalePowerToW = (n, unit) => {
        if (!Number.isFinite(n)) return NaN;
        const u = String(unit || '').trim();
        if (!u) return n;

        const ul = u.toLowerCase();

        // Avoid scaling energy units
        if (ul.includes('kwh') || ul.includes('mwh') || ul.includes('wh')) return n;

        if (ul === 'kw' || ul.endsWith(' kw') || ul.startsWith('kw ') || ul.includes('kilowatt')) return n * 1000;
        if (ul === 'mw' || ul.endsWith(' mw') || ul.startsWith('mw ') || ul.includes('megawatt')) return n * 1000000;
        if (ul === 'gw' || ul.endsWith(' gw') || ul.startsWith('gw ') || ul.includes('gigawatt')) return n * 1000000000;
        return n;
      };
      /**
       * Code-Teil: readNumber
       * Zweck: Liest einen Wert aus Cache, Konfiguration, DOM oder ioBroker-State mit passenden Fallbacks.
       * Zusammenhang: Gehört zu ioBroker-Adapterkern (Adapter-Lifecycle, Webserver, REST-/SSE-API, State-Anlage, Lizenz und EMS-Engine) und wird von benachbarten UI-/API-/EMS-Bausteinen genutzt.
       * Wartung/TypeScript: Änderungen können Adapterstart, APIs, States und Webserver beeinflussen; unload/connection immer mittesten. Beim TS-Umbau Parameter, Rückgabe und genutzte State-/Config-Objekte explizit typisieren.
       */
      const readNumber = async (id, kind, opts = {}) => {
        const sid = String(id || '').trim();
        if (!sid) return NaN;

        const st = await getState(sid);
        if (!st || st.val === undefined || st.val === null) return NaN;
        if (opts.display === true && ((st.q !== undefined && st.q !== 0) || !Number.isFinite(st.ts) || st.ts > now + 1000)) return NaN;

        // IMPORTANT: We intentionally do NOT apply stale filtering here.
        // Some devices update SoC or power only sporadically; the UI should still show
        // the last known value. Offline detection is handled separately via
        // connected/offline states and a heartbeat timestamp.
        const allowStale = (opts && opts.allowStale !== undefined) ? !!opts.allowStale : true;
        if (!allowStale) {
          // Use 'ts' (last update) instead of 'lc' (last change) so a polling adapter
          // stays "Online" even if the numeric value does not change.
          if (typeof st.ts !== 'number' || !Number.isFinite(st.ts) || (now - st.ts) > staleMs) return NaN;
        }

        let n = parseNum(st.val);
        if (!Number.isFinite(n)) return NaN;

        if (kind === 'soc' || kind === 'soc-display') {
          // Accept both percent (0..100) and fraction (0..1) formats.
          const unit = await getUnit(sid);
          const ul = String(unit || '').toLowerCase();
          if (!ul.includes('%')) {
            if (n > 0 && n <= 1) n = n * 100;
          }
          if (kind === 'soc-display' && (n < 0 || n > 100)) return NaN;
          if (Number.isFinite(n)) {
            if (n < 0) n = 0;
            if (n > 100) n = 100;
          }
          return n;
        }

        if (kind === 'power') {
          let unit = await getUnit(sid);

          // If unit is missing on the DP, try to infer it from a string value (e.g. "4,62 kW")
          if (!unit && typeof st.val === 'string') {
            const sl = String(st.val).toLowerCase();
            if (sl.includes('kwh') || sl.includes('mwh')) unit = '';
            else if (sl.includes('kw')) unit = 'kW';
            else if (sl.includes('mw')) unit = 'MW';
            else if (sl.includes('gw')) unit = 'GW';
            else if (sl.includes(' w')) unit = 'W';
            else if (sl.endsWith('w')) unit = 'W';
          }

          if (opts.display === true && unit && !/^(?:[kmg]?w|(?:kilo|mega|giga)?watts?)$/i.test(String(unit).trim().replace(/\s+/g, ''))) return NaN;
          return scalePowerToW(n, unit);
        }

        return n;
      };

      let totalCharge = 0;
      let totalDischarge = 0;
      const batteryFlowSources = new Set();
      let totalPvAc = 0;
      let totalPvDc = 0;
      let totalPvUnknown = 0;
      const seenPvSourceIds = new Set();
      const pvSourceRows = [];
      // Doppelte Leistungs-DPs dürfen weder Farmleistung noch NVP-Bilanz aufblasen.
      // Pro eindeutigem Signed- oder Split-Feedbackpfad wird deshalb genau einmal summiert.
      const seenPowerSourceKeys = new Set();
      let powerSourcesOnline = 0;
      let onlineFresh = 0;
      let available = 0;
      let degraded = 0;
      let dispatchAvailableCount = 0;
      let availableChargePowerW = 0;
      let availableDischargePowerW = 0;
      let availableChargePowerUnbounded = false;
      let availableDischargePowerUnbounded = false;
      let configured = 0;

      // SoC aggregation must be stable in Farm mode even when a storage
      // temporarily stops responding (adapter hiccups).
      // We therefore aggregate SoC from the *last known* value per storage
      // (independent of the online flag) and expose additional quality flags.
      const socListAll = [];
      const socListOnline = [];
      const socWeightedEntriesAll = [];
      const socWeightedEntriesOnline = [];
      let socSourcesTotal = 0;
      let socSourcesOnline = 0;

      const statusRows = [];
      const overviewMembers = [];
      const overviewPvSources = [];
      const farmWritableStorageCount = list.filter((row) => this._nwStorageFarmRowHasWritableDatapoint(row)).length;

      const maxLicensedStorages = this._nwLicenseMaxStorages();
      for (const [rowIndex, row] of list.entries()) {
        if (!row || typeof row !== 'object') continue;
        if (row.enabled === false) continue;
        configured++;

        const status = {
          licenseBlocked: rowIndex >= maxLicensedStorages,
          name: String(row.name || '').trim() || `Speicher ${configured}`,
          group: String(row.group || '').trim(),
          dispatchKey: this._sfGetStorageDispatchKey(row, configured - 1),
          setSignedPowerId: String(row.setSignedPowerId || '').trim(),
          setChargePowerId: String(row.setChargePowerId || '').trim(),
          setDischargePowerId: String(row.setDischargePowerId || '').trim(),
          feneconGridSetpointId: String(row.feneconGridSetpointId || '').trim(),
          feneconEssActualPowerId: String(row.feneconEssActualPowerId || '').trim(),
          feneconControlMode: String(row.feneconControlMode || 'auto'),
          vendorProfile: String(row.vendorProfile || 'generic'),
          coupling: String(row.coupling || ''),
          signedPowerId: String(row.signedPowerId || '').trim(),
          chargePowerId: String(row.chargePowerId || '').trim(),
          dischargePowerId: String(row.dischargePowerId || '').trim(),
          socId: String(row.socId || '').trim(),
          soc: null,
          chargePowerW: null,
          dischargePowerW: null,
          signedPowerW: null,
          powerSourceKey: '',
          powerSourceOnline: false,
          pvPowerW: null,
          pvSourceId: '',
          pvSourceCoupling: '',
          pvSourceOnline: false,
          online: false,
          displayOnline: false,
          dispatchAvailable: false,
          chargeDispatchAvailable: false,
          dischargeDispatchAvailable: false,
          maxChargeW: null,
          maxDischargeW: null,
        };

        const socId = String(row.socId || '').trim();
        const feneconEssActualId = String(row.feneconEssActualPowerId || '').trim();
        const signedId = String(feneconEssActualId || row.signedPowerId || '').trim();
        const invSigned = !!row.invertSignedPowerSign;
        const chgId = String(row.chargePowerId || '').trim();
        const dchgId = String(row.dischargePowerId || '').trim();
        const invChg = !!row.invertChargeSign;
        const invDchg = !!row.invertDischargeSign;
        const setSignedPowerId = String(row.setSignedPowerId || '').trim();
        const setChargePowerId = String(row.setChargePowerId || '').trim();
        const setDischargePowerId = String(row.setDischargePowerId || '').trim();
        const feneconGridSetpointId = String(row.feneconGridSetpointId || '').trim();
        const directTargetAvailable = !!(setSignedPowerId || setChargePowerId || setDischargePowerId);
        const feneconMode = nwResolveFeneconControlMode({
          vendorProfile: row.vendorProfile,
          coupling: row.coupling,
          feneconControlMode: row.feneconControlMode,
          feneconGridSetpointId,
          setSignedPowerId,
          setChargePowerId,
          setDischargePowerId,
        }, {
          writableStorageCount: farmWritableStorageCount,
          otherWritableStorageCount: Math.max(0, farmWritableStorageCount - 1),
          directTargetAvailable,
        });
        const nativeFeneconSetpoint = feneconMode.mode === 'fems-grid' ? feneconGridSetpointId : '';
        const hasChargeSetpoint = !!(nativeFeneconSetpoint || setSignedPowerId || setChargePowerId);
        const hasDischargeSetpoint = !!(nativeFeneconSetpoint || setSignedPowerId || setDischargePowerId);
        const hasAnySetpoint = !!(nativeFeneconSetpoint || setSignedPowerId || setChargePowerId || setDischargePowerId);

        // Feldschutz 0.8.79: Ist-Leistungs-DPs der Speicherfarm dürfen niemals
        // auf Steuer-/Sollwert-DPs zeigen. Sonst liest die Farm ihre eigene
        // dischargePowerW-/powerSetpointW-Vorgabe als echte Entladung zurück;
        // die NVP-Regelung sieht dann eine künstlich hohe Batterie-Istleistung
        // und kann bis zu absurden Sollwerten hochintegrieren.
        const targetPowerIds = [setSignedPowerId, setChargePowerId, setDischargePowerId, feneconGridSetpointId].filter(Boolean);
        // Hersteller-/Objektpfad-offen: Ein manuell zugeordneter Istwert wird nur
        // dann verworfen, wenn er exakt dasselbe ioBroker-Objekt wie ein zugeordneter
        // Sollwert verwendet. Namen wie `.ctrl.` oder `setpoint` sind kein Beweis und
        // dürfen legitime Fremd-DPs nicht blockieren.
        const isMappedSetpointPowerId = (id) => {
          const sid = String(id || '').trim();
          return !!sid && targetPowerIds.includes(sid);
        };
        const signedFeedbackUsable = !!signedId && !isMappedSetpointPowerId(signedId);
        const chargeFeedbackUsable = !!chgId && !isMappedSetpointPowerId(chgId);
        const dischargeFeedbackUsable = !!dchgId && !isMappedSetpointPowerId(dchgId);
        const ignoredPowerFeedback = [];
        if (signedId && !signedFeedbackUsable) ignoredPowerFeedback.push('signedPowerId ist identisch mit einem Sollwert-DP');
        if (chgId && !chargeFeedbackUsable) ignoredPowerFeedback.push('chargePowerId ist identisch mit einem Sollwert-DP');
        if (dchgId && !dischargeFeedbackUsable) ignoredPowerFeedback.push('dischargePowerId ist identisch mit einem Sollwert-DP');
        if (ignoredPowerFeedback.length) status.powerFeedbackIgnoredReason = ignoredPowerFeedback.join('; ');

        const powerSourceKey = signedFeedbackUsable
          ? `signed:${signedId}`
          : ((chargeFeedbackUsable || dischargeFeedbackUsable)
            ? `split:${chargeFeedbackUsable ? chgId : ''}|${dischargeFeedbackUsable ? dchgId : ''}`
            : '');
        let powerSourceDuplicate = false;
        if (powerSourceKey) {
          status.powerSourceKey = powerSourceKey;
          if (seenPowerSourceKeys.has(powerSourceKey)) {
            powerSourceDuplicate = true;
            status.powerDuplicateSource = true;
          } else {
            seenPowerSourceKeys.add(powerSourceKey);
          }
        }

        // Fixed installer limits remain authoritative upper bounds. Separately
        // bound device capabilities may only reduce them. Optional unsupported
        // registers are never automatically bound just because an object exists.
        const availableId = String(row.availableId || '').trim();
        const faultId = String(row.faultId || '').trim();
        const chargeAllowedId = String(row.chargeAllowedId || '').trim();
        const dischargeAllowedId = String(row.dischargeAllowedId || '').trim();
        const cap = Number(row.capacityKWh);
        const w = Number.isFinite(cap) && cap > 0 ? cap : 1;

        const coupling = String(row.coupling || '').trim().toLowerCase();
        const isDcCoupled = coupling === 'dc';
        const isAcCoupled = coupling === 'ac';
        const pvCoupling = isDcCoupled ? 'dc' : (isAcCoupled ? 'ac' : 'unknown');

        const feneconHybridRow = nwIsFeneconHybrid({ vendorProfile: row.vendorProfile, coupling: row.coupling });
        let pvId = String((feneconHybridRow && row.feneconPvDcId) ? row.feneconPvDcId : row.pvPowerId || '').trim();
        status.feneconPvDcId = String(row.feneconPvDcId || '').trim();
        status.feneconPvAcId = String(row.feneconPvAcId || '').trim();
        status.feneconPvTotalId = String(row.feneconPvTotalId || '').trim();

        // ---------------------------------------------------------------------
        // Online/Offline logic
        // ---------------------------------------------------------------------
        // Wichtig für die herstellerneutrale Farm:
        // - Freigabe-/Stör-DPs sind optional. Nicht gesetzt = nicht blockierend.
        // - Stale Messwerte machen den Speicher in der Anzeige "degraded", blockieren den
        //   Dispatch aber nicht automatisch. Viele Systeme aktualisieren SoC/Istleistung selten.
        // - Hart blockiert wird nur bei explizit offline, fehlender Grundkonfiguration, aktiver
        //   Störung oder bewusst gesperrter Freigabe.

        // Infer device base from nexowatt-devices datapoints
        // Support both: "...devices.X.aliases...." and direct "...devices.X...." mappings.
        const devBases = [];
        /**
         * Code-Teil: addBases
         * Zweck: Kapselt einen lokalen Verarbeitungsschritt, damit Aufrufer nicht direkt in Detaildaten eingreifen.
         * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
         * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
         */
        const addBases = (id) => {
          for (const b of inferDeviceBases(id)) {
            if (b && !devBases.includes(b)) devBases.push(b);
          }
        };

        addBases(socId);
        if (signedFeedbackUsable) addBases(signedId);
        if (chargeFeedbackUsable) addBases(chgId);
        if (dischargeFeedbackUsable) addBases(dchgId);
        addBases(feneconGridSetpointId);
        addBases(feneconEssActualId);
        addBases(row.feneconMinPowerId);
        addBases(row.feneconMaxPowerId);
        addBases(row.feneconActualSetpointId);
        addBases(row.feneconPvDcId);
        addBases(row.feneconPvAcId);
        addBases(row.feneconPvTotalId);
        addBases(pvId);
        addBases(availableId);
        addBases(faultId);
        addBases(chargeAllowedId);
        addBases(dischargeAllowedId);
        /**
         * Code-Teil: pickFirstState
         * Zweck: Kapselt einen lokalen Verarbeitungsschritt, damit Aufrufer nicht direkt in Detaildaten eingreifen.
         * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
         * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
         */
        const pickFirstState = async (candidates) => {
          for (const cid of candidates) {
            if (!cid) continue;
            const st = await getState(cid);
            if (st && st.val !== undefined && st.val !== null) return { id: cid, st };
          }
          return { id: '', st: null };
        };

        const { id: connectedId, st: stConn } = await pickFirstState(devBases.map((b) => `${b}.comm.connected`));
        const { id: offlineId, st: stOff } = await pickFirstState(devBases.map((b) => `${b}.alarm.offline`));
        const { id: lastErrorId, st: stErr } = await pickFirstState(devBases.map((b) => `${b}.comm.lastError`));

        // Auto-PV detection (DC-coupled storages):
        // If pvPowerId is not configured OR does not resolve to a state (e.g. a channel was selected),
        // try to use standardized nexowatt-devices datapoints.
        // This keeps the farm PV sum correct even when the installer did not map PV (DC) manually.
        const pvIdState = pvId ? await getState(pvId) : null;
        if ((!pvId || !pvIdState) && isDcCoupled && devBases.length) {
          const candidates = [];
          for (const b of devBases) {
            candidates.push(
              `${b}.r.pvPower`,
              `${b}.r.pvPowerW`,
              `${b}.r.pvPowerDc`,
              `${b}.r.pvPowerDC`,
            );
          }
          for (const cid of candidates) {
            const st = await getState(cid);
            if (st && st.val !== undefined && st.val !== null) {
              pvId = cid;
              // Debug only: included in storagesStatusJson
              status.pvAutoId = cid;
              break;
            }
          }
        }

        const connB = stConn ? toBool(stConn.val) : null;
        const offB = stOff ? toBool(stOff.val) : null;

        const explicitOffline = (offB === true) || (connB === false);

        // Heartbeat ts: prefer device adapter status + power states.
        // NOTE: We intentionally exclude SoC as primary heartbeat because it may update slowly.
        let heartbeatTs = NaN;
        /**
         * Code-Teil: considerTs
         * Zweck: Kapselt einen lokalen Verarbeitungsschritt, damit Aufrufer nicht direkt in Detaildaten eingreifen.
         * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
         * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
         */
        const considerTs = (st) => {
          if (st && typeof st.ts === 'number' && Number.isFinite(st.ts)) {
            heartbeatTs = Number.isFinite(heartbeatTs) ? Math.max(heartbeatTs, st.ts) : st.ts;
          }
        };

        considerTs(stConn);
        considerTs(stOff);
        considerTs(stErr);
        if (signedFeedbackUsable) considerTs(await getState(signedId));
        if (chargeFeedbackUsable) considerTs(await getState(chgId));
        if (dischargeFeedbackUsable) considerTs(await getState(dchgId));
        if (pvId) considerTs(await getState(pvId));
        if (availableId) considerTs(await getState(availableId));
        if (faultId) considerTs(await getState(faultId));
        if (chargeAllowedId) considerTs(await getState(chargeAllowedId));
        if (dischargeAllowedId) considerTs(await getState(dischargeAllowedId));
        // Fallback: if nothing else exists, use SoC ts so minimal configs still show degraded/online.
        if (!Number.isFinite(heartbeatTs) && socId) considerTs(await getState(socId));

        const stale = Number.isFinite(heartbeatTs) ? ((now - heartbeatTs) > staleMs) : false;

        // Do we have any feedback values configured/available?
        // Setpoint-DPs alone are enough for dispatch, but they are not treated as real feedback.
        let hasFeedbackValue = false;
        for (const id of [signedFeedbackUsable ? signedId : '', chargeFeedbackUsable ? chgId : '', dischargeFeedbackUsable ? dchgId : '', pvId, socId, availableId, faultId, chargeAllowedId, dischargeAllowedId]) {
          if (!id) continue;
          const st = await getState(id);
          if (st && st.val !== undefined && st.val !== null) { hasFeedbackValue = true; break; }
        }

        // Health-state for UI/summary
        // - offline: explicit device offline OR no feedback and no controllable setpoint
        // - degraded: stale/no feedback but setpoint exists; dispatch may still continue
        // - online: fresh updates
        let health = 'offline';
        let stateReason = '';

        if (explicitOffline) {
