      .filter(g => g.enabled && g.name);

    return { enabled, dispatchEnabled, mode, storages, groups };
  }
  /**
   * Code-Teil: _sfGetStorageDispatchKey
   * Zweck: Verarbeitet Speicherwerte; signed DP, Split-DPs und Fallbacks müssen konsistent bleiben.
   * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
   * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
   */
  _sfGetStorageDispatchKey(storage, index = 0) {
    const s = (storage && typeof storage === 'object') ? storage : {};
    const feneconGrid = String(s.feneconGridSetpointId || '').trim();
    const setSigned = String(s.setSignedPowerId || '').trim();
    const setCharge = String(s.setChargePowerId || '').trim();
    const setDischarge = String(s.setDischargePowerId || '').trim();
    const signed = String(s.signedPowerId || '').trim();
    const charge = String(s.chargePowerId || '').trim();
    const discharge = String(s.dischargePowerId || '').trim();
    const soc = String(s.socId || '').trim();
    const available = String(s.availableId || '').trim();
    const fault = String(s.faultId || '').trim();
    const name = String(s.name || '').trim().toLowerCase();

    // Setpoint-DPs sind die stabilste Hardware-Identitaet. Danach folgen die
    // Istleistungs- und SoC-Pfade. Der Array-Index ist nur der allerletzte Legacy-
    // Fallback und darf bei normal konfigurierten Farmen keine Zuordnung bestimmen.
    if (feneconGrid) return `fenecon-grid:${feneconGrid}`;
    if (setSigned) return `set-signed:${setSigned}`;
    if (setCharge || setDischarge) return `set-split:${setCharge}|${setDischarge}`;
    if (signed) return `actual-signed:${signed}`;
    if (charge || discharge) return `actual-split:${charge}|${discharge}`;
    if (soc) return `soc:${soc}`;
    if (available || fault) return `health:${available}|${fault}`;
    if (name) return `name:${name}`;
    return `row:${Math.max(0, Number(index) || 0)}`;
  }
  /**
   * Code-Teil: _sfGetDischargeFloorSocPct
   * Zweck: Verarbeitet Wallbox-/Ladepunktdaten und Feature-Sichtbarkeit.
   * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
   * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
   */
  _sfGetDischargeFloorSocPct(source = '') {
    const storageCfg = (this.config && this.config.storage && typeof this.config.storage === 'object') ? this.config.storage : {};
    const src = String(source || '').toLowerCase().trim();

    const ic = (this.config && this.config.installerConfig && typeof this.config.installerConfig === 'object') ? this.config.installerConfig : {};
    const mu = (ic.storageMultiUse && typeof ic.storageMultiUse === 'object') ? ic.storageMultiUse : null;
    const multiUsePolicyActive = !!(this.config && this.config.enableMultiUse && mu && mu.enabled === true);
    // Speicherfarm und Einzelregelung verwenden exakt dieselbe zentrale Policy.
    // Ein deaktiviertes MultiUse darf weder Reserve/LSK noch einen alten 20-%-
    // Eigenverbrauchs-Floor in die Farmverteilung einschleusen.
    const storageAuthority = (typeof this._nwGetStorageControlAuthority === 'function')
      ? this._nwGetStorageControlAuthority()
      : { selectedTopology: 'single' };
    const storageOperatingPolicy = resolveStorageOperatingPolicy({
      storageConfig: storageCfg,
      multiUseConfig: mu,
      multiUseActive: multiUsePolicyActive,
      storageFarmConfig: (this.config && this.config.storageFarm && typeof this.config.storageFarm === 'object') ? this.config.storageFarm : {},
      selectedTopology: storageAuthority.selectedTopology,
      standaloneDefaultEnabled: true,
      standaloneDefaultMinSocPct: 10,
      standaloneDefaultMaxSocPct: 100,
      standaloneDefaultTargetGridImportW: 50,
      standaloneDefaultImportThresholdW: 20,
    });
    const reserveFloor = storageOperatingPolicy.reserve.enabled === true
      ? Math.max(0, Math.min(100, Number(storageOperatingPolicy.reserve.minSocPct) || 0))
      : 0;
    const selfFloor = storageOperatingPolicy.self.enabled === true
      ? Math.max(0, Math.min(100, Number(storageOperatingPolicy.self.minSocPct) || 0))
      : 0;
    const lskFloor = storageOperatingPolicy.lsk.dischargeEnabled === true
      ? Math.max(0, Math.min(100, Number(storageOperatingPolicy.lsk.minSocPct) || 0))
      : 0;

    if (src === 'eigenverbrauch' || src === 'evcs' || src === 'tarif') return Math.max(0, Math.min(100, Math.max(reserveFloor, selfFloor)));
    if (src === 'lastspitze') return Math.max(0, Math.min(100, Math.max(reserveFloor, lskFloor)));
    if (src === 'reserve') return Math.max(0, Math.min(100, reserveFloor));

    return Math.max(0, Math.min(100, Math.max(reserveFloor, selfFloor, lskFloor)));
  }
  /**
   * Code-Teil: _sfGetResponseLimitFactor
   * Zweck: Kapselt einen klar abgegrenzten Verarbeitungsschritt innerhalb dieser Datei.
   * Zusammenhang: Gehört zu ioBroker-Adapterkern (Adapter-Lifecycle, Webserver, REST-/SSE-API, State-Anlage, Lizenz und EMS-Engine) und wird von benachbarten UI-/API-/EMS-Bausteinen genutzt.
   * Wartung/TypeScript: Änderungen können Adapterstart, APIs, States und Webserver beeinflussen; unload/connection immer mittesten. Beim TS-Umbau Parameter, Rückgabe und genutzte State-/Config-Objekte explizit typisieren.
