      if (cooldownUntil > now) return 0.05;

      prev.cooldownUntil = now + 15000;
      prev.lastActualW = actual;
      this._sfDispatchState.set(key, prev);
      return 0.05;
    }

    if (cooldownUntil > now) return 0.05;
    return 1;
  }
