        try { this.updateValue('storageFarm.lastDispatchJson', json, now); } catch (_eUpd) {}
        return {
          applied: false,
          commandEffective: false,
          // Kontrollierte Watchdog-Übergabe, kein Hardwarefehler.
          writeOk: true,
          requestSatisfied: false,
          partiallyAccepted: false,
          status: diag.status,
          reason: diag.reason,
          direction,
          targetW: w,
          requestedW: w,
          plannedDeliveredW: 0,
          deliveredW: 0,
          acceptedDeliveredW: 0,
          failedW: 0,
          unservedW: w,
          commandDpReadbackSupported: false,
          commandDpReadbackOk: true,
          commandDpReadbackStatus: diag.status,
          commandDpReadbackRows: [],
          results: [],
        };
      }
      this._sfFeneconNativeActive = null;
      this._sfFeneconDirectReleaseUntilMs = 0;
      this._sfFeneconDirectReleaseKey = '';
    }
    /**
     * Code-Teil: getLimitW
     * Zweck: Kapselt einen lokalen Verarbeitungsschritt, damit Aufrufer nicht direkt in Detaildaten eingreifen.
     * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
     * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
     */
    const getLimitW = (storage, dir) => {
      const raw = (dir === 'charge') ? (storage && storage.maxChargeW) : (storage && storage.maxDischargeW);
      // Leer / null / undefined = unlimitiert. Eine 0-W-Vorgabe ist dagegen
      // eine gewollte Sperre für diese Richtung und muss die Farm-Verteilung stoppen.
      if (raw === undefined || raw === null) return Number.POSITIVE_INFINITY;
      if (typeof raw === 'string' && raw.trim() === '') return Number.POSITIVE_INFINITY;
      const v = Number(String(raw).replace(',', '.'));
      if (Number.isFinite(v) && v >= 0) return Math.round(v);
      return Number.POSITIVE_INFINITY;
    };
    /**
     * Code-Teil: sumLimitW
     * Zweck: Kapselt einen lokalen Verarbeitungsschritt, damit Aufrufer nicht direkt in Detaildaten eingreifen.
     * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
     * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
     */
    const sumLimitW = (items, dir) => {
      let sum = 0;
      let hasInfinity = false;
      for (const s of items || []) {
        const lim = getLimitW(s, dir);
        if (!Number.isFinite(lim)) hasInfinity = true;
        else sum += Math.max(0, lim);
      }
      return hasInfinity ? Number.POSITIVE_INFINITY : sum;
    };
    /**
     * Code-Teil: buildWeights
     * Zweck: Erzeugt UI-/Konfigurations- oder Datenstruktur.
     * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
     * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
     */
    const buildWeights = (items, dir) => {
      const list = (items || []).slice();
      const finiteSocs = list
        .map(it => Number.isFinite(it.soc) ? Number(it.soc) : NaN)
        .filter(v => Number.isFinite(v));
      const minSoc = finiteSocs.length ? Math.min(...finiteSocs) : NaN;
      const maxSoc = finiteSocs.length ? Math.max(...finiteSocs) : NaN;
      const socSpread = (Number.isFinite(minSoc) && Number.isFinite(maxSoc)) ? (maxSoc - minSoc) : 0;

      return list.map(it => {
        const cap = (Number.isFinite(it.capacityKWh) && it.capacityKWh > 0) ? it.capacityKWh : 1;
        const soc = Number.isFinite(it.soc) ? Number(it.soc) : null;
        let base = 1;

        if (dir === 'charge') {
          base = (typeof soc === 'number') ? Math.max(0, 100 - soc) : 1;
        } else if (dir === 'discharge') {
          if (typeof soc === 'number') {
            const aboveFloor = Math.max(0, soc - dischargeFloorSoc);
            if (aboveFloor <= 0.05) {
              base = 0;
            } else {
              base = Math.pow(aboveFloor, 1.15);
              if (socSpread >= 1 && Number.isFinite(minSoc) && Number.isFinite(maxSoc)) {
                const rel = Math.max(0, Math.min(1, (soc - minSoc) / Math.max(1, socSpread)));
                base *= (0.75 + rel * 0.60);
              }
            }
          } else {
            base = 1;
          }

          // Istleistungs-DPs sind in der Farm ab v0.6.258 reine Mess-/Diagnosewerte.
          // Sie dürfen die Sollwertverteilung nicht drosseln, damit Systeme auch mit
          // Signed-Setpoint-only oder selten aktualisierten Istwerten weiterlaufen.
          const responseLimiterEnabled = !!(this.config && this.config.storageFarm && this.config.storageFarm.enableResponseLimiter === true);
          if (responseLimiterEnabled) base *= this._sfGetResponseLimitFactor(it, 'discharge', now);
        } else {
          base = 1;
        }

        if (!Number.isFinite(base) || base < 0) base = 0;
        return base * cap;
      });
    };
    /**
     * Code-Teil: normalizeWeights
     * Zweck: Kapselt einen lokalen Verarbeitungsschritt, damit Aufrufer nicht direkt in Detaildaten eingreifen.
     * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
     * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
     */
    const normalizeWeights = (list, weights, dir) => {
      let out = (Array.isArray(weights) ? weights.slice() : []).map(v => (Number.isFinite(v) && v > 0) ? v : 0);
      let sumW = out.reduce((a, b) => a + b, 0);

      if (!(sumW > 0) && dir === 'discharge') {
        const socEntries = list
          .map((it, idx) => ({ idx, soc: Number.isFinite(it.soc) ? Number(it.soc) : NaN }))
          .filter(x => Number.isFinite(x.soc))
          .sort((a, b) => b.soc - a.soc);

        if (socEntries.length) {
          const topSoc = socEntries[0].soc;
          out = new Array(list.length).fill(0);
          for (const entry of socEntries) {
            if ((topSoc - entry.soc) <= 0.25) out[entry.idx] = 1;
          }
          sumW = out.reduce((a, b) => a + b, 0);
        }
      }

      if (!(sumW > 0)) {
        out = new Array(list.length).fill(1);
        sumW = out.length;
      }

      return { weights: out, sumW };
    };
    /**
     * Code-Teil: allocateWeightedCapped
     * Zweck: Kapselt einen lokalen Verarbeitungsschritt, damit Aufrufer nicht direkt in Detaildaten eingreifen.
     * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
     * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
     */
    const allocateWeightedCapped = (total, items, dir) => {
      const list = (items || []).slice();
      const requestedW = Math.max(0, Math.round(Number(total) || 0));
      const allocMap = new Map();
      const weightMap = new Map();
      if (requestedW <= 0 || list.length === 0) return { allocMap, weightMap, requestedW, deliveredW: 0, unservedW: requestedW };

      const rawWeights = buildWeights(list, dir);
      const { weights } = normalizeWeights(list, rawWeights, dir);
      const caps = list.map(s => getLimitW(s, dir));

      const alloc = new Array(list.length).fill(0);
      let remaining = requestedW;
      let active = list
        .map((_, idx) => idx)
        .filter(idx => {
          const cap = caps[idx];
          return (cap > 0 || !Number.isFinite(cap)) && (weights[idx] > 0);
        });

      let guard = 0;
      while (remaining > 0 && active.length > 0 && guard++ < 100) {
        const sumW = active.reduce((sum, idx) => sum + (weights[idx] || 0), 0);
        if (!(sumW > 0)) break;

        let used = 0;
        const order = [];
        for (const idx of active) {
          const cap = caps[idx];
          const headroom = Number.isFinite(cap) ? Math.max(0, cap - alloc[idx]) : remaining;
          if (headroom <= 0) continue;
          const raw = remaining * ((weights[idx] || 0) / sumW);
          const floor = Math.floor(raw);
          const add = Math.min(headroom, floor);
          if (add > 0) {
            alloc[idx] += add;
            used += add;
          }
          order.push({ idx, frac: raw - floor, weight: weights[idx] || 0 });
        }

        remaining -= used;

        if (remaining > 0) {
          order.sort((a, b) => (b.frac - a.frac) || (b.weight - a.weight));
          let progressed = false;
          for (const o of order) {
            if (remaining <= 0) break;
            const cap = caps[o.idx];
            const headroom = Number.isFinite(cap) ? Math.max(0, cap - alloc[o.idx]) : remaining;
            if (headroom <= 0) continue;
            alloc[o.idx] += 1;
            remaining -= 1;
            progressed = true;
          }
          if (!progressed) break;
        }

        active = active.filter(idx => {
          const cap = caps[idx];
          return Number.isFinite(cap) ? (alloc[idx] < cap) : true;
        });
      }

      let deliveredW = 0;
      for (let i = 0; i < list.length; i++) {
        const a = Math.max(0, Math.round(alloc[i] || 0));
        deliveredW += a;
        allocMap.set(list[i], a);
        weightMap.set(list[i], weights[i] || 0);
      }

      return { allocMap, weightMap, requestedW, deliveredW, unservedW: Math.max(0, requestedW - deliveredW) };
    };
    /**
     * Code-Teil: canUse
     * Zweck: Kapselt einen lokalen Verarbeitungsschritt, damit Aufrufer nicht direkt in Detaildaten eingreifen.
     * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
     * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
     */
    const canUse = (s) => {
      if (direction === 'charge') return !!(s.setSignedPowerId || s.setChargePowerId);
      if (direction === 'discharge') return !!(s.setSignedPowerId || s.setDischargePowerId);
      return !!(s.setSignedPowerId || s.setChargePowerId || s.setDischargePowerId);
    };

    const eligibleAll = storages.filter(canUse);
    if (eligibleAll.length === 0) return { applied: false, reason: 'no_setpoint_dps' };

    const dispatchEligible = (direction === 'charge')
      ? eligibleAll.filter(s => s.chargeDispatchAvailable === true)
      : ((direction === 'discharge')
          ? eligibleAll.filter(s => s.dischargeDispatchAvailable === true)
          : eligibleAll);

    const eligibleForDispatch = (direction === 'discharge')
      ? dispatchEligible.filter(s => {
          const soc = Number(s && s.soc);
          return !Number.isFinite(soc) || soc > (dischargeFloorSoc + 0.05);
        })
      : dispatchEligible;

    let allocMap = new Map();
    let deliveredAbsW = 0;
    let unservedAbsW = (direction === 'idle') ? 0 : absW;

    if (direction !== 'idle' && eligibleForDispatch.length > 0) {
      if (sf.mode === 'groups' && sf.groups && sf.groups.length > 0) {
        const groups = [...sf.groups].sort((a, b) => (b.priority || 0) - (a.priority || 0));
        const groupBuckets = new Map();
        for (const g of groups) groupBuckets.set(g.name, []);

        for (const s of eligibleForDispatch) {
          const gname = s.group && groupBuckets.has(s.group) ? s.group : null;
          if (!gname) continue;
          const g = groups.find(x => x.name === gname) || null;
          if (g && Number.isFinite(s.soc)) {
            if (typeof g.socMin === 'number' && s.soc < g.socMin) continue;
            if (typeof g.socMax === 'number' && s.soc > g.socMax) continue;
          }
          groupBuckets.get(gname).push(s);
        }
        const activeGroups = groups.filter(g => (groupBuckets.get(g.name) || []).length > 0);
        if (activeGroups.length === 0) {
          const res = allocateWeightedCapped(absW, eligibleForDispatch, direction);
          allocMap = res.allocMap;
          deliveredAbsW = res.deliveredW;
          unservedAbsW = res.unservedW;
        } else {
          const groupPseudo = activeGroups.map(g => {
            const items = groupBuckets.get(g.name) || [];
            const capacityKWh = items.reduce((sum, s) => sum + ((Number.isFinite(s.capacityKWh) && s.capacityKWh > 0) ? s.capacityKWh : 1), 0);
            const groupLimit = sumLimitW(items, direction);
            return {
              name: g.name,
              group: g.name,
              capacityKWh,
              soc: null,
              maxChargeW: direction === 'charge' ? groupLimit : null,
              maxDischargeW: direction === 'discharge' ? groupLimit : null,
            };
          });

          const gRes = allocateWeightedCapped(absW, groupPseudo, direction);
          for (let i = 0; i < activeGroups.length; i++) {
            const pseudo = groupPseudo[i];
            const gAlloc = gRes.allocMap.get(pseudo) || 0;
            const items = groupBuckets.get(activeGroups[i].name) || [];
            const inner = allocateWeightedCapped(gAlloc, items, direction);
            for (const [s, a] of inner.allocMap.entries()) allocMap.set(s, (allocMap.get(s) || 0) + a);
          }
          deliveredAbsW = Array.from(allocMap.values()).reduce((sum, v) => sum + (Number.isFinite(v) ? v : 0), 0);
          unservedAbsW = Math.max(0, absW - deliveredAbsW);
        }
      } else {
        const res = allocateWeightedCapped(absW, eligibleForDispatch, direction);
        allocMap = res.allocMap;
        deliveredAbsW = res.deliveredW;
        unservedAbsW = res.unservedW;
      }
    }

    // Baustein 8: Pro Speicher darf genau eine Sollwert-Kommandofamilie
    // aktiv sein. Vollstaendige Split-DPs gewinnen vor Signed; alternative
    // Familien werden kontrolliert neutralisiert und per State-Readback bestaetigt.
    const results = [];
    for (const s of storages) {
      const alloc = (direction === 'idle') ? 0 : (allocMap.get(s) || 0);
      const chargeW = (direction === 'charge') ? alloc : 0;
      const dischargeW = (direction === 'discharge') ? alloc : 0;

      const outChargeW = s.invertChargeSign ? -chargeW : chargeW;
      const outDischargeW = s.invertDischargeSign ? -dischargeW : dischargeW;
      let outSignedW = direction === 'charge' ? -Math.abs(chargeW) : (direction === 'discharge' ? Math.abs(dischargeW) : 0);
      if (s.invertSetSignedPowerSign) outSignedW = -outSignedW;

      const signedId = String(s.setSignedPowerId || '').trim();
      const chargeId = String(s.setChargePowerId || '').trim();
      const dischargeId = String(s.setDischargePowerId || '').trim();
      const splitPairConflict = !!(chargeId && dischargeId && chargeId === dischargeId);
      const completeSplit = !!(chargeId && dischargeId && !splitPairConflict);
      const anySplit = !!(chargeId || dischargeId);
      let commandFamily = 'none';
      if (completeSplit) commandFamily = 'split';
      else if (signedId) commandFamily = 'signed';
      else if (anySplit && !splitPairConflict) commandFamily = 'split';
      const directionSupported = direction === 'idle'
        || commandFamily === 'signed'
        || (commandFamily === 'split' && (direction === 'charge' ? !!chargeId : !!dischargeId));

      // Explain this exact dispatch decision without redefining the status
      // capability flags or changing the allocator/write path above.
      const directionDispatchAvailable = eligibleForDispatch.includes(s);
      const blockedReasons = [...(direction === 'charge' ? (s.chargeBlockedReasons || [])
        : direction === 'discharge' ? (s.dischargeBlockedReasons || []) : [])];
      if (direction === 'discharge' && dispatchEligible.includes(s) && !directionDispatchAvailable) {
        blockedReasons.push(s._sfReportedSoc === null ? 'soc_missing' : 'soc_at_or_below_discharge_floor');
      }
      const effectiveDischargeLimit = direction === 'discharge'
        ? (directionDispatchAvailable ? getLimitW(s, 'discharge') : 0) : null;

      const r = {
        name: s.name || '',
        dispatchKey: s._sfKey,
        soc: s._sfReportedSoc,
        state: s.state || '',
        online: !!s.online,
        dispatchAvailable: !!s.dispatchAvailable,
        chargeDispatchAvailable: !!s.chargeDispatchAvailable,
        dischargeDispatchAvailable: !!s.dischargeDispatchAvailable,
        maxChargeW: (s.maxChargeW !== null && Number.isFinite(Number(s.maxChargeW))) ? Number(s.maxChargeW) : null,
        maxDischargeW: (s.maxDischargeW !== null && Number.isFinite(Number(s.maxDischargeW))) ? Number(s.maxDischargeW) : null,
        directionDispatchAvailable,
        dischargeFloorSocPct: direction === 'discharge' ? dischargeFloorSoc : null,
        effectiveMaxDischargeW: Number.isFinite(effectiveDischargeLimit) ? effectiveDischargeLimit : null,
        blockedReasons,
        warnings: Array.isArray(s.dispatchWarnings) ? s.dispatchWarnings : [],
        statusMatch: String(s.statusMatch || ''),
        actualChargeW: Number.isFinite(Number(s.chargePowerW)) ? Number(s.chargePowerW) : null,
        actualDischargeW: Number.isFinite(Number(s.dischargePowerW)) ? Number(s.dischargePowerW) : null,
        chargeW,
        dischargeW,
        commandFamily,
        directionSupported,
        splitPairConflict,
        ignoredAlternatives: [],
        ok: true,
        writes: {},
      };

      const selectedIds = new Set();
      if (commandFamily === 'signed' && signedId) selectedIds.add(signedId);
      if (commandFamily === 'split') {
        if (chargeId) selectedIds.add(chargeId);
        if (dischargeId) selectedIds.add(dischargeId);
      }

      const releaseRows = [];
      const releaseOnce = async (key, id) => {
        const objectId = String(id || '').trim();
        if (!objectId || selectedIds.has(objectId) || releaseRows.some((row) => row.objectId === objectId)) return;
        const wr = await this._sfWriteIfChanged(objectId, 0, { keepalive: false });
        r.writes[key] = wr;
        r.ignoredAlternatives.push({ key, objectId });
        releaseRows.push({ key, objectId, wr });
        if (!wr.ok) r.ok = false;
      };

      if (commandFamily !== 'signed') await releaseOnce('releaseSigned', signedId);
      if (commandFamily !== 'split') {
        await releaseOnce('releaseCharge', chargeId);
        await releaseOnce('releaseDischarge', dischargeId);
      }

      const selectedWrites = [];
      const writeSelected = async (key, id, value) => {
        const objectId = String(id || '').trim();
        if (!objectId) return;
        const wr = await this._sfWriteIfChanged(objectId, value, { keepalive: true });
        r.writes[key] = wr;
        selectedWrites.push(wr);
        if (!wr.ok) r.ok = false;
      };

      if (splitPairConflict && !signedId) {
        r.writes.conflict = {
          ok: false,
          skipped: true,
          changed: false,
          reason: 'split_charge_discharge_same_object',
          objectId: chargeId,
        };
        r.ok = false;
      } else if (commandFamily === 'signed') {
        await writeSelected('signed', signedId, outSignedW);
      } else if (commandFamily === 'split') {
        // Gleicher EMS-Tick, aber sichere Reihenfolge: inaktive Richtung zuerst
        // auf 0, danach aktive Richtung mit dem neuen Betrag.
        if (direction === 'discharge') {
          await writeSelected('charge', chargeId, 0);
          await writeSelected('discharge', dischargeId, outDischargeW);
        } else if (direction === 'charge') {
          await writeSelected('discharge', dischargeId, 0);
          await writeSelected('charge', chargeId, outChargeW);
        } else {
          await writeSelected('charge', chargeId, 0);
          await writeSelected('discharge', dischargeId, 0);
        }
      }

      const releaseAccepted = releaseRows.every((row) => row.wr && row.wr.ok === true);
      const commandRequired = selectedWrites.length > 0 || releaseRows.length > 0 || !!r.writes.conflict;
      const selectedAccepted = selectedWrites.length > 0 && selectedWrites.every((wr) => wr && wr.ok === true);
      const commandAccepted = commandRequired
        && directionSupported
        && !r.writes.conflict
        && releaseAccepted
        && selectedAccepted;
      const signedAllocatedW = direction === 'charge' ? -Math.abs(alloc) : (direction === 'discharge' ? Math.abs(alloc) : 0);
      r.commandRequired = commandRequired;
      r.commandAccepted = commandAccepted;
      r.releaseAccepted = releaseAccepted;
      r.selectedAccepted = selectedAccepted;
      r.acceptedW = commandAccepted === true ? signedAllocatedW : 0;
      r.failedW = (commandRequired && commandAccepted !== true && direction !== 'idle') ? signedAllocatedW : 0;
      r.stopAccepted = direction === 'idle' && commandRequired ? commandAccepted === true : null;

      if (commandAccepted === true) this._sfRememberDispatchSnapshot(s, direction, alloc);
      results.push(r);
    }

    const plannedSignedW = direction === 'charge' ? -deliveredAbsW : deliveredAbsW;
    const acceptedSignedW = results.reduce((sum, row) => sum + (Number.isFinite(Number(row.acceptedW)) ? Number(row.acceptedW) : 0), 0);
    const acceptedAbsW = Math.abs(Math.round(acceptedSignedW));
    const failedAbsW = direction === 'idle'
      ? 0
      : Math.max(0, Math.round(deliveredAbsW - acceptedAbsW));
    const failedSignedW = failedAbsW > 0
      ? (direction === 'charge' ? -failedAbsW : failedAbsW)
      : 0;
    const unservedSignedW = unservedAbsW > 0
      ? (direction === 'charge' ? -unservedAbsW : unservedAbsW)
      : 0;
    const commandRows = results.filter((row) => row.commandRequired === true);
    const allConfiguredWritesAccepted = commandRows.length > 0 && commandRows.every((row) => row.commandAccepted === true);
    const failedCommandCount = commandRows.filter((row) => row.commandAccepted !== true).length;
    const commandDpReadbackRows = results.flatMap((row) => Object.entries(row.writes || {}).map(([key, wr]) => {
      const readback = wr && wr.readback && typeof wr.readback === 'object' ? wr.readback : null;
      return {
        storage: row.name || '',
        family: row.commandFamily || 'none',
        key,
        objectId: readback ? String(readback.objectId || '') : '',
        expected: readback && Number.isFinite(Number(readback.expected)) ? Number(readback.expected) : null,
        actual: readback && typeof readback.actual === 'number' && Number.isFinite(readback.actual)
          ? readback.actual : (readback ? readback.actual : null),
        supported: !!(wr && wr.readbackSupported === true),
        ok: wr && typeof wr.readbackOk === 'boolean' ? wr.readbackOk : null,
        pending: !!(readback && readback.pending === true),
        ack: readback && typeof readback.ack === 'boolean' ? readback.ack : null,
        ts: readback ? readback.ts : null,
        q: readback ? readback.q : null,
        confirmationLevel: readback ? String(readback.confirmationLevel || 'none') : 'none',
        status: readback ? String(readback.status || '') : String((wr && wr.reason) || ''),
      };
    }));
    const supportedCommandDpReadbacks = commandDpReadbackRows.filter((row) => row.supported);
    const commandDpReadbackSupported = supportedCommandDpReadbacks.length > 0;
    const commandDpReadbackOk = commandDpReadbackSupported
      ? commandDpReadbackRows.every((row) => row.supported && row.ok === true)
      : true;
    const commandDpReadbackStatus = commandDpReadbackSupported
      ? (commandDpReadbackOk ? 'driver-acknowledged'
        : (commandDpReadbackRows.every(row => !row.supported || row.ok === true || row.pending === true) ? 'pending-ack' : 'command-dp-mismatch'))
      : 'unavailable';
    const commandDpReadbackPending = supportedCommandDpReadbacks.some(row => row.pending === true);
    const commandConfirmationLevel = commandDpReadbackSupported && commandDpReadbackOk
      ? 'driver-acknowledged' : (allConfiguredWritesAccepted ? 'requested' : 'none');
    const anyAcceptedPower = direction === 'idle' ? allConfiguredWritesAccepted : acceptedAbsW > 0;
    const requestSatisfied = direction === 'idle'
      ? allConfiguredWritesAccepted
      : (allConfiguredWritesAccepted && failedAbsW === 0 && unservedAbsW === 0);
    let dispatchStatus = 'farm';
    if (direction === 'idle') dispatchStatus = allConfiguredWritesAccepted ? 'farm-stop' : 'farm-stop-failed';
    else if (!allConfiguredWritesAccepted && acceptedAbsW > 0) dispatchStatus = 'farm-partial';
    else if (!allConfiguredWritesAccepted) dispatchStatus = 'farm-write-failed';
    else if (unservedAbsW > 0) dispatchStatus = 'farm-limited';

    try {
