      };

      // Prime global summary/control states used by the UI.
      await prime('chargingManagement.wallboxCount');
      await prime('chargingManagement.stationCount');
      await prime('chargingManagement.summary.totalPowerW');
      await prime('chargingManagement.summary.totalTargetPowerW');
      await prime('chargingManagement.summary.onlineWallboxes');
      await prime('chargingManagement.control.active');
      await prime('chargingManagement.control.mode');
      await prime('chargingManagement.control.status');
      await prime('chargingManagement.control.budgetW');
      await prime('chargingManagement.control.remainingW');
      await prime('chargingManagement.control.tsControlProductiveJson');
      await prime('chargingManagement.control.tsAllocationShadowJson');
      await prime('chargingManagement.control.tsAllocationProductivePrepJson');
      await prime('chargingManagement.control.tsAllocationProductiveJson');
      await prime('chargingManagement.control.tsAllocationNormalSourceJson');
      await prime('chargingManagement.control.tsNormalSourceJson');
      await prime('chargingManagement.control.tsNormalSourceLockdownJson');
      await prime('chargingManagement.control.tsNormalSource');
      await prime('chargingManagement.control.tsRuntimeSource');
      await prime('chargingManagement.control.tsMigrationReady');
      await prime('chargingManagement.control.tsEvcsJsRemovalJson');
      await prime('chargingManagement.control.tsEvcsJsRemovalReady');
      await prime('chargingManagement.control.tsAdapterRuntimeHandoverJson');
      await prime('chargingManagement.control.tsAdapterRuntimeSource');
      await prime('chargingManagement.control.tsAdapterMigrationReady');
      await prime('chargingManagement.control.tsWritePlanShadowJson');
      await prime('chargingManagement.control.tsWritePlanProductivePrepJson');
      await prime('chargingManagement.control.tsWritePlanProductiveJson');
      await prime('chargingManagement.control.tsWritePlanExecutorJson');
      await prime('chargingManagement.control.tsLegacyDecisionTreeJson');
      await prime('chargingManagement.control.usedW');
      await prime('chargingManagement.control.pvAvailable');

      // Prime per-Ladepunkt runtime states (mode + boost info + station meta)
      for (let i = 1; i <= evcsCount; i++) {
        const base = `chargingManagement.wallboxes.lp${i}`;
        await prime(`${base}.userMode`);
        await prime(`${base}.userAutoSource`);
        await prime(`${base}.userPhaseMode`);
        await prime(`${base}.effectiveMode`);
        await prime(`${base}.phaseMode`);
        await prime(`${base}.phaseSwitchSupported`);
        await prime(`${base}.currentPhaseCount`);
        await prime(`${base}.targetPhaseCount`);
        await prime(`${base}.phaseSwitchState`);
        await prime(`${base}.phaseSwitchReason`);
        await prime(`${base}.phaseCooldownRemainingMs`);
        await prime(`${base}.chargerType`);
        await prime(`${base}.phases`);
        await prime(`${base}.online`);
        await prime(`${base}.charging`);
        await prime(`${base}.chargingSince`);
        await prime(`${base}.targetPowerW`);
        await prime(`${base}.targetCurrentA`);
        await prime(`${base}.stationKey`);
        await prime(`${base}.stationMaxPowerW`);
        await prime(`${base}.allowBoost`);
        await prime(`${base}.boostActive`);
        await prime(`${base}.boostUntil`);
        await prime(`${base}.boostRemainingMin`);
        await prime(`${base}.boostTimeoutMin`);
      }

      // Prime station states (max/remaining) if station keys are known in config.
      /**
       * Code-Teil: toSafe
       * Zweck: Kapselt einen lokalen Verarbeitungsschritt, damit Aufrufer nicht direkt in Detaildaten eingreifen.
       * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
       * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
       */
      const toSafe = (s) => {
        try {
          return String(s || '')
            .trim()
            .toLowerCase()
            .replace(/[^a-z0-9_\-]/g, '_')
            .replace(/_+/g, '_')
            .replace(/^_+|_+$/g, '');
        } catch (_e) {
          return '';
        }
      };
      try {
        const sg = (cfg && cfg.settingsConfig && Array.isArray(cfg.settingsConfig.stationGroups)) ? cfg.settingsConfig.stationGroups : [];
        for (const g of sg) {
          if (!g) continue;
          const sk = (typeof g.stationKey === 'string') ? g.stationKey.trim() : '';
          if (!sk) continue;
          const safe = toSafe(sk);
          if (!safe) continue;
          await prime(`chargingManagement.stations.${safe}.maxPowerW`);
          await prime(`chargingManagement.stations.${safe}.remainingW`);
        }
      } catch (_e) {}
    } catch (_eOuter) {
      // never fail adapter startup due to UI convenience
    }
  }
  /**
 * Returns the SmartHomeConfig structure from adapter config.
 * This is the future generic model for rooms, functions and devices.
 *
 * smartHomeConfig: {
 *   version: 1,
 *   rooms: [
 *     { id: 'living', name: 'Wohnen', icon: 'room-living', floor: 'EG', order: 10, enabled: true }
 *   ],
 *   functions: [
 *     { id: 'light', name: 'Licht', icon: 'func-light', order: 10, enabled: true }
 *   ],
 *   devices: [
 *     {
 *       id: 'living_light_ceiling',
 *       type: 'switch', // switch|dimmer|blind|rtr|sensor|scene
 *       roomId: 'living',
 *       functionId: 'light',
 *       alias: 'Deckenlicht',
 *       icon: 'light-ceiling',
 *       size: 'm', // s|m|l
 *       tags: ['wohnen', 'licht'],
 *       behavior: { readOnly: false, invert: false },
 *       io: {
 *         switch: { readId: 'knx.0.living.light.ceiling', writeId: 'knx.0.living.light.ceiling' }
 *       }
 *     }
 *   ]
 * }
 */
getSmartHomeConfig() {
  const cfg = this.config || {};
  const shc = cfg.smartHomeConfig || {};

  const rooms = Array.isArray(shc.rooms) ? shc.rooms : [];
  let floors = Array.isArray(shc.floors) ? shc.floors : [];

  // Backward compatibility / recovery:
  // If floors are missing but rooms reference floorId, derive a minimal floors list
  // so the editor/runtime can still show the building structure.
  if (!floors.length && rooms.length) {
    const seen = new Set();
    const ids = [];
    for (const r of rooms) {
      const fid = (r && r.floorId) ? String(r.floorId).trim() : '';
      if (!fid) continue;
      if (fid === '__unassigned__') continue;
      if (seen.has(fid)) continue;
      seen.add(fid);
      ids.push(fid);
    }
    if (ids.length) {
      /**
       * Code-Teil: pretty
       * Zweck: Kapselt einen lokalen Verarbeitungsschritt, damit Aufrufer nicht direkt in Detaildaten eingreifen.
       * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
       * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
       */
      const pretty = (s) => {
        const raw = String(s || '').trim();
        if (!raw) return '';
        return raw
          .replace(/[_-]+/g, ' ')
          .replace(/\s+/g, ' ')
          .replace(/\b\w/g, (m) => m.toUpperCase());
      };
      floors = ids.map((id, idx) => ({ id, name: pretty(id) || id, icon: '🏢', order: idx + 1 }));
    }
  }

  return nwNormalizeSmartHomeConfigContract({
    // version 3 keeps the v2 building/navigation model and adds a canonical
    // capability-/IO-contract for all SmartHome tiles.
    version: typeof shc.version === 'number' ? shc.version : 3,
    floors,
    rooms,
    functions: Array.isArray(shc.functions) ? shc.functions : [],
    devices: Array.isArray(shc.devices) ? shc.devices : [],
    scenes: Array.isArray(shc.scenes) ? shc.scenes : [],
    pages: Array.isArray(shc.pages) ? shc.pages : [],
    meta: this._nwIsPlainObject(shc.meta) ? shc.meta : {},
  });
}

nwNormalizeSmartHomeConfig(config) {
  return nwNormalizeSmartHomeConfigContract(config);
}

nwValidateSmartHomeConfig(config) {
  return nwValidateSmartHomeConfigContract(config);
}

/**
 * Returns the NexoLogic editor config (node/graph).
 * Stored inside installer-managed config key `logicEditor`.
 */
getLogicEditorConfig() {
