/**
 * Normalizes a user-provided logic editor config to a safe structure.
 * (This prevents broken configs from breaking runtime logic.)
 */
nwNormalizeLogicEditorConfig(inCfg) {
  /**
   * Code-Teil: isPlain
   * Zweck: Kapselt einen lokalen Verarbeitungsschritt, damit Aufrufer nicht direkt in Detaildaten eingreifen.
   * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
   * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
   */
  const isPlain = (o) => this._nwIsPlainObject(o);
  /**
   * Code-Teil: safeStr
   * Zweck: Kapselt einen lokalen Verarbeitungsschritt, damit Aufrufer nicht direkt in Detaildaten eingreifen.
   * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
   * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
   */
  const safeStr = (s, maxLen) => {
    if (s === null || s === undefined) return '';
    const str = String(s);
    return str.length > maxLen ? str.slice(0, maxLen) : str;
  };

  const cfg = isPlain(inCfg) ? inCfg : {};
  /**
   * Code-Teil: mkId
   * Zweck: Kapselt einen lokalen Verarbeitungsschritt, damit Aufrufer nicht direkt in Detaildaten eingreifen.
   * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
   * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
   */
  const mkId = (prefix) => {
    const rnd = Math.random().toString(36).slice(2, 8);
    return `${prefix}_${Date.now().toString(36)}_${rnd}`;
  };
  const out = {
    version: (typeof cfg.version === 'number' && Number.isFinite(cfg.version)) ? cfg.version : 1,
    updatedAt: (typeof cfg.updatedAt === 'number' && Number.isFinite(cfg.updatedAt)) ? cfg.updatedAt : Date.now(),
    graphs: [],
  };
  /**
   * Code-Teil: clamp
   * Zweck: Kapselt einen lokalen Verarbeitungsschritt, damit Aufrufer nicht direkt in Detaildaten eingreifen.
   * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
   * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
   */
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
  /**
   * Code-Teil: toNum
   * Zweck: Kapselt einen lokalen Verarbeitungsschritt, damit Aufrufer nicht direkt in Detaildaten eingreifen.
   * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
   * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
   */
  const toNum = (v, def) => {
    const n = Number(v);
    return Number.isFinite(n) ? n : def;
  };

  const graphs = Array.isArray(cfg.graphs) ? cfg.graphs : [];
  for (const g of graphs) {
    if (!isPlain(g)) continue;
    const id = safeStr(g.id || 'main', 64) || 'main';
    const graph = {
      id,
      name: safeStr(g.name || 'Hauptlogik', 120) || 'Hauptlogik',
      enabled: g.enabled === undefined ? true : !!g.enabled,
      board: {
        w: clamp(toNum(g.board && g.board.w, 2400), 800, 12000),
        h: clamp(toNum(g.board && g.board.h, 1400), 600, 12000),
      },
      nodes: [],
      links: [],
    };

    const nodes = Array.isArray(g.nodes) ? g.nodes : [];
    for (const n of nodes) {
      if (!isPlain(n)) continue;
      const node = {
        id: safeStr(n.id || mkId('n'), 80) || mkId('n'),
        type: safeStr(n.type || '', 64),
        label: safeStr(n.label || '', 120),
        enabled: n.enabled === undefined ? true : !!n.enabled,
        x: clamp(toNum(n.x, 40), 0, graph.board.w - 40),
        y: clamp(toNum(n.y, 40), 0, graph.board.h - 40),
        params: {},
      };
      // params: only primitives
      if (isPlain(n.params)) {
        for (const [k, v] of Object.entries(n.params)) {
          const key = safeStr(k, 64);
          if (!key) continue;
          if (v === null || v === undefined) continue;
          if (typeof v === 'string' || typeof v === 'number' || typeof v === 'boolean') {
            node.params[key] = v;
          }
        }
      }
      graph.nodes.push(node);
    }

    const links = Array.isArray(g.links) ? g.links : [];
    for (const l of links) {
      if (!isPlain(l)) continue;
      const from = isPlain(l.from) ? l.from : {};
      const to = isPlain(l.to) ? l.to : {};
      const link = {
        id: safeStr(l.id || mkId('l'), 80) || mkId('l'),
        from: { node: safeStr(from.node || '', 80), port: safeStr(from.port || '', 40) },
        to: { node: safeStr(to.node || '', 80), port: safeStr(to.port || '', 40) },
      };
      if (!link.from.node || !link.from.port || !link.to.node || !link.to.port) continue;
      graph.links.push(link);
    }

    out.graphs.push(graph);
  }

  // Ensure at least one graph exists
  if (!out.graphs.length) {
    out.graphs.push({
      id: 'main',
      name: 'Hauptlogik',
      enabled: true,
      board: { w: 2400, h: 1400 },
      nodes: [],
      links: [],
    });
  }

  return out;
}

nwValidateLogicEditorConfig(config) {
  return validateNexoLogicConfig(config);
}

/**
 * Code-Teil: buildSmartHomeDevicesFromConfig
 * Zweck: Erzeugt oder aktualisiert die sichtbare Darstellung bzw. das dazugehörige Datenmodell.
 * Zusammenhang: Gehört zu ioBroker-Adapterkern (Adapter-Lifecycle, Webserver, REST-/SSE-API, State-Anlage, Lizenz und EMS-Engine) und wird von benachbarten UI-/API-/EMS-Bausteinen genutzt.
 * Wartung/TypeScript: Änderungen können Gebäudestruktur, Kachelbedienung und Popover-Verhalten beeinflussen. Beim TS-Umbau Parameter, Rückgabe und genutzte State-/Config-Objekte explizit typisieren.
 */
buildSmartHomeDevicesFromConfig() {
  const smCfg = (this.config && this.config.smartHome) || {};
  const enabled = smartHomeEnabled(this.config, this._nwNativeConfigBase);
  const dps = smCfg.datapoints || {};
  const devices = [];

  if (!enabled) {
    this.smartHomeDevices = [];
    return this.smartHomeDevices;
  }

  // --- SmartHomeConfig v1: rooms/functions/devices (primary source) ---
  const shc = this.getSmartHomeConfig ? this.getSmartHomeConfig() : null;
  const floors = (shc && Array.isArray(shc.floors)) ? shc.floors : [];
  const rooms = (shc && Array.isArray(shc.rooms)) ? shc.rooms : [];
  const funcs = (shc && Array.isArray(shc.functions)) ? shc.functions : [];
  const cfgDevices = (shc && Array.isArray(shc.devices)) ? shc.devices : [];
  const cfgScenes = (shc && Array.isArray(shc.scenes)) ? shc.scenes : [];
  const hasConfigDevices = cfgDevices.length > 0;
  /**
   * Code-Teil: resolveRoomName
   * Zweck: Wählt die richtige Datenquelle/Fallback-Logik aus.
   * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
   * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
   */
  const resolveRoomName = (roomId) => {
    if (!roomId) return '';
    const r = rooms.find(rm => rm && rm.id === roomId);
    return (r && r.name) || roomId;
  };
  /**
   * Code-Teil: resolveRoomFloorId
   * Zweck: Wählt die richtige Datenquelle/Fallback-Logik aus.
   * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
   * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
   */
  const resolveRoomFloorId = (roomId) => {
    if (!roomId) return '';
    const r = rooms.find(rm => rm && rm.id === roomId);
    return (r && r.floorId) ? String(r.floorId) : '';
  };
  /**
   * Code-Teil: resolveFloorName
   * Zweck: Wählt die richtige Datenquelle/Fallback-Logik aus.
   * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
   * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
   */
  const resolveFloorName = (floorId) => {
    if (!floorId) return '';
    const f = floors.find(fl => fl && String(fl.id) === String(floorId));
    return (f && f.name) ? String(f.name) : String(floorId);
  };
  /**
   * Code-Teil: resolveFunctionName
   * Zweck: Wählt die richtige Datenquelle/Fallback-Logik aus.
   * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
   * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
   */
  const resolveFunctionName = (fnId) => {
    if (!fnId) return '';
    const f = funcs.find(fn => fn && fn.id === fnId);
    return (f && f.name) || fnId;
  };

  if (hasConfigDevices) {
    cfgDevices.forEach(cfgDev => {
      if (!cfgDev || !cfgDev.id) return;
      const type = cfgDev.type || 'switch';
      const roomId = cfgDev.roomId || '';
      const floorId = roomId
        ? resolveRoomFloorId(roomId)
        : String((Object.prototype.hasOwnProperty.call(cfgDev, 'floorId') ? cfgDev.floorId : '') || '').trim();
      const floorName = resolveFloorName(floorId);
      const roomName = roomId ? resolveRoomName(roomId) : (floorName || 'Allgemein');
      const fnName = resolveFunctionName(cfgDev.functionId);
      const behavior = cfgDev.behavior || {};
      const ioCfg = cfgDev.io || {};
      const size = cfgDev.size || 'm';
      const order = (typeof cfgDev.order === 'number') ? cfgDev.order : undefined;

      const dev = {
        id: cfgDev.id,
        type,
        ...(typeof order === 'number' ? { order } : {}),
        // Keep stable IDs for filtering / navigation presets
        roomId,
        floorId,
        functionId: cfgDev.functionId || '',
        room: roomName,
        function: fnName,
        alias: cfgDev.alias || cfgDev.id,
        icon: cfgDev.icon || '',
        ui: {
          size,
          showRoom: true,
          showValue: true,
          ...(cfgDev.ui && typeof cfgDev.ui.color === 'string' ? { color: cfgDev.ui.color } : {}),
          ...(typeof order === 'number' ? { order } : {}),
          unit: (cfgDev.ui && cfgDev.ui.unit) || cfgDev.unit || '',
          precision: (cfgDev.ui && typeof cfgDev.ui.precision === 'number')
            ? cfgDev.ui.precision
            : (typeof cfgDev.precision === 'number' ? cfgDev.precision : undefined),
        },
        templateId: cfgDev.templateId || undefined,
        capabilities: this._nwIsPlainObject(cfgDev.capabilities) ? { ...cfgDev.capabilities } : {},
        behavior: {
          readOnly: !!behavior.readOnly,
          favorite: !!behavior.favorite,
          invert: !!behavior.invert,
          commandMode: ['toggle', 'set', 'momentary'].includes(String(behavior.commandMode || '').toLowerCase())
            ? String(behavior.commandMode).toLowerCase()
            : 'toggle',
          pulseMs: Number.isFinite(Number(behavior.pulseMs)) ? Math.max(50, Math.min(60000, Number(behavior.pulseMs))) : 250,
          staleAfterSec: Number.isFinite(Number(behavior.staleAfterSec)) ? Math.max(0, Math.min(604800, Number(behavior.staleAfterSec))) : 0,
        },
        io: {},
      };

      if (type === 'switch' || type === 'scene') {
        const sw = ioCfg.switch || {};
        const readId = sw.readId || sw.writeId || '';
        const writeId = sw.writeId || sw.readId || '';
        if (readId || writeId) dev.io.switch = { readId, writeId };
      } else if (type === 'color') {
        const sw = ioCfg.switch || {};
        const lvl = ioCfg.level || {};
        const col = ioCfg.color || {};
        const white = ioCfg.white || {};
        const ct = ioCfg.colorTemperature || {};
        if (sw.readId || sw.writeId) dev.io.switch = { readId: sw.readId || sw.writeId || '', writeId: sw.writeId || sw.readId || '' };
        if (lvl.readId || lvl.writeId) {
          dev.io.level = {
            readId: lvl.readId || lvl.writeId || '',
            writeId: lvl.writeId || lvl.readId || '',
            min: typeof lvl.min === 'number' ? lvl.min : 0,
            max: typeof lvl.max === 'number' ? lvl.max : 100,
            step: typeof lvl.step === 'number' ? lvl.step : 1,
          };
        }
        if (col.readId || col.writeId) {
          dev.io.color = { readId: col.readId || col.writeId || '', writeId: col.writeId || col.readId || '', format: col.format || 'hex' };
        }
        if (white.readId || white.writeId) {
          dev.io.white = {
            readId: white.readId || white.writeId || '', writeId: white.writeId || white.readId || '',
            min: typeof white.min === 'number' ? white.min : 0,
            max: typeof white.max === 'number' ? white.max : 100,
            step: typeof white.step === 'number' ? white.step : 1,
          };
        }
        if (ct.readId || ct.writeId) {
          dev.io.colorTemperature = {
            readId: ct.readId || ct.writeId || '', writeId: ct.writeId || ct.readId || '',
            min: typeof ct.min === 'number' ? ct.min : 2000,
            max: typeof ct.max === 'number' ? ct.max : 6500,
            step: typeof ct.step === 'number' ? ct.step : 100,
          };
        }
      } else if (type === 'dimmer') {
        const sw = ioCfg.switch || {};
        const lvl = ioCfg.level || {};
        const ct = ioCfg.colorTemperature || {};
        if (sw.readId || sw.writeId) dev.io.switch = { readId: sw.readId || sw.writeId || '', writeId: sw.writeId || sw.readId || '' };
        if (lvl.readId || lvl.writeId) {
          dev.io.level = {
            readId: lvl.readId || lvl.writeId || '', writeId: lvl.writeId || lvl.readId || '',
            min: typeof lvl.min === 'number' ? lvl.min : 0,
            max: typeof lvl.max === 'number' ? lvl.max : 100,
            step: typeof lvl.step === 'number' ? lvl.step : 1,
          };
        }
        if (ct.readId || ct.writeId) {
          dev.io.colorTemperature = {
            readId: ct.readId || ct.writeId || '', writeId: ct.writeId || ct.readId || '',
            min: typeof ct.min === 'number' ? ct.min : 2000,
            max: typeof ct.max === 'number' ? ct.max : 6500,
            step: typeof ct.step === 'number' ? ct.step : 100,
          };
        }
      } else if (type === 'blind') {
        const lvl = ioCfg.level || {};
        const cover = ioCfg.cover || {};
        if (lvl.readId || lvl.writeId) {
          dev.io.level = { readId: lvl.readId || lvl.writeId || '', writeId: lvl.writeId || lvl.readId || '', min: 0, max: 100, step: typeof lvl.step === 'number' ? lvl.step : 1 };
        }
        dev.io.cover = {
          positionId: cover.positionId || lvl.readId || lvl.writeId || '',
          positionWriteId: cover.positionWriteId || lvl.writeId || cover.positionId || lvl.readId || '',
          upId: cover.upId || '', downId: cover.downId || '', stopId: cover.stopId || '',
          tiltReadId: cover.tiltReadId || '', tiltWriteId: cover.tiltWriteId || cover.tiltReadId || '',
          movingId: cover.movingId || '', directionId: cover.directionId || '', lockId: cover.lockId || '',
          windAlarmId: cover.windAlarmId || '', rainAlarmId: cover.rainAlarmId || '', frostAlarmId: cover.frostAlarmId || '',
          actionId: cover.actionId || '', actionMap: this._nwIsPlainObject(cover.actionMap) ? { ...cover.actionMap } : undefined,
        };
      } else if (type === 'rtr') {
        const climate = ioCfg.climate || {};
        dev.io.climate = {
          currentTempId: climate.currentTempId || '', setpointId: climate.setpointId || '', modeId: climate.modeId || '', humidityId: climate.humidityId || '',
          powerId: climate.powerId || '', fanSpeedId: climate.fanSpeedId || '', swingId: climate.swingId || '', demandId: climate.demandId || '',
          windowId: climate.windowId || '', errorId: climate.errorId || '',
          minSetpoint: typeof climate.minSetpoint === 'number' ? climate.minSetpoint : 15,
          maxSetpoint: typeof climate.maxSetpoint === 'number' ? climate.maxSetpoint : 30,
          step: typeof climate.step === 'number' ? climate.step : 0.5,
        };
        if (!dev.ui.unit) dev.ui.unit = '°C';
        if (typeof dev.ui.precision !== 'number') dev.ui.precision = 1;
      } else if (type === 'player') {
        const player = ioCfg.player || {};
        dev.io.player = {
          playingId: player.playingId || '', titleId: player.titleId || '', artistId: player.artistId || '', sourceId: player.sourceId || '', coverId: player.coverId || '',
          volumeReadId: player.volumeReadId || '', volumeWriteId: player.volumeWriteId || player.volumeReadId || '',
          volumeMin: typeof player.volumeMin === 'number' ? player.volumeMin : 0, volumeMax: typeof player.volumeMax === 'number' ? player.volumeMax : 100,
          toggleId: player.toggleId || '', playId: player.playId || '', pauseId: player.pauseId || '', stopId: player.stopId || '', nextId: player.nextId || '', prevId: player.prevId || '',
          stationId: player.stationId || '', playlistId: player.playlistId || '',
          muteReadId: player.muteReadId || '', muteWriteId: player.muteWriteId || player.muteReadId || '',
          powerReadId: player.powerReadId || '', powerWriteId: player.powerWriteId || player.powerReadId || '',
          seekReadId: player.seekReadId || '', seekWriteId: player.seekWriteId || player.seekReadId || '',
          seekMin: typeof player.seekMin === 'number' ? player.seekMin : 0,
          seekMax: typeof player.seekMax === 'number' ? player.seekMax : 100,
          seekStep: typeof player.seekStep === 'number' ? player.seekStep : 1,
          shuffleId: player.shuffleId || '', repeatId: player.repeatId || '', ttsWriteId: player.ttsWriteId || '',
        };
        if (Array.isArray(cfgDev.stations)) dev.stations = cfgDev.stations.map((row) => ({ name: row && typeof row.name === 'string' ? row.name : '', value: row && Object.prototype.hasOwnProperty.call(row, 'value') ? row.value : '' })).filter((row) => row.name || String(row.value || '').trim());
        if (Array.isArray(cfgDev.playlists)) dev.playlists = cfgDev.playlists.map((row) => ({ name: row && typeof row.name === 'string' ? row.name : '', value: row && Object.prototype.hasOwnProperty.call(row, 'value') ? row.value : '' })).filter((row) => row.name || String(row.value || '').trim());
      } else if (type === 'sensor') {
        const sensor = ioCfg.sensor || {};
        dev.io.sensor = {
          readId: sensor.readId || '', writeId: sensor.writeId || '', valueType: sensor.valueType || 'number',
          min: typeof sensor.min === 'number' ? sensor.min : -1000000000,
          max: typeof sensor.max === 'number' ? sensor.max : 1000000000,
          step: typeof sensor.step === 'number' ? sensor.step : 1,
        };
      } else if (type === 'camera') {
        const cam = ioCfg.camera || {};
        dev.io.camera = { snapshotUrl: typeof cam.snapshotUrl === 'string' ? cam.snapshotUrl : '', liveUrl: typeof cam.liveUrl === 'string' ? cam.liveUrl : '', refreshMs: typeof cam.refreshMs === 'number' ? cam.refreshMs : 5000 };
        if (typeof cam.urlStateId === 'string' && cam.urlStateId.trim()) dev.io.camera.urlStateId = cam.urlStateId.trim();
      } else if (type === 'widget') {
        const w = ioCfg.widget || {};
        dev.io.widget = { kind: typeof w.kind === 'string' && w.kind.trim() ? w.kind.trim() : 'iframe', url: typeof w.url === 'string' ? w.url : '', openUrl: typeof w.openUrl === 'string' ? w.openUrl : '', embed: !!w.embed, height: typeof w.height === 'number' ? w.height : 260, label: typeof w.label === 'string' ? w.label : '' };
      }

      if (this._nwIsPlainObject(ioCfg.indicators)) dev.io.indicators = { ...ioCfg.indicators };
      if (ioCfg.deviceControls) {
        dev.io.deviceControls = normalizeDeviceControls(ioCfg.deviceControls);
        nwRetainDeclaredLegacyWrites(ioCfg, dev.io);
      }
      if (cfgDev.customView) dev.customView = normalizeCustomView(cfgDev.customView);
      devices.push(dev);
    });

    // --- SmartHome Scenes (virtual devices) ---
    // Scenes are configured in SmartHomeConfig.scenes and are executed by the adapter.
    // They appear as type "scene" tiles without a switch datapoint.
    if (Array.isArray(cfgScenes) && cfgScenes.length) {
      for (const sc of cfgScenes) {
        if (!sc || !sc.id) continue;

        const rawId = String(sc.id).trim();
        if (!rawId) continue;
        // Ensure unique device IDs (avoid collision with real devices)
        const id = devices.some((d) => d && d.id === rawId) ? `scene_${rawId}` : rawId;

        const roomId = String(sc.roomId || '').trim();
        const floorId = roomId
          ? resolveRoomFloorId(roomId)
          : String((Object.prototype.hasOwnProperty.call(sc, 'floorId') ? sc.floorId : '') || '').trim();

        const floorName = resolveFloorName(floorId);
        const roomName = roomId ? resolveRoomName(roomId) : (floorName || 'Allgemein');
        const fnName = resolveFunctionName(String(sc.functionId || '').trim());
        const size = (sc.ui && sc.ui.size) ? String(sc.ui.size).trim() : (String(sc.size || '').trim() || 'm');
        const order = (typeof sc.order === 'number') ? sc.order : undefined;

        const dev = {
          id,
          type: 'scene',
          ...(typeof order === 'number' ? { order } : {}),
          roomId,
          floorId,
          functionId: String(sc.functionId || '').trim(),
          room: roomName,
          function: fnName,
          alias: String(sc.alias || sc.name || sc.title || sc.id).trim() || rawId,
          icon: String(sc.icon || '').trim(),
          ui: {
