        const order = (typeof sc.order === 'number') ? sc.order : undefined;

        devices.push({
          id,
          type: 'scene',
          ...(typeof order === 'number' ? { order } : {}),
          roomId,
          floorId,
          functionId: String(sc.functionId || '').trim(),
          room: roomName,
          function: fnName,
          alias: String(sc.alias || sc.name || sc.title || sc.id).trim() || rawId,
          icon: String(sc.icon || '').trim(),
          ui: {
            size,
            showRoom: true,
            showValue: true,
            unit: '',
            ...(typeof order === 'number' ? { order } : {}),
          },
          behavior: {
            readOnly: false,
            favorite: !!(sc.behavior && sc.behavior.favorite),
          },
          sceneId: rawId,
          io: {},
        });
      }
    }
  } catch (_e) {}

  pushScene(dps.scene2, {
    id: 'scene2',
    alias: 'Szene Alles aus',
    room: 'Wohnen',
    func: 'Szene',
    icon: 'S2',
  });

  pushScene(dps.scene3, {
    id: 'scene3',
    alias: 'Szene 3',
    room: 'Wohnen',
    func: 'Szene',
    icon: 'S3',
  });

  pushScene(dps.scene4, {
    id: 'scene4',
    alias: 'Szene 4',
    room: 'Wohnen',
    func: 'Szene',
    icon: 'S4',
  });

  this.smartHomeDevices = devices;
  return this.smartHomeDevices;
}

/**
 * Code-Teil: getSmartHomeDevicesWithState
 * Zweck: Liest einen Wert aus Cache, Konfiguration, DOM oder ioBroker-State mit passenden Fallbacks.
 * Zusammenhang: Gehört zu ioBroker-Adapterkern (Adapter-Lifecycle, Webserver, REST-/SSE-API, State-Anlage, Lizenz und EMS-Engine) und wird von benachbarten UI-/API-/EMS-Bausteinen genutzt.
 * Wartung/TypeScript: Änderungen können Gebäudestruktur, Kachelbedienung und Popover-Verhalten beeinflussen. Beim TS-Umbau Parameter, Rückgabe und genutzte State-/Config-Objekte explizit typisieren.
 */
async getSmartHomeDevicesWithState() {
  const devices = (this.smartHomeDevices && this.smartHomeDevices.length)
    ? this.smartHomeDevices
    : this.buildSmartHomeDevicesFromConfig();

  const timersCfg = (typeof this.getSmartHomeTimersConfig === 'function')
    ? this.getSmartHomeTimersConfig()
    : (this._nwShTimersCfg || { version: 1, updatedAt: 0, timers: [] });
  const timersArr = (timersCfg && Array.isArray(timersCfg.timers)) ? timersCfg.timers : [];
  const timerByDev = Object.create(null);
  for (const timer of timersArr) {
    if (timer && timer.deviceId) timerByDev[String(timer.deviceId)] = timer;
  }
  const nextByDev = this._nwShTimersNextByDeviceId || Object.create(null);

  const toNumberStrict = (value) => {
    if (value === null || value === undefined || value === '') return undefined;
    if (typeof value === 'number') return Number.isFinite(value) ? value : undefined;
    if (typeof value === 'string') {
      const normalized = value.trim().replace(',', '.');
      if (!normalized) return undefined;
      const parsed = Number(normalized);
      return Number.isFinite(parsed) ? parsed : undefined;
    }
    return undefined;
  };
  const toBooleanStrict = (value) => {
    if (typeof value === 'boolean') return value;
    if (typeof value === 'number' && Number.isFinite(value)) {
      if (value === 0) return false;
      if (value === 1) return true;
      return value > 0;
    }
    if (typeof value === 'string') {
      const normalized = value.trim().toLowerCase();
      if (['true', '1', 'on', 'yes', 'ja', 'active', 'open', 'playing', 'play'].includes(normalized)) return true;
      if (['false', '0', 'off', 'no', 'nein', 'inactive', 'closed', 'pause', 'paused', 'stop', 'stopped'].includes(normalized)) return false;
    }
    return undefined;
  };
  const toStringStrict = (value) => {
    if (value === null || value === undefined) return undefined;
    if (typeof value === 'string') return value;
    if (typeof value === 'number' || typeof value === 'boolean') return String(value);
    return undefined;
  };
  const colorToHex = (value, format) => {
    if (value === null || value === undefined) return undefined;
    const clamp = (v) => Math.max(0, Math.min(255, Math.round(Number(v))));
    const hex2 = (v) => clamp(v).toString(16).padStart(2, '0');
    const fmt = String(format || 'hex').trim().toLowerCase();
    if ((fmt === 'int' || fmt === 'integer' || fmt === 'number') && Number.isFinite(Number(value))) {
      return '#' + Math.max(0, Math.min(16777215, Math.round(Number(value)))).toString(16).padStart(6, '0');
    }
    if (typeof value === 'number' && Number.isFinite(value)) {
      return '#' + Math.max(0, Math.min(16777215, Math.round(value))).toString(16).padStart(6, '0');
    }
    let text = String(value).trim();
    const rgbMatch = text.match(/(\d{1,3})\s*[,; ]\s*(\d{1,3})\s*[,; ]\s*(\d{1,3})/);
    if (fmt === 'rgb' || rgbMatch) {
      if (!rgbMatch) return undefined;
      return ('#' + hex2(rgbMatch[1]) + hex2(rgbMatch[2]) + hex2(rgbMatch[3])).toLowerCase();
    }
    if (/^0x/i.test(text)) text = text.slice(2);
    if (text.startsWith('#')) text = text.slice(1);
    if (/^[0-9a-f]{6}$/i.test(text)) return ('#' + text).toLowerCase();
    if (/^\d+$/.test(text)) {
      const parsed = Number(text);
      if (Number.isFinite(parsed)) return '#' + Math.max(0, Math.min(16777215, Math.round(parsed))).toString(16).padStart(6, '0');
    }
    return undefined;
  };

  const result = [];
  const deviceSnapshotReader = createDeviceSnapshotReader({
    readObject: id => this.getForeignObjectAsync(id),
    readState: id => this.getForeignStateAsync(id),
  });
  for (const dev of devices) {
    const copy = JSON.parse(JSON.stringify(dev));
    copy.state = {};
    copy.fieldQuality = {};
    const behavior = copy.behavior || {};
    const staleAfterMs = Math.max(0, Number(behavior.staleAfterSec || 0)) * 1000;
    const qualityRows = [];
    let configuredReads = 0;

    const readField = async (field, id, parser, affectsQuality = true) => {
      const dpId = String(id || '').trim();
      if (!dpId) {
        copy.fieldQuality[field] = { configured: false, valid: false, status: 'not-configured', reason: 'Kein Lese-Datenpunkt zugeordnet' };
        return undefined;
      }
      if (affectsQuality) configuredReads += 1;
      try {
        const rawState = await this.getForeignStateAsync(dpId);
        const hasState = !!rawState && Object.prototype.hasOwnProperty.call(rawState, 'val');
        const present = hasState && rawState.val !== null && rawState.val !== undefined && !(typeof rawState.val === 'number' && !Number.isFinite(rawState.val));
        const q = rawState && Number.isFinite(Number(rawState.q)) ? Number(rawState.q) : 0;
        const ts = rawState && Number.isFinite(Number(rawState.ts)) ? Number(rawState.ts) : (rawState && Number.isFinite(Number(rawState.lc)) ? Number(rawState.lc) : 0);
        const ageMs = ts > 0 ? Math.max(0, Date.now() - ts) : null;
        const stale = staleAfterMs > 0 && ageMs !== null && ageMs > staleAfterMs;
        const qualityOk = q === 0;
        let parsed;
        if (present && qualityOk && !stale) parsed = parser(rawState.val);
        const parseOk = parsed !== undefined && parsed !== null && !(typeof parsed === 'number' && !Number.isFinite(parsed));
        const valid = present && qualityOk && !stale && parseOk;
        const status = !hasState || !present
          ? 'unknown'
          : (!qualityOk ? 'error' : (stale ? 'stale' : (parseOk ? 'online' : 'invalid')));
        const reason = !hasState || !present
          ? 'Kein gültiger State-Wert vorhanden'
          : (!qualityOk ? `Datenpunkt-Qualität q=${q}` : (stale ? 'State ist veraltet' : (parseOk ? 'OK' : 'Wertformat ungültig')));
        const row = { configured: true, id: dpId, valid, status, reason, q, ts, ageMs };
        copy.fieldQuality[field] = row;
        if (affectsQuality) qualityRows.push(row);
        return valid ? parsed : undefined;
      } catch (error) {
        const row = { configured: true, id: dpId, valid: false, status: 'offline', reason: error && error.message ? error.message : 'State nicht erreichbar' };
        copy.fieldQuality[field] = row;
        if (affectsQuality) qualityRows.push(row);
        return undefined;
      }
    };

    const io = copy.io || {};
    if (io.switch && io.switch.readId) {
      const value = await readField('on', io.switch.readId, toBooleanStrict);
      if (typeof value === 'boolean') copy.state.on = behavior.invert ? !value : value;
    }
    if (io.level && io.level.readId) {
      const value = await readField('level', io.level.readId, toNumberStrict);
      if (typeof value === 'number') {
        const min = typeof io.level.min === 'number' ? io.level.min : 0;
        const max = typeof io.level.max === 'number' ? io.level.max : 100;
        const normalized = Math.max(Math.min(min, max), Math.min(Math.max(min, max), value));
        copy.state.level = normalized;
        if (copy.type === 'blind') copy.state.position = Math.max(0, Math.min(100, normalized));
        if ((copy.type === 'dimmer' || copy.type === 'color') && typeof copy.state.on !== 'boolean') copy.state.on = normalized > min;
      }
    }
    if (io.color && io.color.readId) {
      const value = await readField('color', io.color.readId, (raw) => colorToHex(raw, io.color.format));
      if (typeof value === 'string') copy.state.color = value;
    }
    if (io.white && io.white.readId) {
      const value = await readField('white', io.white.readId, toNumberStrict);
      if (typeof value === 'number') copy.state.white = value;
    }
    if (io.colorTemperature && io.colorTemperature.readId) {
      const value = await readField('colorTemperature', io.colorTemperature.readId, toNumberStrict);
      if (typeof value === 'number') copy.state.colorTemperature = value;
    }

    if (io.cover) {
      const coverReads = [
        ['tilt', io.cover.tiltReadId, toNumberStrict],
        ['moving', io.cover.movingId, toBooleanStrict],
        ['direction', io.cover.directionId, toStringStrict],
        ['locked', io.cover.lockId, toBooleanStrict],
        ['windAlarm', io.cover.windAlarmId, toBooleanStrict],
        ['rainAlarm', io.cover.rainAlarmId, toBooleanStrict],
        ['frostAlarm', io.cover.frostAlarmId, toBooleanStrict],
      ];
      for (const [field, id, parser] of coverReads) {
        if (!id) continue;
        const value = await readField(field, id, parser);
        if (value !== undefined) copy.state[field] = value;
      }
    }

    if (io.climate) {
      const climateReads = [
        ['currentTemp', io.climate.currentTempId, toNumberStrict],
        ['setpoint', io.climate.setpointId, toNumberStrict],
        ['mode', io.climate.modeId, toStringStrict],
        ['humidity', io.climate.humidityId, toNumberStrict],
        ['power', io.climate.powerId, toBooleanStrict],
        ['fanSpeed', io.climate.fanSpeedId, (raw) => toNumberStrict(raw) ?? toStringStrict(raw)],
        ['swing', io.climate.swingId, (raw) => toBooleanStrict(raw) ?? toStringStrict(raw)],
        ['demand', io.climate.demandId, (raw) => toNumberStrict(raw) ?? toBooleanStrict(raw) ?? toStringStrict(raw)],
        ['windowOpen', io.climate.windowId, toBooleanStrict],
        ['climateError', io.climate.errorId, (raw) => toBooleanStrict(raw) ?? toStringStrict(raw)],
      ];
      for (const [field, id, parser] of climateReads) {
        if (!id) continue;
        const value = await readField(field, id, parser);
        if (value !== undefined) copy.state[field] = value;
      }
    }

    if (io.player) {
      const playerReads = [
        ['playing', io.player.playingId, toBooleanStrict],
        ['title', io.player.titleId, toStringStrict],
        ['artist', io.player.artistId, toStringStrict],
        ['source', io.player.sourceId, toStringStrict],
        ['cover', io.player.coverId, toStringStrict],
        ['volume', io.player.volumeReadId, toNumberStrict],
        ['muted', io.player.muteReadId, toBooleanStrict],
        ['power', io.player.powerReadId, toBooleanStrict],
        ['seek', io.player.seekReadId, toNumberStrict],
        ['shuffle', io.player.shuffleId, (raw) => toBooleanStrict(raw) ?? toNumberStrict(raw) ?? toStringStrict(raw)],
        ['repeat', io.player.repeatId, (raw) => toBooleanStrict(raw) ?? toNumberStrict(raw) ?? toStringStrict(raw)],
      ];
      for (const [field, id, parser] of playerReads) {
        if (!id) continue;
        const value = await readField(field, id, parser);
        if (value !== undefined) copy.state[field] = value;
      }
      if (typeof copy.state.playing === 'boolean') copy.state.on = copy.state.playing;
      else if (typeof copy.state.power === 'boolean') copy.state.on = copy.state.power;
    }

    if (io.sensor && io.sensor.readId) {
      const valueType = String(io.sensor.valueType || 'number').toLowerCase();
      const parser = valueType === 'boolean'
        ? toBooleanStrict
        : (valueType === 'string' ? toStringStrict : toNumberStrict);
      const value = await readField('value', io.sensor.readId, parser);
      if (value !== undefined) copy.state.value = value;
      if (!copy.ui.unit) {
        try {
          const object = await this.getForeignObjectAsync(io.sensor.readId);
          const unit = object && object.common && object.common.unit !== null && object.common.unit !== undefined ? String(object.common.unit).trim() : '';
          if (unit) copy.ui.unit = unit;
        } catch (_error) {}
      }
    }

    // Statuspunkte sind rein lesend. Ein fehlender Batteriepunkt darf die
    // eigentliche Gerätebedienung nicht als offline markieren; reale UNREACH-
    // und ERROR-Signale übersteuern dagegen den zusammengefassten Status.
    if (io.indicators) {
      const ind = io.indicators;
      if (ind.batteryId) {
        const unit = ind.batteryUnit === 'low' ? 'low' : '%';
        const value = await readField('battery', ind.batteryId, unit === 'low'
          ? (raw) => typeof raw === 'boolean' ? raw : undefined
          : (raw) => typeof raw === 'number' && Number.isFinite(raw) && raw >= 0 && raw <= 100 ? raw : undefined, false);
        if (value !== undefined) { copy.state.battery = value; copy.state.batteryUnit = unit; }
      }
      if (ind.unreachableId) {
        const value = await readField('unreachable', ind.unreachableId, (raw) => typeof raw === 'boolean' ? raw : undefined, false);
        if (typeof value === 'boolean') copy.state.unreachable = value;
      }
      if (ind.errorId) {
        const value = await readField('deviceError', ind.errorId, (raw) => {
          if (typeof raw === 'boolean') return raw;
          if (typeof raw === 'number' && Number.isFinite(raw)) return raw;
          if (typeof raw !== 'string') return undefined;
          const text = raw.trim().slice(0, 160);
          return ['', '0', 'false', 'ok', 'none', 'no error', 'kein fehler'].includes(text.toLowerCase()) ? false : text;
        }, false);
        if (value !== undefined) copy.state.deviceError = value;
      }
    }
    if (copy.type === 'camera' && io.camera && io.camera.urlStateId) {
      const url = await readField('cameraUrl', io.camera.urlStateId, normalizeSmartHomeCameraStateUrl);
      // Dynamische Quellen verwenden niemals einen alten URL-Schnappschuss als
      // frischen Wert. Bestehende Kameras ohne urlStateId bleiben unverändert.
      copy.io.camera.snapshotUrl = url || '';
      copy.io.camera.liveUrl = url || '';
    }

    if (copy.type === 'scene' && typeof copy.state.on === 'boolean') copy.state.active = copy.state.on;

    let qualityStatus = 'ready';
    let qualityReason = 'Kein Lese-Datenpunkt erforderlich';
    if (configuredReads > 0) {
      const offline = qualityRows.find((row) => row.status === 'offline');
      const error = qualityRows.find((row) => row.status === 'error');
      const stale = qualityRows.find((row) => row.status === 'stale');
      const invalid = qualityRows.find((row) => row.status === 'invalid');
      const online = qualityRows.filter((row) => row.valid);
      if (offline) { qualityStatus = 'offline'; qualityReason = offline.reason; }
      else if (error) { qualityStatus = 'error'; qualityReason = error.reason; }
      else if (stale) { qualityStatus = 'stale'; qualityReason = stale.reason; }
      else if (online.length > 0) { qualityStatus = 'online'; qualityReason = 'Alle verfügbaren Zustände gültig'; }
      else if (invalid) { qualityStatus = 'invalid'; qualityReason = invalid.reason; }
      else { qualityStatus = 'unknown'; qualityReason = 'Noch kein gültiger Zustand verfügbar'; }
    }
    if (copy.state.unreachable === true) {
      qualityStatus = 'offline'; qualityReason = 'Gerät meldet nicht erreichbar';
    } else if (copy.state.deviceError === true || (typeof copy.state.deviceError === 'number' && copy.state.deviceError !== 0)
      || (typeof copy.state.deviceError === 'string' && copy.state.deviceError.length > 0)) {
      qualityStatus = 'error'; qualityReason = 'Gerät meldet eine Störung';
    }
    copy.quality = {
      status: qualityStatus,
      reason: qualityReason,
      valid: qualityStatus === 'online' || qualityStatus === 'ready',
      online: qualityStatus === 'online' || qualityStatus === 'ready',
      stale: qualityStatus === 'stale',
      error: qualityStatus === 'error' || qualityStatus === 'offline' || qualityStatus === 'invalid',
      configuredReads,
      validReads: qualityRows.filter((row) => row.valid).length,
    };
    copy.state.error = copy.quality.error;

    try {
      const timer = timerByDev[copy.id];
      if (timer) {
        const next = nextByDev[copy.id];
        copy.timer = {
          enabled: !!timer.enabled,
          days: Array.isArray(timer.days) ? timer.days : [],
          onTime: String(timer.onTime || ''),
          offTime: String(timer.offTime || ''),
          ...(typeof timer.onLevel === 'number' ? { onLevel: timer.onLevel } : {}),
          ...(next && typeof next.at === 'number' ? { nextAt: next.at, nextKind: next.kind } : {}),
        };
      }
    } catch (_error) {}

    if (dev.io && dev.io.deviceControls) {
      try {
        copy.deviceControls = await buildDeviceControls(dev.io.deviceControls, deviceSnapshotReader, behavior.readOnly === true, { staleAfterMs });
      } catch (_deviceControlsError) {
        copy.deviceControls = { profile: dev.io.deviceControls.profile, fields: [], error: 'EOS_CONTROL_SNAPSHOT_UNAVAILABLE' };
      }
    }
    result.push(copy);
  }
  return result;
}

/**
 * Code-Teil: migrateNativeConfig
 * Zweck: Kapselt einen klar abgegrenzten Verarbeitungsschritt innerhalb dieser Datei.
 * Zusammenhang: Gehört zu ioBroker-Adapterkern (Adapter-Lifecycle, Webserver, REST-/SSE-API, State-Anlage, Lizenz und EMS-Engine) und wird von benachbarten UI-/API-/EMS-Bausteinen genutzt.
 * Wartung/TypeScript: Änderungen können Adapterstart, APIs, States und Webserver beeinflussen; unload/connection immer mittesten. Beim TS-Umbau Parameter, Rückgabe und genutzte State-/Config-Objekte explizit typisieren.
 */
async migrateNativeConfig() {
    // IMPORTANT:
    // We ONLY normalize values in-memory for the current runtime.
    // Writing back into system.adapter.<instance>.native triggers an ioBroker restart
    // and breaks the VIS/App‑Center UX ("Failed to fetch" + SSE disconnect).
    try {
      this.config = this.config || {};
      const nat = this.config;

      // ioBroker convention: use native.ip for network binding.
      // Older NexoWatt versions used native.bind; keep it as a legacy fallback
      // but migrate the runtime config so JSONConfig/Admin can use ip going forward.
      if (!nat.ip && nat.bind) nat.ip = nat.bind;
      if (!nat.ip) nat.ip = '0.0.0.0';
      if (!nat.bind) nat.bind = nat.ip;

      let changed = false;
      /**
       * Code-Teil: ensureObject
       * Zweck: Kapselt einen lokalen Verarbeitungsschritt, damit Aufrufer nicht direkt in Detaildaten eingreifen.
       * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
       * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
       */
      const ensureObject = (key) => {
        const v = nat[key];
        if (!v || typeof v !== 'object' || Array.isArray(v)) {
          nat[key] = {};
          changed = true;
        }
      };
      /**
       * Code-Teil: setNumber
       * Zweck: Setzt Werte im DOM, Cache, State oder in der Konfiguration.
       * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
       * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
       */
      const setNumber = (path, def) => {
        const parts = String(path).split('.');
        if (!parts.length) return;
        let cur = nat;
        for (let i = 0; i < parts.length - 1; i++) {
          const p = parts[i];
          if (!cur[p] || typeof cur[p] !== 'object' || Array.isArray(cur[p])) {
            cur[p] = {};
            changed = true;
          }
          cur = cur[p];
        }
        const last = parts[parts.length - 1];
        const raw = cur[last];

        // Normalize to number (JSONConfig number fields behave poorly with "" / strings in some Admin versions)
        let n;
        if (raw === '' || raw === null || raw === undefined) {
          n = Number(def);
        } else if (typeof raw === 'number') {
          n = raw;
        } else {
          n = Number(raw);
          if (!Number.isFinite(n)) n = Number(def);
        }

        if (!Number.isFinite(n)) n = Number(def);

        // Only write if different type/value to avoid unnecessary object writes
        if (cur[last] !== n) {
          cur[last] = n;
          changed = true;
        }
      };
      /**
       * Code-Teil: setBoolean
       * Zweck: Setzt Werte im DOM, Cache, State oder in der Konfiguration.
       * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
       * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
       */
      const setBoolean = (path, def) => {
        const parts = String(path).split('.');
        let cur = nat;
        for (let i = 0; i < parts.length - 1; i++) {
          const p = parts[i];
          if (!cur[p] || typeof cur[p] !== 'object' || Array.isArray(cur[p])) {
            cur[p] = {};
            changed = true;
          }
          cur = cur[p];
        }
        const last = parts[parts.length - 1];
        const raw = cur[last];
        const b = (raw === undefined || raw === null) ? !!def : !!raw;
        if (cur[last] !== b) {
          cur[last] = b;
          changed = true;
        }
      };

      // Ensure sub-objects exist (avoid "null" breaking JSONConfig bindings)
      ensureObject('peakShaving');
      ensureObject('storageFarm');
      ensureObject('storage');
      ensureObject('chargingManagement');

      // Peak Shaving (EMS – Peak Shaving)
      setNumber('peakShaving.maxPowerW', 0);
      setNumber('peakShaving.reserveW', 0);
      setNumber('peakShaving.safetyMarginW', 0);
      setNumber('peakShaving.smoothingSeconds', 10);
      setNumber('peakShaving.hysteresisW', 500);
      setNumber('peakShaving.activateDelaySeconds', 2);
      setNumber('peakShaving.releaseDelaySeconds', 5);

      // Farm update interval
      setNumber('storageFarm.schedulerIntervalMs', 1000);

      // Global scheduler tick
      setNumber('schedulerIntervalMs', 1000);

      // Charging Management defaults
      setNumber('chargingManagement.pvChargeReserveW', 500);
      setNumber('chargingManagement.pvStartSettleSec', 20);
      // OCPP ist push-/ereignisbasiert. Diese beiden Zeitfenster gelten nur
      // für OCPP-Ladepunkte und verlangsamen den globalen EMS-Regelzyklus nicht.
      setNumber('chargingManagement.ocppStartResponseTimeoutSec', 75);
      setNumber('chargingManagement.ocppStartSettleSec', 60);
      setNumber('chargingManagement.pvStartStableSec', 10);
      setNumber('chargingManagement.pvConnectorStopDelaySec', 45);
      setNumber('chargingManagement.pvMinRunSec', 45);
      setNumber('chargingManagement.pvRunDeficitToleranceW', 600);
      setNumber('chargingManagement.pvRampUpAperTick', 0.5);
      setNumber('chargingManagement.pvRampUpWPerTick', 350);

      // Storage reserve defaults (avoid NaN/blank blocking Admin save)
      setBoolean('storage.reserveEnabled', false);
      setNumber('storage.reserveMinSocPct', 20);
      setNumber('storage.reserveTargetSocPct', 25);
      setNumber('storage.reserveGridChargeW', 0);

      if (changed) {
        this.log.info('Config normalized for runtime (numeric/boolean native values).');
      }
    } catch (e) {
      this.log.warn('Config migration failed: ' + (e && e.message ? e.message : e));
    }
}

  /**
   * Remove stale/orphaned objects that were created dynamically in older configurations
   * (e.g. Verbraucher/Erzeuger history channels that are no longer mapped).
   *
   * Important safety rules:
   * - We ONLY delete objects inside this adapter namespace.
   * - We only delete well-known dynamic branches where the desired existence is
   *   unambiguously derived from the current config.
   */
  /**
   * Code-Teil: cleanupOrphanedObjects
   * Zweck: Kapselt einen lokalen Verarbeitungsschritt, damit Aufrufer nicht direkt in Detaildaten eingreifen.
   * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
   * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
   */
  async cleanupOrphanedObjects() {
    try {
      // Keep in sync with ems/modules/charging-management.js (toSafeIdPart)
      /**
       * Code-Teil: toSafeIdPart
       * Zweck: Kapselt einen lokalen Verarbeitungsschritt, damit Aufrufer nicht direkt in Detaildaten eingreifen.
       * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
       * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
       */
      const toSafeIdPart = (input) => {
        const s = String(input || '').trim();
        if (!s) return '';
        return s.toLowerCase().replace(/[^a-z0-9_]+/g, '_').replace(/^_+|_+$/g, '').slice(0, 64);
      };

      const dps = (this.config && this.config.datapoints) || {};
      /**
       * Code-Teil: delRec
       * Zweck: Kapselt einen lokalen Verarbeitungsschritt, damit Aufrufer nicht direkt in Detaildaten eingreifen.
       * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
       * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
       */
      const delRec = async (id) => {
        try {
          // recursive removes child states/channels
          await this.delObjectAsync(id, { recursive: true });
        } catch (_e) {
          // ignore
        }
      };

      // 1) Historie optional series (Energiefluss: Verbraucher/Erzeuger)
      const MAX_CONSUMERS = 10;
      const MAX_PRODUCERS = 5;

      for (let i = 1; i <= MAX_CONSUMERS; i++) {
        const info = this._nwGetFlowSlotInfo ? this._nwGetFlowSlotInfo('consumers', i) : null;
        const mapped = info && String(info.objectId || '').trim();
        if (!mapped) {
          await delRec(`historie.consumers.c${i}`);
        }
      }

      for (let i = 1; i <= MAX_PRODUCERS; i++) {
        const info = this._nwGetFlowSlotInfo ? this._nwGetFlowSlotInfo('producers', i) : null;
        const mapped = info && String(info.objectId || '').trim();
        if (!mapped) {
          await delRec(`historie.producers.p${i}`);
        }
      }

      // 2) EVCS + Charging-Management dynamic channels beyond configured count
      // (Typical source of "leftover" objects after reducing the number of Ladepunkte)
      const evcsCount = Number(this.evcsCount || 0);
      if (Number.isFinite(evcsCount) && evcsCount >= 0) {
        // Be conservative: only clean a reasonable upper range.
        const MAX_EVCSSLOTS = 10;
        for (let i = evcsCount + 1; i <= MAX_EVCSSLOTS; i++) {
          await delRec(`evcs.${i}`);
          await delRec(`chargingManagement.wallboxes.lp${i}`);
          await delRec(`historie.evcs.lp${i}`);
        }
      }

      // 3) Charging-Management station groups: remove channels that are not part of the current config
      try {
        const cm = (this.config && this.config.chargingManagement) || {};
        const wallboxes = Array.isArray(cm.wallboxes) ? cm.wallboxes : [];
        const keep = new Set();
        for (const wb of wallboxes) {
          if (!wb) continue;
          const k = String(wb.stationKey || '').trim();
          const safe = toSafeIdPart(k);
          if (safe) keep.add(safe);
        }
        // Always cleanup child station channels. If no station keys are configured anymore,
        // this removes ALL previously created station group channels.
        const view = await this.getObjectViewAsync('system', 'channel', {
          startkey: `${this.namespace}.chargingManagement.stations.`,
          endkey: `${this.namespace}.chargingManagement.stations.\u9999`
        }).catch(() => null);

        const rows = (view && view.rows) ? view.rows : [];
        for (const r of rows) {
          const fullId = r && r.id ? String(r.id) : '';
          if (!fullId.startsWith(`${this.namespace}.chargingManagement.stations.`)) continue;
          const short = fullId.slice(this.namespace.length + 1); // remove '<namespace>.'
          const parts = short.split('.');
          const stationKey = parts.length >= 3 ? parts[2] : '';
          if (!stationKey) continue;
          if (keep.size === 0 || !keep.has(stationKey)) {
            await delRec(short);
          }
        }
      } catch (_eStations) {}

    } catch (e) {
      this.log.debug('cleanupOrphanedObjects failed: ' + (e && e.message ? e.message : e));
    }
  }

  // Abschnitt: Startablauf. Reihenfolge beachten: States anlegen, Lizenz/Config laden, Webserver starten, EMS initialisieren, Live-State veröffentlichen.
/**
 * Code-Teil: onReady
 * Zweck: Kapselt einen lokalen Verarbeitungsschritt, damit Aufrufer nicht direkt in Detaildaten eingreifen.
 * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
 * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
 */
async onReady() {
    if (this._nwShuttingDown) return;
    let admitted = false;
    let admissionFailure = '';
    const assertStartupAuthority = () => {
      if (this._nwShuttingDown) throw new Error('EOS_UI_STOPPING');
      // Optional setup catches may swallow a rejection, but may never erase a
      // loss already observed during this startup attempt. Restoration requires restart.
      if (admitted && !admissionFailure) {
        if (this._bridge.canWrite() !== true) admissionFailure = 'EOS_UI_OWNERSHIP_LOST';
        else if (!centralLicenseSnapshot(this._bridge).ok) admissionFailure = 'EOS_UI_LICENSE_LOST';
      }
      if (admissionFailure) throw new Error(admissionFailure);
    };
    const startupStep = async (operation) => {
      assertStartupAuthority();
      let result;
      try {
        result = await operation();
      } catch (error) {
        if (admitted && !admissionFailure && error
          && ['EOS_UI_OWNERSHIP_LOST', 'EOS_UI_LICENSE_LOST'].includes(error.message)) {
          admissionFailure = error.message;
        }
        assertStartupAuthority();
        throw error;
      }
      assertStartupAuthority();
      return result;
    };
    this._hostedStartup = { state: 'starting', error: '' };
    try {
      if (!centralLicenseSnapshot(this._bridge).ok) {
        await startupStep(() => this.startServer());
        this._hostedStartup = { state: 'unlicensed', error: 'EOS_LICENSE_REQUIRED' };
        return;
      }
      if (this._bridge.canWrite() !== true) {
        await startupStep(() => this.startServer());
        this._hostedStartup = { state: 'blocked', error: 'EOS_UI_OWNERSHIP_REQUIRED' };
        this.log.error('EOS_UI_OWNERSHIP_REQUIRED: Bedienoberfläche verfügbar, Regelung gesperrt.');
        return;
      }
      admitted = true;
      this._hostedStartupPhase = 'configuration';
