      const needed = [];
      if (/^\/api\/(?:smarthome|logic)(?:\/|$)/.test(route)) needed.push('smartHome');
      if (/^\/api\/ledger(?:\/|$)/.test(route)
        || /^\/api\/mesh\/coordinator\/accounting(?:\/|$)/.test(route)) needed.push('wallet');
      if (/^\/api\/mesh\/coordinator\/accounting\/report(?:\/|$)/.test(route)) needed.push('billing');
      if (needed.some(grant => !this._nwHasCentralLicenseGrant(grant))) {
        sendNoStore(res);
        return res.status(403).json({ ok: false, error: 'EOS_FEATURE_LICENSE_REQUIRED' });
      }
      return next();
    });

    // -------------------------------------------------------------------
    // License gate: the adapter/UI is locked until a valid license key is
    // configured in the ioBroker Admin (Lizenz-Seite).
    // -------------------------------------------------------------------
    // API-Kommentar: USE-Route. Zweck: stellt einen Web-/API-Endpunkt bereit. Zusammenhang: Frontend-Dateien in www/* können diesen Endpunkt direkt nutzen. Route/Handler: (req, res, next) => {
    app.use(async (req, res, next) => {
