        }

        // Recovery: if floors are missing but rooms reference floorId, derive minimal floors.
        if ((!out.floors || !out.floors.length) && Array.isArray(out.rooms) && out.rooms.length) {
          const seen = new Set();
          const ids = [];
          for (const r of out.rooms) {
            const fid = (r && r.floorId) ? String(r.floorId).trim() : '';
            if (!fid) continue;
            if (fid === '__unassigned__') continue;
            if (seen.has(fid)) continue;
            seen.add(fid);
            ids.push(fid);
          }
          if (ids.length) {
            /**
             * Code-Teil: pretty
             * Zweck: Kapselt einen lokalen Verarbeitungsschritt, damit Aufrufer nicht direkt in Detaildaten eingreifen.
             * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
             * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
             */
            const pretty = (s) => {
              const raw = String(s || '').trim();
              if (!raw) return '';
              return raw
                .replace(/[_-]+/g, ' ')
                .replace(/\s+/g, ' ')
                .replace(/\b\w/g, (m) => m.toUpperCase());
            };
            out.floors = ids.map((id, idx) => ({ id, name: pretty(id) || id, icon: '🏢', order: idx + 1 }));
          }
        }

        // Sanitize pages to avoid runtime issues in the SmartHome UI
        if (Array.isArray(out.pages)) {
          out.pages = out.pages
            .map((p, idx) => {
              const id = String(p && p.id ? p.id : `page_${idx + 1}`).trim();
              const title = String(p && (p.title || p.name || p.id) ? (p.title || p.name || p.id) : `Seite ${idx + 1}`).trim();
              const icon = String(p && p.icon ? p.icon : '').trim();
              const viewMode = String(p && p.viewMode ? p.viewMode : '').trim();
              const roomIds = Array.isArray(p && p.roomIds) ? p.roomIds.map((x) => String(x).trim()).filter(Boolean) : [];
              const funcIds = Array.isArray(p && p.funcIds) ? p.funcIds.map((x) => String(x).trim()).filter(Boolean) : [];
              const types = Array.isArray(p && p.types) ? p.types.map((x) => String(x).trim()).filter(Boolean) : [];
              const favoritesOnly = !!(p && p.favoritesOnly);
              const order = Number.isFinite(+((p && p.order) ?? idx)) ? +((p && p.order) ?? idx) : idx;
              const href = String(p && p.href ? p.href : '').trim();
              const parentId = String(p && p.parentId ? p.parentId : '').trim();
              const cardSizeRaw = String(p && (p.cardSize ?? (p.layout && p.layout.cardSize)) ? (p.cardSize ?? (p.layout && p.layout.cardSize)) : '').trim();
              const cardSize = ['auto', 's', 'm', 'l', 'xl'].includes(cardSizeRaw) ? cardSizeRaw : 'auto';
              const sortByRaw = String(p && (p.sortBy ?? (p.layout && p.layout.sortBy)) ? (p.sortBy ?? (p.layout && p.layout.sortBy)) : '').trim();
              const sortBy = ['order', 'name', 'type'].includes(sortByRaw) ? sortByRaw : 'order';
              const groupByType = !!(p && ((p.groupByType ?? (p.layout && p.layout.groupByType))));
              return { id, title, icon, viewMode, roomIds, funcIds, types, favoritesOnly, order, href, parentId, cardSize, sortBy, groupByType };
            })
            .filter((p) => p.id && p.title);
        }

        // Sanitize scenes to avoid runtime issues in the SmartHome UI
        // Schema (minimal): { id, alias, roomId, functionId, icon, order, ui:{size}, behavior:{favorite}, actions:[{deviceId, kind, value}] }
        {
          /**
           * Code-Teil: isPlain
           * Zweck: Kapselt einen lokalen Verarbeitungsschritt, damit Aufrufer nicht direkt in Detaildaten eingreifen.
           * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
           * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
           */
          const isPlain = (o) => this._nwIsPlainObject(o);
          /**
           * Code-Teil: safeStr
           * Zweck: Kapselt einen lokalen Verarbeitungsschritt, damit Aufrufer nicht direkt in Detaildaten eingreifen.
           * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
           * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
           */
          const safeStr = (v, maxLen) => {
            if (v === null || v === undefined) return '';
            const s = String(v).trim();
            if (!s) return '';
            return s.length > maxLen ? s.slice(0, maxLen) : s;
          };

          if (Array.isArray(out.scenes)) {
            out.scenes = out.scenes
              .filter((s) => isPlain(s))
              .map((s, idx) => {
                const rawId = safeStr(s.id || `scene_${idx + 1}`, 80) || `scene_${idx + 1}`;
                const alias = safeStr(s.alias || s.name || s.title || rawId, 120) || rawId;
                const icon = safeStr(s.icon || '', 32);
                const roomId = safeStr(s.roomId || '', 64);
                const functionId = safeStr(s.functionId || '', 64);
                const floorId = safeStr(s.floorId || '', 64);
                const order = Number.isFinite(+((s.order) ?? idx)) ? +((s.order) ?? idx) : idx;

                const sizeRaw = safeStr((s.ui && (s.ui.size ?? s.ui.cardSize)) ? (s.ui.size ?? s.ui.cardSize) : (s.size || ''), 12).toLowerCase();
                const size = ['s', 'm', 'l', 'xl', 'auto'].includes(sizeRaw) ? sizeRaw : 'm';

                const behavior = isPlain(s.behavior) ? s.behavior : {};

                const actionsIn = Array.isArray(s.actions) ? s.actions : [];
                const actions = [];
                for (const a of actionsIn) {
                  if (!isPlain(a)) continue;
                  const deviceId = safeStr(a.deviceId || a.idDevice || a.targetId || '', 80);
                  const kind = safeStr(a.kind || a.type || 'switch', 40) || 'switch';

                  // Szenenwerte bleiben primitive Werte. Die zentrale
                  // SmartHome-Vertragsprüfung normalisiert Aktionstypen,
                  // kontrolliert Datenpunkt-Fähigkeiten und erkennt rekursive
                  // Szenen, statt unbekannte Aktionen stillschweigend in einen
                  // Schalter umzuwandeln oder zu verwerfen.
                  let value = Object.prototype.hasOwnProperty.call(a, 'value')
                    ? a.value
                    : (Object.prototype.hasOwnProperty.call(a, 'val') ? a.val : a.sceneId);
                  if (typeof value === 'string') {
                    const t = value.trim();
                    if (t.toLowerCase() === 'true') value = true;
                    else if (t.toLowerCase() === 'false') value = false;
                    else if (['level', 'cover', 'coverTilt', 'rtrSetpoint', 'white', 'colorTemperature', 'playerVolume', 'playerSeek', 'value'].includes(kind)) {
                      const num = parseFloat(t.replace(',', '.'));
                      if (Number.isFinite(num) && t !== '') value = num;
                    }
                  }
                  if (value !== null && typeof value === 'object') continue;
                  actions.push({ deviceId, kind, value });
                }

                return {
                  id: rawId,
                  alias,
                  icon,
                  roomId,
                  functionId,
                  floorId,
                  order,
                  ui: { size },
                  behavior: { favorite: !!behavior.favorite },
                  actions,
                };
              })
              .filter((s) => s && s.id && s.alias);

            // Remove duplicates by id (keep first)
            const seen = new Set();
            out.scenes = out.scenes.filter((s) => {
              if (!s || !s.id) return false;
              if (seen.has(s.id)) return false;
              seen.add(s.id);
              return true;
            });
          }
        }

        const validation = this.nwValidateSmartHomeConfig(out);
        if (!validation.ok) {
          return res.status(400).json({
            ok: false,
            error: 'invalid SmartHome config',
            issues: validation.errors,
            warnings: validation.warnings,
          });
        }
        const normalizedOut = validation.config;
        const previousConfig = this.getSmartHomeConfig ? this._nwDeepClone(this.getSmartHomeConfig()) : this._nwDeepClone((this.config && this.config.smartHomeConfig) || {});
        const previousDevices = Array.isArray(this.smartHomeDevices) ? this._nwDeepClone(this.smartHomeDevices) : [];
        const previousPatch = this._nwInstallerConfigPatch;

        // Transaktionaler Wechsel: erst Runtime aus der vollständigen neuen
        // Konfiguration erzeugen, danach persistent speichern. Bei jedem Fehler
        // bleibt der zuvor funktionierende Stand aktiv.
        this.config = this.config || {};
        this.config.smartHomeConfig = normalizedOut;
        this._nwShcfgDetectCache.clear();
        try {
          if (typeof this.buildSmartHomeDevicesFromConfig === 'function') this.buildSmartHomeDevicesFromConfig();
        } catch (e) {
          this.config.smartHomeConfig = previousConfig;
          this.smartHomeDevices = previousDevices;
          return res.status(400).json({ ok: false, error: 'runtime activation failed', message: 'Konfiguration konnte nicht aktiviert werden.' });
        }

        try {
          const basePatch = (this._nwInstallerConfigPatch && typeof this._nwInstallerConfigPatch === 'object') ? this._nwInstallerConfigPatch : {};
          let mergedPatch = this.nwDeepMerge({}, basePatch);
          mergedPatch = this.nwDeepMerge(mergedPatch, { smartHomeConfig: normalizedOut });
          if (await this.persistInstallerConfigToState(mergedPatch) === false) throw new Error('SmartHome-Konfiguration konnte nicht gespeichert werden.');
          this._nwInstallerConfigPatch = mergedPatch;
        } catch (e) {
          this.config.smartHomeConfig = previousConfig;
          this.smartHomeDevices = previousDevices;
          this._nwInstallerConfigPatch = previousPatch;
          try { if (typeof this.buildSmartHomeDevicesFromConfig === 'function') this.buildSmartHomeDevicesFromConfig(); } catch (_rollbackError) {}
          this.log.warn('SmartHomeConfig save rolled back: ' + e.message);
          return res.status(500).json({ ok: false, error: 'persist failed', message: 'Konfiguration konnte nicht gespeichert werden.', rolledBack: true });
        }

        res.json({ ok: true, config: normalizedOut, persisted: true, warnings: validation.warnings });
      } catch (e) {
        this.log.warn('SmartHomeConfig save API error: ' + e.message);
        res.status(500).json({ ok: false, error: 'internal error' });
      } finally { endMeshAppSave(mutationToken); }
    });

    // Technische Datenpunktauswahl: Installer/Admin liest mögliche Zuordnungen. Kunden erhalten keinen freien DP-Zugriff.
    app.get('/api/smarthome/dpsearch', requireDpDiscovery, async (req, res) => {
      try {
        const qRaw = (req.query && req.query.q) || '';
        const q = (typeof qRaw === 'string' ? qRaw : String(qRaw || '')).trim();
        const qLower = (q || '').toLowerCase();

        const limitRaw = (req.query && req.query.limit) || '';
        let limit = parseInt(limitRaw, 10);
        if (!Number.isFinite(limit) || limit <= 0) limit = 200;
        if (limit > 5000) limit = 5000;

        if (typeof this.getForeignObjectsAsync !== 'function') {
          this.log.warn('SmartHomeConfig dpsearch: getForeignObjectsAsync not available');
          return res.json({ ok: false, error: 'datapoint search not supported' });
        }

        // Cache all state objects for a short period to avoid heavy DB reads while typing

        const now = Date.now();

        const ttlMs = 15000;

        if (!this._nwDpCache || !this._nwDpCache.ts || (now - this._nwDpCache.ts) > ttlMs) {

          const all = await this.getForeignObjectsAsync('*', 'state');

          const items = [];

          for (const id of Object.keys(all || {})) {

            const obj = all[id];

            if (!obj || !obj.common) continue;

            const nameRaw = obj.common.name || '';

            const name = typeof nameRaw === 'string' ? nameRaw : JSON.stringify(nameRaw);

            items.push({

              id,

              name,

              role: obj.common.role || '',

              type: obj.common.type || '',

              unit: obj.common.unit || '',

              idLower: String(id).toLowerCase(),

              nameLower: String(name).toLowerCase(),

            });

          }

          // Stable, user-friendly order

          items.sort((a, b) => a.idLower.localeCompare(b.idLower));

          // Build byId map (plain object) for fast lookup

          const byId = {};

          for (const it of items) {

            if (!it || !it.id) continue;

            byId[it.id] = it;

          }

          // Build a lightweight trie for folder-like browsing (dot-separated IDs)
          /**
           * Code-Teil: makeNode
           * Zweck: Kapselt einen lokalen Verarbeitungsschritt, damit Aufrufer nicht direkt in Detaildaten eingreifen.
           * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
           * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
           */
          const makeNode = () => ({ children: Object.create(null), item: null });

          const root = makeNode();

          for (const it of items) {

            const sid = String(it.id || '');

            if (!sid) continue;

            const parts = sid.split('.').filter(Boolean);

            let node = root;

            for (const seg of parts) {

              if (!node.children[seg]) node.children[seg] = makeNode();

              node = node.children[seg];

            }

            node.item = it;

          }

          this._nwDpCache = { ts: now, items, byId, trie: root };

        }

        const items = (this._nwDpCache && this._nwDpCache.items) ? this._nwDpCache.items : [];

        const results = [];
        const seen = new Set();
        /**
         * Code-Teil: pushItem
         * Zweck: Kapselt einen lokalen Verarbeitungsschritt, damit Aufrufer nicht direkt in Detaildaten eingreifen.
         * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
         * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
         */
        function pushItem(it) {
          if (!it || !it.id || seen.has(it.id)) return;
          seen.add(it.id);
          results.push({
            id: it.id,
            name: it.name,
            role: it.role,
            type: it.type,
            unit: it.unit,
          });
        }

        if (!qLower) {
          // Browse-Mode: zeige zuerst typische Admin-Bereiche
          const preferredPrefixes = ['0_userdata.0.', 'alias.0.', 'javascript.0.'];
          for (const pref of preferredPrefixes) {
            for (const it of items) {
              if (!it.idLower.startsWith(pref)) continue;
              pushItem(it);
              if (results.length >= limit) break;
            }
            if (results.length >= limit) break;
          }

          if (results.length < limit) {
            for (const it of items) {
              pushItem(it);
              if (results.length >= limit) break;
            }
          }

          return res.json({ ok: true, results });
        }

        for (const it of items) {
          if (it.idLower.indexOf(qLower) !== -1 || it.nameLower.indexOf(qLower) !== -1) {
            pushItem(it);
            if (results.length >= limit) break;
          }
        }

        res.json({ ok: true, results });
      } catch (e) {
        this.log.warn('SmartHomeConfig dpsearch error: ' + e.message);
        res.status(500).json({ ok: false, error: 'internal error' });
      }
    });

    // --- SmartHomeConfig DP-Test (Installer): read/write a datapoint quickly ---
    // Read current foreign state
    // Technische Datenpunktauswahl: Installer/Admin liest mögliche Zuordnungen. Kunden erhalten keinen freien DP-Zugriff.
    app.get('/api/smarthome/dpget', requireDpDiscovery, async (req, res) => {
      try {
        const idRaw = (req.query && req.query.id) || '';
        const id = (typeof idRaw === 'string' ? idRaw : String(idRaw || '')).trim();
        if (!id) return res.status(400).json({ ok: false, error: 'missing id' });
        if (id.length > 300) return res.status(400).json({ ok: false, error: 'id too long' });
        if (typeof this.getForeignStateAsync !== 'function') {
          return res.status(500).json({ ok: false, error: 'getForeignStateAsync not available' });
        }
        const st = await this.getForeignStateAsync(id);
        if (!st) {
          return res.json({ ok: true, id, state: null });
        }
        res.json({
          ok: true,
          id,
          state: {
            val: st.val,
            ack: !!st.ack,
            ts: st.ts || 0,
            lc: st.lc || 0,
            from: st.from || '',
            q: typeof st.q !== 'undefined' ? st.q : null,
          },
        });
      } catch (e) {
        this.log.warn('SmartHome dpget error: ' + (e && e.message ? e.message : e));
        res.status(500).json({ ok: false, error: 'internal error' });
      }
    });

    // Write foreign state (installer only). Use with care.
    // API-Kommentar: POST-Route. Zweck: stellt einen Web-/API-Endpunkt bereit. Zusammenhang: Frontend-Dateien in www/* können diesen Endpunkt direkt nutzen. Route/Handler: '/api/smarthome/dpset', requireInstaller, async (req, res) => {
    app.post('/api/smarthome/dpset', requireInstaller, async (req, res) => {
      try {
        const body = req.body || {};
        const id = String(body.id || '').trim();
        if (!id) return res.status(400).json({ ok: false, error: 'missing id' });
        if (id.length > 300) return res.status(400).json({ ok: false, error: 'id too long' });

        let val = body.val;
        if (typeof val === 'string') {
          const t = val.trim();
          if (t.toLowerCase() === 'true') val = true;
          else if (t.toLowerCase() === 'false') val = false;
          else {
            // Try to parse numbers (installer often pastes values)
            const num = parseFloat(t.replace(',', '.'));
            if (Number.isFinite(num) && t !== '') val = num;
          }
        }

        if (typeof this.setForeignStateAsync !== 'function') {
          return res.status(500).json({ ok: false, error: 'setForeignStateAsync not available' });
        }

        await this.setForeignStateAsync(id, val);
        res.json({ ok: true, id, written: true });
      } catch (e) {
        this.log.warn('SmartHome dpset error: ' + (e && e.message ? e.message : e));
        res.status(500).json({ ok: false, error: 'internal error' });
      }
    });

    // --- Installer / EMS Apps API ---
    // Diese API dient dazu, die Konfiguration (native) auch direkt über die Installer-Webseite
    // zu pflegen. Änderungen werden in system.adapter.<namespace>.native persistiert.
    /**
     * Code-Teil: _nwDeepMerge
     * Zweck: Kapselt einen lokalen Verarbeitungsschritt, damit Aufrufer nicht direkt in Detaildaten eingreifen.
     * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
     * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
     */
    // Derselbe geprüfte Merge schützt auch ältere Aufrufpfade vor Prototyp-Mutation.
    const _nwDeepMerge = (target, patch) => this.nwDeepMerge(target, patch);

    // --- EMS App-Center (Phase 2) ---
    // We treat each EMS capability as an installable "App" for this site/instance.
    // The runtime remains backward compatible by mapping App states to existing enable* flags.
    const _nwAppCatalog = [
      { id: 'charging', label: 'Lademanagement', desc: 'PV-Überschussladen, Budget, Ladepunkte/Connectors', enableFlag: 'enableChargingManagement', mandatory: false },
      { id: 'peak', label: 'Peak-Shaving', desc: 'Lastspitzenkappung / Import-Limit / Atypische HLZF', enableFlag: 'enablePeakShaving', mandatory: false },
      { id: 'storage', label: 'Speicherregelung', desc: 'Eigenverbrauch / Speicher-Setpoints (herstellerunabhängig)', enableFlag: 'enableStorageControl', mandatory: false },
      { id: 'storagefarm', label: 'Speicherfarm', desc: 'Mehrere Speichersysteme als Pool/Gruppen', enableFlag: 'enableStorageFarm', mandatory: false },
      { id: 'dynamicGrid', label: 'Dynamischer Netzanschluss', desc: 'Bereichsbezogene Netzlimits und frei zugeordnete Speicher', enableFlag: 'enableDynamicGrid', mandatory: false, noLegacyDefault: true },
      { id: 'arbitrage', label: 'Arbitrage', desc: 'Freigegebener Speicherhandel im Haushalt oder als eigenständiger Speicherbetrieb', enableFlag: 'enableArbitrage', mandatory: false, noLegacyDefault: true },
      { id: 'thermal', label: 'Wärmepumpe & Klima', desc: 'PV-Überschuss-Steuerung (Setpoint, On/Off oder SG-Ready) mit Schnellsteuerung', enableFlag: 'enableThermalControl', mandatory: false },
      { id: 'heatingrod', label: 'Heizstab', desc: 'Native 1..12 Stufen Heizstab-Regelung über Relais / KNX-Aktoren', enableFlag: 'enableHeatingRodControl', mandatory: false },
      { id: 'bhkw', label: 'BHKW', desc: 'BHKW-Steuerung (Start/Stop, SoC-geführt) mit Schnellsteuerung', enableFlag: 'enableBhkwControl', mandatory: false },
      { id: 'generator', label: 'Generator', desc: 'Generator-Steuerung (Notstrom/Netzparallelbetrieb, SoC-geführt) mit Schnellsteuerung', enableFlag: 'enableGeneratorControl', mandatory: false },
      { id: 'threshold', label: 'Schwellwertsteuerung', desc: 'Regeln (Wenn X > Y dann Schalten/Setzen) – optional mit Endkunden-Anpassung', enableFlag: 'enableThresholdControl', mandatory: false },
      { id: 'relay', label: 'Relaissteuerung', desc: 'Manuelle Relais / generische Ausgänge (optional endkundentauglich)', enableFlag: 'enableRelayControl', mandatory: false },
      { id: 'grid', label: 'Netzlimits', desc: 'Dauerhafter Netzanschlussschutz mit Import-Soft-/Hard-Limit; 0‑Einspeisung bleibt optional', enableFlag: 'enableGridConstraints', mandatory: true },
      { id: 'aiAdvisor', label: 'KI‑Energieberater', desc: 'Beratende KI‑Optimierung / Energie‑Tipps ohne automatische Schaltbefehle', enableFlag: 'enableAiAdvisor', mandatory: false },
      { id: 'energyWallet', label: 'Energie-Wertkonto', desc: 'PV-Wert, Eigenverbrauchswert und Einspeisewert für das Kundenfrontend (Home + EOS)', enableFlag: 'enableEnergyWallet', mandatory: true },
      { id: 'energyLedger', label: 'Energieherkunft & Ladebilanz', desc: 'Read-only 15-Minuten-Bilanz und Herkunftsjournal', enableFlag: 'enableEnergyLedger', mandatory: false },
      // Verborgener AppCenter-Zustand: Das Stationsdisplay wird unter Ladepunkte konfiguriert.
      // Die Normalisierung muss es trotzdem erhalten, wenn ein anderer AppCenter-Reiter speichert.
      { id: 'chargeKiosk', label: 'DC-Stationsdisplay', desc: 'Tokenisierte Stationsseiten für DC-Ladepunkte', enableFlag: 'enableChargeKiosk', mandatory: false, hidden: true },
      { id: 'meshMicrogrid', label: 'EOS Mesh/Microgrid', desc: 'Lokale Energie-Knoten, Cluster und sichere Feldsteuerung', enableFlag: 'enableMeshMicrogrid', mandatory: false },
      // tariff is a shared helper module (provider + budget). Keep it always present.
      { id: 'tariff', label: 'Tarife', desc: 'Preis-Signal / Ladepark-Budget / Netzladung-Freigabe', enableFlag: null, mandatory: true },
      { id: 'para14a', label: '§14a Steuerung', desc: 'Abregelung/Leistungsdeckel für steuerbare Verbraucher (falls aktiviert)', enableFlag: null, mandatory: false },
      { id: 'multiuse', label: 'MultiUse', desc: 'Weitere interne Logik-Bausteine', enableFlag: 'enableMultiUse', mandatory: false },
      { id: 'netOperator', label: 'Netzbetreiber-Schnittstelle', desc: 'Kanonische read-only Schnittstelle hinter einem zertifizierten EZA-/Parkregler', enableFlag: 'enableNetOperatorInterface', mandatory: false },
      { id: 'operatingStrategies', label: 'Betriebsstrategien', desc: 'EOS: modulare Ressourcen, DP-Zuordnung, Saisonprofile und Nachtenergie-Reserve', enableFlag: null, mandatory: false },
    ];
    /**
     * Code-Teil: _nwNormalizeEmsApps
     * Zweck: Kapselt einen lokalen Verarbeitungsschritt, damit Aufrufer nicht direkt in Detaildaten eingreifen.
     * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
     * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
     */
    const _nwNormalizeEmsApps = (nativeObj) => {
      const n = nativeObj && typeof nativeObj === 'object' ? nativeObj : {};
      const stored = (n.emsApps && typeof n.emsApps === 'object') ? n.emsApps : {};
      const appsStored = (stored.apps && typeof stored.apps === 'object') ? stored.apps : {};

      const out = {
        schemaVersion: 1,
        apps: {},
      };

