    };

    /** Neue/geänderte Stations-Bearer verlangen ein langes URL-sicheres Format.
     * Unveränderte Alt-Tokens bleiben bis zur bewussten Neuverknüpfung verwendbar;
     * kein automatisches Abschalten bestehender Kiosks oder Hardware-Regelung.
     * Die Syntaxprüfung kann Zufälligkeit nicht beweisen: UI erzeugt 128 Crypto-Bits.
     */
    const nwValidateStationTokenChanges = (patch) => {
      const rows = patch && patch.chargeKiosk && patch.chargeKiosk.stations;
      if (!Array.isArray(rows)) return '';
      const existing = this.config && this.config.chargeKiosk && this.config.chargeKiosk.stations || [];
      const identity = (row, index) => String(row && (row.id || row.key || row.stationId || row.stationKey) || `dc_station_${index + 1}`);
      const used = new Set();
      for (let i = 0; i < rows.length; i++) {
        const row = rows[i] || {};
        const token = String(row.token || row.displayToken || '').trim();
        const old = existing.find((entry, index) => identity(entry, index) === identity(row, i));
        const unchanged = old && String(old.token || old.displayToken || '').trim() === token;
        if (token && used.has(token)) return 'Stations-Token dürfen nicht mehrfach verwendet werden.';
        if (token) used.add(token);
        if (!unchanged && (row.enabled !== false || token) && !/^[A-Za-z0-9_-]{32,128}$/.test(token)) return 'Neuen Stations-Token sicher erzeugen (mindestens 128 Bit, 32 bis 128 URL-sichere Zeichen).';
      }
      return '';
    };

    // Abschnitt: Installer/App-Center-APIs. Änderungen wirken direkt auf EMS-Module und DP-Mapping.
    const requireHistoryInstaller = (req, res, next) => {
      if (!['admin', 'installer'].includes(req.nwSession?.role)) return sendForbidden(res);
      return next();
    };
    const historyResponse = () => ({ ok: true, config: redactInfluxHistoryConfig({ history: this.config?.history || { provider: 'adapter' } }).history, configurationRevision: this._nwInstallerConfigRevision(), status: this._nwDirectHistory.status() });
    const historyFailure = (res, error) => {
      const rawCode = error?.code;
      const code = typeof rawCode === 'string' && /^EOS_INFLUX_[A-Z_]{1,64}$/.test(rawCode) ? rawCode : 'EOS_INFLUX_REQUEST_FAILED';
      const invalid = ['EOS_INFLUX_CONFIG_INVALID', 'EOS_INFLUX_PROVIDER_INVALID', 'EOS_INFLUX_TOKEN_INVALID', 'EOS_INFLUX_CA_INVALID', 'EOS_INFLUX_URL_INVALID', 'EOS_INFLUX_NEW_DESTINATION_REQUIRES_TOKEN'].includes(code);
