        cfgOut = _nwMaskTariffProviderForUi(cfgOut);
        // 1.0.3: Nur die an die UI gelieferte Kopie wird auf die aktuelle Edition
        // begrenzt. Alte Pro-Konfigurationen bleiben intern erhalten, dürfen bei einer
        // Home-Lizenz aber weder als installiert erscheinen noch Pro-only Komponenten
        // und deren APIs aktivieren.
        if (cfgOut.emsApps && typeof cfgOut.emsApps === 'object') {
          cfgOut.emsApps = this._nwApplyLicenseLimitsToEmsApps(cfgOut.emsApps);
        }
        cfgOut.meshApp = this._meshCoordinator?.appState() || { installed: false, enabled: false, protected: false };
        cfgOut.license = this._nwBuildLicenseFeatureInfo();
        cfgOut.locale = this._nwBuildLocaleInfo();
        cfgOut.countryProfile = Object.assign({}, cfgOut.countryProfile || {}, this._nwBuildCountryProfileInfo());
        cfgOut.regressionSafety = this._nwInstallerRegressionSafetyLastReport || { schema: 'nexowatt.installer-regression-safety.v1', ok: true, checks: [] };
        res.json({ ok: true, license: cfgOut.license, config: cfgOut, configurationRevision });
      } catch (e) {
        this.log.warn('Installer config API error: ' + e.message);
        res.status(500).json({ ok: false, error: 'internal error' });
      }
    });

    // API-Kommentar: POST-Route. Zweck: stellt einen Web-/API-Endpunkt bereit. Zusammenhang: Frontend-Dateien in www/* können diesen Endpunkt direkt nutzen. Route/Handler: '/api/installer/config', requireInstaller, async (req, res) => {
    app.post('/api/installer/config', requireInstaller, async (req, res) => {
      const meshSaveToken = beginMeshAppSave();
      if (!meshSaveToken) return res.status(409).json({ error: 'Konfiguration wird bereits gespeichert.' });
      try {
        sendNoStore(res);
        const body = req.body || {};
        this._nwAssertInstallerConfigRevision(body.expectedConfigurationRevision);
        const patch = body.patch && typeof body.patch === 'object' ? body.patch : {};
        const restartEms = body.restartEms !== false; // default true
        const tokenError = nwValidateStationTokenChanges(patch);
        if (tokenError) return res.status(400).json({ ok: false, error: 'invalid_station_token', message: tokenError });

        const hasFreshLicenseInfo = !!(this._nwLicenseInfo && typeof this._nwLicenseInfo === 'object' && this._nwLicenseInfo.ok === true && this._nwLicenseOk === true);
        if (!hasFreshLicenseInfo) {
          try { await this._nwRefreshLicenseFromConfiguredKey(false); } catch (_eLicRefresh) {}
        }

        const allowedRoot = new Set([
          // Legacy enable flags (kept for backwards compatibility)
          'enableChargingManagement','enablePeakShaving','enableStorageControl','enableStorageFarm','enableDynamicGrid','enableArbitrage','enableThermalControl','enableHeatingRodControl','enableBhkwControl','enableGeneratorControl','enableThresholdControl','enableRelayControl','enableGridConstraints','enableAiAdvisor','enableEnergyWallet','enableEnergyLedger','enableChargeKiosk','enableMeshMicrogrid','enableNetOperatorInterface','enableMultiUse',

          // Phase 2: App Center state
          'emsApps',

          // Scheduler + base mapping
          'schedulerIntervalMs','installerConfig','countryProfile','energyWallet','tariffProvider','chargeKiosk','meshMicrogrid','netOperatorInterface','operatingStrategies','datapoints','vis','settings',

          // App/module configs
          'peakShaving','gridConstraints','nvpTopology','dynamicGridConnection','partnerIntegrations','storageFarm','storage','thermal','heatingRod','bhkw','generator','threshold','relay','aiAdvisor','energyWallet','energyLedger','chargeKiosk','meshMicrogrid','netOperatorInterface','operatingStrategies','chargingManagement',

