        if (Object.prototype.hasOwnProperty.call(safePatch, 'dynamicGridConnection')) mergedPatch.dynamicGridConnection = this._nwDeepClone(safePatch.dynamicGridConnection);
        if (Object.prototype.hasOwnProperty.call(safePatch, 'partnerIntegrations')) {
          if (JSON.stringify(safePatch.partnerIntegrations) !== JSON.stringify(currentPartnerConfig(this.config))) return res.status(409).json({ ok: false, error: 'PARTNER_DEDICATED_SAVE_REQUIRED', message: 'Partnerfreigaben wurden geändert. Bitte neu laden und die Partneransicht verwenden.' });
          mergedPatch.partnerIntegrations = this._nwDeepClone(currentPartnerConfig(this.config));
        }
