        } catch (_e) {}

        if (Object.prototype.hasOwnProperty.call(safePatch, 'nvpTopology')) {
          const desired = safePatch.nvpTopology;
          if (JSON.stringify(desired) === JSON.stringify(currentNvpConfig(this))) {
