        // Regler ist nur für DC/Hybrid und als exklusiver Writer zulässig.
        const singleStorage = mergedPatch.storage && typeof mergedPatch.storage === 'object' ? mergedPatch.storage : {};
        const singleDp = singleStorage.datapoints && typeof singleStorage.datapoints === 'object' ? singleStorage.datapoints : {};
        const singleFenecon = nwValidateFeneconSingleConfig({
          vendorProfile: singleStorage.vendorProfile,
          coupling: singleStorage.coupling,
          feneconControlMode: singleStorage.feneconControlMode,
          feneconGridSetpointObjectId: singleDp.feneconGridSetpointObjectId,
          feneconEssActualPowerObjectId: singleDp.feneconEssActualPowerObjectId,
          setSignedPowerId: singleDp.targetPowerObjectId,
          setChargePowerId: singleDp.targetChargePowerObjectId,
          setDischargePowerId: singleDp.targetDischargePowerObjectId,
        }, {
          writableStorageCount: 1,
          otherWritableStorageCount: 0,
          directTargetAvailable: !!(
            String(singleDp.targetPowerObjectId || '').trim()
            || String(singleDp.targetChargePowerObjectId || '').trim()
            || String(singleDp.targetDischargePowerObjectId || '').trim()
          ),
        });
        if (singleFenecon.ok !== true) {
          return res.status(400).json({
            ok: false,
            error: 'fenecon_single_config_invalid',
            message: `FENECON-Konfiguration ungültig: ${singleFenecon.reason}`,
            details: singleFenecon,
          });
        }
        const farmRowsForValidation = mergedPatch.storageFarm && Array.isArray(mergedPatch.storageFarm.storages)
          ? this._nwNormalizeStorageFarmRows(mergedPatch.storageFarm.storages)
          : [];
        const farmFenecon = nwValidateFeneconFarmRows(farmRowsForValidation);
        if (!farmFenecon.ok) {
          return res.status(400).json({
            ok: false,
            error: 'fenecon_farm_config_invalid',
            message: `FENECON-Speicherfarm ungültig: ${farmFenecon.reason}`,
            details: farmFenecon,
          });
        }

        // Bereits aktive/verriegelte Regelung darf auch bei direktem API-Save nicht verschwinden.
        try { this._meshCoordinator?.assertAppChange(this.nwApplyInstallerPatchToRuntimeConfig(this.config, mergedPatch)); }
        catch (error) { const failure = safeConfigurationFailure(error); return res.status(failure.status).json(failure.body); }
        // Persist patch to states (no ioBroker restart)
        await this._nwProvisionInstallerObjects(this.nwApplyInstallerPatchToRuntimeConfig(this.config, mergedPatch));
        if (await this.persistInstallerConfigToState(mergedPatch) === false) throw new Error('Installer-Konfiguration konnte nicht gespeichert werden.');
        this._nwInstallerConfigPatch = mergedPatch;

        // Persist an additional uninstall-proof backup into 0_userdata.0 (best-effort)
        try { await this.nwWriteUserdataBackup(mergedPatch, 'config-save'); } catch (_e) {}

        // Pause old writers before exposing the new mappings to runtime consumers.
        if (restartEms && this.emsEngine?.stopForReconfigure) await this.emsEngine.stopForReconfigure();
        // Apply patch to runtime config (App-Center SoT: replace installer-managed sections)
        this.config = (this.config && typeof this.config === 'object') ? this.config : {};
        this.config = this.nwApplyInstallerPatchToRuntimeConfig(this.config, mergedPatch);
        await this._nwApplyInstallerRuntime(restartEms, 'config-save');

        try { await this._nwInitLicense(); } catch (e) { try { this.log.warn('License refresh after installer config save failed: ' + (e && e.message ? e.message : e)); } catch (_eLog) {} }
        let cfgOut = await _nwHydrateStorageFarmConfigFromRuntimeStates(_nwPickPersistedInstallerConfig());
        cfgOut = _nwMaskTariffProviderForUi(cfgOut);
        // 1.0.3: Nur die an die UI gelieferte Kopie wird auf die aktuelle Edition
        // begrenzt. Alte Pro-Konfigurationen bleiben intern erhalten, dürfen bei einer
