        cfgOut.license = this._nwBuildLicenseFeatureInfo();
        cfgOut.locale = this._nwBuildLocaleInfo();
        cfgOut.countryProfile = Object.assign({}, cfgOut.countryProfile || {}, this._nwBuildCountryProfileInfo());
