            totalStates: Object.keys(compactObjects).length,
            connectorCount: 0,
            connectors: [],
          });
        }

        let objects = {};
        let usedFallback = false;

        try {
          objects = await this.getForeignObjectsAsync('ocpp.*', 'state');
        } catch (_e) {
          objects = {};
        }

        if (!objects || Object.keys(objects).length === 0) {
          // Fallback: scan all states and filter by id/name containing "ocpp"
          usedFallback = true;
          try {
            const all = await this.getForeignObjectsAsync('*', 'state');
            objects = {};
            for (const [id, obj] of Object.entries(all || {})) {
              const sid = String(id || '');
              if (!sid) continue;
              const idLower = sid.toLowerCase();
              let hit = false;

              if (idLower.startsWith('ocpp.') || idLower.includes('.ocpp.')) hit = true;

              if (!hit && obj && obj.common && obj.common.name) {
                const n = obj.common.name;
                const name = (typeof n === 'string') ? n : JSON.stringify(n);
                if (String(name || '').toLowerCase().includes('ocpp')) hit = true;
              }

              if (hit) objects[sid] = obj;
            }
          } catch (_e2) {
            objects = {};
          }
        }

        const ignoreSeg = new Set([
          'chargepoints','chargepoint','charge_points','cps','cp',
          'clients','client','server',
          'stations','station',
          'evses','evse',
          'connectors','connector',
          'ports','port'
        ]);
        /**
         * Code-Teil: deriveStationKey
         * Zweck: Leitet Werte aus anderen Messwerten ab.
         * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
         * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
         */
        const deriveStationKey = (parts) => {
          const clean = [];
          for (const p of parts || []) {
            const s = String(p || '').trim();
            if (!s) continue;
            const l = s.toLowerCase();
            if (ignoreSeg.has(l)) continue;
            if (/^\d+$/.test(l)) continue;
            clean.push(s);
          }
          if (clean.length) return clean[clean.length - 1];

          // Fallback: last non-empty part
          for (let i = (parts || []).length - 1; i >= 0; i--) {
            const s = String(parts[i] || '').trim();
            if (s) return s;
          }
          return '';
        };
        /**
         * Code-Teil: parseConnector
         * Zweck: Parst Rohdaten in ein sicheres internes Format.
         * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
         * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
         */
        const parseConnector = (id) => {
          const sid = String(id || '').trim();
          if (!sid) return null;
          const parts = sid.split('.').filter(Boolean);
          if (parts.length < 3) return null;

          // ioBroker OCPP adapter (common layout):
          //   ocpp.<instance>.<chargePointId>.<connectorNo>....
          // Example:
          //   ocpp.0.0311107102121190684.1.meterValues.Power_Active_Import
          // Here the connector number is a pure number segment right after the charge point id.
          // Additionally, some states may exist directly under the chargePointId (no connector segment)
          // → treat them as connector 0 (Main).
          try {
            const p0 = String(parts[0] || '').toLowerCase();
            const p1 = String(parts[1] || '');
            const p2 = String(parts[2] || '');
            const p3 = (parts.length >= 4) ? String(parts[3] || '') : '';
            if (p0 === 'ocpp' && /^\d+$/.test(p1) && p2) {
              if (p3 && /^\d+$/.test(p3)) {
                const connectorNo = Number(p3);
                const base = parts.slice(0, 4).join('.');
                const stationKey = p2;
                return { base, stationKey, connectorNo };
              }

              // Station-level state (no numeric connector segment)
              const base = parts.slice(0, 3).join('.') + '.0';
              const stationKey = p2;
              return { base, stationKey, connectorNo: 0 };
            }
          } catch (_e) {}

          for (let i = 0; i < parts.length; i++) {
            const seg = String(parts[i] || '');
            const low = seg.toLowerCase();

            // connector1 / connector_1 / port2 / evse3
            let m = low.match(/^(connector|port|evse)[_-]?(\d+)$/);
            if (m) {
              const connectorNo = Number(m[2]);
              const base = parts.slice(0, i + 1).join('.');
              const stationKey = deriveStationKey(parts.slice(2, i));
              return { base, stationKey, connectorNo };
            }

            // connector.1 / connectors.1 / ports.2 / evses.1
            if (['connector','connectors','port','ports','evse','evses'].includes(low) && i + 1 < parts.length) {
              const next = String(parts[i + 1] || '');
              if (/^\d+$/.test(next)) {
                const connectorNo = Number(next);
                const base = parts.slice(0, i + 2).join('.');
                const stationKey = deriveStationKey(parts.slice(2, i));
                return { base, stationKey, connectorNo };
              }
            }
          }

          return null;
        };

        /** @type {Record<string, any>} */
        const groups = {};
        for (const [id, obj] of Object.entries(objects || {})) {
          const info = parseConnector(id);
          if (!info || !info.base) continue;

          const key = info.base;
          if (!groups[key]) {
            groups[key] = {
              base: info.base,
              stationKey: String(info.stationKey || '').trim(),
              connectorNo: Number(info.connectorNo) || 0,
              states: [],
            };
          }

          groups[key].states.push({
            id: String(id),
            common: (obj && obj.common) ? obj.common : {},
          });
        }
        /**
         * Code-Teil: scoreState
         * Zweck: Kapselt einen lokalen Verarbeitungsschritt, damit Aufrufer nicht direkt in Detaildaten eingreifen.
         * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
         * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
         */
        const scoreState = (it, kind) => {
          try {
            const id = String((it && it.id) || '');
            const idLower = id.toLowerCase();
            const c = (it && it.common) ? it.common : {};
            const type = String(c.type || '').toLowerCase();
            const role = String(c.role || '').toLowerCase();
            const unit = String(c.unit || '').toLowerCase();
            const read = c.read !== false;
            const write = !!c.write;

            let s = 0;

            if (kind === 'power') {
              // Prefer standard ioBroker-OCPP instantaneous import power
              // Example: ocpp.0.<cpId>.<connector>.meterValues.Power_Active_Import
              if (idLower.includes('metervalues.power_active_import')) s += 100;
              if (idLower.endsWith('power_active_import')) s += 60;
              // Avoid last-transaction consumption (is NOT instantaneous power)
              if (idLower.includes('lasttransactionconsumption') || idLower.includes('last_transaction_consumption')) s -= 120;
              if (type === 'number') s += 2;
              if (role.includes('value.power')) s += 10;
              if (unit === 'w') s += 10;
              if (idLower.includes('power')) s += 5;
              // Prefer import for consumption-like metrics
              if (idLower.includes('import')) s += 2;
              if (idLower.includes('export')) s -= 2;
              if (read && !write) s += 2;
              if (unit === 'kw') s -= 3; // prefer W
            } else if (kind === 'energy') {
              // Prefer standard ioBroker-OCPP cumulative import energy register
              // Example: ocpp.0.<cpId>.<connector>.meterValues.Energy_Active_Import_Register
              if (idLower.includes('metervalues.energy_active_import_register')) s += 100;
              if (idLower.endsWith('energy_active_import_register')) s += 60;
              // Interval is acceptable if register is not available, but less preferred
              if (idLower.includes('metervalues.energy_active_import_interval')) s += 20;
              if (idLower.endsWith('energy_active_import_interval')) s += 10;
              // Avoid last-transaction consumption (is NOT total energy)
              if (idLower.includes('lasttransactionconsumption') || idLower.includes('last_transaction_consumption')) s -= 120;
              if (type === 'number') s += 2;
              if (role.includes('value.energy')) s += 10;
              if (unit === 'kwh') s += 10;
              if (idLower.includes('energy') || idLower.includes('meter')) s += 4;
              if (idLower.includes('import')) s += 2;
              if (idLower.includes('export')) s -= 2;
              if (read && !write) s += 2;
            } else if (kind === 'status') {
              if (type === 'string') s += 6;
              if (role.includes('text') || role.includes('state')) s += 2;
              if (idLower.includes('status') || idLower.includes('state')) s += 4;
              if (read) s += 1;
            } else if (kind === 'online') {
              if (type === 'boolean') s += 6;
              if (role.includes('indicator.reachable') || role.includes('indicator.connected') || role.includes('indicator.online')) s += 6;
              if (idLower.includes('online') || idLower.includes('reachable') || idLower.includes('connected')) s += 4;
              if (read) s += 1;
            } else if (kind === 'setCurrentA') {
              if (type === 'number') s += 2;
              if (write) s += 10;
              if (unit === 'a') s += 10;
              if (idLower.includes('current')) s += 5;
              if (role.includes('level')) s += 2;
            } else if (kind === 'setPowerW') {
              if (type === 'number') s += 2;
              if (write) s += 10;
              if (unit === 'w') s += 10;
              if (idLower.includes('power')) s += 5;
              if (role.includes('level')) s += 2;
            } else if (kind === 'enableWrite') {
              if (type === 'boolean') s += 5;
              if (write) s += 10;
              if (idLower.includes('enable') || idLower.includes('enabled') || idLower.includes('active') || idLower.includes('authorize')) s += 4;
              if (role.includes('switch') || role.includes('button')) s += 2;
            } else if (kind === 'active') {
              if (type === 'boolean') s += 5;
              if (idLower.includes('active') || idLower.includes('enabled')) s += 4;
              if (read) s += 1;
            }

            return s;
          } catch (_e) {
            return 0;
          }
        };
        /**
         * Code-Teil: pickBestId
         * Zweck: Kapselt einen lokalen Verarbeitungsschritt, damit Aufrufer nicht direkt in Detaildaten eingreifen.
         * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
         * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
         */
        const pickBestId = (states, kind) => {
          let best = '';
          let bestScore = 0;
          for (const it of states || []) {
            const sc = scoreState(it, kind);
            if (sc > bestScore) {
              bestScore = sc;
              best = it && it.id ? String(it.id) : '';
            }
          }

          // Require a minimum confidence to avoid wrong auto-mapping
          return (bestScore >= 8) ? best : '';
        };

        let connectors = [];
        for (const g of Object.values(groups)) {
          const st = g.states || [];

          const ids = {
            powerId: pickBestId(st, 'power'),
            energyTotalId: pickBestId(st, 'energy'),
            statusId: pickBestId(st, 'status'),
            onlineId: pickBestId(st, 'online'),
            setCurrentAId: pickBestId(st, 'setCurrentA'),
            setPowerWId: pickBestId(st, 'setPowerW'),
            enableWriteId: pickBestId(st, 'enableWrite'),
            activeId: pickBestId(st, 'active'),
          };
          const hasAny = Object.values(ids).some(v => v && String(v).trim());
          if (!hasAny) continue;

          const energyState = (st || []).find((entry) => entry && String(entry.id || '') === String(ids.energyTotalId || ''));
          const energyUnit = String(energyState && energyState.common ? energyState.common.unit || '' : '').replace(/\s+/g, '').toLowerCase();
          const energyTotalInputIsWh = energyUnit === 'wh';

          const stationKey = String(g.stationKey || '').trim();
          const connectorNo = Number(g.connectorNo) || 0;

          const name = stationKey
            ? (`${stationKey}${connectorNo ? (' Port ' + connectorNo) : ''}`)
            : (`OCPP${connectorNo ? (' Port ' + connectorNo) : ''}`);

          connectors.push({
            stationKey,
            connectorNo,
            base: String(g.base || ''),
            name,
            ids,
            energyTotalInputIsWh,
            energyUnit,
          });
        }

        // Heuristics for ioBroker OCPP adapter:
        // - If a station has connectors 1..N, connector 0 is typically "Main" and should NOT create
        //   an extra Ladepunkt. Connector 0 may provide a shared station-online signal, but its
        //   connector status must never be inherited by connector 1..N. Faulted/Preparing/Charging
        //   remain connector-specific truths.
        try {
          const byStation = {};
          for (const c of connectors) {
            const key = String(c.stationKey || '').trim() || String(c.base || '');
            if (!byStation[key]) byStation[key] = [];
            byStation[key].push(c);
          }

          // Propagate only true station-level IDs. `statusId` is deliberately
          // excluded because connector 0 is not the operating status of connector 1..N.
          for (const arr of Object.values(byStation)) {
            const c0 = (arr || []).find(x => Number(x && x.connectorNo) === 0);
            if (!c0 || !c0.ids) continue;
            for (const cx of (arr || [])) {
              if (!cx || Number(cx.connectorNo) <= 0) continue;
              cx.ids = (cx.ids && typeof cx.ids === 'object') ? cx.ids : {};
              // Connector 0 darf ausschließlich die Stations-Erreichbarkeit liefern.
              // Enable-/Active-/Status-DPs sind connectorbezogene Aktorwahrheiten und
              // werden niemals auf Connector 1..N vererbt.
              if (!cx.ids.onlineId && c0.ids.onlineId) cx.ids.onlineId = c0.ids.onlineId;
            }
          }

          // Filter: drop connector 0 if there is any numbered connector
          const filtered = [];
          for (const arr of Object.values(byStation)) {
            const hasNumbered = (arr || []).some(x => x && Number(x.connectorNo) > 0);
            if (hasNumbered) {
              for (const cx of (arr || [])) {
                if (cx && Number(cx.connectorNo) > 0) filtered.push(cx);
              }
            } else {
              filtered.push(...(arr || []));
            }
          }
          connectors = filtered;
        } catch (_e) {}

        connectors.sort((a, b) => {
          const ak = String(a.stationKey || '');
          const bk = String(b.stationKey || '');
          if (ak !== bk) return ak.localeCompare(bk);
          return (Number(a.connectorNo) || 0) - (Number(b.connectorNo) || 0);
        });

        const limited = connectors.slice(0, maxConnectors);

        res.json({
          ok: true,
          ts: now,
          usedFallback,
          totalStates: Object.keys(objects || {}).length,
          connectorCount: connectors.length,
          connectors: limited,
        });
      } catch (e) {
        try { this.log.warn('OCPP discover API error: ' + (e && e.message ? e.message : e)); } catch (_e2) {}
        res.status(500).json({ ok: false, error: 'internal error' });
      }
    });

    // --- NexoWatt-Devices discovery (Installer → Schnell‑Inbetriebnahme) ---
    // Scans foreign objects under `nexowatt-devices.*.devices.*` and returns a compact
    // device list with known alias datapoints (aliases.*). The frontend can use this to
    // auto-fill App-Center mappings (EVCS / PV‑Regelung / Thermik / §14a).
    //
    // IMPORTANT: This endpoint only discovers; it never writes config.
    // Der Kundentarif gilt für die gesamte Anlage. Der Kunde kann ausschließlich
    // Anbieter/Vertragswerte wählen; Anlagenfreigaben und freie DP-Pfade bleiben geschützt.
    const requireCustomerTariff = async (req, res, next) => {
      if (!['customer', 'installer', 'admin'].includes(req.nwSession?.role)) return res.status(403).json({ ok: false, error: 'forbidden' });
      if (!this._nwIsFeatureLicensed('dynamicTariffs')) return res.status(403).json({ ok: false, error: 'EOS_TARIFF_LICENSE_REQUIRED' });
      return next();
    };
    const customerTariffSnapshot = () => {
      const root = this.nwApplyInstallerPatchToRuntimeConfig(this.config || {}, this._nwInstallerConfigPatch || {});
      return { ok: true, revision: this._nwInstallerConfigRevision(),
        ...customerTariffView(root, this.namespace, tariffProviderRegistry.publicRegistry(), this._tariffProviderSnapshot) };
    };
    app.get('/api/customer/tariff-provider', requireCustomerWorkspace, requireCustomerTariff, (_req, res) => {
      try { sendNoStore(res); res.json(customerTariffSnapshot()); }
      catch (error) { const failure = safeConfigurationFailure(error); res.status(failure.status).json(failure.body); }
    });
    app.put('/api/customer/tariff-provider', requireCustomerWorkspace, requireCustomerTariff, async (req, res) => {
      const token = beginMeshAppSave();
      if (!token) return res.status(409).json({ ok: false, error: 'EOS_TARIFF_BUSY', message: 'Eine Einstellung wird gerade gespeichert. Bitte kurz warten.' });
      try {
        sendNoStore(res);
        const body = req.body;
        if (!body || typeof body !== 'object' || Array.isArray(body)
          || Object.keys(body).some(key => !['expectedRevision', 'config'].includes(key))) {
          throw createPublicHttpError(422, 'EOS_TARIFF_INVALID', 'Die Tarifanfrage enthält unzulässige Felder.');
        }
        // Unlike legacy installer clients, this new API always requires a freshly loaded revision.
        if (typeof body.expectedRevision !== 'string' || body.expectedRevision !== this._nwInstallerConfigRevision()) {
          throw createPublicHttpError(409, 'EOS_TARIFF_CONFIG_CHANGED', 'Die Anlageneinstellungen wurden inzwischen geändert. Bitte den Tarif neu laden und deine Eingaben vergleichen.');
        }
        if (this._nwShuttingDown || this._bridge.canWrite() !== true) throw createPublicHttpError(409, 'EOS_UI_OWNERSHIP_REQUIRED', 'Die Systemfreigabe ist nicht verfügbar.');
        const effective = this.nwApplyInstallerPatchToRuntimeConfig(this.config || {}, this._nwInstallerConfigPatch || {});
        const changed = prepareCustomerTariffChange(effective, body.config, this.namespace, tariffProviderRegistry.publicRegistry());
        const patch = this._nwDeepClone(this._nwInstallerConfigPatch || {});
        patch.tariffProvider = changed.tariffProvider;
        if (changed.datapoints) patch.datapoints = changed.datapoints;
        if (await this.persistInstallerConfigToState(patch) === false) throw createPublicHttpError(503, 'EOS_TARIFF_SAVE_FAILED', 'Der Tarif konnte nicht gespeichert werden. Bisherige Einstellungen bleiben bestehen.');
        this._nwInstallerConfigPatch = patch;
        this._nwInstallerConfigRawPatch = this._nwDeepClone(patch);
        this.config = this.nwApplyInstallerPatchToRuntimeConfig(this.config || {}, patch);
        try {
          const tariffModule = this.emsEngine?.mm?.modules?.find(entry => entry.key === 'tariffProvider')?.instance;
          if (tariffModule && typeof tariffModule.invalidateConfiguration === 'function') await tariffModule.invalidateConfiguration();
          if (changed.datapoints && tariffModule && typeof tariffModule.applyTariffMappings === 'function') await tariffModule.applyTariffMappings();
          // No EMS restart and no actuator activation. Changed read mappings use existing subscriptions.
          if (changed.datapoints) await this.subscribeConfiguredStates();
        } catch (_error) {
          throw createPublicHttpError(503, 'EOS_TARIFF_APPLY_PENDING', 'Der Tarif ist gespeichert. Die Übernahme der neuen Preisquelle ist noch nicht bestätigt; bitte Status neu laden.');
        }
        try { await this.nwWriteUserdataBackup(patch, 'customer-tariff'); }
        catch (_error) { this.log.warn('EOS_TARIFF_BACKUP_FAILED: Tarif gespeichert; zusätzliche Sicherung fehlgeschlagen.'); }
        res.json(customerTariffSnapshot());
      } catch (error) {
        const failure = safeConfigurationFailure(error);
        res.status(failure.status).json(failure.body);
      } finally { endMeshAppSave(token); }
    });

    // Dynamische Tarife: Provider-Katalog und Verbindungstest. Die APIs sind
    // installergeschützt und geben niemals Token/Secrets zurück.
    app.get('/api/installer/tariff-provider/providers', requireInstaller, async (_req, res) => {
      try {
        sendNoStore(res);
        const registry = tariffProviderRegistry.publicRegistry();
        const ns = String(this.namespace || `nexowatt-ui.${this.instance || 0}`);
        const internalDatapoints = {};
        for (const [key, suffix] of Object.entries(registry.internalDatapoints || {})) {
          internalDatapoints[key] = `${ns}.${suffix}`;
        }
        res.json({ ok: true, ...registry, internalDatapoints });
      } catch (e) {
        res.status(500).json({ ok: false, error: 'provider_registry_failed', message: 'Anfrage konnte intern nicht verarbeitet werden.' });
      }
    });

    app.post('/api/installer/tariff-provider/test', requireInstaller, async (req, res) => {
      try {
        sendNoStore(res);
        const body = req && req.body && typeof req.body === 'object' ? req.body : {};
        const persisted = _nwPickPersistedInstallerConfig();
        const incoming = body.config && typeof body.config === 'object' ? body.config : {};
        const mergedProvider = _nwMergeTariffProviderSecrets(incoming, persisted && persisted.tariffProvider);
        const normalized = this.nwNormalizeInstallerPatch({ tariffProvider: mergedProvider }, this.config || {});
        const cfg = normalized && normalized.patch && normalized.patch.tariffProvider ? normalized.patch.tariffProvider : mergedProvider;
        if (String(cfg.providerId || 'manual-dp') === 'manual-dp') {
          return res.json({ ok: true, status: 'manual-datapoints', providerId: 'manual-dp', intervalCount: 0, note: 'Manuelle Datenpunkte benötigen keinen API-Test.' });
        }
        const result = await tariffProviderRegistry.fetchProvider(cfg);
        const intervals = Array.isArray(result && result.intervals) ? result.intervals : [];
        const now = Date.now();
        const split = tariffProviderRegistry.splitTodayTomorrow(intervals, now, cfg.timeZone);
        const values = tariffProviderRegistry.currentAndAverage(intervals, now);
        res.json({
          ok: true,
          status: 'ok',
          providerId: String(cfg.providerId || ''),
          sourceId: String(cfg.sourceId || cfg.providerId || ''),
          intervalCount: intervals.length,
          todayCount: split.today.length,
          tomorrowCount: split.tomorrow.length,
          currentPriceEurPerKwh: Number.isFinite(values.current) ? values.current : null,
          averagePriceEurPerKwh: Number.isFinite(values.average) ? values.average : null,
          firstStartsAt: intervals[0] ? intervals[0].startsAt : '',
          lastEndsAt: intervals.length ? intervals[intervals.length - 1].endsAt : '',
          sample: intervals.slice(0, 4),
        });
      } catch (e) {
        const message = String(e && e.message || e || 'provider_test_failed').replace(/Bearer\s+[A-Za-z0-9._~+\/-]+/gi, 'Bearer ***').slice(0, 500);
        res.status(400).json({ ok: false, error: 'provider_test_failed', message });
      }
    });

    // API-Kommentar: GET-Route. Zweck: stellt einen Web-/API-Endpunkt bereit. Zusammenhang: Frontend-Dateien in www/* können diesen Endpunkt direkt nutzen. Route/Handler: '/api/nwdevices/discover', requireInstaller, async (_req, res) => {
    app.get('/api/nwdevices/discover', requireInstaller, async (_req, res) => {
      try {
        const now = Date.now();
        const patterns = ['nexowatt-devices.*.devices.*', `${this._owner.namespace}.devices.*`];
        const devChannels = {}; const stateObjects = {}; const manifestStates = {};
        for (const pattern of patterns) {
          Object.assign(devChannels, await this.getForeignObjectsAsync(pattern, 'channel'));
          Object.assign(stateObjects, await this.getForeignObjectsAsync(pattern, 'state'));
          if (typeof this.getForeignStatesAsync === 'function') {
            Object.assign(manifestStates, await this.getForeignStatesAsync(`${pattern}.aliases.meta.manifest`));
          }
        }

        const statesByDev = new Map();
        for (const [stateId, obj] of Object.entries(stateObjects || {})) {
          const sid = String(stateId || '');
          const match = sid.match(/^((?:nexowatt-devices|eos-admin)\.\d+\.devices\..+)\.aliases\./);
          if (!match) continue;
          if (!statesByDev.has(match[1])) statesByDev.set(match[1], {});
          statesByDev.get(match[1])[sid] = obj;
        }
        const normName = (value) => {
          if (typeof value === 'string') return value.trim();
          if (value && typeof value === 'object') {
            const first = value.de || value.en || value.nl || value.text || Object.values(value).find((x) => typeof x === 'string');
            return typeof first === 'string' ? first.trim() : '';
          }
          return '';
        };
        const parseManifest = (baseId) => {
          const stateId = `${baseId}.aliases.meta.manifest`;
          const raw = manifestStates && manifestStates[stateId] ? manifestStates[stateId].val : null;
          if (raw && typeof raw === 'object') return raw;
          if (typeof raw === 'string' && raw.trim()) {
            try { return JSON.parse(raw); } catch (_e) {}
          }
