        const rawIds = Array.isArray(body.ids) ? body.ids : [];
        const maxAgeMs = (body.maxAgeMs !== undefined && body.maxAgeMs !== null && Number.isFinite(Number(body.maxAgeMs)))
          ? Math.max(0, Math.round(Number(body.maxAgeMs)))
