        /** @type {string[]} */
        const ids = [];
        const seen = new Set();
        for (const raw of rawIds) {
          const id = (raw === null || raw === undefined) ? '' : String(raw).trim();
          if (!id) continue;
          if (seen.has(id)) continue;
