// NexoLogic kann frei zugeordnete Datenpunkte schreiben: Einrichtung nur für Installer/Admin.
app.post('/api/logic/editor', requireNexoLogicConfig, async (req, res) => {
  const mutationToken = beginMeshAppSave();
  if (!mutationToken) return res.status(409).json({ ok: false, error: 'INSTALLER_CONFIG_BUSY' });
  try {
    const previousConfig = this.getLogicEditorConfig ? this._nwDeepClone(this.getLogicEditorConfig()) : this._nwDeepClone((this.config && this.config.logicEditor) || { version: 1, graphs: [] });
    const body = (req && req.body) || {};
    const inCfg = body.config;
    const out = this.nwNormalizeLogicEditorConfig(inCfg);
    const validation = this.nwValidateLogicEditorConfig(out);
    if (!validation.ok) {
      return res.status(400).json({ ok: false, error: 'NexoLogic-Konfiguration ist ungültig.', issues: validation.errors });
    }

    // Zuerst die neue Runtime vollständig starten. Schlägt dies fehl, bleibt die
    // vorherige Konfiguration aktiv beziehungsweise wird automatisch reaktiviert.
    await this.replaceLogicEngine(out, previousConfig);
    this.config = this.config || {};
    this.config.logicEditor = out;

    try {
      // Der gespeicherte Gesamtpatch bleibt die Basis; die Normalisierung liefert
      // einen {patch, changed}-Wrapper, der selbst keine Installer-Konfiguration ist.
      const basePatch = this._nwInstallerConfigPatch || {};
      const merged = this.nwDeepMerge(this._nwDeepClone(basePatch), { logicEditor: out });
      const normalized = this.nwNormalizeInstallerPatch(merged, this.config || {});
      const patch = normalized.patch;
      const persisted = await this.persistInstallerConfigToState(patch);
      if (persisted === false) throw new Error('Konfiguration konnte nicht persistent gespeichert werden.');
      this._nwInstallerConfigPatch = patch;
      res.json({ ok: true, config: out, persisted: persisted !== false, validation });
    } catch (persistError) {
      await this.replaceLogicEngine(previousConfig, null);
      this.config.logicEditor = previousConfig;
      throw persistError;
    }
  } catch (e) {
    const failure = safeConfigurationFailure(e);
    this.log.warn('Logic editor SAVE error: ' + failure.body.error);
    const issues = failure.body.error === 'NEXOLOGIC_CONFIG_INVALID' && 'details' in failure.body ? failure.body.details : [];
    res.status(failure.status).json({ ...failure.body, issues });
  } finally { endMeshAppSave(mutationToken); }
});

