      };
      const start = queryNumber('from', Date.now() - 24*3600*1000);
      const end = queryNumber('to', Date.now());
      // Historie wird im 10‑Minuten‑Raster nach Influx geschrieben.
      // Default daher ebenfalls 10 Minuten (Frontend kann weiterhin explizit steuern).
      const stepS = queryNumber('step', 600);
      // Bound allocations before asking the history provider. Normal day/week/
      // month/year presets use at most 745 buckets. Larger custom selections
      // must request a coarser step instead of allocating millions of pairs.
      const maxHistoryPoints = 4096;
      if (!Number.isSafeInteger(start) || !Number.isSafeInteger(end) || start < 0 || end <= start ||
          !Number.isFinite(stepS) || stepS <= 0 || !Number.isFinite(stepS * 1000) ||
          Math.ceil((end - start) / Math.max(60000, stepS * 1000)) + 1 > maxHistoryPoints) {
        return res.status(400).json({ ok: false, error: 'EOS_HISTORY_RANGE_INVALID' });
      }
      const historyCfgSig = JSON.stringify({
        h: (this.config && this.config.history) || {},
        d: (this.config && this.config.datapoints) || {},
        v: (this.config && this.config.vis && this.config.vis.flowSlots) || {},
        evcsCount: Number(this.evcsCount || 0),
        dyn: !!(this.stateCache?.['settings.dynamicTariff']?.value),
        fee: !!(this.stateCache?.['settings.netFeeEnabled']?.value),
        price: Number(this.stateCache?.['settings.price']?.value || 0),
      });
      const cacheKey = `${start}|${end}|${stepS}|${historyCfgSig}`;
      const cachedPayload = this._nwGetHistoryApiCached(cacheKey, 5000);
      if (cachedPayload) return res.json(cachedPayload);
      if (this._nwHistoryApiInflight instanceof Map && this._nwHistoryApiInflight.has(cacheKey)) {
        try {
          const inflightPayload = await this._nwHistoryApiInflight.get(cacheKey);
          if (inflightPayload) return res.json(inflightPayload);
        } catch (_e) {}
      }
      // Keep identical requests deduplicated and put backpressure on distinct
      // computations; deleting an in-flight Map entry would not stop its work.
      if (!(this._nwHistoryApiInflight instanceof Map)) this._nwHistoryApiInflight = new Map();
      if (this._nwHistoryApiInflight.size >= 4) {
        return res.status(503).json({ ok: false, error: 'EOS_HISTORY_BUSY' });
      }
      const historyDeadlineMs = performance.now() + 5000;
      const requestCancels = new Set();
      /**
       * Code-Teil: computeHistoryPayload
       * Zweck: Berechnet abgeleitete Werte.
       * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
       * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
       */
      const computeHistoryPayload = (async () => {
      try {
        const inst = this._nwGetHistoryInstance();
        // sendTo callbacks run after the surrounding route try/catch has left.
        // Settle errors inside the callback and share one budget across all
        // candidate fallbacks, counters and current-state reads.
        const historyRequest = (dispatch, normalize) => new Promise((resolve, reject) => {
          const failure = code => Object.assign(new Error(code), { code });
          if (this._nwShuttingDown) return reject(failure('EOS_HISTORY_CANCELLED'));
          const remainingMs = historyDeadlineMs - performance.now();
          if (remainingMs <= 0) return reject(failure('EOS_HISTORY_TIMEOUT'));
          let settled = false;
          let timer = null;
          const finish = (error, value) => {
            if (settled) return;
            settled = true;
            if (timer) clearTimeout(timer);
            this._nwPendingHistoryRequests?.delete(cancel);
            requestCancels.delete(cancel);
            if (error) reject(error);
            else resolve(value);
          };
          const cancel = () => finish(failure('EOS_HISTORY_CANCELLED'));
          if (!(this._nwPendingHistoryRequests instanceof Set)) this._nwPendingHistoryRequests = new Set();
          this._nwPendingHistoryRequests.add(cancel);
          requestCancels.add(cancel);
          timer = setTimeout(() => finish(failure('EOS_HISTORY_TIMEOUT')), remainingMs);
          timer.unref?.();
          const reply = value => {
            if (settled) return;
            if (this._nwShuttingDown) return cancel();
            if (performance.now() >= historyDeadlineMs) return finish(failure('EOS_HISTORY_TIMEOUT'));
            try { finish(null, normalize(value)); }
            catch (_e) { finish(failure('EOS_HISTORY_RESPONSE_INVALID')); }
          };
          try {
            // Also observe transports that return a rejecting Promise despite
            // having a callback signature. No detached rejection may escape.
            const pending = dispatch(reply);
            if (pending && typeof pending.then === 'function') {
              Promise.resolve(pending).catch(() => finish(failure('EOS_HISTORY_UNAVAILABLE')));
            }
          } catch (_e) { finish(failure('EOS_HISTORY_UNAVAILABLE')); }
        });

        // For many states we log data sparsely (e.g. only "on change").
        // In that case the aggregated history query only returns values for time-buckets
        // that contain at least one raw datapoint. Buckets without any datapoint are missing.
        // If we draw a line chart on such sparse buckets, the renderer connects far away points
        // with long diagonal lines (looks like ramps) which is misleading and was not intended.
        //
        // Solution: densify the returned data to an equidistant time-grid ("step") and
        // forward-fill (hold last) values. This yields clean plots and also improves the
        // kWh integration in the frontend.
        const stepMs = Math.max(60_000, stepS * 1000);
        const requestSeriesCache = new Map();
        /**
         * Code-Teil: densifyHoldLast
         * Zweck: Kapselt einen klar abgegrenzten Verarbeitungsschritt innerhalb dieser Datei.
         * Zusammenhang: Gehört zu ioBroker-Adapterkern (Adapter-Lifecycle, Webserver, REST-/SSE-API, State-Anlage, Lizenz und EMS-Engine) und wird von benachbarten UI-/API-/EMS-Bausteinen genutzt.
         * Wartung/TypeScript: Änderungen können Adapterstart, APIs, States und Webserver beeinflussen; unload/connection immer mittesten. Beim TS-Umbau Parameter, Rückgabe und genutzte State-/Config-Objekte explizit typisieren.
         */
        const densifyHoldLast = (values, rangeStart = start, rangeEnd = end, rangeStepMs = stepMs, maxHoldMs = Infinity) => {
          const rStart = Number(rangeStart);
          const rEnd = Number(rangeEnd);
          const rStep = Number(rangeStepMs);
          if (!Array.isArray(values) || values.length === 0 || !Number.isFinite(rStart) || !Number.isFinite(rEnd) || !Number.isFinite(rStep) || rStep <= 0) {
            return Array.isArray(values) ? values : [];
          }

          const n = Math.max(0, Math.floor((rEnd - rStart) / rStep));
          if (n + 2 > maxHistoryPoints + 1) throw new Error('EOS_HISTORY_RANGE_INVALID');
          const byIdx = new Map();

          for (const row of values) {
            const ts = normTsMs(row?.[0]);
            const val = Number(row?.[1]);
            if (!Number.isFinite(ts)) continue;

            const idx = Math.round((ts - rStart) / rStep);
            if (idx < 0 || idx > n) continue;
            if (!Number.isFinite(val)) continue;

            byIdx.set(idx, val);
          }

          const out = [];
          let havePrev = false;
          let prev = null;
          let prevTs = -Infinity;
          for (let i = 0; i <= n; i++) {
            if (byIdx.has(i)) {
              prev = byIdx.get(i);
              havePrev = true;
              prevTs = rStart + i * rStep;
            }
            const ts = rStart + i * rStep;
            out.push([ts, havePrev && ts - prevTs <= maxHoldMs ? prev : null]);
          }

          // Ensure the series reaches exactly `rangeEnd` so the chart does not visually "stop"
          // before the right edge when the end is not aligned to the step grid.
          // This also improves kWh integration for the last partial bucket.
          if (out.length) {
            const lastTs = out[out.length - 1][0];
            if (Number.isFinite(lastTs) && lastTs < rEnd) {
              out.push([rEnd, havePrev && rEnd - prevTs <= maxHoldMs ? prev : null]);
            }
          }
          return out;
        };

        // History series should keep backward compatibility with legacy mapped
        // helper states, but also work out of the box with the adapter's canonical
        // historie.* states. Therefore we try configured mappings first and fall back
        // automatically to the canonical adapter Historie IDs.
        const idCandidates = {
          pv: this._nwGetHistoryDpCandidates('pvPower'),
          load: this._nwGetHistoryDpCandidates('consumptionTotal'),
          buy: this._nwGetHistoryDpCandidates('gridBuyPower'),
          sell: this._nwGetHistoryDpCandidates('gridSellPower'),
          chg: this._nwGetHistoryDpCandidates('storageChargePower'),
          dchg: this._nwGetHistoryDpCandidates('storageDischargePower'),
          soc: this._nwGetHistoryDpCandidates('storageSoc'),
          evcs: this._nwGetHistoryDpCandidates('evcsPower'),
          priceBase: this._nwGetHistoryDpCandidates('priceBase'),
          priceNetFee: this._nwGetHistoryDpCandidates('priceNetFee'),
          priceTotal: this._nwGetHistoryDpCandidates('priceTotal')
        };

        // Optional series (Energiefluss: Verbraucher/Erzeuger)
        // NOTE: We only include configured slots so the frontend can hide them when not set up.
        const dps = (this.config && this.config.datapoints) || {};
        const vis = (this.config && this.config.vis) || {};
        const fs = (vis && vis.flowSlots && typeof vis.flowSlots === 'object') ? vis.flowSlots : {};

        const extraConsumerReq = [];
        const extraProducerReq = [];

        const MAX_CONSUMERS = 10;
        const MAX_PRODUCERS = 5;

        for (let i = 1; i <= MAX_CONSUMERS; i++) {
          const info = this._nwGetFlowSlotInfo ? this._nwGetFlowSlotInfo('consumers', i) : null;
          const mapped = info && String(info.objectId || '').trim();
          if (!mapped) continue;
          const dpKey = info && info.key ? info.key : `consumer${i}Power`;
          const name = info && info.name ? String(info.name) : `Verbraucher ${i}`;
          const candidates = this._nwGetHistoryDpCandidates(dpKey);
          extraConsumerReq.push({ idx: i, name, candidates });
        }

        for (let i = 1; i <= MAX_PRODUCERS; i++) {
          const info = this._nwGetFlowSlotInfo ? this._nwGetFlowSlotInfo('producers', i) : null;
          const mapped = info && String(info.objectId || '').trim();
          if (!mapped) continue;
          const dpKey = info && info.key ? info.key : `producer${i}Power`;
          const name = info && info.name ? String(info.name) : `Erzeuger ${i}`;
          const candidates = this._nwGetHistoryDpCandidates(dpKey);
          extraProducerReq.push({ idx: i, name, candidates });
        }
        /**
         * Code-Teil: normTsMs
         * Zweck: Kapselt einen lokalen Verarbeitungsschritt, damit Aufrufer nicht direkt in Detaildaten eingreifen.
         * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
         * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
         */
        const normTsMs = (ts) => {
          if (ts === null || ts === undefined) return null;
          if (typeof ts === 'number') {
            if (!Number.isFinite(ts)) return null;
            // Heuristic: influxdb can return seconds; we need ms
            if (ts > 0 && ts < 1e12) return Math.round(ts * 1000);
            return Math.round(ts);
          }
          if (ts instanceof Date) return ts.getTime();
          if (typeof ts === 'string') {
            const s = ts.trim();
            if (!s) return null;
            const asNum = Number(s);
            if (Number.isFinite(asNum)) {
              if (asNum > 0 && asNum < 1e12) return Math.round(asNum * 1000);
              return Math.round(asNum);
            }
            const parsed = Date.parse(s);
            if (!Number.isNaN(parsed)) return parsed;
            return null;
          }
          const n = Number(ts);
          if (Number.isFinite(n)) {
            if (n > 0 && n < 1e12) return Math.round(n * 1000);
            return Math.round(n);
          }
          return null;
        };

        /**
         * Code-Teil: ask
         * Zweck: Kapselt einen klar abgegrenzten Verarbeitungsschritt innerhalb dieser Datei.
         * Zusammenhang: Gehört zu ioBroker-Adapterkern (Adapter-Lifecycle, Webserver, REST-/SSE-API, State-Anlage, Lizenz und EMS-Engine) und wird von benachbarten UI-/API-/EMS-Bausteinen genutzt.
         * Wartung/TypeScript: Änderungen können Adapterstart, APIs, States und Webserver beeinflussen; unload/connection immer mittesten. Beim TS-Umbau Parameter, Rückgabe und genutzte State-/Config-Objekte explizit typisieren.
         */
        const ask = (id, query = {}) => {
          const sid = this._nwTrimId(id);
          const queryStart = Number.isFinite(Number(query.start)) ? Number(query.start) : start;
          const queryEnd = Number.isFinite(Number(query.end)) ? Number(query.end) : end;
          const queryStepMs = Math.max(60 * 1000, Number.isFinite(Number(query.stepMs)) ? Number(query.stepMs) : (stepS * 1000));
          const cacheId = sid || String(id || '');
          const cacheKey = `${cacheId}|${queryStart}|${queryEnd}|${queryStepMs}`;
          if (requestSeriesCache.has(cacheKey)) return requestSeriesCache.get(cacheKey);
          const options = { start: queryStart, end: queryEnd, step: queryStepMs, aggregate: 'average', addId: false, ignoreNull: true };
          // Canonical power/SoC states are exported periodically even when unchanged
          // (tolAbs=0, Influx changesOnly=false). Missing later buckets are unknown,
          // not permission to extend an old measurement across a device outage.
          // Explicit legacy mappings and tariff states can be on-change: keep their
          // established sparse-series contract instead of inventing a freshness age.
          const periodicHistory = ['core.', 'evcs.', 'consumers.', 'producers.']
            .some(part => sid?.startsWith(`${this.namespace}.historie.${part}`));
          const exportRaw = Number(this.config?.history?.exportIntervalMs || this.config?.history?.intervalMs);
          const exportMs = Math.max(600000, Math.min(3600000, Number.isFinite(exportRaw) ? Math.round(exportRaw) : 600000));
          const maxHoldMs = periodicHistory ? Math.max(exportMs, queryStepMs) : Infinity;
          const promise = !sid ? Promise.resolve({ id: sid || id, values: [] }) : historyRequest(
            callback => this._nwDispatchHistory(inst, { id: sid, options }, callback),
            result => ({ id: sid, values: densifyHoldLast(
              this._nwNormalizeHistoryResult(result, 10000).map(point => [point.ts, point.val]),
              queryStart, queryEnd, queryStepMs, maxHoldMs,
            ) }),
          );

          requestSeriesCache.set(cacheKey, promise);
          return promise;
        };

        /**
         * Code-Teil: askCandidates
         * Zweck: Kapselt einen klar abgegrenzten Verarbeitungsschritt innerhalb dieser Datei.
         * Zusammenhang: Gehört zu ioBroker-Adapterkern (Adapter-Lifecycle, Webserver, REST-/SSE-API, State-Anlage, Lizenz und EMS-Engine) und wird von benachbarten UI-/API-/EMS-Bausteinen genutzt.
         * Wartung/TypeScript: Änderungen können Adapterstart, APIs, States und Webserver beeinflussen; unload/connection immer mittesten. Beim TS-Umbau Parameter, Rückgabe und genutzte State-/Config-Objekte explizit typisieren.
         */
        const askCandidates = async (candidates, query = {}) => {
          const list = Array.isArray(candidates) ? candidates : [candidates];
          let first = null;
          for (const candidate of list) {
            const sid = this._nwTrimId(candidate);
            if (!sid) continue;
            const resu = await ask(sid, query);
            if (!first) first = resu;
            if (Array.isArray(resu && resu.values) && resu.values.length >= 2) return resu;
          }
          return first || { id: '', values: [] };
        };

        const dynamicTariffActiveNow = !!(this.stateCache && this.stateCache['settings.dynamicTariff'] && this.stateCache['settings.dynamicTariff'].value);
        const netFeeActiveNow = !!(this.stateCache && this.stateCache['settings.netFeeEnabled'] && this.stateCache['settings.netFeeEnabled'].value);
        const pricingActiveNow = !!(dynamicTariffActiveNow || netFeeActiveNow);
        const wantSocSeries = stepMs <= (10 * 60 * 1000);
        const manualGrossPriceNow = tariffPriceNumber(this.stateCache?.['settings.price']?.value);
        const grossPriceCandidates = [
          `${this.namespace}.historie.tariff.providerCurrentEurPerKwh`,
          `${this.namespace}.tarif.preisAktuellEurProKwh`,
