        const emptySeries = { id: '', values: [] };

        const [pv, load, buy, sell, chg, dchg, soc, evcs, priceBase, priceNetFee, priceTotal, priceGross] = await Promise.all([
          askCandidates(idCandidates.pv),
          askCandidates(idCandidates.load),
          askCandidates(idCandidates.buy),
          askCandidates(idCandidates.sell),
          askCandidates(idCandidates.chg),
          askCandidates(idCandidates.dchg),
          wantSocSeries ? askCandidates(idCandidates.soc) : Promise.resolve(emptySeries),
          askCandidates(idCandidates.evcs),
          pricingActiveNow ? askCandidates(idCandidates.priceBase) : Promise.resolve(emptySeries),
          pricingActiveNow ? askCandidates(idCandidates.priceNetFee) : Promise.resolve(emptySeries),
          pricingActiveNow ? askCandidates(idCandidates.priceTotal) : Promise.resolve(emptySeries),
          pricingActiveNow ? askCandidates(grossPriceCandidates) : Promise.resolve(emptySeries)
        ]);
        /**
         * Code-Teil: _normalizeHistoryPairs
         * Zweck: Kapselt einen lokalen Verarbeitungsschritt, damit Aufrufer nicht direkt in Detaildaten eingreifen.
         * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
         * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
         */
        const _normalizeHistoryPairs = (values) => {
          const out = [];
          const src = Array.isArray(values) ? values : [];
          for (const row of src) {
            if (!Array.isArray(row) || row.length < 2 || row[1] === null || row[1] === undefined) continue;
            const ts = normTsMs(row[0]);
            const val = Number(row[1]);
            if (!Number.isFinite(ts) || !Number.isFinite(val)) continue;
            out.push([ts, val]);
          }
          out.sort((a, b) => a[0] - b[0]);
          return out;
        };
        /**
         * Code-Teil: _valueAtHold
         * Zweck: Kapselt einen lokalen Verarbeitungsschritt, damit Aufrufer nicht direkt in Detaildaten eingreifen.
         * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
         * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
         */
        const _valueAtHold = (pairs, ts) => {
          // _normalizeHistoryPairs already returns sorted finite rows. Binary
          // search preserves last-value semantics (including duplicate times)
          // without rescanning a year of prices for every chart bucket.
          const src = Array.isArray(pairs) ? pairs : [];
          let low = 0;
          let high = src.length;
          while (low < high) {
            const mid = low + Math.floor((high - low) / 2);
            if (src[mid][0] <= ts) low = mid + 1;
            else high = mid;
          }
          return low > 0 ? src[low - 1][1] : null;
        };

