        const normalizedPricingSeries = _buildNormalizedPricingSeries({
          startTs: start,
          endTs: end,
          grossSeries: priceGross,
          baseSeries: priceBase,
          totalSeries: priceTotal,
          netFeeSeries: priceNetFee,
          manualGrossPrice: manualGrossPriceNow,
          dynamicTariffActive: dynamicTariffActiveNow,
        });

        // --- Robustness for E‑Mobilität (EVCS) ---
        // In der Praxis kann es vorkommen, dass die Historie-Abfrage für den
        // aggregierten EV-Kanal ("historie.core.ev.totalW") leer zurückkommt,
        // obwohl Daten existieren (z.B. falsches Mapping/alte Konfiguration).
        //
        // Ziel: Die VIS-Historie soll immer aus unseren automatisch angelegten
        // Historie-Datenpunkten lesen, ohne dass der Kunde manuell nacharbeiten muss.
        //
        // Fallback-Strategie:
        //  1) Wenn weder explizite History-Mappings noch Auto-Fallback Daten liefern,
        //     versuche den kanonischen DP `${namespace}.historie.core.ev.totalW`.
        //  2) Wenn weiterhin leer: aggregiere aus den pro Ladepunkt angelegten
        //     Historie-DPs `${namespace}.historie.evcs.lpX.powerW`.
        //
        // Damit bekommen wir in jedem Fall eine belastbare Zeitreihe für "E‑Mobilität".
        /**
         * Code-Teil: evcsHasData
         * Zweck: Verarbeitet Wallbox-/Ladepunktdaten und Feature-Sichtbarkeit.
         * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
         * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
         */
        const evcsHasData = (s) => Array.isArray(s?.values) && s.values.length >= 2;
        if (!evcsHasData(evcs)) {
          const canonicalEvcsId = `${this.namespace}.historie.core.ev.totalW`;
          if (evcs.id !== canonicalEvcsId) {
            const alt = await ask(canonicalEvcsId);
            if (evcsHasData(alt)) {
              evcs.id = canonicalEvcsId;
              evcs.values = alt.values;
              evcs._source = 'canonical';
            }
          }
        }
        if (!evcsHasData(evcs)) {
          const count = Number(this.evcsCount || 0);
          if (count > 0) {
            const lpIds = [];
            for (let i = 1; i <= count; i++) {
              lpIds.push(`${this.namespace}.historie.evcs.lp${i}.powerW`);
            }
            const sumByTs = new Map();
            const samplesByTs = new Map();
            // Avoid keeping up to 200 full charge-point arrays alive together.
            // Eight parallel reads still share the whole request deadline.
            for (let offset = 0; offset < lpIds.length; offset += 8) {
              const batchIds = lpIds.slice(offset, offset + 8);
              const lpSeries = await Promise.all(batchIds.map(id => ask(id)));
              for (const series of lpSeries) {
                for (const point of series.values) {
                  const ts = Number(point[0]);
                  if (!Number.isFinite(ts)) continue;
                  if (!sumByTs.has(ts)) sumByTs.set(ts, 0);
                  if (point[1] === null || point[1] === undefined) continue;
                  const value = Number(point[1]);
                  if (!Number.isFinite(ts) || !Number.isFinite(value)) continue;
                  sumByTs.set(ts, (sumByTs.get(ts) || 0) + value);
                  samplesByTs.set(ts, (samplesByTs.get(ts) || 0) + 1);
                }
              }
              for (const id of batchIds) requestSeriesCache.delete(`${id}|${start}|${end}|${Math.max(60000, stepS * 1000)}`);
            }
            const vals = Array.from(sumByTs.entries())
              .sort((a, b) => a[0] - b[0])
              .map(([ts, v]) => [ts, samplesByTs.get(ts) === count ? v : null]);
            if (vals.length >= 2) {
              evcs.id = `${this.namespace}.historie.evcs.sum.powerW`;
              evcs.values = vals;
              evcs._source = 'lp-sum';
            }
          }
        }

        const [extraConsumers, extraProducers] = await Promise.all([
          Promise.all(extraConsumerReq.map(async (c) => {
            const r = await askCandidates(c.candidates);
            return { idx: c.idx, name: c.name, id: r.id, values: r.values };
          })),
          Promise.all(extraProducerReq.map(async (p) => {
            const r = await askCandidates(p.candidates);
            return { idx: p.idx, name: p.name, id: r.id, values: r.values };
          }))
        ]);

// --- Optional: Energy totals from kWh counters (more accurate than integrating W) ---
// If the customer mapped kWh counters in the App-Center, we can compute exact energy
// for the selected range by subtracting counter values (first -> last).
// This removes sampling / bucket effects and aligns better with other EMS.
const energy = {};
const energyEnd = Math.min(end, Date.now());
/**
 * Code-Teil: readCounterPoint
 * Zweck: Liest Werte mit Fallbacks aus Cache/State/Config.
 * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
 * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
 */
const readCounterPoint = (id, newest) => {
  if (!id) return Promise.resolve(null);
  const options = {
    start, end: energyEnd, aggregate: 'none', addId: false, ignoreNull: true,
    count: 1, returnNewestEntries: !!newest, removeBorderValues: false,
  };
  return historyRequest(
    callback => this._nwDispatchHistory(inst, { id, options }, callback),
    result => {
      const points = this._nwNormalizeHistoryResult(result, 10000);
      return points.length ? (newest ? points[points.length - 1] : points[0]) : null;
    },
  );
};
/**
 * Code-Teil: readCurrentCounterPoint
 * Zweck: Liest Werte mit Fallbacks aus Cache/State/Config.
 * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
 * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
 */
const readCurrentCounterPoint = (id) => historyRequest(
  callback => Promise.resolve(this.getForeignStateAsync(id)).then(callback),
  state => {
    // Missing/null state values must not become a new zero counter reading.
    const points = this._nwNormalizeHistoryResult({ result: [state] }, 1);
    return points[0] || null;
  },
);
/**
 * Code-Teil: counterDelta
 * Zweck: Kapselt einen lokalen Verarbeitungsschritt, damit Aufrufer nicht direkt in Detaildaten eingreifen.
 * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
 * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
 */
const counterDelta = async (id) => {
  const a = await readCounterPoint(id, false);
  let b = null;
  const endIsNearNow = Math.abs(Date.now() - energyEnd) <= (12 * 60 * 60 * 1000);
  if (endIsNearNow) {
    try { b = await readCurrentCounterPoint(id); }
    catch (error) {
      if (error?.code !== 'EOS_HISTORY_UNAVAILABLE') throw error;
    }
  }
  if (!b) b = await readCounterPoint(id, true);
  if (!a || !b) return null;
  const d = Number(b.val) - Number(a.val);
  if (!Number.isFinite(d) || d < 0) return null;
  return d;
};

// App-Center kWh counters (optional)
const energyIds = {
  production: this._nwTrimId(String(dps.productionEnergyKwh || '')),
  consumption: this._nwTrimId(String(dps.consumptionEnergyKwh || '')),
  gridImport: this._nwTrimId(String(dps.gridEnergyKwh || '')),
  // optional future extensions (not yet in UI, but supported if present)
  gridExport: this._nwTrimId(String(dps.gridSellEnergyKwh || dps.gridExportEnergyKwh || '')),
  storageCharge: this._nwTrimId(String(dps.storageChargeEnergyKwh || '')),
  storageDischarge: this._nwTrimId(String(dps.storageDischargeEnergyKwh || '')),
  ev: this._nwTrimId(String(dps.evEnergyKwh || dps.evcsEnergyKwh || '')),
};

const energyCounterTasks = [];
if (energyIds.production) energyCounterTasks.push(counterDelta(energyIds.production).then((val) => ['productionKwh', val]));
if (energyIds.consumption) energyCounterTasks.push(counterDelta(energyIds.consumption).then((val) => ['consumptionKwh', val]));
if (energyIds.gridImport) energyCounterTasks.push(counterDelta(energyIds.gridImport).then((val) => ['gridImportKwh', val]));
if (energyIds.gridExport) energyCounterTasks.push(counterDelta(energyIds.gridExport).then((val) => ['gridExportKwh', val]));
if (energyIds.storageCharge) energyCounterTasks.push(counterDelta(energyIds.storageCharge).then((val) => ['storageChargeKwh', val]));
if (energyIds.storageDischarge) energyCounterTasks.push(counterDelta(energyIds.storageDischarge).then((val) => ['storageDischargeKwh', val]));
if (energyIds.ev) energyCounterTasks.push(counterDelta(energyIds.ev).then((val) => ['evKwh', val]));
if (energyCounterTasks.length) {
  const resolvedEnergyCounters = await Promise.all(energyCounterTasks);
  for (const [key, val] of resolvedEnergyCounters) {
    if (val != null) energy[key] = val;
  }
}

energy.__endMs = energyEnd;

// Fast energy totals derived from the already loaded chart series.
// This keeps cards and chart on the same source while avoiding a second heavy
// round-trip to Influx for month/year ranges.
const energyExact = {};
const energyExactEnd = Math.min(end, Date.now());
const energyExactStepMs = Math.max(60 * 1000, stepMs);
/**
 * Code-Teil: integrateSeriesKwh
 * Zweck: Kapselt einen klar abgegrenzten Verarbeitungsschritt innerhalb dieser Datei.
 * Zusammenhang: Gehört zu ioBroker-Adapterkern (Adapter-Lifecycle, Webserver, REST-/SSE-API, State-Anlage, Lizenz und EMS-Engine) und wird von benachbarten UI-/API-/EMS-Bausteinen genutzt.
 * Wartung/TypeScript: Änderungen können Adapterstart, APIs, States und Webserver beeinflussen; unload/connection immer mittesten. Beim TS-Umbau Parameter, Rückgabe und genutzte State-/Config-Objekte explizit typisieren.
 */
const integrateSeriesKwh = (series, defaultEndMs, stepMsForSeries, positiveOnly = true) => {
  const vals = Array.isArray(series?.values) ? series.values : [];
  if (!vals.length) return null;
  let kwh = 0;
  let integrated = false;
  const endTs = Number.isFinite(Number(defaultEndMs)) ? Number(defaultEndMs) : Date.now();
  const fallbackStep = Math.max(60 * 1000, Number(stepMsForSeries) || energyExactStepMs);
  for (let i = 0; i < vals.length; i++) {
    const cur = vals[i];
    if (!Array.isArray(cur) || cur.length < 2) continue;
    const ts = Number(cur[0]);
    if ((cur[1] === null || cur[1] === undefined) && ts < endTs) return null;
    let v = Number(cur[1]);
    if (!Number.isFinite(ts) || !Number.isFinite(v) || ts >= endTs) continue;
    const nextTs = (i + 1 < vals.length && Array.isArray(vals[i + 1]) && Number.isFinite(Number(vals[i + 1][0])))
      ? Number(vals[i + 1][0])
      : endTs;
    let dt = Math.min(nextTs, endTs) - ts;
    if (!Number.isFinite(dt) || dt <= 0) continue;
    dt = Math.min(dt, fallbackStep * 2);
    v = positiveOnly ? Math.max(0, v) : Math.abs(v);
    kwh += (v * dt) / 3600000000;
    integrated = true;
  }
  return integrated ? kwh : null;
};
/**
 * Code-Teil: clipSeriesForIntegration
 * Zweck: Kapselt einen lokalen Verarbeitungsschritt, damit Aufrufer nicht direkt in Detaildaten eingreifen.
 * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
 * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
 */
const clipSeriesForIntegration = (series, clipEndMs) => {
  const vals = Array.isArray(series?.values) ? series.values : [];
  if (!vals.length || !Number.isFinite(Number(clipEndMs))) return { id: series?.id || '', values: [] };
  const clipEnd = Number(clipEndMs);
  const out = [];
  let lastVal = null;
  for (const row of vals) {
    if (!Array.isArray(row) || row.length < 2) continue;
    const ts = Number(row[0]);
    const v = row[1] === null || row[1] === undefined ? null : Number(row[1]);
    if (!Number.isFinite(ts) || (v !== null && !Number.isFinite(v))) continue;
    if (ts > clipEnd) break;
    out.push([ts, v]);
    lastVal = v;
    if (ts === clipEnd) return { id: series?.id || '', values: out };
  }
  if (out.length && out[out.length - 1][0] < clipEnd && Number.isFinite(lastVal)) {
    out.push([clipEnd, lastVal]);
  }
  return { id: series?.id || '', values: out };
};
/**
 * Code-Teil: buildEnergyExact
 * Zweck: Erzeugt UI-/Konfigurations- oder Datenstruktur.
 * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
 * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
 */
const buildEnergyExact = async () => {
  const pvExact = clipSeriesForIntegration(pv, energyExactEnd);
  const loadExact = clipSeriesForIntegration(load, energyExactEnd);
  const buyExact = clipSeriesForIntegration(buy, energyExactEnd);
  const sellExact = clipSeriesForIntegration(sell, energyExactEnd);
  const chgExact = clipSeriesForIntegration(chg, energyExactEnd);
