    const rfidStr = (report && report.rfid && report.rfid !== 'ALL') ? report.rfid : 'ALL';
    const filename = `RFID_${rfidStr}_${fromStr}_${toStr}.csv`;

    const csv = '\ufeff' + nwRfidReportToCsv(report);
