        res.status(200).send(pdf);
      } catch (e) {
        res.status(500).type('text/plain').send('HLZF PDF Export Fehler.');
      }
    });

    // Abschnitt: Live-State-Snapshot. Diese Antwort ist die wichtigste Datenquelle für Dashboard, Settings und viele Unterseiten.
    // API-Kommentar: GET-Route. Zweck: stellt einen Web-/API-Endpunkt bereit. Zusammenhang: Frontend-Dateien in www/* können diesen Endpunkt direkt nutzen. Route/Handler: '/api/state', (_req, res) => {
    app.get('/api/state', async (req, res) => {
      // TS-Migration 0.7.100: /api/state nutzt produktiv den TS-Builder.
      // Installer erhalten nach gültiger Anmeldung die vollständige Diagnose;
      // das Kundenfrontend bekommt ausschließlich den redigierten Betriebs-Snapshot.
      this._nwRunApiStateTsShadowComparison('GET /api/state');
      const tsStates = this._nwBuildApiStateTsRuntimeResponse('GET /api/state');
      const source = tsStates || this.stateCache;
      const access = authEnabled ? await resolveAccess(req) : null;
      const installerAccess = !!(authEnabled && access && access.isInstaller);
      return res.json(installerAccess ? source : nwBuildPublicStateSnapshot(source, true));
    });

    // RFID-Kundendaten liegen bewusst nicht mehr im globalen State-/SSE-Snapshot.
    // Der Editor lädt sie nur bei Bedarf über diesen kontrollierten Endpunkt.
    app.get('/api/rfid/customer', requireAuth, async (_req, res) => {
      try {
        const valueOf = (key, fallback) => {
          const rec = this.stateCache && this.stateCache[key];
          return rec && Object.prototype.hasOwnProperty.call(rec, 'value') ? rec.value : fallback;
        };
        const rawWhitelist = String(valueOf('evcs.rfid.whitelistJson', '[]') || '[]');
        let whitelist = [];
        try {
          const parsed = JSON.parse(rawWhitelist);
          whitelist = Array.isArray(parsed) ? parsed : [];
        } catch (_e) { whitelist = []; }
        return res.json({
          ok: true,
          enabled: valueOf('evcs.rfid.enabled', false) === true,
          whitelist,
          whitelistJson: JSON.stringify(whitelist),
          learning: {
            active: valueOf('evcs.rfid.learning.active', false) === true,
            lastCaptured: String(valueOf('evcs.rfid.learning.lastCaptured', '') || ''),
            lastCapturedTs: Number(valueOf('evcs.rfid.learning.lastCapturedTs', 0)) || 0,
          },
        });
      } catch (e) {
        return res.status(500).json({ ok: false, error: 'internal_error' });
      }
    });

    app.get('/api/installer/notification-mail', requireMailAdmin, async (_req, res) => {
      res.set('Cache-Control', 'no-store');
      try {
        const mail = this._getNotificationMail();
        await mail.init();
        return res.json({ ok: true, config: mail.publicConfig() });
      } catch (_error) { return res.status(503).json({ ok: false, error: 'Geschützte SMTP-Konfiguration nicht verfügbar.' }); }
    });
    app.post('/api/installer/notification-mail', requireMailAdmin, async (req, res) => {
      res.set('Cache-Control', 'no-store');
      try {
        const config = await this._getNotificationMail().configure(req.body || {});
        return res.json({ ok: true, config });
      } catch (error) { return res.status(400).json({ ok: false, error: String(error?.message || 'SMTP-Konfiguration konnte nicht gespeichert werden.') }); }
    });

    // Test email for notification commissioning
    // API-Kommentar: POST-Route. Zweck: stellt einen Web-/API-Endpunkt bereit. Zusammenhang: Frontend-Dateien in www/* können diesen Endpunkt direkt nutzen. Route/Handler: '/api/notify/test', requireAuth, async (req, res) => {
    app.post('/api/notify/test', requireAuth, async (req, res) => {
      try {
        const body = (req && req.body) ? req.body : {};
        const toBody = (body && body.to) ? String(body.to).trim() : '';
        const configuredTo = this._notifyGetSettingString('email', '');
        const access = await resolveStrictAccess(req);
        if (toBody && toBody.toLowerCase() !== String(configuredTo || '').trim().toLowerCase() && !(access && access.isInstaller)) {
          return res.status(403).json({ ok: false, error: 'recipient_forbidden', message: 'Kunden dürfen nur die konfigurierte Empfängeradresse testen.' });
        }
        const to = toBody || configuredTo;
        if (!to) return res.status(400).json({ ok: false, error: 'missing recipient' });

        const now = Date.now();
        const subject = 'NexoWatt EOS: Test-Benachrichtigung';
        const text = [
          `Zeit: ${new Date(now).toLocaleString()}`,
          `Adapter: ${this.namespace}`,
          '',
          'Dies ist eine Testbenachrichtigung. Wenn du diese E-Mail erhältst, ist der Versand korrekt konfiguriert.'
        ].join('\n');

        const r = await this._notifySendEmail(to, subject, text);
        return res.status(r?.ok ? 200 : 503).json({ ok: !!r?.ok, error: r?.error, result: r });
      } catch (e) {
        return res.status(500).json({ ok: false, error: 'internal_error' });
      }
    });

    // generic setter for customer-facing settings and commands
    // API-Kommentar: POST-Route. Zweck: stellt einen Web-/API-Endpunkt bereit. Zusammenhang: Frontend-Dateien in www/* können diesen Endpunkt direkt nutzen. Route/Handler: '/api/set', requireAuth, async (req, res) => {
    app.post('/api/set', requireAuth, async (req, res) => {
      try {
        const scope = req.body && req.body.scope;
        const key = req.body && req.body.key;
        const value = req.body && req.body.value;
        if (!['settings', 'installer', 'ems', 'bhkw', 'generator', 'threshold', 'relay', 'evcs', 'rfid', 'flow', 'storageFarm'].includes(scope) || typeof key !== 'string' || !key || key.length > 256) return res.status(400).json({ ok: false, error: 'bad request' });

        if (scope === 'settings' && key === 'email' && String(value || '').trim() && !validAddress(String(value).trim())) return res.status(400).json({ ok: false, error: 'Bitte eine einzelne gültige E-Mail-Adresse eingeben.' });

        // TS-Migration 0.7.100: /api/set erstellt weiterhin eine Diagnose,
        // kann bekannte lokale settings.*-Werte aber jetzt produktiv über den TS-Schreibplan anwenden.
        this._nwRunApiSetTsShadowPlan(scope, key, value);

        // Netzschutz: Peak‑Shaving darf nicht durch Endkunden (VIS) deaktiviert werden.
        // Konfiguration erfolgt ausschließlich über das Installer‑/App‑Center.
        if (scope === 'settings' && String(key) === 'peakShavingEnabled') {
          return res.status(403).json({ ok: false, error: 'forbidden' });
        }

        // Tarif: PV Saisonprofil – KI ist immer aktiv (Endkundenfreundlich).
        // Manuelle Quartalsfaktoren bleiben optional als Basiswerte (Feintuning).
        if (scope === 'settings' && String(key) === 'tariffPvSeasonAiEnabled') {
          try {
            const forced = true;
            const map2 = (this.config && this.config.settings) || {};
            const mapped2 = map2[key];
            const id2 = (typeof mapped2 === 'string' && mapped2.trim()) ? mapped2.trim() : '';
            if (id2) {
              const forcedWriteResult = await this.setForeignStateAsync(id2, forced);
              if (isActuatorAuthorityBlockedResult(forcedWriteResult)) {
                return res.status(409).json({ ok: false, error: 'blocked_by_actuator_authority', blockedBy: forcedWriteResult.blockedByOwner || '' });
              }
            } else {
              const localId2 = `settings.${key}`;
              await this.setStateAsync(localId2, { val: forced, ack: false });
            }
            return res.json({ ok: true });
          } catch (e) {
            this.log.warn('set error (tariffPvSeasonAiEnabled): ' + (e && e.message ? e.message : e));
            return res.status(500).json({ ok: false, error: 'internal error' });
          }
        }

        // TS-Migration 0.7.100: einfache lokale Kundeneinstellungen produktiv über TS schreiben.
        // Komplexe Scopes und unbekannte Settings fallen weiter auf die alte JS-Route zurück.
        const tsSettingsWrite = await this._nwTryApplyApiSetTsSettingsPlan(scope, key, value);
        if (tsSettingsWrite && tsSettingsWrite.handled) {
          if (tsSettingsWrite.ok === false) {
            return res.status(409).json({ ok: false, error: tsSettingsWrite.reason || 'write_failed', blockedBy: tsSettingsWrite.blockedBy || '' });
          }
          return res.json({ ok: true, source: 'ts-settings-plan' });
        }

        // Customer-facing KI-Energieberater toggle.
        // Store this as local VIS state so the customer can decide without opening installer/admin config.
        if (scope === 'settings' && String(key) === 'aiAdvisorEnabled') {
          const b = !!value;
          try {
            await this.setStateAsync('settings.aiAdvisorEnabled', { val: b, ack: false });
            try { this.updateValue('settings.aiAdvisorEnabled', b, Date.now()); } catch (_e) {}
            return res.json({ ok: true });
          } catch (e) {
            this.log.warn('set error (aiAdvisorEnabled): ' + (e && e.message ? e.message : e));
            return res.status(500).json({ ok: false, error: 'internal error' });
          }
        }

        // Technische Mappings brauchen unmittelbar vor der Schreibverzweigung
        // eine echte aktuelle Fachrolle, unabhängig von Kunden-Auth/Legacy-Policy.
        if (scope === 'installer') {
          const access = await resolveStrictAccess(req);
          if (!hasCapability(access, 'mapping.edit')) return res.status(access.role === 'none' ? 401 : 403).json({ ok: false, error: 'forbidden' });
        }
        // EMS setter: end-customer control for charging management (per wallbox)
        // - userMode: auto|pv|minpv|boost
        // - regEnabled: Regelung an/aus (Automatik)
        if (scope === 'ems') {
          const k = String(key || '');

          // Multi-Lademanagement: Ein gemeinsamer Kundenschalter setzt den
          // Speicherschutz konsistent für alle aktiven Ladepunkte. Die Bedienung
          // existiert nur nach ausdrücklicher Installerfreigabe im AppCenter.
          if (/^(?:evcs\.)?(?:global|all)\.(?:storageAssist|storageAssistEnabled|userStorageAssistEnabled)$/i.test(k)) {
            const settings = this.config && this.config.settingsConfig && typeof this.config.settingsConfig === 'object'
              ? this.config.settingsConfig
              : {};
            const active = _nwActiveEvcsControlRows();
            const installerAllowed = settings.evcsGlobalStorageAssistCustomerAllowed === true && active.length >= 2;
            if (!installerAllowed) return res.status(403).json({ ok: false, error: 'global_storage_assist_locked' });
            const enabled = !!value;
            const updated = [];
            const previous = [];
            try {
              for (const entry of active) {
                const id = `chargingManagement.wallboxes.lp${entry.index}.userStorageAssistEnabled`;
                const cached = this.stateCache && this.stateCache[id];
                previous.push({ id, value: cached && Object.prototype.hasOwnProperty.call(cached, 'value') ? !!cached.value : false });
                await this.setStateAsync(id, enabled, false);
                try { this.updateValue(id, enabled, Date.now()); } catch (_e) {}
                updated.push(`lp${entry.index}`);
              }
              this._nwRequestImmediateEmsTick('api:evcs-global-storage-assist');
              return res.json({ ok: true, scope: 'global', enabled, updated });
            } catch (_e) {
              const rolledBack = [];
              const rollbackFailed = [];
              for (const entry of previous) {
                if (!updated.includes(String(entry.id).match(/lp\d+/i)?.[0] || '')) continue;
                try {
                  await this.setStateAsync(entry.id, entry.value, false);
                  try { this.updateValue(entry.id, entry.value, Date.now()); } catch (_eUpdate) {}
                  rolledBack.push(String(entry.id).match(/lp\d+/i)?.[0] || entry.id);
                } catch (_eRollback) {
                  rollbackFailed.push(String(entry.id).match(/lp\d+/i)?.[0] || entry.id);
                }
              }
              return res.status(409).json({ ok: false, error: 'global_storage_assist_partial_write', updated, rolledBack, rollbackFailed });
            }
          }

          let safe = '';
          let prop = '';

          // Supported keys (examples):
          // - evcs.1.userMode
          // - evcs.1.regEnabled
          // - lp1.userMode
          // - lp1.regEnabled
          // - chargingManagement.wallboxes.lp1.userMode
          // - chargingManagement.wallboxes.lp1.userEnabled
          // - chargingManagement.wallboxes.lp1.userStationEnabled
          const mIdx = k.match(/^(?:evcs\.)?(\d+)\.(userMode|emsMode|autoSource|userAutoSource|regEnabled|stationEnabled|userStationEnabled|phaseMode|userPhaseMode|storageAssist|storageAssistEnabled|userStorageAssistEnabled|goalEnabled|goalTargetSocPct|goalFinishTs|goalBatteryKwh)$/i);
          if (mIdx) {
            const idx = Math.max(1, Math.round(Number(mIdx[1] || 0)));
            safe = `lp${idx}`;
            prop = String(mIdx[2] || '').toLowerCase();
          } else {
            const mLp = k.match(/^lp(\d+)\.(userMode|emsMode|autoSource|userAutoSource|regEnabled|stationEnabled|userStationEnabled|phaseMode|userPhaseMode|storageAssist|storageAssistEnabled|userStorageAssistEnabled|goalEnabled|goalTargetSocPct|goalFinishTs|goalBatteryKwh)$/i);
            if (mLp) {
              const idx = Math.max(1, Math.round(Number(mLp[1] || 0)));
              safe = `lp${idx}`;
              prop = String(mLp[2] || '').toLowerCase();
            } else {
              const m2 = k.match(/^chargingManagement\.(?:wallboxes\.)?([a-z0-9_]+)\.(userMode|autoSource|userAutoSource|userEnabled|regEnabled|stationEnabled|userStationEnabled|phaseMode|userPhaseMode|storageAssist|storageAssistEnabled|userStorageAssistEnabled|goalEnabled|goalTargetSocPct|goalFinishTs|goalBatteryKwh)$/i);
              if (m2) {
                safe = String(m2[1] || '').trim();
                prop = String(m2[2] || '').toLowerCase();
              }
            }
          }
          if (!safe || !prop) return res.status(400).json({ ok: false, error: 'bad request' });

          // Kundenseitige Freigabe der physischen Ladestation. Dieser State ist
          // bewusst vom Connector-/Fahrzeugstatus (`activeId`) und von der
          // EMS-Regelungsfreigabe (`userEnabled`) getrennt. PV-Warten mit 0 W
          // darf ihn niemals automatisch auf false setzen.
          if (prop === 'stationenabled' || prop === 'userstationenabled') {
            const b = !!value;
            const id = `chargingManagement.wallboxes.${safe}.userStationEnabled`;
            try {
              await this.setStateAsync(id, b, false);
              const controlTs = Date.now();
              try { this.updateValue(id, b, controlTs); } catch (_e) {}
              this._nwRequestImmediateEmsTick(`api:${id}`);

              // Eine ausdrückliche Kundensperre beendet einen eventuell aktiven
              // Boost-Override. Der gewählte Grundmodus bleibt erhalten.
              if (!b) {
                try {
                  await this.setStateAsync(`chargingManagement.wallboxes.${safe}.boostActive`, false, true);
                  await this.setStateAsync(`chargingManagement.wallboxes.${safe}.boostSince`, 0, true);
                  await this.setStateAsync(`chargingManagement.wallboxes.${safe}.boostUntil`, 0, true);
                  await this.setStateAsync(`chargingManagement.wallboxes.${safe}.boostRemainingMin`, 0, true);
                } catch (_e2) {
                  // ignore
                }
              }
              return res.json({ ok: true });
            } catch (_e) {
              return res.status(409).json({ ok: false, error: 'not_ready' });
            }
          }

          // Regelung (Automatik) an/aus
          if (prop === 'regenabled' || prop === 'userenabled') {
            const b = !!value;
            const id = `chargingManagement.wallboxes.${safe}.userEnabled`;
            try {
              await this.setStateAsync(id, b, false);
              const controlTs = Date.now();
              try { this.updateValue(id, b, controlTs); } catch (_e) {}
              this._nwRequestImmediateEmsTick(`api:${id}`);

              // UX: beim Deaktivieren Boost-Indikatoren sofort zurücksetzen (keine "hängenden" Zustände)
              if (!b) {
                try {
                  await this.setStateAsync(`chargingManagement.wallboxes.${safe}.boostActive`, false, true);
                  await this.setStateAsync(`chargingManagement.wallboxes.${safe}.boostSince`, 0, true);
                  await this.setStateAsync(`chargingManagement.wallboxes.${safe}.boostUntil`, 0, true);
                  await this.setStateAsync(`chargingManagement.wallboxes.${safe}.boostRemainingMin`, 0, true);
                } catch (_e2) {
                  // ignore
                }
              }
              return res.json({ ok: true });
            } catch (e) {
              return res.status(409).json({ ok: false, error: 'not_ready' });
            }
          }

          // Auto-Quelle: Die Betriebsstrategie darf ausschließlich innerhalb
          // des Ladebetriebsmodus Auto übernehmen. Der Default bleibt die
          // bestehende Standard-Automatik; ein Wechsel verändert keine anderen Modi.
          if (prop === 'autosource' || prop === 'userautosource') {
            const raw = String(value === null || value === undefined ? 'standard' : value).trim().toLowerCase();
            const v = ['strategy', 'operatingstrategies', 'operating-strategies', 'eos-strategy', 'betriebsstrategie'].includes(raw)
              ? 'strategy'
              : 'standard';
            const id = `chargingManagement.wallboxes.${safe}.userAutoSource`;
            try {
              await this.setStateAsync(id, v, false);
              try { this.updateValue(id, v, Date.now()); } catch (_e) {}
              this._nwRequestImmediateEmsTick(`api:${id}`);
              return res.json({ ok: true, value: v });
            } catch (_e) {
              return res.status(409).json({ ok: false, error: 'not_ready' });
            }
          }

          // AC-Phasenmodus: fixed-1p | fixed-3p | auto-pv
          // Dieser Wert ist bewusst ein User-Override und wird von der TS-EVCS-Allocation/Write-Plan-Kette ausgewertet.
          if (prop === 'phasemode' || prop === 'userphasemode') {
            let v = String(value === null || value === undefined ? 'auto-pv' : value).trim().toLowerCase();
            v = v.replace(/_/g, '-');
            if (v === 'auto' || v === 'autopv' || v === 'pvauto' || v === 'auto-1p-3p' || v === 'auto13') v = 'auto-pv';
            if (v === '1' || v === '1p' || v === 'fixed1p' || v === 'fixed-1') v = 'fixed-1p';
            if (v === '3' || v === '3p' || v === 'fixed3p' || v === 'fixed-3') v = 'fixed-3p';
            if (!['fixed-1p', 'fixed-3p', 'auto-pv'].includes(v)) v = 'auto-pv';
            const id = `chargingManagement.wallboxes.${safe}.userPhaseMode`;
            try {
              await this.setStateAsync(id, v, false);
              try { this.updateValue(id, v, Date.now()); } catch (_e) {}
              this._nwRequestImmediateEmsTick(`api:${id}`);
              return res.json({ ok: true });
            } catch (_e) {
              return res.status(409).json({ ok: false, error: 'not_ready' });
            }
          }

          // Speicher-Mitnutzung pro Ladepunkt: Der Kunde darf nur setzen, wenn der Installateur
          // die Bedienung im App-Center pro Ladepunkt freigegeben hat.
          if (prop === 'storageassist' || prop === 'storageassistenabled' || prop === 'userstorageassistenabled') {
            const idxMatch = String(safe || '').match(/lp(\d+)/i);
            const idx = idxMatch ? Math.max(1, Math.round(Number(idxMatch[1] || 0))) : 0;
            const rawList = this.config && this.config.settingsConfig && Array.isArray(this.config.settingsConfig.evcsList)
              ? this.config.settingsConfig.evcsList
              : [];
            const cfgRow = idx > 0 ? (rawList[idx - 1] || null) : null;
            const runtimeRow = idx > 0 && Array.isArray(this.evcsList) ? (this.evcsList[idx - 1] || null) : null;
            const settings = this.config && this.config.settingsConfig && typeof this.config.settingsConfig === 'object'
              ? this.config.settingsConfig
              : {};
            const globalControl = settings.evcsGlobalStorageAssistCustomerAllowed === true && _nwActiveEvcsControlRows().length >= 2;
            if (globalControl) {
              return res.status(409).json({ ok: false, error: 'storage_assist_global_control_required' });
            }
            const installerAllowed = !!((cfgRow && cfgRow.storageAssistCustomerAllowed === true)
              || (runtimeRow && runtimeRow.storageAssistCustomerAllowed === true));
            if (!installerAllowed) {
              return res.status(403).json({ ok: false, error: 'storage_assist_locked' });
            }

            const b = !!value;
            const id = `chargingManagement.wallboxes.${safe}.userStorageAssistEnabled`;
            try {
              await this.setStateAsync(id, b, false);
              try { this.updateValue(id, b, Date.now()); } catch (_e) {}
              this._nwRequestImmediateEmsTick(`api:${id}`);
              return res.json({ ok: true });
            } catch (_e) {
              return res.status(409).json({ ok: false, error: 'not_ready' });
            }
          }

          // Zeit-Ziel Laden (Depot-/Deadline-Laden)
          // - goalEnabled: Aktiv/aus
          // - goalTargetSocPct: Ziel-SoC 0..100
          // - goalFinishTs: Deadline als UNIX Timestamp (ms)
          // - goalBatteryKwh: optionale Kapazität zur genaueren Planung
          if (prop === 'goalenabled') {
            const b = !!value;
            const id = `chargingManagement.wallboxes.${safe}.goalEnabled`;
            try {
              await this.setStateAsync(id, b, false);
              try { this.updateValue(id, b, Date.now()); } catch (_e) {}
              this._nwRequestImmediateEmsTick(`api:${id}`);
              return res.json({ ok: true });
            } catch (_e) {
              return res.status(409).json({ ok: false, error: 'not_ready' });
            }
          }

          if (prop === 'goaltargetsocpct' || prop === 'goaltargetsoc') {
            const n = Number(value);
            if (!Number.isFinite(n)) return res.status(400).json({ ok: false, error: 'bad request' });
            const v = Math.max(0, Math.min(100, Math.round(n)));
            const id = `chargingManagement.wallboxes.${safe}.goalTargetSocPct`;
            try {
              await this.setStateAsync(id, v, false);
              try { this.updateValue(id, v, Date.now()); } catch (_e) {}
              this._nwRequestImmediateEmsTick(`api:${id}`);
              return res.json({ ok: true });
            } catch (_e) {
              return res.status(409).json({ ok: false, error: 'not_ready' });
            }
          }

          if (prop === 'goalfinishts') {
            const n = Number(value);
            if (!Number.isFinite(n)) return res.status(400).json({ ok: false, error: 'bad request' });
            // Allow 0 to clear; otherwise clamp to a reasonable range (now..+1y) to avoid bad writes
            const now = Date.now();
            let v = Math.round(n);
            if (v < 0) v = 0;
            if (v > 0) {
              const max = now + 366 * 24 * 3600 * 1000;
              if (v > max) v = max;

              // Enforce 15‑minute raster (00/15/30/45) to match UI and avoid odd minute values.
              // Snap in local time (Date) so DST transitions behave as expected.
              try {
                const dt = new Date(v);
                dt.setSeconds(0, 0);
                const m = dt.getMinutes();
                const snapped = Math.round(m / 15) * 15;
                dt.setMinutes(snapped, 0, 0);
                v = dt.getTime();
              } catch (_e) {
                // ignore
              }

              // Re-clamp after snapping (snapping may roll over to next hour/day)
              if (v > max) v = max;
            }
            const id = `chargingManagement.wallboxes.${safe}.goalFinishTs`;
            try {
              await this.setStateAsync(id, v, false);
              try { this.updateValue(id, v, Date.now()); } catch (_e) {}
              this._nwRequestImmediateEmsTick(`api:${id}`);
              return res.json({ ok: true });
            } catch (_e) {
              return res.status(409).json({ ok: false, error: 'not_ready' });
            }
          }

          if (prop === 'goalbatterykwh') {
            const n = Number(value);
            if (!Number.isFinite(n)) return res.status(400).json({ ok: false, error: 'bad request' });
            // Allow 0 to clear; clamp to reasonable max (0..2000kWh)
            const v = Math.max(0, Math.min(5000, Math.round(n * 10) / 10));
            const id = `chargingManagement.wallboxes.${safe}.goalBatteryKwh`;
            try {
              await this.setStateAsync(id, v, false);
              try { this.updateValue(id, v, Date.now()); } catch (_e) {}
              this._nwRequestImmediateEmsTick(`api:${id}`);
              return res.json({ ok: true });
            } catch (_e) {
              return res.status(409).json({ ok: false, error: 'not_ready' });
            }
          }

          // Modus: auto|pv|minpv|boost
          let v = String(value === null || value === undefined ? 'auto' : value).trim().toLowerCase();
          if (v === 'min+pv') v = 'minpv';
          if (!['auto', 'pv', 'minpv', 'boost'].includes(v)) v = 'auto';

          const id = `chargingManagement.wallboxes.${safe}.userMode`;
          try {
            await this.setStateAsync(id, v, false);
            const controlTs = Date.now();
            try { this.updateValue(id, v, controlTs); } catch (_e) {}
            this._nwRequestImmediateEmsTick(`api:${id}`);

            // UX/Serienreife: allow manual boost cancel.
            // If the operator switches away from boost, clear the boost runtime indicators
            // immediately (do not wait for the next scheduler tick), so the UI can switch
            // modes reliably and the user doesn't feel "stuck".
            if (v !== 'boost') {
              try {
                await this.setStateAsync(`chargingManagement.wallboxes.${safe}.boostActive`, false, true);
                await this.setStateAsync(`chargingManagement.wallboxes.${safe}.boostSince`, 0, true);
                await this.setStateAsync(`chargingManagement.wallboxes.${safe}.boostUntil`, 0, true);
                await this.setStateAsync(`chargingManagement.wallboxes.${safe}.boostRemainingMin`, 0, true);
              } catch (_e2) {
                // ignore
              }
            }
            return res.json({ ok: true });
          } catch (e) {
            return res.status(409).json({ ok: false, error: 'not_ready' });
          }
        }

        // BHKW Steuerung – Schnellsteuerung (Modus + Start/Stop)
        // Keys:
        // - b1.mode (auto|manual|off)
        // - b1.command (start|stop)
        if (scope === 'bhkw') {
          const cfg = this.config || {};
          if (!cfg.enableBhkwControl) return res.status(409).json({ ok: false, error: 'not_ready' });

          const k = String(key || '').trim();
          const m = k.match(/^b(\d+)\.(mode|command)$/i);
          if (!m) return res.status(400).json({ ok: false, error: 'bad request' });

          const idx = Math.max(1, Math.min(10, Math.round(Number(m[1] || 0)) || 0));
          const prop = String(m[2] || '').toLowerCase();
          const bhkwRows = Array.isArray(cfg.bhkw?.devices) ? cfg.bhkw.devices : [];
          const bhkwDevice = bhkwRows.find((row, rowIndex) => {
            const rowIdx = Math.max(1, Math.min(10, Math.round(Number(row?.idx ?? row?.index ?? rowIndex + 1) || rowIndex + 1)));
            return rowIdx === idx;
          });
          if (!bhkwDevice || bhkwDevice.enabled !== true || bhkwDevice.userCanControl === false) {
            return res.status(403).json({ ok: false, error: 'customer_control_disabled' });
          }

          // Endkunden-Frontend: sichtbare und im AppCenter freigegebene BHKW-Schnellsteuerung bleibt ohne Passwort bedienbar.

          if (prop === 'mode') {
            let v = String(value === null || value === undefined ? 'auto' : value).trim().toLowerCase();
            if (v === 'manuell') v = 'manual';
            if (v === 'aus') v = 'off';
            if (!['auto', 'manual', 'off'].includes(v)) v = 'auto';

            const id = `bhkw.user.b${idx}.mode`;
            try {
              await this.setStateAsync(id, v, false);
              try { this.updateValue(id, v, Date.now()); } catch (_e) {}
              return res.json({ ok: true });
            } catch (_e) {
              return res.status(409).json({ ok: false, error: 'not_ready' });
            }
          }

          if (prop === 'command') {
            let v = String(value === null || value === undefined ? '' : value).trim().toLowerCase();
            if (v === 'on') v = 'start';
            if (v === 'off') v = 'stop';
            if (!['start', 'stop', ''].includes(v)) v = '';

            const id = `bhkw.user.b${idx}.command`;
            try {
              await this.setStateAsync(id, v, false);
              try { this.updateValue(id, v, Date.now()); } catch (_e) {}
              return res.json({ ok: true });
            } catch (_e) {
              return res.status(409).json({ ok: false, error: 'not_ready' });
            }
          }

          return res.status(400).json({ ok: false, error: 'bad request' });
        }

        // Generator Steuerung – Schnellsteuerung (Modus + Start/Stop)
        // Keys:
        // - g1.mode (auto|manual|off)
        // - g1.command (start|stop)
        if (scope === 'generator') {
          const cfg = this.config || {};
          if (!cfg.enableGeneratorControl) return res.status(409).json({ ok: false, error: 'not_ready' });

          const k = String(key || '').trim();
          const m = k.match(/^g(\d+)\.(mode|command)$/i);
          if (!m) return res.status(400).json({ ok: false, error: 'bad request' });

          const idx = Math.max(1, Math.min(10, Math.round(Number(m[1] || 0)) || 0));
          const prop = String(m[2] || '').toLowerCase();
          const generatorRows = Array.isArray(cfg.generator?.devices) ? cfg.generator.devices : [];
          const generatorDevice = generatorRows.find((row, rowIndex) => {
            const rowIdx = Math.max(1, Math.min(10, Math.round(Number(row?.idx ?? row?.index ?? rowIndex + 1) || rowIndex + 1)));
            return rowIdx === idx;
          });
          if (!generatorDevice || generatorDevice.enabled !== true || generatorDevice.userCanControl === false) {
            return res.status(403).json({ ok: false, error: 'customer_control_disabled' });
          }

          // Endkunden-Frontend: sichtbare und im AppCenter freigegebene Generator-Schnellsteuerung bleibt ohne Passwort bedienbar.

          if (prop === 'mode') {
            let v = String(value === null || value === undefined ? 'auto' : value).trim().toLowerCase();
            if (v === 'manuell') v = 'manual';
            if (v === 'aus') v = 'off';
            if (!['auto', 'manual', 'off'].includes(v)) v = 'auto';

            const id = `generator.user.g${idx}.mode`;
            try {
              await this.setStateAsync(id, v, false);
              try { this.updateValue(id, v, Date.now()); } catch (_e) {}
              return res.json({ ok: true });
            } catch (_e) {
              return res.status(409).json({ ok: false, error: 'not_ready' });
            }
          }

          if (prop === 'command') {
            let v = String(value === null || value === undefined ? '' : value).trim().toLowerCase();
            if (v === 'on') v = 'start';
            if (v === 'off') v = 'stop';
            if (!['start', 'stop', ''].includes(v)) v = '';

            const id = `generator.user.g${idx}.command`;
            try {
              await this.setStateAsync(id, v, false);
              try { this.updateValue(id, v, Date.now()); } catch (_e) {}
              return res.json({ ok: true });
            } catch (_e) {
              return res.status(409).json({ ok: false, error: 'not_ready' });
            }
          }

          return res.status(400).json({ ok: false, error: 'bad request' });
        }

        // Schwellwertsteuerung – sichtbare Endkunden-Overrides ohne Rollen-/Passwortsperre
        // Keys:
        // - r1.enabled
        // - r1.mode
        // - r1.threshold
        if (scope === 'threshold') {
          const cfg = this.config || {};
          const thrApp = (cfg.emsApps && cfg.emsApps.apps) ? cfg.emsApps.apps.threshold : null;
          const thrInstalled = !!(thrApp ? thrApp.installed : cfg.enableThresholdControl);
          if (!thrInstalled) return res.status(409).json({ ok: false, error: 'not_ready' });

          const k = String(key || '').trim();
          const m = k.match(/^r(\d+)\.(enabled|threshold|mode|minOnSec|minOffSec)$/i);
          if (!m) return res.status(400).json({ ok: false, error: 'bad request' });

          const idx = Math.max(1, Math.min(10, Math.round(Number(m[1] || 0)) || 0));
          const prop = String(m[2] || '').toLowerCase();

          // Frontend-Regeln sind bedienbar, sobald sie im LIVE-Frontend sichtbar sind.
          const t = (cfg.threshold && typeof cfg.threshold === 'object') ? cfg.threshold : {};
          const list = Array.isArray(t.rules) ? t.rules : [];
          let rule = null;
          for (let i = 0; i < list.length; i++) {
            const r = list[i] || {};
            const ridx = Math.max(1, Math.min(10, Math.round(Number(r.idx ?? r.index ?? (i + 1)) || (i + 1))));
            if (ridx === idx) { rule = r; break; }
          }

          // Keine zusätzlichen Endkunden-Sperrflags: sichtbare Regeln sind direkt bedienbar.

          // Best effort: ensure objects exist (robust against partial upgrades)
          try {
            await this.setObjectNotExistsAsync('threshold.user', { type: 'channel', common: { name: 'User' }, native: {} });
            await this.setObjectNotExistsAsync(`threshold.user.r${idx}`, { type: 'channel', common: { name: `Regel ${idx}` }, native: {} });
            await this.setObjectNotExistsAsync(`threshold.user.r${idx}.enabled`, { type: 'state', common: { name: 'Regel aktiv (User)', type: 'boolean', role: 'switch.enable', read: true, write: true, def: true }, native: {} });
            await this.setObjectNotExistsAsync(`threshold.user.r${idx}.threshold`, { type: 'state', common: { name: 'Schwellwert (User)', type: 'number', role: 'level', read: true, write: true, def: 0 }, native: {} });
            await this.setObjectNotExistsAsync(`threshold.user.r${idx}.minOnSec`, { type: 'state', common: { name: 'MinOn (User)', type: 'number', role: 'value', unit: 's', read: true, write: true, def: 0 }, native: {} });
            await this.setObjectNotExistsAsync(`threshold.user.r${idx}.minOffSec`, { type: 'state', common: { name: 'MinOff (User)', type: 'number', role: 'value', unit: 's', read: true, write: true, def: 0 }, native: {} });
            await this.setObjectNotExistsAsync(`threshold.user.r${idx}.mode`, { type: 'state', common: { name: 'Modus (User)', type: 'number', role: 'value', read: true, write: true, def: 1, min: 0, max: 2, states: { 0: 'Aus', 1: 'Auto', 2: 'An' } }, native: {} });
          } catch (_e) {}

          if (prop === 'mode') {
            const mv = Number(value);
            if (!Number.isFinite(mv)) return res.status(400).json({ ok: false, error: 'bad request' });
            const mode = Math.max(0, Math.min(2, Math.round(mv)));

            await this.setStateAsync(`threshold.user.r${idx}.mode`, { val: mode, ack: false });
            try { this.updateValue(`threshold.user.r${idx}.mode`, mode, Date.now()); } catch(_e) {}

            const en = (mode !== 0);
            await this.setStateAsync(`threshold.user.r${idx}.enabled`, { val: en, ack: false });
            try { this.updateValue(`threshold.user.r${idx}.enabled`, en, Date.now()); } catch(_e) {}

            return res.json({ ok: true });
          }

          if (prop === 'enabled') {
            const b = !!value;
            await this.setStateAsync(`threshold.user.r${idx}.enabled`, { val: b, ack: false });
            try { this.updateValue(`threshold.user.r${idx}.enabled`, b, Date.now()); } catch(_e) {}

            // Sync mode (Kompatibilität): enabled=false -> Aus (0), enabled=true -> Auto (1) (manual_on bleibt erhalten)
            try {
              const stMode = await this.getStateAsync(`threshold.user.r${idx}.mode`);
              const curMode = (stMode && stMode.val !== null && stMode.val !== undefined) ? Number(stMode.val) : NaN;
              const newMode = b ? ((Number.isFinite(curMode) && Math.round(curMode) === 2) ? 2 : 1) : 0;
              await this.setStateAsync(`threshold.user.r${idx}.mode`, { val: newMode, ack: false });
              try { this.updateValue(`threshold.user.r${idx}.mode`, newMode, Date.now()); } catch(_e) {}
            } catch(_e) {}

            return res.json({ ok: true });
          }

          if (prop === 'minonsec') {
            const n = Number(value);
            if (!Number.isFinite(n)) return res.status(400).json({ ok: false, error: 'bad request' });
            const v = Math.max(0, Math.min(86400, Math.round(n)));
            await this.setStateAsync(`threshold.user.r${idx}.minOnSec`, { val: v, ack: false });
            try { this.updateValue(`threshold.user.r${idx}.minOnSec`, v, Date.now()); } catch(_e) {}
            return res.json({ ok: true });
          }

          if (prop === 'minoffsec') {
            const n = Number(value);
            if (!Number.isFinite(n)) return res.status(400).json({ ok: false, error: 'bad request' });
            const v = Math.max(0, Math.min(86400, Math.round(n)));
            await this.setStateAsync(`threshold.user.r${idx}.minOffSec`, { val: v, ack: false });
            try { this.updateValue(`threshold.user.r${idx}.minOffSec`, v, Date.now()); } catch(_e) {}
            return res.json({ ok: true });
          }

          // threshold
          const n = Number(value);
          if (!Number.isFinite(n)) return res.status(400).json({ ok: false, error: 'bad request' });
          await this.setStateAsync(`threshold.user.r${idx}.threshold`, { val: n, ack: false });
          try { this.updateValue(`threshold.user.r${idx}.threshold`, n, Date.now()); } catch(_e) {}
          return res.json({ ok: true });
        }

        // Relaissteuerung – sichtbare manuelle Ausgänge ohne Rollen-/Passwortsperre
        // Keys:
        // - r1.switch  (boolean)
        // - r1.value   (number)
        if (scope === 'relay') {
          const cfg = this.config || {};
          if (!cfg.enableRelayControl) return res.status(409).json({ ok: false, error: 'not_ready' });

          const k = String(key || '').trim();
          const m = k.match(/^r(\d+)\.(switch|value)$/i);
          if (!m) return res.status(400).json({ ok: false, error: 'bad request' });

          const idx = Math.max(1, Math.min(10, Math.round(Number(m[1] || 0)) || 0));
          const prop = String(m[2] || '').toLowerCase();

          const r = (cfg.relay && typeof cfg.relay === 'object') ? cfg.relay : {};
          const list = Array.isArray(r.relays) ? r.relays : [];
          let it = null;
          for (let i = 0; i < list.length; i++) {
            const x = list[i] || {};
            const ridx = Math.max(1, Math.min(10, Math.round(Number(x.idx ?? x.index ?? (i + 1)) || (i + 1))));
            if (ridx === idx) { it = x; break; }
          }
          if (!it) return res.status(404).json({ ok: false, error: 'not_found' });

          const enabled = (typeof it.enabled === 'boolean') ? !!it.enabled : true;
          if (!enabled) return res.status(409).json({ ok: false, error: 'disabled' });

          const type = (String(it.type || '').toLowerCase() === 'boolean' || String(it.type || '').toLowerCase() === 'bool' || String(it.type || '').toLowerCase() === 'switch') ? 'boolean' : 'number';
          const writeId = String(it.writeId || it.writeObjectId || '').trim();
          if (!writeId) return res.status(409).json({ ok: false, error: 'not_ready' });

          const invert = (typeof it.invert === 'boolean') ? !!it.invert : false;
          const relayOwner = `manual.relay.r${idx}`;
          const writeRelayValue = (rawValue, valueKind) => withActuatorShadowContext(this, {
            owner: relayOwner,
            module: 'relayControl',
            priority: 750,
            reason: `Manuelle Relaisbedienung r${idx}.${valueKind}`,
            leaseMs: 5 * 60 * 1000,
            kind: 'manual-relay',
            enforceAuthority: true,
          }, () => this.setForeignStateAsync(writeId, rawValue));

          if (prop === 'switch') {
            if (type !== 'boolean') return res.status(400).json({ ok: false, error: 'bad request' });

            let b = !!value;
            if (invert) b = !b;

            try {
              const relayWriteResult = await writeRelayValue(b, 'switch');
              if (isActuatorAuthorityBlockedResult(relayWriteResult)) return res.status(409).json({ ok: false, error: 'blocked_by_actuator_authority', blockedBy: relayWriteResult.blockedByOwner });
              try {
                const base = `relay.controls.r${idx}`;
                await this.setObjectNotExistsAsync('relay', { type: 'channel', common: { name: 'Relaissteuerung' }, native: {} });
                await this.setObjectNotExistsAsync('relay.controls', { type: 'channel', common: { name: 'Controls' }, native: {} });
                await this.setObjectNotExistsAsync(base, { type: 'channel', common: { name: `Ausgang ${idx}` }, native: {} });
                await this.setObjectNotExistsAsync(`${base}.lastWriteOk`, { type: 'state', common: { name: 'Letzter Schreibbefehl OK', type: 'boolean', role: 'indicator', read: true, write: false, def: false }, native: {} });
                await this.setObjectNotExistsAsync(`${base}.lastWriteTs`, { type: 'state', common: { name: 'Letzter Schreibbefehl Zeitpunkt', type: 'number', role: 'value.time', read: true, write: false, def: 0 }, native: {} });
                await this.setObjectNotExistsAsync(`${base}.lastWriteValue`, { type: 'state', common: { name: 'Letzter Schreibwert', type: 'boolean', role: 'state', read: true, write: false, def: false }, native: {} });
                await this.setObjectNotExistsAsync(`${base}.lastWriteError`, { type: 'state', common: { name: 'Letzter Schreibfehler', type: 'string', role: 'text', read: true, write: false, def: '' }, native: {} });
                await this.setStateAsync(`${base}.lastWriteOk`, { val: true, ack: true });
                await this.setStateAsync(`${base}.lastWriteTs`, { val: Date.now(), ack: true });
                await this.setStateAsync(`${base}.lastWriteValue`, { val: invert ? !b : b, ack: true });
                await this.setStateAsync(`${base}.lastWriteError`, { val: '', ack: true });
              } catch (_e2) {
                // ignore diagnostics errors
              }
              return res.json({ ok: true });
            } catch (e) {
              try {
                const base = `relay.controls.r${idx}`;
                await this.setStateAsync(`${base}.lastWriteOk`, { val: false, ack: true });
                await this.setStateAsync(`${base}.lastWriteTs`, { val: Date.now(), ack: true });
                await this.setStateAsync(`${base}.lastWriteError`, { val: String(e && e.message ? e.message : e), ack: true });
              } catch (_e3) {}
              return res.status(409).json({ ok: false, error: 'write_failed' });
            }
          }

          // value
          if (type !== 'number') return res.status(400).json({ ok: false, error: 'bad request' });

          const n = Number(value);
          if (!Number.isFinite(n)) return res.status(400).json({ ok: false, error: 'bad request' });

          const min = Number.isFinite(Number(it.min)) ? Number(it.min) : null;
          const max = Number.isFinite(Number(it.max)) ? Number(it.max) : null;
          const step = Number.isFinite(Number(it.step)) ? Number(it.step) : null;

          let v = n;
          if (min !== null) v = Math.max(min, v);
          if (max !== null) v = Math.min(max, v);
          if (step !== null && step > 0) v = Math.round(v / step) * step;
          if (invert) v = -v;

          try {
            const relayWriteResult = await writeRelayValue(v, 'value');
            if (isActuatorAuthorityBlockedResult(relayWriteResult)) return res.status(409).json({ ok: false, error: 'blocked_by_actuator_authority', blockedBy: relayWriteResult.blockedByOwner });
