          this.updateValue(key, scaled, ts);
        }
      };

      const concurrency = 8;
      for (let i = 0; i < plan.length; i += concurrency) {
        const slice = plan.slice(i, i + concurrency);
        await Promise.all(slice.map((entry) => applyState(entry)));
