    return this._para14aEebusApi.flushImplementationFeedback(context || {});
  }

  /**
   * Code-Teil: onStateChange
   * Zweck: Kapselt einen lokalen Verarbeitungsschritt, damit Aufrufer nicht direkt in Detaildaten eingreifen.
   * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
   * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
   */
  /**
   * Ablauf und Zusammenhang: Übernimmt ioBroker-Ereignisse in die Adapter-Laufzeit und verteilt relevante Änderungen an Anzeige, Einstellungen und Regelung. Bestätigte Messwerte und Bedien-Schreibwünsche dürfen dabei nicht verwechselt werden.
   */
  onStateChange(id, state) {
    if (this._nwShuttingDown) return;
    if (state && state.ack === false && String(id).startsWith(this.namespace + '.')
      && !centralLicenseSnapshot(this._bridge).ok) return;
    // Feed EMS datapoint cache (for embedded charging engine)
    try {
      if (this.emsEngine && this.emsEngine.dp && typeof this.emsEngine.dp.handleStateChange === 'function') {
        this.emsEngine.dp.handleStateChange(id, state);
        // NVP-Schnellregler: Eine frische externe Netzpunktprobe löst nach einem
        // kurzen Debounce unmittelbar den normalen zentralen EMS-Tick aus. Die
        // Engine erkennt die autoritativen NVP-Quellen selbst und ignoriert ihre
        // internen abgeleiteten States, sodass kein StateChange-Loop entstehen kann.
        if (state && typeof this.emsEngine.handleExternalStateChange === 'function') {
          this.emsEngine.handleExternalStateChange(id, state);
        }
      }
    } catch (_e) {}

    // Löschereignisse müssen den EMS-Messwertcache invalidieren; die übrigen
    // UI-/Regel-Handler verarbeiten weiterhin nur vorhandene State-Werte.
    if (!state) return;

    // Feed NexoLogic engine (node/graph)
    try {
      if (this.logicEngine && typeof this.logicEngine.handleStateChange === 'function') {
        this.logicEngine.handleStateChange(id, state);
      }
    } catch (_e2) {}
    try {
      const evcsHandledKeys = this._nwApplyEvcsInputSourceState(id, state, 'state-change');
      const key = this.keyFromId(id);
      const evcsMappedAlreadyHandled = !!(key && evcsHandledKeys && evcsHandledKeys.has(key));
      const ownReadOnlyEvcsMirrorAck = !!(key
        && state.ack === true
        && this._nwIsOwnStateId(id)
        && this._nwIsReadOnlyEvcsMirrorKey(key));
      let normalizedMappedValue = state.val;
      if (key && !evcsMappedAlreadyHandled && !ownReadOnlyEvcsMirrorAck) {
        normalizedMappedValue = this._nwScaleMappedValue(key, id, state.val);
        this.updateValue(key, normalizedMappedValue, state.ts);

        // Bedienzustände der Ladepunkte werden sofort im stateCache sichtbar und
        // lösen einen debouncten zentralen EMS-Tick aus. Das gilt auch für externe
        // ioBroker-Schreibzugriffe, nicht nur für die NexoWatt-Weboberfläche.
        if (/^chargingManagement\.wallboxes\.[a-z0-9_]+\.(userMode|userAutoSource|userEnabled|userStationEnabled|userPhaseMode|userStorageAssistEnabled|goalEnabled|goalTargetSocPct|goalFinishTs|goalBatteryKwh)$/i.test(key)) {
          this._nwRequestImmediateEmsTick(`state:${key}`);
        }
      }

      // Weather-App activation (FIS → Einstellungen)
      try {
        if (key === 'settings.weatherEnabled') {
          const enabled = this._notifyParseBool(state.val, false);
          if (enabled) this.startWeatherService();
          else this.stopWeatherService();
        } else if (key === 'settings.weatherUsageMode' || key === 'settings.weatherApiKey') {
          if (this._notifyGetSettingBool('weatherEnabled', false)) {
            this.startWeatherService();
            this.nwUpdateWeather('settings').catch(() => {});
          }
        }
        if (key && /^settings[.](weatherEnabled|weatherUsageMode|weatherApiKey|forecastSourceMode|openMeteoPvEnabled|forecastFallbackToDatapoints|openMeteoLatitude|openMeteoLongitude|openMeteoTimezone|forecastUpdateIntervalMin|forecastHorizonHours|pvForecastPlanningSafetyPct|pvForecastInstalledKwp|pvForecastTiltDeg|pvForecastAzimuthDeg|pvForecastLossPercent|pvForecastInverterLimitW|pvForecastArrays)$/.test(key)) {
          try { this._openMeteoPvForecastRuntime && this._openMeteoPvForecastRuntime.refresh().catch(() => {}); } catch (_eForecast) {}
        }
      } catch (_e) {}

      // Auto‑PV: cache PV‑Inverter values from nexowatt-devices (no manual mapping)
      try {
        const pvAuto = this._derivedFlow?.auto?.pvInverters;
        if (pvAuto && pvAuto.ids && pvAuto.ids.has(id)) {
          const tsMs = Number(state.ts) || Date.now();
          pvAuto.cache.set(id, { val: state.val, ts: tsMs });
          this.scheduleDerivedFlowUpdate('autoPv');
        }
      } catch (_e) {}

      // Sync: EVCS numerischer Modus (evcs.<i>.mode) <-> EMS User-Mode (chargingManagement.wallboxes.lp<i>.userMode)
      try {
        if (key) {
          // 1) Wenn ein externer oder interner Modus-DP geschrieben wird (ack=false), übersetze in userMode.
          const m = key.match(/^evcs\.(\d+)\.mode$/);
          if (m && state && state.ack === false) {
            const idx = Number(m[1]);
            const mv = Number(state.val);
            const userMode = (mv === 1) ? 'boost' : (mv === 2) ? 'minpv' : (mv === 3) ? 'pv' : 'auto';
            const userModeKey = `chargingManagement.wallboxes.lp${idx}.userMode`;
            this.setStateAsync(userModeKey, userMode, false).catch(()=>{});
            try { this.updateValue(userModeKey, userMode, Number(state.ts) || Date.now()); } catch (_e3) {}
            this._nwRequestImmediateEmsTick(`state:${userModeKey}`);
          }

          // 2) Wenn userMode geändert wird, spiegle in evcs.<i>.mode (ack=true), damit UI/Kompatibilität stimmt.
          const um = key.match(/^chargingManagement\.wallboxes\.lp(\d+)\.userMode$/);
          if (um) {
            const idx = Number(um[1]);
            const v = String(state.val ?? '').toLowerCase();
            const numMode = (v === 'boost') ? 1 : (v === 'minpv') ? 2 : (v === 'pv') ? 3 : 0;
            this.setStateAsync(`evcs.${idx}.mode`, numMode, true).catch(()=>{});
          }
        }
      } catch (_e) {}

      if (key && key.startsWith('evcs.')) {
        const ownState = this._nwIsOwnStateId(id);
        // Externe Quellen werden durch den robusten EVCS-Publisher gespiegelt.
