    // Speicherfarm nur dann als Quelle verwenden, wenn sie in der Admin-Konfiguration
    // wirklich aktiv ist und konfigurierte Speicher enthält. Ein alter stateCache-Wert
    // "storageFarm.enabled=true" darf normale Einzelanlagen nicht übernehmen.
    const farmMetrics = (typeof this._nwResolveStorageFarmMetricsFromCache === 'function')
      ? this._nwResolveStorageFarmMetricsFromCache({ now })
      : null;
    const sfEnabled = !!(farmMetrics && farmMetrics.active);
    if (farmSelectedForControl) {
      let signed = farmMetrics ? numericMeasurement(farmMetrics.totalPowerW) : null;
      if (signed !== null && Number.isFinite(signed)) {
        // storageFarm.totalPowerW ist bereits pro Speicher normalisiert und besitzt
        // eine feste Konvention (+ Entladen / - Laden). Das globale Einzel-Speicher-
        // Anzeige-Invert darf diesen kanonischen Farmwert nicht ein zweites Mal drehen.
        if (Math.abs(signed) <= deadbandW) signed = 0;
        const c = signed < 0 ? Math.abs(signed) : 0;
        const d = signed > 0 ? signed : 0;
        return {
          chargeW: Math.round(c),
          dischargeW: Math.round(d),
          signedW: Math.round(signed),
          src: 'storageFarmNet',
          inverted: false,
          fromSigned: true,
          derived: false,
          mirror: true,
          grossChargeW: farmMetrics.grossChargeW,
          grossDischargeW: farmMetrics.grossDischargeW,
          staleMs: {
            farmPower: farmMetrics.ageMs && farmMetrics.ageMs.totalPowerW,
            farmCharge: this._nwGetCacheAgeMs('storageFarm.totalChargePowerW', now),
            farmDischarge: this._nwGetCacheAgeMs('storageFarm.totalDischargePowerW', now),
          },
        };
      }

      // Die Farm ist die exklusive Mess- und Schreibtopologie. Fehlt ihr
      // Aggregat, darf kein alter Einzel-Speicher-DP als stiller Ersatz erscheinen.
      return {
        chargeW: 0,
        dischargeW: 0,
        signedW: 0,
        src: sfEnabled ? 'storageFarm-missing-power' : 'storageFarm-unavailable',
        inverted: false,
        fromSigned: true,
        derived: false,
        mirror: true,
        staleMs: {
          farmPower: this._nwGetCacheAgeMs('storageFarm.totalPowerW', now),
          farmCharge: this._nwGetCacheAgeMs('storageFarm.totalChargePowerW', now),
          farmDischarge: this._nwGetCacheAgeMs('storageFarm.totalDischargePowerW', now),
        },
      };
    }

    const batterySigned = batteryMapped ? readMapped('batteryPower', true, true) : null;
    const chargeRaw = chargeMapped ? readMapped('storageChargePower', true, true) : null;
    const dischargeRaw = dischargeMapped ? readMapped('storageDischargePower', true, true) : null;

    // Beide Split-Felder auf denselben DP gemappt = tatsächlich ein signed DP.
    if (sameChargeDischargeId && chargeRaw !== null) {
      return fromSigned(chargeRaw, 'sameChargeDischargeSigned', { mirror: true });
    }

    // Getrennte Lade-/Entlade-DPs sind autoritativ. Eine fehlende Seite wird als 0 W
    // behandelt; sie wird nicht durch Bilanzwerte ersetzt. Das schützt Historie und
    // Regelung vor verfälschten Speicherwerten bei konstantem/stalem 0-Wert.
    if (chargeRaw !== null || dischargeRaw !== null) {
      let c = chargeRaw !== null ? Math.abs(Number(chargeRaw)) : 0;
      let d = dischargeRaw !== null ? Math.abs(Number(dischargeRaw)) : 0;
      if (!Number.isFinite(c)) c = 0;
      if (!Number.isFinite(d)) d = 0;
      if (c <= deadbandW) c = 0;
      if (d <= deadbandW) d = 0;
      if (inv) { const t = c; c = d; d = t; }
      const grossChargeW = Math.max(0, c);
      const grossDischargeW = Math.max(0, d);
      const signedW = grossDischargeW - grossChargeW;
      const normalizedChargeW = signedW < 0 ? Math.abs(signedW) : 0;
      const normalizedDischargeW = signedW > 0 ? signedW : 0;
      const splitConflictNormalized = grossChargeW > deadbandW && grossDischargeW > deadbandW;
      return {
        chargeW: Math.round(normalizedChargeW),
        dischargeW: Math.round(normalizedDischargeW),
        signedW: Math.round(signedW),
        grossChargeW: Math.round(grossChargeW),
        grossDischargeW: Math.round(grossDischargeW),
        splitConflictNormalized,
        src: `${inv ? 'chargeDischarge(inv)' : 'chargeDischarge'}${splitConflictNormalized ? '-net-normalized' : ''}`,
        inverted: inv,
        fromSigned: false,
        derived: false,
        mirror: false,
        staleMs: ageInfo(),
      };
    }

    // Signed Batterie-DP ist der Fallback, wenn keine Split-DPs einen Wert liefern.
    if (batterySigned !== null) {
      return fromSigned(batterySigned, 'batterySigned', { mirror: true });
    }

    // Rechen-Fallback nur, wenn überhaupt kein Speicher-DP konfiguriert ist.
    // Wenn ein Speicher-DP konfiguriert, aber aktuell nicht lesbar ist, zeigen wir keinen
    // geratenen Wert, damit Historie/Regelung nicht verfälscht werden.
    if (!anyStorageMapped) {
      const derived = fromBalance();
      if (derived) return derived;
    }

    return {
      chargeW: 0,
      dischargeW: 0,
      signedW: 0,
      src: anyStorageMapped ? 'mapped-missing' : 'missing',
      inverted: inv,
      fromSigned: false,
      derived: false,
      mirror: !anyStorageMapped,
      staleMs: ageInfo(),
    };
  }

  /**
   * Code-Teil: _nwNormalizeEnergyFlowTsMode
   *
   * Zweck:
   * Normalisiert den internen Energiefluss-TypeScript-Modus auf `js`, `shadow` oder `ts`.
   *
   * Zusammenhang:
   * Diese Funktion ist die Sicherheitsklammer für die spätere produktive TS-Umschaltung.
   * Sie verhindert, dass Tippfehler oder alte Config-Werte versehentlich die Runtime umstellen.
   *
   * Wichtig:
   * `shadow` bedeutet: JavaScript bleibt produktiv, TypeScript rechnet nur parallel.
   */
  _nwNormalizeEnergyFlowTsMode(value) {
    const mode = String(value === null || value === undefined ? '' : value).trim().toLowerCase();
    if (mode === 'ts' || mode === 'typescript') return 'ts';
    if (mode === 'js' || mode === 'javascript') return 'js';
    if (mode === 'shadow' || mode === 'compare' || mode === 'diagnose') return 'shadow';
    return 'shadow';
  }

  /**
   * Code-Teil: _nwGetEnergyFlowTsMode
   *
   * Zweck:
   * Ermittelt den aktuellen Energiefluss-TS-Modus aus Config oder Environment.
   *
   * Reihenfolge:
   * 1. Environment `NEXOWATT_ENERGYFLOW_TS_MODE` für Labortests.
   * 2. `config.tsMigration.energyFlowMode` als spätere Admin-/Config-Quelle.
   * 3. Legacy-Feld `config.energyFlowTsMode`, falls ein Teststand es bereits setzt.
   *
   * Sicherheitsregel:
   * Der Default bleibt `shadow`, also JS produktiv + TS-Vergleich. Keine automatische
   * Umschaltung auf TS ohne explizite Freigabe.
   */
  _nwGetEnergyFlowTsMode() {
    try {
      const env = process && process.env ? process.env.NEXOWATT_ENERGYFLOW_TS_MODE : '';
      if (env) return this._nwNormalizeEnergyFlowTsMode(env);
    } catch (_eEnv) {}
    const cfg = (this.config && typeof this.config === 'object') ? this.config : {};
    const tm = (cfg.tsMigration && typeof cfg.tsMigration === 'object') ? cfg.tsMigration : {};
    return this._nwNormalizeEnergyFlowTsMode(tm.energyFlowMode || cfg.energyFlowTsMode || 'shadow');
  }

  /**
   * Code-Teil: _nwBuildEnergyFlowTsEffectivePlan
   *
   * Zweck:
   * Baut einen sicheren Umschaltplan aus JS-Runtime-Werten und TS-Shadow-Werten.
   *
   * Zusammenhang:
   * 0.7.101 aktiviert die produktive Umschaltung kontrolliert: TS darf nur bei sauberem Gate übernehmen.
   * Der Plan beschreibt, welche Quelle in diesem Tick verwendet wird. TS kann nur dann
   * produktiv werden, wenn alle Sicherheitsgates erfüllt sind; sonst bleibt JS aktiv.
   *
   * Wichtig:
   * Diese Funktion schreibt keine States und verändert keine Runtime-Werte. Sie liefert nur
   * Diagnose/Planung, damit eine spätere Version die Umschaltung kontrolliert übernehmen kann.
   */
  _nwBuildEnergyFlowTsEffectivePlan(mode, runtimeValues, tsValues, shadowResult) {
    const normalizedMode = this._nwNormalizeEnergyFlowTsMode(mode);
    const gate = this._nwGetEnergyFlowTsSwitchConfig ? this._nwGetEnergyFlowTsSwitchConfig() : { productionAllowed: false };
    const tsReady = !!(shadowResult && shadowResult.available && shadowResult.ok && tsValues && typeof tsValues === 'object');
    const candidateSafety = this._nwValidateEnergyFlowTsCandidate(shadowResult);
    const plantGate = this._nwEvaluateEnergyFlowPlantGate ? this._nwEvaluateEnergyFlowPlantGate(gate) : { required: true, ok: false, blockers: ['Reale Anlagen-Auswertung nicht verfügbar.'] };
    const plantGateWarmupOnly = this._nwIsEnergyFlowPlantGateWarmupOnly ? this._nwIsEnergyFlowPlantGateWarmupOnly(plantGate) : false;
    const fixedSourceState = this._nwGetEnergyFlowTsFixedSourceState ? this._nwGetEnergyFlowTsFixedSourceState() : null;
    const fixedSourceReady = !!(fixedSourceState && fixedSourceState.ready === true);
    const normalSourceActive = fixedSourceReady && gate.normalSourceAfterFixedReady !== false;
    const plantGateAllowsTs = !plantGate.required || plantGate.ok === true || plantGateWarmupOnly === true || normalSourceActive === true;
    const wantsTs = normalizedMode === 'ts';
    const useTsCandidate = wantsTs && tsReady && gate.productionAllowed === true && candidateSafety.ok === true && plantGateAllowsTs;
    const blockedReasons = [];
    if (wantsTs && gate.productionAllowed !== true) blockedReasons.push('Sicherheitsfreigabe energyFlowProductionAllowed fehlt.');
    if (wantsTs && !tsReady) {
      if (!shadowResult || !shadowResult.available) blockedReasons.push('TypeScript-Energiefluss-Spiegel nicht verfügbar.');
      if (shadowResult && shadowResult.ok === false) blockedReasons.push('Shadow-Vergleich meldet Abweichungen.');
      if (!tsValues || typeof tsValues !== 'object') blockedReasons.push('TS-Werte fehlen.');
    }
    if (wantsTs && tsReady && candidateSafety.ok !== true) {
      blockedReasons.push(...candidateSafety.blockers);
    }
    if (wantsTs && tsReady && candidateSafety.ok === true && plantGate.required && plantGate.ok !== true && !plantGateWarmupOnly && !normalSourceActive) {
      blockedReasons.push(...(Array.isArray(plantGate.blockers) ? plantGate.blockers : ['Reale Anlagen-Auswertung ist nicht stabil.']));
    }
    if (normalizedMode === 'js') blockedReasons.push('Modus js: TypeScript-Energiefluss ist deaktiviert.');
    if (normalizedMode === 'shadow') blockedReasons.push('Modus shadow: JavaScript bleibt produktiv; TypeScript ist nur Diagnose.');
    return {
      mode: normalizedMode,
      productionAllowed: gate.productionAllowed === true,
      source: useTsCandidate ? (normalSourceActive ? 'ts-normal' : 'ts-candidate') : 'js-runtime',
      canUseTs: tsReady && candidateSafety.ok === true,
      wouldUseTs: useTsCandidate,
      runtimeAuthoritative: !useTsCandidate,
      values: useTsCandidate ? tsValues : runtimeValues,
      candidateSafety,
      plantEvaluationRequired: !!plantGate.required,
      plantEvaluationOk: plantGate.required ? (plantGate.ok === true || plantGateWarmupOnly === true) : true,
      plantEvaluationSoftReleased: !!plantGateWarmupOnly,
      normalSourceActive,
      fixedSourceReady,
      fixedSourceState,
      plantEvaluation: plantGate,
      blockedReasons,
      safetyText: useTsCandidate
        ? 'TS-Werte werden produktiv genutzt, weil Modus ts, energyFlowProductionAllowed, Shadow-Vergleich, Kandidatenprüfung, Warmup und Anlagen-Gate sauber sind.'
        : 'Produktiv bleibt die JavaScript-Runtime.',
    };
  }

  /**
   * Code-Teil: _nwValidateEnergyFlowTsCandidate
   *
   * Zweck:
   * Prüft die vom TypeScript-Energiefluss-Resolver gelieferten Kandidatenwerte,
   * bevor sie im Modus `ts` als effektive Energieflusswerte genutzt werden dürfen.
   *
   * Zusammenhang:
   * Diese Prüfung ist der zusätzliche Sicherheitsgurt für 0.7.82. Der Shadow-Vergleich
   * sagt, ob JS und TS nahe beieinander liegen; diese Funktion prüft zusätzlich, ob die
   * TS-Kandidatenwerte selbst vollständig, nicht-negativ und plausibel sind.
   *
   * Wichtig:
   * Wenn etwas unklar ist, bleibt die JavaScript-Runtime führend. So schützen wir
   * LIVE-Werte, History und Speicher-/Netzdiagnosen vor fehlerhaften Kandidatenwerten.
   */
  _nwValidateEnergyFlowTsCandidate(tsShadow = {}) {
    const values = (tsShadow && tsShadow.ts && typeof tsShadow.ts === 'object') ? tsShadow.ts : null;
    const blockers = [];
    const warnings = [];
    if (!values) {
      return { ok: false, blockers: ['TS-Kandidatenwerte fehlen.'], warnings, values: {} };
    }

    let storageRatedPowerW = Number(this.config && this.config.storage && this.config.storage.ratedPowerW);
    if (!Number.isFinite(storageRatedPowerW) || storageRatedPowerW <= 0) {
      storageRatedPowerW = 0;
      try {
        const farmRows = this.config && this.config.storageFarm && Array.isArray(this.config.storageFarm.storages)
          ? this.config.storageFarm.storages
          : [];
        storageRatedPowerW = farmRows.reduce((sum, row) => {
          if (!row || row.enabled === false) return sum;
          const maxChargeW = Number(row.maxChargeW);
          const maxDischargeW = Number(row.maxDischargeW);
          const rowRatedW = Math.max(
            Number.isFinite(maxChargeW) && maxChargeW > 0 ? maxChargeW : 0,
            Number.isFinite(maxDischargeW) && maxDischargeW > 0 ? maxDischargeW : 0,
          );
          return sum + rowRatedW;
        }, 0);
      } catch (_e) {
        storageRatedPowerW = 0;
      }
    }
    const storagePowerProfile = (nwFeatureFlagsService && typeof nwFeatureFlagsService.storagePerformanceProfile === 'function')
      ? nwFeatureFlagsService.storagePerformanceProfile(this._nwCurrentLicenseEdition(), storageRatedPowerW)
      : { energyFlowPlausibilityMaxW: 1000000 };
    const candidatePowerMaxW = Math.max(1000000, Number(storagePowerProfile.energyFlowPlausibilityMaxW || 1000000));

    const required = [
      ['gridBuyW', 'Netzbezug'],
      ['gridSellW', 'Netzeinspeisung'],
      ['storageChargeW', 'Speicher Laden'],
      ['storageDischargeW', 'Speicher Entladen'],
      ['buildingLoadW', 'Gebäudelast'],
    ];
    const normalized = {};
    for (const [key, label] of required) {
      const n = Number(values[key]);
      if (!Number.isFinite(n)) {
        blockers.push(`${label} fehlt oder ist nicht numerisch.`);
        continue;
      }
      if (n < 0) blockers.push(`${label} ist negativ (${n} W).`);
      if (Math.abs(n) > candidatePowerMaxW) blockers.push(`${label} ist für das ${String(storagePowerProfile.label || 'Lizenz')}-Leistungsprofil unrealistisch groß (${n} W > ${candidatePowerMaxW} W).`);
      normalized[key] = Math.round(n);
    }

    if ((normalized.storageChargeW || 0) > 100 && (normalized.storageDischargeW || 0) > 100) {
      warnings.push('Speicher meldet gleichzeitig Laden und Entladen > 100 W. Wert wird nicht blockiert, Mapping sollte aber geprüft werden.');
    }
    if ((normalized.gridBuyW || 0) > 100 && (normalized.gridSellW || 0) > 100) {
      warnings.push('Netz meldet gleichzeitig Bezug und Einspeisung > 100 W. Wert wird nicht blockiert, Mapping sollte aber geprüft werden.');
    }
    if (tsShadow && tsShadow.ok === false) blockers.push('Shadow-Vergleich meldet Abweichungen.');
    if (tsShadow && Array.isArray(tsShadow.mismatches) && tsShadow.mismatches.length) blockers.push('Shadow-Mismatches vorhanden.');

    return {
      ok: blockers.length === 0,
      blockers,
      warnings,
      values: normalized,
    };
  }

  /**
   * Code-Teil: _nwGetEnergyFlowTsMirrorResolver
   *
   * Zweck:
   * Lädt den aus TypeScript erzeugten Energiefluss-Resolver-Spiegel für einen
   * reinen Shadow-/Vergleichsmodus.
   *
   * Zusammenhang:
   * Der produktive Energiefluss wird weiterhin durch die vorhandene JavaScript-Logik
   * berechnet. Diese Methode lädt nur die TS-Spiegeldatei, damit wir beide Ergebnisse
   * nebeneinander vergleichen können, ohne Anzeige, History oder Regelung zu ändern.
   *
   * Wichtig:
   * Fehler beim Laden dürfen den Adapter niemals stoppen. Wenn der Spiegel fehlt oder
   * defekt ist, bleibt die bisherige Runtime unverändert aktiv.
   */
  _nwGetEnergyFlowTsMirrorResolver() {
    try {
      if (this._energyFlowTsMirrorResolver) return this._energyFlowTsMirrorResolver;
      if (this._energyFlowTsMirrorResolverFailed) return null;
      const mod = require(path.join(__dirname, 'lib', 'ts-mirrors', 'energy-flow', 'resolvers', 'energy-flow-resolver.js'));
      if (mod && typeof mod.buildEnergyFlowSnapshot === 'function') {
        this._energyFlowTsMirrorResolver = mod;
        return mod;
      }
      this._energyFlowTsMirrorResolverFailed = true;
      return null;
    } catch (e) {
      this._energyFlowTsMirrorResolverFailed = true;
      try { this.log.debug(`[energy-flow-ts-shadow] mirror unavailable: ${e && e.message ? e.message : e}`); } catch (_e) {}
      return null;
    }
  }

  /**
   * Code-Teil: _nwBuildEnergyFlowTsShadowInput
   *
   * Zweck:
   * Übersetzt die aktuell von der JavaScript-Runtime berechneten Eingänge in die
   * Eingabeform des TypeScript-Energiefluss-Resolvers.
   *
   * Zusammenhang:
   * Diese Funktion ist eine Brücke für den Migrationsvergleich. Sie verbindet die
   * vorhandenen Mapping-/Cachewerte aus `main.js` mit den Typverträgen aus `src-ts`.
   *
   * Wichtig:
   * Die Ausgabe dieser Funktion darf noch keine Produktivwerte ersetzen. Sie dient nur
   * dem Vergleich, damit wir später sehen, ob der TS-Resolver wirklich identisch oder
   * besser rechnet.
   */
  _nwBuildEnergyFlowTsShadowInput(ctx = {}) {
    const dps = (this.config && this.config.datapoints && typeof this.config.datapoints === 'object') ? this.config.datapoints : {};
    const idOf = (key) => String(dps[key] || '').trim();
    const chargeMapped = !!idOf('storageChargePower');
    const dischargeMapped = !!idOf('storageDischargePower');
    const batteryMapped = !!idOf('batteryPower');
    const sameChargeDischargeId = !!(chargeMapped && dischargeMapped && idOf('storageChargePower') === idOf('storageDischargePower'));
    const gridBuyMapped = !!idOf('gridBuyPower');
    const gridSellMapped = !!idOf('gridSellPower');
    const gridSignedMapped = !!idOf('gridPointPower');
    const storageFlow = ctx.storageFlow || {};
    const storageSrc = String(storageFlow.src || '');
    const storageFromFarm = storageSrc.indexOf('storageFarm') === 0;

    return {
      ts: Number(ctx.ts) || Date.now(),
      pvW: Number.isFinite(Number(ctx.productionW)) ? Number(ctx.productionW) : 0,
      buildingLoadW: ctx.consumptionMapped ? this._nwGetNumberFromCache('consumptionTotal') : undefined,
      grid: {
        hasConfiguredSplitDp: !!(gridBuyMapped || gridSellMapped),
        hasConfiguredSignedDp: !!(gridSignedMapped && !(gridBuyMapped || gridSellMapped)),
        importW: Number.isFinite(Number(ctx.gridBuyW)) ? Number(ctx.gridBuyW) : 0,
        exportW: Number.isFinite(Number(ctx.gridSellW)) ? Number(ctx.gridSellW) : 0,
        signedW: Number.isFinite(Number(ctx.gridNetRaw)) ? Number(ctx.gridNetRaw) : null,
        signedConvention: 'positive-import',
      },
      storage: {
        hasConfiguredSplitDp: !!((chargeMapped || dischargeMapped) && !sameChargeDischargeId) || storageFromFarm,
        hasConfiguredSignedDp: !!(batteryMapped || sameChargeDischargeId) && !storageFromFarm,
        chargeW: Number.isFinite(Number(ctx.chargeW)) ? Number(ctx.chargeW) : 0,
        dischargeW: Number.isFinite(Number(ctx.dischargeW)) ? Number(ctx.dischargeW) : 0,
        signedW: batteryMapped
          ? this._nwGetRawNumberFromCache('batteryPower', null, null, Number(ctx.ts) || Date.now())
          : (sameChargeDischargeId ? this._nwGetRawNumberFromCache('storageChargePower', null, null, Number(ctx.ts) || Date.now()) : null),
        socPct: this._nwGetNumberFromCache('storageSoc'),
        signedConvention: this._nwIsBatterySignInverted() ? 'positive-charge' : 'positive-discharge',
        calculatedSignedW: (!chargeMapped && !dischargeMapped && !batteryMapped && storageFlow.derived) ? Number(storageFlow.signedW) : undefined,
        balance: {
          pvW: Number.isFinite(Number(ctx.productionW)) ? Number(ctx.productionW) : 0,
          gridImportW: Number.isFinite(Number(ctx.gridBuyW)) ? Number(ctx.gridBuyW) : 0,
          gridExportW: Number.isFinite(Number(ctx.gridSellW)) ? Number(ctx.gridSellW) : 0,
          additionalKnownLoadW: ctx.consumptionMapped ? this._nwGetNumberFromCache('consumptionTotal') : undefined,
        },
      },
      evcsW: Number.isFinite(Number(ctx.evW)) ? Number(ctx.evW) : 0,
      heatingRodW: Number.isFinite(Number(ctx.heatingRodW)) ? Number(ctx.heatingRodW) : 0,
      thermalW: Number.isFinite(Number(ctx.thermalW)) ? Number(ctx.thermalW) : 0,
    };
  }

  /**
   * Code-Teil: _nwRunEnergyFlowTsShadowComparison
   *
   * Zweck:
   * Führt den neuen TypeScript-Energiefluss-Resolver parallel aus und vergleicht dessen
   * Ergebnis mit der aktuell produktiven JavaScript-Runtime.
   *
   * Zusammenhang:
   * Das ist der Sicherheitsgurt für die spätere Migration. Abweichungen werden nur
   * diagnostiziert/geloggt. Dashboard, History, Heizstab, Core-Limits und KI verwenden
   * weiterhin die bisher berechneten JavaScript-Werte.
   *
   * Wichtig:
   * Diese Funktion darf niemals produktive Werte überschreiben. Genau deshalb bleibt
   * 0.7.75 ein Shadow-/Vergleichsschritt und keine Umschaltung.
   */
  _nwRunEnergyFlowTsShadowComparison(ctx = {}) {
    try {
      const mode = this._nwNormalizeEnergyFlowTsMode(ctx.mode || this._nwGetEnergyFlowTsMode());
      if (mode === 'js') {
        const runtimeValues = {
          gridBuyW: Math.round(Number(ctx.gridBuyW) || 0),
          gridSellW: Math.round(Number(ctx.gridSellW) || 0),
          storageChargeW: Math.round(Number(ctx.chargeW) || 0),
          storageDischargeW: Math.round(Number(ctx.dischargeW) || 0),
          buildingLoadW: Math.round(Number(ctx.loadTotalW) || 0),
        };
        return {
          available: false,
          source: 'js-mode',
          mode,
          ok: true,
          mismatches: [],
          runtime: runtimeValues,
          ts: null,
          effectivePlan: this._nwBuildEnergyFlowTsEffectivePlan(mode, runtimeValues, null, { available: false, ok: true }),
        };
      }
      const resolver = this._nwGetEnergyFlowTsMirrorResolver();
      if (!resolver || typeof resolver.buildEnergyFlowSnapshot !== 'function') return { available: false, source: 'missing', mode };
      const input = this._nwBuildEnergyFlowTsShadowInput(ctx);
      const snapshot = resolver.buildEnergyFlowSnapshot(input);
      const tsValues = {
        gridBuyW: Math.round(Number(snapshot && snapshot.grid ? snapshot.grid.importW : 0) || 0),
        gridSellW: Math.round(Number(snapshot && snapshot.grid ? snapshot.grid.exportW : 0) || 0),
        storageChargeW: Math.round(Number(snapshot && snapshot.storage ? snapshot.storage.chargeW : 0) || 0),
        storageDischargeW: Math.round(Number(snapshot && snapshot.storage ? snapshot.storage.dischargeW : 0) || 0),
        buildingLoadW: Number.isFinite(Number(snapshot && snapshot.buildingLoadW)) ? Math.round(Number(snapshot.buildingLoadW)) : null,
      };
      const runtimeValues = {
        gridBuyW: Math.round(Number(ctx.gridBuyW) || 0),
        gridSellW: Math.round(Number(ctx.gridSellW) || 0),
        storageChargeW: Math.round(Number(ctx.chargeW) || 0),
        storageDischargeW: Math.round(Number(ctx.dischargeW) || 0),
        buildingLoadW: Math.round(Number(ctx.loadTotalW) || 0),
      };
      const toleranceW = Number.isFinite(Number(ctx.toleranceW)) ? Math.max(0, Number(ctx.toleranceW)) : 120;
      const mismatches = [];
      const compare = (key, label, tol = toleranceW) => {
        const a = runtimeValues[key];
        const b = tsValues[key];
        if (b === null || b === undefined || !Number.isFinite(Number(a))) return;
        if (Math.abs(Number(a) - Number(b)) > tol) mismatches.push(`${label}: js=${a}W ts=${b}W`);
      };
      compare('gridBuyW', 'gridBuyW');
      compare('gridSellW', 'gridSellW');
      compare('storageChargeW', 'storageChargeW');
      compare('storageDischargeW', 'storageDischargeW');
      // Gebäudelast ist durch Anti-Spike-Hold/Fallback absichtlich weniger streng.
      compare('buildingLoadW', 'buildingLoadW', Math.max(750, toleranceW * 4));

      const result = {
        available: true,
        source: mode === 'ts' ? 'ts-mirror-switch-candidate' : 'ts-mirror-shadow',
        mode,
        ok: mismatches.length === 0,
        mismatches,
        runtime: runtimeValues,
        ts: tsValues,
        storageSource: snapshot && snapshot.storage ? snapshot.storage.source : '',
        gridSource: snapshot && snapshot.grid ? snapshot.grid.source : '',
      };
      result.effectivePlan = this._nwBuildEnergyFlowTsEffectivePlan(mode, runtimeValues, tsValues, result);
      result.candidateSafety = result.effectivePlan ? result.effectivePlan.candidateSafety : null;

      if (mismatches.length) {
        const hash = mismatches.join('|');
        const now = Number(ctx.ts) || Date.now();
        const lastHash = this._energyFlowTsShadowWarnHash;
        const lastAt = Number(this._energyFlowTsShadowWarnAt) || 0;
        if (hash !== lastHash || (now - lastAt) > 5 * 60 * 1000) {
          this._energyFlowTsShadowWarnHash = hash;
          this._energyFlowTsShadowWarnAt = now;
          try { this.log.warn(`[energy-flow-ts-shadow] Runtime/TS mismatch: ${mismatches.join('; ')}`); } catch (_e) {}
        }
      }
      return result;
    } catch (e) {
      try { this.log.debug(`[energy-flow-ts-shadow] comparison failed: ${e && e.message ? e.message : e}`); } catch (_e) {}
      return { available: false, source: 'error', error: e && e.message ? String(e.message) : String(e) };
    }
  }

  /**
   * Code-Teil: _nwGetEnergyFlowTsSwitchConfig
   *
   * Zweck:
   * Liest den internen Migrationsmodus für den Energiefluss.
   *
   * Zusammenhang:
   * Ab 0.7.80 bereiten wir die kontrollierte Umschaltung JS → TS vor. Der
   * Adapter darf aber nicht automatisch auf TS wechseln, nur weil ein Spiegel
   * vorhanden ist. Diese Funktion kapselt daher den gewünschten Modus und eine
   * zusätzliche Sicherheitsfreigabe.
   *
   * Wichtig:
   * Standard ist ab 0.7.101 der kontrollierte `ts`-Kandidatenmodus. `ts` wird
   * aber nur produktiv, wenn zusätzlich Sicherheitsfreigabe, Shadow-Vergleich,
   * Kandidatenprüfung, Warmup und reale Anlagen-Auswertung sauber sind.
   */
  _nwGetEnergyFlowTsSwitchConfig() {
    const cfg = (this.config && this.config.tsMigration && typeof this.config.tsMigration === 'object') ? this.config.tsMigration : {};
    let rawMode = '';
    try { rawMode = process && process.env ? String(process.env.NEXOWATT_ENERGYFLOW_TS_MODE || '') : ''; } catch (_eEnv) {}
    if (!rawMode) rawMode = String(cfg.energyFlowMode || cfg.energyFlowTsMode || cfg.flowMode || 'ts');
    const mode = ['js', 'shadow', 'ts'].includes(String(rawMode).trim().toLowerCase()) ? String(rawMode).trim().toLowerCase() : 'ts';
    const productionAllowed = cfg.energyFlowProductionAllowed === true || cfg.allowEnergyFlowTsProduction === true;
    const warmupRaw = Math.round(Number(cfg.energyFlowCandidateWarmupTicks));
    const warmupTicks = Number.isFinite(warmupRaw) ? Math.max(1, Math.min(30, warmupRaw)) : 3;
    const autoFallback = cfg.energyFlowCandidateAutoFallback !== false;
    const requireStablePlantEvaluation = cfg.energyFlowRequireStablePlantEvaluation !== false;
    const plantMinSamplesRaw = Math.round(Number(cfg.energyFlowPlantMinSamples));
    const plantMinSamples = Number.isFinite(plantMinSamplesRaw) ? Math.max(1, Math.min(120, plantMinSamplesRaw)) : 5;
    const plantMinOkRaw = Math.round(Number(cfg.energyFlowPlantMinConsecutiveOk));
    const plantMinConsecutiveOk = Number.isFinite(plantMinOkRaw) ? Math.max(1, Math.min(120, plantMinOkRaw)) : 5;
    const fixedMinRaw = Math.round(Number(cfg.energyFlowFixedSourceMinTsTicks));
    const fixedSourceMinTsTicks = Number.isFinite(fixedMinRaw) ? Math.max(3, Math.min(240, fixedMinRaw)) : 12;
    const normalSourceAfterFixedReady = cfg.energyFlowTsNormalSourceAfterFixedReady !== false;
    return { requestedMode: mode, productionAllowed, warmupTicks, autoFallback, requireStablePlantEvaluation, plantMinSamples, plantMinConsecutiveOk, fixedSourceMinTsTicks, normalSourceAfterFixedReady };
  }

  /**
   * Code-Teil: _nwBuildEnergyFlowTsRuntimePlantSample
   *
   * Zweck:
   * Erstellt einen echten Laufzeit-Sample nur für den Energiefluss-TS-Kandidaten.
   *
   * Zusammenhang:
   * Bisher hing das Plant-Gate stark an App-Center-Diagnoseabrufen und an anderen
   * Bereichen wie Core-Limits/Heizstab. Für die Energiefluss-Produktivschaltung ist
   * aber entscheidend, ob der Energiefluss selbst über mehrere echte Adapter-Ticks
   * stabil ist. 0.7.102 reduziert deshalb unnötige JS-Fallbacks, ohne das Gate zu
   * entfernen.
   *
   * Wichtig:
   * Dieser Sample schaltet nichts. Er liefert nur eine stabilere Entscheidungsbasis
   * für `_nwEvaluateEnergyFlowTsSwitch`.
   */
  _nwBuildEnergyFlowTsRuntimePlantSample(tsShadow = {}) {
    const mismatches = Array.isArray(tsShadow && tsShadow.mismatches) ? tsShadow.mismatches : [];
    const available = !!(tsShadow && tsShadow.available && tsShadow.ts && typeof tsShadow.ts === 'object');
    const hasError = !!(tsShadow && (tsShadow.error || tsShadow.parseError));
    const ok = available && !hasError && (tsShadow.ok === true || mismatches.length === 0) && mismatches.length === 0;
    const blockers = [];
    const warnings = [];
    if (!available) blockers.push('Energiefluss-TS-Resolver liefert noch keinen Runtime-Snapshot.');
    if (hasError) blockers.push('Energiefluss-TS-Resolver meldet Fehler.');
    if (mismatches.length) blockers.push(`Energiefluss-TS-Shadow meldet ${mismatches.length} Abweichung(en).`);
    return {
      ts: Date.now(),
      ok,
      available,
      source: String((tsShadow && tsShadow.source) || 'energy-flow-ts-runtime'),
      mismatchCount: mismatches.length,
      mismatches: mismatches.slice(0, 5),
      blockers,
      warnings,
      shadowOk: tsShadow && tsShadow.ok === true,
    };
  }

  /**
   * Code-Teil: _nwSummarizeEnergyFlowTsRuntimePlantSamples
   *
   * Zweck:
   * Bewertet die letzten echten Energiefluss-TS-Runtime-Samples. Dieser Summary wird
   * ab 0.7.102 für das Plant-Gate des Energieflusses bevorzugt.
   *
   * Zusammenhang:
   * Dadurch muss der Betreiber nicht erst das App-Center offen lassen, damit Samples
   * gesammelt werden. Jeder echte Energiefluss-Tick kann zur Stabilität beitragen.
   */
  _nwSummarizeEnergyFlowTsRuntimePlantSamples(samples = []) {
    const list = Array.isArray(samples) ? samples.filter(Boolean) : [];
    const last = list.length ? list[list.length - 1] : null;
    let consecutiveOk = 0;
    for (let i = list.length - 1; i >= 0; i--) {
      if (!list[i] || list[i].ok !== true) break;
      consecutiveOk++;
    }
    const okCount = list.filter((x) => x && x.ok === true).length;
    const blockerCount = list.reduce((sum, x) => sum + (Array.isArray(x && x.blockers) ? x.blockers.length : 0), 0);
    const warningCount = list.reduce((sum, x) => sum + (Array.isArray(x && x.warnings) ? x.warnings.length : 0), 0);
    const mismatchCount = list.reduce((sum, x) => sum + Math.max(0, Number(x && x.mismatchCount) || 0), 0);
    const okRatioPct = list.length ? Math.round((okCount / list.length) * 1000) / 10 : 0;
    return {
      version: 1,
      source: 'energy-flow-ts-runtime-plant-evaluation-v1',
      ts: Date.now(),
      sampleCount: list.length,
      okCount,
      okRatioPct,
      consecutiveOk,
      blockerCount,
      warningCount,
      mismatchCount,
      status: !list.length ? 'waiting' : (last && last.ok ? 'observing' : 'blocked'),
      stable: list.length >= 5 && consecutiveOk >= 5 && blockerCount === 0 && mismatchCount === 0,
      lastSample: last,
      recentSamples: list.slice(-10),
      nextAction: list.length >= 5 && consecutiveOk >= 5 && blockerCount === 0 && mismatchCount === 0
        ? 'Energiefluss-TS ist über echte Runtime-Ticks stabil. JS-Fallback bleibt nur noch Sicherheitsnetz.'
        : 'Weitere echte Energiefluss-Ticks sammeln oder Blocker prüfen.',
    };
  }

  /**
   * Code-Teil: _nwUpdateEnergyFlowTsRuntimePlantEvaluation
   *
   * Zweck:
   * Aktualisiert den energiefluss-spezifischen Runtime-Puffer. Dieser Puffer wird in
   * jedem Energiefluss-Tick gepflegt und reduziert unnötige JS-Fallbacks, weil die
   * Stabilitätsbewertung nicht mehr nur über App-Center-Diagnoseabrufe entsteht.
   */
  _nwUpdateEnergyFlowTsRuntimePlantEvaluation(tsShadow = {}) {
    try {
      const sample = this._nwBuildEnergyFlowTsRuntimePlantSample(tsShadow || {});
      const current = Array.isArray(this._energyFlowTsRuntimePlantSamples) ? this._energyFlowTsRuntimePlantSamples : [];
      const next = current.concat(sample).slice(-90);
      this._energyFlowTsRuntimePlantSamples = next;
      return this._nwSummarizeEnergyFlowTsRuntimePlantSamples(next);
    } catch (e) {
      return {
        version: 1,
        source: 'energy-flow-ts-runtime-plant-evaluation-v1',
        ts: Date.now(),
        sampleCount: 0,
        okCount: 0,
        consecutiveOk: 0,
        blockerCount: 1,
        warningCount: 0,
        mismatchCount: 0,
        stable: false,
        status: 'error',
        blockers: ['Energiefluss-Runtime-Anlagenauswertung fehlgeschlagen: ' + (e && e.message ? e.message : e)],
        nextAction: 'Adapterlog prüfen; Energiefluss bleibt auf JS-Fallback.',
      };
    }
  }

  /**
   * Code-Teil: _nwEvaluateEnergyFlowPlantGate
   *
   * Zweck:
   * Prüft die reale Anlagen-Auswertung als zusätzliche Freigabe für den produktiven
   * Energiefluss-TS-Kandidatenmodus.
   *
   * Zusammenhang:
   * 0.7.85 verschärft die Umschaltregel: Ein einzelner sauberer Shadow-Tick reicht
   * nicht mehr aus. Der Adapter muss mehrere stabile Anlagen-Samples gesammelt haben,
   * bevor TS produktiv Energieflusswerte liefern darf. Ab 0.7.102 nutzt der Energiefluss bevorzugt eigene Runtime-Samples, damit keine App-Center-Diagnose offen bleiben muss.
   *
   * Wichtig:
   * Wenn keine Samples vorhanden sind, bleibt die JavaScript-Runtime führend. Das
   * schützt LIVE, History und Regelungen vor einer zu frühen TS-Umschaltung.
   */
  _nwEvaluateEnergyFlowPlantGate(cfg = {}) {
    const runtimeEvaluation = cfg && cfg.runtimePlantEvaluation && typeof cfg.runtimePlantEvaluation === 'object'
      ? cfg.runtimePlantEvaluation
      : null;
    const samples = Array.isArray(this._tsShadowPlantSamples) ? this._tsShadowPlantSamples : [];
    const evaluation = runtimeEvaluation || (this._nwSummarizeTsShadowPlantSamples ? this._nwSummarizeTsShadowPlantSamples(samples) : { stable: false, sampleCount: samples.length, consecutiveOk: 0, blockerCount: 1, mismatchCount: 0, nextAction: 'Anlagenauswertung nicht verfügbar.' });
    const minSamples = Math.max(1, Math.min(120, Math.round(Number(cfg.plantMinSamples) || 5)));
    const minConsecutiveOk = Math.max(1, Math.min(120, Math.round(Number(cfg.plantMinConsecutiveOk) || 5)));
    const sampleCount = Math.max(0, Math.round(Number(evaluation.sampleCount) || 0));
    const consecutiveOk = Math.max(0, Math.round(Number(evaluation.consecutiveOk) || 0));
    const stableByCounts = sampleCount >= minSamples && consecutiveOk >= minConsecutiveOk && Number(evaluation.blockerCount || 0) === 0 && Number(evaluation.mismatchCount || 0) === 0;
    const ok = evaluation.stable === true && stableByCounts;
    const blockers = [];
    const gateLabel = runtimeEvaluation ? 'Energiefluss-Runtime-Auswertung' : 'Reale Anlagen-Auswertung';
    if (sampleCount < minSamples) blockers.push(`${gateLabel}: erst ${sampleCount}/${minSamples} Samples gesammelt.`);
    if (consecutiveOk < minConsecutiveOk) blockers.push(`${gateLabel}: erst ${consecutiveOk}/${minConsecutiveOk} OK-Samples in Folge.`);
    if (Number(evaluation.blockerCount || 0) > 0) blockers.push(`Reale Anlagen-Auswertung meldet ${Number(evaluation.blockerCount || 0)} Blocker.`);
    if (Number(evaluation.mismatchCount || 0) > 0) blockers.push(`Reale Anlagen-Auswertung meldet ${Number(evaluation.mismatchCount || 0)} Abweichungen.`);
    if (evaluation.stable !== true && !blockers.length) blockers.push('Reale Anlagen-Auswertung ist noch nicht stabil.');
    return {
      required: cfg.requireStablePlantEvaluation !== false,
      source: runtimeEvaluation ? 'energy-flow-runtime' : 'shadow-plant',
      ok,
      stable: evaluation.stable === true,
      sampleCount,
      consecutiveOk,
      minSamples,
      minConsecutiveOk,
      evaluation,
      blockers,
      nextAction: evaluation.nextAction || '',
    };
  }

  /**
   * Code-Teil: _nwIsEnergyFlowPlantGateWarmupOnly
   *
   * Zweck:
   * Unterscheidet harte Anlagen-Blocker von reinem Beobachtungs-/Warmup-Rückstand.
   *
   * Zusammenhang:
   * 0.7.101 hat TS als produktiven Energiefluss-Kandidaten aktiviert. In der Praxis
   * fiel der Adapter aber unnötig lange auf JS zurück, wenn die reale Anlagen-Auswertung
   * noch nicht genug Samples gesammelt hatte, obwohl der aktuelle Tick bereits per
   * Shadow-Vergleich und Kandidatenprüfung sauber war.
   *
   * Wichtig:
   * Diese Funktion reduziert nur den JS-Fallback bei reinen Warmup-Gründen wie
   * „erst 2/5 Samples“. Harte Blocker wie Shadow-Mismatches, echte Blocker oder
   * fehlende TS-Werte bleiben weiterhin blockierend.
   */
  _nwIsEnergyFlowPlantGateWarmupOnly(plantGate = {}) {
    if (!plantGate || plantGate.required === false || plantGate.ok === true) return false;
    const evaluation = (plantGate.evaluation && typeof plantGate.evaluation === 'object') ? plantGate.evaluation : {};
    const blockerCount = Number(evaluation.blockerCount || 0);
    const mismatchCount = Number(evaluation.mismatchCount || 0);
    if (blockerCount > 0 || mismatchCount > 0) return false;
    const blockers = Array.isArray(plantGate.blockers) ? plantGate.blockers.map((x) => String(x || '')) : [];
    if (!blockers.length) return false;
    const allowed = blockers.every((text) => {
      const normalized = text.toLowerCase();
      return normalized.includes('samples gesammelt')
        || normalized.includes('ok-samples in folge')
        || normalized.includes('noch nicht stabil');
    });
    return allowed === true;
  }

  /**
   * Code-Teil: _nwIsEnergyFlowHardFallbackReason
   *
   * Zweck:
   * Unterscheidet harte TS-Blocker von normalen Warmup-/Beobachtungsgründen.
   *
   * Zusammenhang:
   * 0.7.103 reduziert den alten JS-Fallback weiter. Ein einmal stabiler
   * TS-Energiefluss soll nicht bei weichen Warmup-Gründen unnötig lange auf JS
   * zurückfallen. Harte Gründe wie Shadow-Mismatch, fehlender Spiegel oder ungültige
   * Kandidatenwerte bleiben weiterhin blockierend.
   */
  _nwIsEnergyFlowHardFallbackReason(reason = '') {
    const text = String(reason || '').toLowerCase();
    return text.includes('mismatch')
      || text.includes('mirror-unavailable')
      || text.includes('candidate-invalid')
      || text.includes('without-safety')
      || text.includes('error');
  }

  /**
   * Code-Teil: _nwBuildEnergyFlowFixedSourceInput
   *
   * Zweck:
   * Verdichtet die aktuelle Schaltentscheidung zu einem kleinen Input für die
   * TS-Fixed-Source-Vorbereitung.
   */
  _nwBuildEnergyFlowFixedSourceInput(switchState = {}) {
    return {
      useTs: switchState.useTs === true,
      requestedMode: String(switchState.requestedMode || ''),
      publishedSource: String(switchState.publishedSource || (switchState.useTs ? (switchState.normalSourceActive ? 'ts-normal' : 'ts-candidate') : 'js-runtime')),
      reason: String(switchState.reason || ''),
      shadowOk: switchState.shadowOk === true,
      candidateOk: switchState.candidateOk === true,
      plantOk: switchState.plantEvaluationOk === true,
      warmupOk: Number(switchState.okTicks || 0) >= Number(switchState.warmupTicks || 1),
      ts: Date.now(),
    };
  }

  /**
   * Code-Teil: _nwUpdateEnergyFlowTsFixedSourceState
   *
   * Zweck:
   * Sammelt, ob der Energiefluss über mehrere echte Adapter-Ticks stabil als
   * `ts-candidate` lief. Sobald genug TS-Ticks in Folge vorhanden sind, wird die
   * feste TS-Quelle vorbereitet. Ab 0.7.104 wird daraus die TS-Normalquelle.
   *
   * Wichtig:
   * Diese Funktion entfernt den JS-Fallback nicht. Sie markiert nur, dass TS im
   * Normalfall als feste Energieflussquelle vorbereitet ist. Bei harten Fehlern bleibt
   * JS weiterhin Sicherheitsnetz.
   */
  _nwUpdateEnergyFlowTsFixedSourceState(switchState = {}) {
    const cfg = this._nwGetEnergyFlowTsSwitchConfig ? this._nwGetEnergyFlowTsSwitchConfig() : { fixedSourceMinTsTicks: 12 };
    const minTsTicks = Math.max(3, Math.min(240, Math.round(Number(cfg.fixedSourceMinTsTicks) || 12)));
    const input = this._nwBuildEnergyFlowFixedSourceInput ? this._nwBuildEnergyFlowFixedSourceInput(switchState) : { useTs: false, reason: '', ts: Date.now() };
    const prev = this._energyFlowTsFixedSourceState || {
      version: 1,
      source: 'energy-flow-ts-fixed-source-normal-v2',
      sinceTs: Date.now(),
      consecutiveTsTicks: 0,
      consecutiveJsFallbackTicks: 0,
      totalTsTicks: 0,
      totalJsFallbackTicks: 0,
      hardFallbackCount: 0,
      ready: false,
    };
    const hardFallback = !input.useTs && this._nwIsEnergyFlowHardFallbackReason && this._nwIsEnergyFlowHardFallbackReason(input.reason);
    if (input.useTs) {
      prev.consecutiveTsTicks = Math.max(0, Number(prev.consecutiveTsTicks) || 0) + 1;
      prev.consecutiveJsFallbackTicks = 0;
      prev.totalTsTicks = Math.max(0, Number(prev.totalTsTicks) || 0) + 1;
      prev.lastTsActiveTs = input.ts;
      if (!prev.firstTsActiveTs) prev.firstTsActiveTs = input.ts;
      if (prev.consecutiveTsTicks >= minTsTicks) {
        prev.ready = true;
        prev.readySinceTs = prev.readySinceTs || input.ts;
      }
    } else {
      prev.consecutiveTsTicks = 0;
      prev.consecutiveJsFallbackTicks = Math.max(0, Number(prev.consecutiveJsFallbackTicks) || 0) + 1;
      prev.totalJsFallbackTicks = Math.max(0, Number(prev.totalJsFallbackTicks) || 0) + 1;
      prev.lastFallbackTs = input.ts;
      prev.lastFallbackReason = input.reason;
      if (hardFallback) {
        prev.hardFallbackCount = Math.max(0, Number(prev.hardFallbackCount) || 0) + 1;
        prev.ready = false;
        prev.readySinceTs = 0;
      }
    }
    prev.minTsTicks = minTsTicks;
    prev.last = input;
    prev.lastTs = input.ts;
    prev.status = prev.ready ? 'ts-normal-source-ready' : (input.useTs ? 'collecting-ts' : (hardFallback ? 'hard-fallback' : 'soft-fallback'));
    prev.normalSourceReady = prev.ready === true;
    prev.nextAction = prev.ready
      ? 'TS ist als Energiefluss-Normalquelle vorbereitet. JS-Fallback bleibt nur noch Notfallback bei harten Blockern.'
      : `Weitere TS-Ticks sammeln: ${Math.max(0, Number(prev.consecutiveTsTicks) || 0)}/${minTsTicks}.`;
    this._energyFlowTsFixedSourceState = prev;
    return prev;
  }

  /**
   * Code-Teil: _nwGetEnergyFlowTsFixedSourceState
   *
   * Zweck:
   * Liefert den aktuellen Status der festen TS-Energieflussquelle für Diagnose und
   * App-Center.
   */
  _nwGetEnergyFlowTsFixedSourceState() {
    return this._energyFlowTsFixedSourceState || {
      version: 1,
      source: 'energy-flow-ts-fixed-source-normal-v2',
      ready: false,
      status: 'waiting',
      consecutiveTsTicks: 0,
      consecutiveJsFallbackTicks: 0,
      totalTsTicks: 0,
      totalJsFallbackTicks: 0,
      minTsTicks: 12,
      nextAction: 'Noch keine Energiefluss-TS-Ticks gesammelt. TS wird erst nach stabiler Serie zur Normalquelle.',
    };
  }

  /**
   * Code-Teil: _nwEvaluateEnergyFlowTsSwitch
   *
   * Zweck:
   * Bewertet, ob der TS-Energiefluss für diesen Tick produktiv genutzt werden
   * dürfte.
   *
   * Zusammenhang:
   * Diese Entscheidung ist die technische Vorbereitung für die spätere Umschaltung.
   * In der Grundeinstellung bleibt JS führend. TS darf nur aktiv werden, wenn der
   * Betreiber den Modus bewusst auf `ts` stellt, die Sicherheitsfreigabe gesetzt ist
   * und der Shadow-Vergleich keine relevanten Abweichungen meldet.
   *
   * Wichtig:
   * Diese Funktion ändert selbst keine Werte. Sie liefert nur einen Schaltplan für
   * `updateDerivedFlowStates`, damit die Migration nachvollziehbar und rückfallfähig
   * bleibt.
   */
  _nwEvaluateEnergyFlowTsSwitch(tsShadow) {
    const cfg = this._nwGetEnergyFlowTsSwitchConfig();
    const shadowAvailable = !!(tsShadow && tsShadow.available && tsShadow.ts);
    const shadowOk = !!(shadowAvailable && (tsShadow.ok === true || (Array.isArray(tsShadow.mismatches) && tsShadow.mismatches.length === 0)));
    const candidateSafety = this._nwValidateEnergyFlowTsCandidate ? this._nwValidateEnergyFlowTsCandidate(tsShadow) : { ok: shadowOk, blockers: [], warnings: [], values: {} };
    const warmupTicks = Math.max(1, Math.min(30, Math.round(Number(cfg.warmupTicks) || 3)));
    const runtimePlantEvaluation = this._nwUpdateEnergyFlowTsRuntimePlantEvaluation
      ? this._nwUpdateEnergyFlowTsRuntimePlantEvaluation(tsShadow)
      : null;
    const plantGate = this._nwEvaluateEnergyFlowPlantGate
      ? this._nwEvaluateEnergyFlowPlantGate({ ...cfg, runtimePlantEvaluation })
      : { required: true, ok: false, blockers: ['Energiefluss-Runtime-Auswertung nicht verfügbar.'] };
    const plantGateWarmupOnly = this._nwIsEnergyFlowPlantGateWarmupOnly ? this._nwIsEnergyFlowPlantGateWarmupOnly(plantGate) : false;
    const fixedSourceState = this._nwGetEnergyFlowTsFixedSourceState ? this._nwGetEnergyFlowTsFixedSourceState() : null;
    const fixedSourceReady = !!(fixedSourceState && fixedSourceState.ready === true);
    const normalSourceMode = fixedSourceReady && cfg.normalSourceAfterFixedReady !== false;
    const state = this._energyFlowTsCandidateState || { okTicks: 0, lastReason: '', lastUseTs: false, lastTs: 0 };
    let effectiveMode = 'js';
    let reason = 'default-js';

    /**
     * Code-Teil: Kandidaten-Warmup für TS-Energiefluss.
     *
     * Zweck:
     * TS darf nicht direkt beim ersten sauberen Shadow-Tick produktiv werden. Erst mehrere
     * aufeinanderfolgende saubere Vergleiche zählen als stabil. Bei Abweichung oder fehlender
     * Freigabe wird der Zähler zurückgesetzt und die alte JS-Runtime bleibt führend.
     *
     * Wichtig:
     * Dieser Zustand liegt nur im Speicher des laufenden Adapters. Nach Neustart muss der
     * Kandidatenmodus erneut stabile Ticks sammeln. Das schützt History und Energieflusswerte
     * vor versehentlichen Umschaltungen.
     */
    if (cfg.requestedMode !== 'ts') {
      state.okTicks = 0;
      state.lastUseTs = false;
    }

    if (cfg.requestedMode === 'shadow') {
      reason = 'shadow-only';
    } else if (cfg.requestedMode === 'ts') {
      if (!cfg.productionAllowed) {
        state.okTicks = 0;
        reason = 'ts-requested-without-safety-flag';
      } else if (!shadowAvailable) {
        state.okTicks = 0;
        reason = 'ts-mirror-unavailable';
      } else if (!shadowOk) {
        state.okTicks = 0;
        reason = cfg.autoFallback === false ? 'ts-shadow-mismatch-blocked' : 'ts-shadow-mismatch-auto-fallback';
      } else if (!candidateSafety.ok) {
        state.okTicks = 0;
        reason = 'ts-candidate-invalid';
      } else if (plantGate.required && plantGate.ok !== true && !plantGateWarmupOnly) {
        state.okTicks = 0;
        reason = 'ts-real-plant-evaluation-not-stable';
      } else {
        state.okTicks = Math.min(warmupTicks, (Number(state.okTicks) || 0) + 1);
        if (normalSourceMode) {
          // 0.7.104: TS ist nach stabiler Fixed-Source-Phase die Normalquelle.
          // Harte Blocker wurden oben bereits abgefangen; JS bleibt nur Notfallback.
          state.okTicks = Math.max(warmupTicks, Number(state.okTicks) || 0);
          effectiveMode = 'ts';
          reason = 'ts-normal-source-active';
        } else if (state.okTicks >= warmupTicks) {
          effectiveMode = 'ts';
          reason = 'ts-candidate-active';
        } else {
          reason = 'ts-candidate-warmup';
        }
      }
    }

    state.lastReason = reason;
    state.lastUseTs = effectiveMode === 'ts';
    state.lastTs = Date.now();
    this._energyFlowTsCandidateState = state;

    return {
      requestedMode: cfg.requestedMode,
      productionAllowed: !!cfg.productionAllowed,
      warmupTicks,
      okTicks: Math.max(0, Number(state.okTicks) || 0),
      candidateStable: (Number(state.okTicks) || 0) >= warmupTicks,
      autoFallback: cfg.autoFallback !== false,
      effectiveMode,
      useTs: effectiveMode === 'ts',
      shadowAvailable,
      shadowOk,
      candidateOk: !!candidateSafety.ok,
      candidateSafety,
      plantEvaluationRequired: !!plantGate.required,
      plantEvaluationOk: plantGate.required ? (plantGate.ok === true || plantGateWarmupOnly === true) : true,
      plantEvaluationSoftReleased: !!plantGateWarmupOnly,
      plantEvaluation: plantGate,
      fixedSourceReady,
      normalSourceMode,
      fixedSourceState,
      reason,
    };
  }

  /**
   * Code-Teil: _nwBuildEffectiveEnergyFlowValues
   *
   * Zweck:
   * Baut aus JS-Runtimewerten und optionalen TS-Shadowwerten die Werte, die in
   * diesem Tick veröffentlicht werden dürfen.
   *
   * Zusammenhang:
   * Dies ist die zentrale Stelle für den späteren produktiven Energiefluss-Umbau.
   * Solange der Modus `js` oder `shadow` ist, kommen alle Werte aus der alten
   * JavaScript-Runtime. Nur im explizit freigegebenen Modus `ts` werden die
   * geprüften TS-Werte übernommen.
   *
   * Wichtig:
   * Der Default ist jetzt produktiver TS-Kandidatenmodus, aber nur hinter allen Freigaben.
   * Wenn ein Gate blockiert, bleibt automatisch die JavaScript-Runtime aktiv.
   */
  _nwBuildEffectiveEnergyFlowValues(runtimeValues = {}, tsShadow = {}) {
    const switchState = this._nwEvaluateEnergyFlowTsSwitch(tsShadow);
    const tsValues = (tsShadow && tsShadow.ts && typeof tsShadow.ts === 'object') ? tsShadow.ts : {};
    const candidateValues = switchState && switchState.candidateSafety && switchState.candidateSafety.values
      ? switchState.candidateSafety.values
      : {};
    const sourceValues = switchState.useTs ? candidateValues : runtimeValues;
    const valueOf = (key, fallbackKey = key) => {
      const v = sourceValues ? sourceValues[key] : undefined;
      if (Number.isFinite(Number(v))) return Math.round(Number(v));
      const fallback = runtimeValues ? runtimeValues[fallbackKey] : 0;
      return Number.isFinite(Number(fallback)) ? Math.round(Number(fallback)) : 0;
    };
    // 0.7.104: Erst Fixed-/Normalquellenstatus aktualisieren, dann die veröffentlichte Quelle setzen.
    // Dadurch kann der Tick, der die stabile TS-Serie voll macht, bereits als `ts-normal` sichtbar werden.
    switchState.fixedSourceState = this._nwUpdateEnergyFlowTsFixedSourceState
      ? this._nwUpdateEnergyFlowTsFixedSourceState(switchState)
      : switchState.fixedSourceState;
    switchState.fixedSourceReady = !!(switchState.fixedSourceState && switchState.fixedSourceState.ready);
    switchState.normalSourceActive = !!(switchState.useTs && switchState.fixedSourceReady);
    switchState.publishedSource = switchState.useTs ? (switchState.normalSourceActive ? 'ts-normal' : 'ts-candidate') : 'js-runtime';
    const effective = {
      switchState,
      candidate: this._nwBuildEnergyFlowTsCandidateAudit(runtimeValues, tsValues, switchState, tsShadow),
      gridBuyW: valueOf('gridBuyW'),
      gridSellW: valueOf('gridSellW'),
      storageChargeW: valueOf('storageChargeW'),
      storageDischargeW: valueOf('storageDischargeW'),
      buildingLoadW: valueOf('buildingLoadW', 'loadTotalW'),
    };
    effective.activeTest = this._nwRecordEnergyFlowTsActiveTestSample(effective, runtimeValues, tsValues);
    return effective;
  }

  /**
   * Code-Teil: _nwRecordEnergyFlowTsActiveTestSample
   *
   * Zweck:
   * Protokolliert echte Energiefluss-Ticks während des kontrollierten TS-Aktivtests.
   * Dadurch sehen wir, ob der Adapter tatsächlich TS-Werte veröffentlicht oder wegen
   * Sicherheitsgate/Warmup/Anlagen-Auswertung weiter auf JavaScript zurückfällt.
   *
   * Zusammenhang:
   * Dieser Status wird im Energiefluss-Debug-JSON und in der App-Center-Diagnose
   * angezeigt. Die Funktion entscheidet nicht selbst über die Umschaltung; sie beobachtet
   * nur die Entscheidung aus `_nwEvaluateEnergyFlowTsSwitch`.
   *
   * Wichtig:
   * Die Liste liegt nur im RAM. Sie schreibt keine History und verändert keine EMS-Werte.
   * Damit bleibt der Aktivtest jederzeit rückfallfähig und ohne Altlasten nach Neustart.
   */
  _nwRecordEnergyFlowTsActiveTestSample(effective = {}, runtimeValues = {}, tsValues = {}) {
    const now = Date.now();
    const sw = (effective && effective.switchState && typeof effective.switchState === 'object') ? effective.switchState : {};
    const candidate = (effective && effective.candidate && typeof effective.candidate === 'object') ? effective.candidate : {};
    const blockers = [];
    if (Array.isArray(candidate.blockers)) blockers.push(...candidate.blockers.map((x) => String(x)));
    if (Array.isArray(sw.blockedReasons)) blockers.push(...sw.blockedReasons.map((x) => String(x)));
    if (sw.plantEvaluation && Array.isArray(sw.plantEvaluation.blockers)) blockers.push(...sw.plantEvaluation.blockers.map((x) => String(x)));
    const uniqueBlockers = Array.from(new Set(blockers.filter(Boolean))).slice(0, 12);
    const sample = {
      ts: now,
      iso: new Date(now).toISOString(),
      requestedMode: String(sw.requestedMode || ''),
      effectiveMode: String(sw.effectiveMode || ''),
      publishedSource: String(sw.publishedSource || (sw.useTs ? 'ts-candidate' : 'js-runtime')),
      useTs: sw.useTs === true,
      reason: String(sw.reason || ''),
      productionAllowed: sw.productionAllowed === true,
      shadowAvailable: sw.shadowAvailable === true,
      shadowOk: sw.shadowOk === true,
      candidateOk: sw.candidateOk === true,
      plantEvaluationRequired: sw.plantEvaluationRequired === true,
      plantEvaluationOk: sw.plantEvaluationOk === true,
      okTicks: Number(sw.okTicks) || 0,
      warmupTicks: Number(sw.warmupTicks) || 0,
      gridBuyW: Math.round(Number(effective.gridBuyW) || 0),
      gridSellW: Math.round(Number(effective.gridSellW) || 0),
      storageChargeW: Math.round(Number(effective.storageChargeW) || 0),
      storageDischargeW: Math.round(Number(effective.storageDischargeW) || 0),
      buildingLoadW: Math.round(Number(effective.buildingLoadW) || 0),
      runtime: {
        gridBuyW: Math.round(Number(runtimeValues.gridBuyW) || 0),
        gridSellW: Math.round(Number(runtimeValues.gridSellW) || 0),
        storageChargeW: Math.round(Number(runtimeValues.storageChargeW) || 0),
        storageDischargeW: Math.round(Number(runtimeValues.storageDischargeW) || 0),
        buildingLoadW: Math.round(Number(runtimeValues.buildingLoadW) || Number(runtimeValues.loadTotalW) || 0),
      },
      ts: {
        gridBuyW: Number.isFinite(Number(tsValues.gridBuyW)) ? Math.round(Number(tsValues.gridBuyW)) : null,
        gridSellW: Number.isFinite(Number(tsValues.gridSellW)) ? Math.round(Number(tsValues.gridSellW)) : null,
        storageChargeW: Number.isFinite(Number(tsValues.storageChargeW)) ? Math.round(Number(tsValues.storageChargeW)) : null,
        storageDischargeW: Number.isFinite(Number(tsValues.storageDischargeW)) ? Math.round(Number(tsValues.storageDischargeW)) : null,
        buildingLoadW: Number.isFinite(Number(tsValues.buildingLoadW)) ? Math.round(Number(tsValues.buildingLoadW)) : null,
      },
      blockers: uniqueBlockers,
    };
    if (!Array.isArray(this._energyFlowTsActiveTestSamples)) this._energyFlowTsActiveTestSamples = [];
    const samples = this._energyFlowTsActiveTestSamples;
    const signature = JSON.stringify({ src: sample.publishedSource, r: sample.reason, ts: sample.useTs, b: sample.blockers.join('|') });
    const last = samples.length ? samples[samples.length - 1] : null;
    if (!last || last.signature !== signature || (now - Number(last.ts || 0)) >= 15000) {
      samples.push({ ...sample, signature });
      const cutoff = now - 60 * 60 * 1000;
      while (samples.length > 240 || (samples.length && Number(samples[0].ts || 0) < cutoff)) samples.shift();
    }
    return this._nwSummarizeEnergyFlowTsActiveTestSamples();
  }

  /**
   * Code-Teil: _nwSummarizeEnergyFlowTsActiveTestSamples
   *
   * Zweck:
   * Verdichtet die gesammelten Energiefluss-Aktivtest-Samples zu einem lesbaren Status
   * für das App-Center. Wir wollen sofort sehen, ob TS wirklich aktiv ist oder ob der
   * Adapter richtigerweise weiter auf JS zurückfällt.
   */
  _nwSummarizeEnergyFlowTsActiveTestSamples() {
    const samples = Array.isArray(this._energyFlowTsActiveTestSamples) ? this._energyFlowTsActiveTestSamples.slice() : [];
    const latest = samples.length ? samples[samples.length - 1] : null;
    let consecutiveTs = 0;
    let consecutiveJs = 0;
    for (let i = samples.length - 1; i >= 0; i--) {
      if (samples[i] && samples[i].useTs) consecutiveTs++;
      else break;
    }
    for (let i = samples.length - 1; i >= 0; i--) {
      if (samples[i] && !samples[i].useTs) consecutiveJs++;
      else break;
    }
    const tsCount = samples.filter((x) => x && x.useTs).length;
    const jsCount = samples.length - tsCount;
    const blockerCount = samples.reduce((sum, x) => sum + (Array.isArray(x && x.blockers) ? x.blockers.length : 0), 0);
    const status = !samples.length
      ? 'collecting'
      : (latest && latest.useTs ? 'ts-active' : (latest && latest.requestedMode === 'ts' ? 'fallback-js' : 'shadow-or-js'));
    const nextAction = status === 'ts-active'
      ? 'TS ist im kontrollierten Aktivtest wirksam. Werte im LIVE-Dashboard und History-Vorschau gegen JS/Shadow beobachten.'
      : (status === 'fallback-js'
        ? 'Modus TS ist gewählt, aber ein Sicherheitsgate blockiert noch. Blocker/Warmup/Anlagen-Auswertung prüfen.'
        : 'TS ist noch nicht als Produktivquelle angefordert. Shadow weiter beobachten oder Modus TS bewusst aktivieren.');
    return {
      version: 1,
      source: 'energy-flow-ts-active-test-v1',
      ts: Date.now(),
      status,
      sampleCount: samples.length,
      tsCount,
      jsCount,
      tsRatioPct: samples.length ? Math.round((tsCount / samples.length) * 1000) / 10 : 0,
      consecutiveTs,
      consecutiveJs,
      blockerCount,
      latest,
      recentSamples: samples.slice(-12).map((x) => ({
        ts: x.ts,
        iso: x.iso,
        requestedMode: x.requestedMode,
        effectiveMode: x.effectiveMode,
        publishedSource: x.publishedSource,
        useTs: x.useTs,
        reason: x.reason,
        blockers: x.blockers,
      })),
      nextAction,
    };
  }

  /**
   * Code-Teil: _nwBuildEnergyFlowTsCandidateAudit
   *
   * Zweck:
   * Baut eine lesbare Diagnose für den sicheren TS-Kandidatenmodus.
   *
   * Zusammenhang:
   * Diese Diagnose landet im Energiefluss-Debug-JSON und im App-Center. Sie zeigt,
   * ob die TS-Werte nur Kandidat sind, ob sie produktiv genutzt wurden und welche
   * Sicherheitsgründe eine Nutzung verhindern.
   *
   * Wichtig:
   * Die Funktion verändert keine Produktivwerte. Sie dokumentiert nur, warum ein Tick
   * bei JS geblieben ist oder warum TS im ausdrücklich freigegebenen Kandidatenmodus
   * genutzt wurde.
   */
  _nwBuildEnergyFlowTsCandidateAudit(runtimeValues = {}, tsValues = {}, switchState = {}, tsShadow = {}) {
    const keys = ['gridBuyW', 'gridSellW', 'storageChargeW', 'storageDischargeW', 'buildingLoadW'];
    const diffs = keys.map((key) => {
      const js = Number(runtimeValues && runtimeValues[key]);
      const ts = Number(tsValues && tsValues[key]);
      return {
        key,
        js: Number.isFinite(js) ? Math.round(js) : null,
        ts: Number.isFinite(ts) ? Math.round(ts) : null,
        diff: (Number.isFinite(js) && Number.isFinite(ts)) ? Math.round(ts - js) : null,
      };
    });
    const safety = (switchState && switchState.candidateSafety && typeof switchState.candidateSafety === 'object') ? switchState.candidateSafety : null;
    return {
      source: 'energy-flow-ts-candidate-audit-v1',
      requestedMode: switchState.requestedMode || '',
      effectiveMode: switchState.effectiveMode || 'js',
      publishedSource: switchState.publishedSource || (switchState.useTs ? 'ts-candidate' : 'js-runtime'),
      useTs: !!switchState.useTs,
      reason: switchState.reason || '',
      productionAllowed: !!switchState.productionAllowed,
      shadowAvailable: !!switchState.shadowAvailable,
      shadowOk: !!switchState.shadowOk,
      candidateOk: !!(safety && safety.ok),
      blockers: [].concat(
        safety && Array.isArray(safety.blockers) ? safety.blockers : [],
        switchState && switchState.plantEvaluation && Array.isArray(switchState.plantEvaluation.blockers) ? switchState.plantEvaluation.blockers : []
      ),
      warnings: safety && Array.isArray(safety.warnings) ? safety.warnings : [],
      plantEvaluationRequired: !!(switchState && switchState.plantEvaluationRequired),
      plantEvaluationOk: !!(switchState && switchState.plantEvaluationOk),
      plantEvaluation: switchState && switchState.plantEvaluation ? switchState.plantEvaluation : null,
      fixedSourceReady: !!(switchState && switchState.fixedSourceReady),
      normalSourceActive: !!(switchState && switchState.normalSourceActive),
      fixedSourceState: switchState && switchState.fixedSourceState ? switchState.fixedSourceState : null,
      okTicks: Number(switchState.okTicks) || 0,
      warmupTicks: Number(switchState.warmupTicks) || 0,
      diffs,
      shadowSource: tsShadow && tsShadow.source ? String(tsShadow.source) : '',
    };
  }

  /**
   * Code-Teil: _nwEnergyFlowTsLiveTestStateFromSwitch
   *
   * Zweck:
   * Übersetzt die interne TS-Schaltentscheidung in einen kurzen, menschenlesbaren
   * Status für App-Center und ioBroker-State.
   *
   * Zusammenhang:
   * Der Energiefluss kann im Modus `js`, `shadow` oder `ts` laufen. Diese Funktion
   * macht sichtbar, ob TS wirklich produktiv veröffentlicht, nur Diagnose ist oder
   * durch Warmup/Anlagen-Gate/Sicherheitsfreigabe blockiert wird.
   *
   * Wichtig:
   * Diese Funktion ändert keine Werte. Sie ist reine Diagnose für den kontrollierten
   * Livetest und hilft, bei Problemen sofort wieder auf JS/Shadow zurückzuschalten.
   */
  _nwEnergyFlowTsLiveTestStateFromSwitch(switchState = {}) {
    const requested = String(switchState.requestedMode || switchState.mode || '').toLowerCase();
    const source = String(switchState.publishedSource || switchState.effectiveMode || '').toLowerCase();
    const reason = String(switchState.reason || '').toLowerCase();
    if (source.includes('ts') || switchState.useTs === true) return 'ts-active';
    if (requested === 'ts') {
      if (reason.includes('warmup')) return 'ts-warmup';
      if (reason.includes('plant') || switchState.plantEvaluationOk === false) return 'ts-blocked-plant-gate';
      if (switchState.candidateOk === false || reason.includes('candidate')) return 'ts-blocked-candidate';
      if (switchState.shadowOk === false || reason.includes('shadow')) return 'ts-blocked-shadow';
      if (switchState.productionAllowed !== true || reason.includes('safety')) return 'ts-blocked-safety';
      return 'ts-blocked';
    }
    if (requested === 'shadow') return 'shadow-only';
    if (requested === 'js') return 'js-only';
    return 'js-runtime';
  }

  /**
   * Code-Teil: _nwParseTsShadowJson
   *
   * Zweck:
   * Liest ein Shadow-Diagnosefeld defensiv aus. Die Diagnose-States kommen aus
   * Core-Limits, Heizstab und Energiefluss teilweise als JSON-String, teilweise
   * als Objekt oder noch leerer State.
   *
   * Zusammenhang:
   * Diese Hilfsfunktion ist die Grundlage für die Umschaltbereitschaft der
   * TypeScript-Migration. Sie darf keine produktiven Werte ändern, sondern nur
   * vorhandene Diagnose-States auswerten.
   *
   * Wichtig:
   * Ungültiges JSON darf den Adapter nicht stoppen. Es wird als Diagnosefehler
   * zurückgegeben, damit das App-Center den Zustand sichtbar machen kann.
   */
  _nwParseTsShadowJson(raw, fallback = null) {
    if (raw && typeof raw === 'object') return raw;
    const text = (raw === null || raw === undefined) ? '' : String(raw).trim();
    if (!text) return fallback;
    try {
      const parsed = JSON.parse(text);
      return (parsed && typeof parsed === 'object') ? parsed : fallback;
    } catch (e) {
      return { ok: false, available: false, source: 'parse-error', parseError: true, error: e && e.message ? String(e.message) : String(e), raw: text.slice(0, 500) };
    }
  }

  /**
   * Code-Teil: _nwCollectTsShadowMismatches
   *
   * Zweck:
   * Normalisiert unterschiedliche Shadow-Strukturen zu einer einheitlichen Liste
   * von Abweichungen. Core-Limits, Heizstab und Energiefluss benutzen noch nicht
   * exakt dieselbe JSON-Struktur.
   *
   * Zusammenhang:
   * Diese Liste entscheidet, ob ein Bereich später gefahrlos produktiv von TS
   * übernommen werden darf. Mehr als null Abweichungen bedeutet: noch nicht
   * umschalten.
   */
  _nwCollectTsShadowMismatches(shadow) {
    const out = [];
    if (!shadow || typeof shadow !== 'object') return out;
    const add = (entry, idx, prefix) => {
      if (!entry) return;
      if (typeof entry === 'string') {
        out.push({ label: entry, index: idx, raw: entry });
        return;
      }
      if (typeof entry === 'object') {
        out.push({
          label: String(entry.key || entry.field || entry.path || entry.label || `${prefix || 'Abweichung'} ${idx + 1}`),
          js: entry.js !== undefined ? entry.js : (entry.runtime !== undefined ? entry.runtime : entry.old),
          ts: entry.ts !== undefined ? entry.ts : (entry.shadow !== undefined ? entry.shadow : entry.new),
          diff: entry.diff !== undefined ? entry.diff : (entry.delta !== undefined ? entry.delta : ''),
          raw: entry,
        });
      }
    };
    if (Array.isArray(shadow.mismatches)) shadow.mismatches.forEach((m, i) => add(m, i, 'Mismatch'));
    if (Array.isArray(shadow.diffs)) shadow.diffs.forEach((m, i) => add(m, i, 'Diff'));
    if (shadow.comparison && typeof shadow.comparison === 'object') {
      Object.keys(shadow.comparison).forEach((key) => {
        const v = shadow.comparison[key];
        if (v && typeof v === 'object' && (v.match === false || v.ok === false || v.diff || v.delta)) {
          add({ label: key, ...v }, out.length, 'Comparison');
        }
      });
    }
    if (!out.length && shadow.ok === false && shadow.error) add({ label: 'Fehler', diff: String(shadow.error) }, 0, 'Fehler');
    return out;
  }

  /**
   * Code-Teil: _nwEvaluateTsShadowBlock
   *
   * Zweck:
   * Bewertet einen einzelnen Shadow-Block wie Core-Limits, Heizstab oder
   * Energiefluss und erzeugt daraus eine klare Ampel für die Migration.
   *
   * Zusammenhang:
   * Das Ergebnis wird an das App-Center ausgeliefert. Es ist reine Diagnose und
   * ersetzt keine produktiven EMS-Werte.
   */
  _nwEvaluateTsShadowBlock(id, label, shadow, options = {}) {
    const required = options.required !== false;
    const maxMismatches = Number.isFinite(Number(options.maxMismatches)) ? Math.max(0, Number(options.maxMismatches)) : 0;
    if (!shadow || typeof shadow !== 'object') {
      return { id, label, ready: false, status: required ? 'no-data' : 'optional-missing', severity: required ? 'warn' : 'info', mismatchCount: 0, blockers: required ? ['Noch kein Shadow-Snapshot vorhanden.'] : [], warnings: required ? [] : ['Optionaler Shadow-Snapshot fehlt.'], source: 'missing' };
    }
    const mismatches = this._nwCollectTsShadowMismatches(shadow);
    const blockers = [];
    const warnings = [];
    if (shadow.parseError) blockers.push('Shadow-JSON konnte nicht geparst werden.');
    if (shadow.error) blockers.push(String(shadow.error));
    if (shadow.available === false) blockers.push('TypeScript-Spiegel nicht verfügbar.');
    if (mismatches.length > maxMismatches) blockers.push(`${mismatches.length} Abweichung(en) über erlaubtem Grenzwert ${maxMismatches}.`);
    if (mismatches.length && mismatches.length <= maxMismatches) warnings.push(`${mismatches.length} tolerierte Abweichung(en).`);
    const ready = blockers.length === 0 && (shadow.ok !== false || mismatches.length <= maxMismatches);
    return {
      id,
      label,
      ready,
      status: ready ? 'ready' : 'blocked',
      severity: ready ? 'ok' : 'warn',
      mismatchCount: mismatches.length,
      blockers,
      warnings,
      source: shadow.source || 'ts-shadow',
      summary: ready ? 'bereit' : 'nicht bereit',
      sampleMismatches: mismatches.slice(0, 5),
    };
  }

  /**
   * Code-Teil: _nwBuildTsShadowPlantSample
   *
   * Zweck:
   * Erstellt aus der aktuellen Shadow-Readiness einen kompakten Messpunkt für die
   * reale Anlagenbeobachtung. Dadurch sehen wir nicht nur einen Momentzustand,
   * sondern ob Energiefluss/Core-Limits/Heizstab über mehrere Diagnoseabrufe
   * stabil zusammenpassen.
   *
   * Zusammenhang:
   * Wird von der App-Center-Diagnose-API genutzt. Produktiv bleibt weiterhin die
   * bestehende Runtime; dieser Messpunkt ist nur eine Auswertungshilfe für die
   * TypeScript-Migration.
   */
  _nwBuildTsShadowPlantSample(readiness = {}) {
    const safeBlock = (block) => {
      const b = (block && typeof block === 'object') ? block : {};
      return {
        ready: b.ready === true,
        status: String(b.status || (b.ready ? 'ready' : 'missing')),
        mismatchCount: Math.max(0, Math.round(Number(b.mismatchCount) || 0)),
        source: String(b.source || 'unknown'),
      };
    };
    const blockers = Array.isArray(readiness.blockers) ? readiness.blockers.map((x) => String(x || '')).filter(Boolean) : [];
    const warnings = Array.isArray(readiness.warnings) ? readiness.warnings.map((x) => String(x || '')).filter(Boolean) : [];
    const sample = {
      ts: Date.now(),
      overallReady: readiness && readiness.overallReady === true,
      readyForEnergyFlowSwitch: readiness && readiness.readyForEnergyFlowSwitch === true,
      readyForCoreLimitsSwitch: readiness && readiness.readyForCoreLimitsSwitch === true,
      readyForHeatingRodSwitch: readiness && readiness.readyForHeatingRodSwitch === true,
      energyFlowMode: String(readiness.energyFlowMode || ''),
      energyFlow: safeBlock(readiness.energyFlow),
      coreLimits: safeBlock(readiness.coreLimits),
      heatingRod: safeBlock(readiness.heatingRod),
      blockerCount: blockers.length,
      warningCount: warnings.length,
      blockers: blockers.slice(0, 8),
      warnings: warnings.slice(0, 8),
    };
    sample.ok = sample.readyForEnergyFlowSwitch && sample.readyForCoreLimitsSwitch && sample.readyForHeatingRodSwitch && sample.blockerCount === 0;
    sample.mismatchCount = sample.energyFlow.mismatchCount + sample.coreLimits.mismatchCount + sample.heatingRod.mismatchCount;
    return sample;
  }

  /**
   * Code-Teil: _nwSummarizeTsShadowPlantSamples
   *
   * Zweck:
   * Bewertet die letzten echten Shadow-Samples. Diese Zusammenfassung zeigt dem
   * Installer, ob die echte Anlage stabil genug wirkt, um später einen nächsten
   * Umschaltschritt zu planen.
   *
   * Wichtig:
   * Die Grenzwerte sind bewusst konservativ. Ein einzelnes gutes Sample ist nur
   * ein Hinweis, aber noch keine Freigabe für produktiven TypeScript-Betrieb.
   */
  _nwSummarizeTsShadowPlantSamples(samples = []) {
    const list = Array.isArray(samples) ? samples.filter(Boolean) : [];
    const last = list[list.length - 1] || null;
    let consecutiveOk = 0;
    for (let i = list.length - 1; i >= 0; i--) {
      if (!list[i] || list[i].ok !== true) break;
      consecutiveOk++;
    }
    const okCount = list.filter((x) => x && x.ok === true).length;
    const blockerCount = list.reduce((sum, x) => sum + Math.max(0, Number(x && x.blockerCount) || 0), 0);
    const warningCount = list.reduce((sum, x) => sum + Math.max(0, Number(x && x.warningCount) || 0), 0);
    const mismatchCount = list.reduce((sum, x) => sum + Math.max(0, Number(x && x.mismatchCount) || 0), 0);
    const okRatioPct = list.length ? Math.round(okCount / list.length * 1000) / 10 : 0;
    const enoughSamples = list.length >= 5;
    const stable = enoughSamples && consecutiveOk >= 5 && blockerCount === 0 && mismatchCount === 0;
    const status = !list.length ? 'waiting' : (stable ? 'stable' : (last && last.ok ? 'observing' : 'blocked'));
    const nextAction = !list.length
      ? 'Diagnose-Status öffnen und einige Minuten reale Samples sammeln.'
      : (stable
        ? 'Anlage wirkt im Shadow stabil. Nächsten TS-Umschaltschritt nur kontrolliert und mit Rückfall auf JS planen.'
        : (last && last.ok
          ? 'Weitere OK-Samples sammeln; noch nicht produktiv umschalten.'
          : 'Blocker/Abweichungen auswerten, bevor TypeScript produktiv genutzt wird.'));
    return {
      version: 1,
      source: 'real-plant-shadow-evaluation-v1',
      ts: Date.now(),
      sampleCount: list.length,
      okCount,
      okRatioPct,
      consecutiveOk,
      blockerCount,
      warningCount,
      mismatchCount,
      enoughSamples,
      stable,
      status,
      lastSample: last,
      recentSamples: list.slice(-10),
      nextAction,
    };
  }

  /**
   * Code-Teil: _nwUpdateTsShadowPlantEvaluation
   *
   * Zweck:
   * Aktualisiert einen kleinen In-Memory-Rolling-Buffer für die echte Anlagen-
   * Shadow-Diagnose und liefert die Zusammenfassung an das App-Center zurück.
   *
   * Zusammenhang:
   * Die Daten werden nur im laufenden Adapterprozess gehalten. Nach Neustart wird
   * neu gesammelt. Dadurch verfälschen wir keine History und schreiben keine
   * dauerhaften Migrationswerte in ioBroker-States.
   */
  _nwUpdateTsShadowPlantEvaluation(_control = {}, readiness = {}) {
    try {
      const sample = this._nwBuildTsShadowPlantSample(readiness || {});
      const current = Array.isArray(this._tsShadowPlantSamples) ? this._tsShadowPlantSamples : [];
      const next = current.concat(sample).slice(-60);
      this._tsShadowPlantSamples = next;
      return this._nwSummarizeTsShadowPlantSamples(next);
    } catch (e) {
      return {
        version: 1,
        source: 'real-plant-shadow-evaluation-v1',
        ts: Date.now(),
        status: 'error',
        stable: false,
        sampleCount: 0,
        okCount: 0,
        okRatioPct: 0,
        consecutiveOk: 0,
        blockerCount: 1,
        warningCount: 0,
        mismatchCount: 0,
        blockers: ['Anlagenauswertung konnte nicht erstellt werden: ' + (e && e.message ? e.message : e)],
        nextAction: 'Adapterlog prüfen; produktive TS-Umschaltung blockiert.',
      };
    }
  }

  /**
   * Code-Teil: _nwEvaluateEnergyFlowSwitchReadinessFromControl
   *
   * Zweck:
   * Führt die drei sichtbaren Shadow-Diagnosen zu einer Migrationsbewertung
   * zusammen. Dadurch wissen wir, ob Energiefluss, Core-Limits oder Heizstab für
   * eine spätere produktive TS-Umschaltung vorbereitet sind.
   *
   * Zusammenhang:
   * Diese Funktion wird in der Diagnose-API genutzt und im App-Center angezeigt.
   * Sie ist die fachliche Brücke zwischen Shadow-Modus und späterer TS-Umschaltung.
   *
   * Wichtig:
   * Auch wenn `readyForEnergyFlowSwitch` true ist, wird in dieser Version noch
   * nichts umgeschaltet. Die Entscheidung bleibt weiterhin manuell und erfolgt
   * erst in einer späteren Version.
   */
  _nwEvaluateEnergyFlowSwitchReadinessFromControl(control = {}) {
    const coreShadow = this._nwParseTsShadowJson(control.emsBudgetTsShadowJson, null);
    const heatingShadowRaw = this._nwParseTsShadowJson(control.heatingRodTsShadowJson, null);
    const heatingDebug = this._nwParseTsShadowJson(control.heatingRodDebugJson, null);
    const heatingShadow = heatingShadowRaw || (heatingDebug && heatingDebug.tsShadow ? heatingDebug.tsShadow : null);
    const flowInputs = this._nwParseTsShadowJson(control.energyFlowInputsJson, null);
    const flowShadow = flowInputs && flowInputs.tsShadow ? flowInputs.tsShadow : null;
    const energyFlowMode = this._nwNormalizeEnergyFlowTsMode((flowShadow && flowShadow.mode) || control.energyFlowTsMode || this._nwGetEnergyFlowTsMode());
    const energyFlowEffectivePlan = flowShadow && flowShadow.effectivePlan ? flowShadow.effectivePlan : null;

    const core = this._nwEvaluateTsShadowBlock('coreLimits', 'Core-Limits', coreShadow, { required: true, maxMismatches: 0 });
    const heatingRod = this._nwEvaluateTsShadowBlock('heatingRod', 'Heizstab', heatingShadow, { required: true, maxMismatches: 0 });
    const energyFlow = this._nwEvaluateTsShadowBlock('energyFlow', 'Energiefluss', flowShadow, { required: true, maxMismatches: 0 });
    const blocks = [core, heatingRod, energyFlow];
    const blockers = blocks.flatMap((b) => (Array.isArray(b.blockers) ? b.blockers.map((x) => `${b.label}: ${x}`) : []));
    const warnings = blocks.flatMap((b) => (Array.isArray(b.warnings) ? b.warnings.map((x) => `${b.label}: ${x}`) : []));
    const readiness = {
      version: 1,
      source: 'shadow-readiness-v1',
      ts: Date.now(),
      energyFlowMode,
      energyFlowEffectivePlan,
      readyForEnergyFlowSwitch: !!energyFlow.ready,
      readyForCoreLimitsSwitch: !!core.ready,
      readyForHeatingRodSwitch: !!heatingRod.ready,
      overallReady: blocks.every((b) => b.ready),
      energyFlow,
      coreLimits: core,
      heatingRod,
      blockers,
      warnings,
      energyFlowCandidateSafety: energyFlowEffectivePlan && energyFlowEffectivePlan.candidateSafety ? energyFlowEffectivePlan.candidateSafety : null,
      nextAction: blockers.length
        ? 'Shadow-Abweichungen zuerst auswerten; TS darf noch nicht produktiv übernehmen.'
        : (energyFlowMode === 'ts'
          ? 'TS-Modus ist intern gewählt und Shadow ist sauber. 0.7.82 nutzt den Kandidaten nur mit Modus ts, Sicherheitsfreigabe und bestandener Kandidatenprüfung.'
          : 'Shadow-Werte sind aktuell sauber. Eine kontrollierte Umschaltung kann in einer späteren Version vorbereitet werden.'),
    };
    return readiness;
  }

  /**
   * Code-Teil: _nwRecordAndSummarizeTsShadowEvaluation
   *
   * Zweck:
   * Bewertet die Shadow-Diagnose nicht nur als Momentaufnahme, sondern sammelt
   * eine kurze Laufzeit-Historie der echten Anlage. Dadurch sieht der Installer,
   * ob Energiefluss, Core-Limits und Heizstab über mehrere Aktualisierungen stabil
   * bleiben oder ob sporadische Abweichungen auftreten.
   *
   * Zusammenhang:
   * Die Funktion wird ausschließlich in der Diagnose-API genutzt. Sie verändert
   * keine produktiven EMS-Werte, keine Energieflusswerte und keine Schaltlogik.
   *
   * Wichtig:
   * Die Auswertung ist bewusst flüchtig im RAM. Nach Adapter-Neustart beginnt die
   * Beobachtung neu. Das verhindert, dass alte Testwerte spätere Freigaben blockieren.
   */
  _nwRecordAndSummarizeTsShadowEvaluation(control = {}, readiness = {}) {
    const now = Date.now();
    const blockSummary = (block, id) => {
      const b = (block && typeof block === 'object') ? block : {};
      return {
        id,
        ready: !!b.ready,
        status: String(b.status || (b.ready ? 'ready' : 'unknown')),
        mismatchCount: Number.isFinite(Number(b.mismatchCount)) ? Number(b.mismatchCount) : 0,
        blockers: Array.isArray(b.blockers) ? b.blockers.map((x) => String(x)).slice(0, 6) : [],
        warnings: Array.isArray(b.warnings) ? b.warnings.map((x) => String(x)).slice(0, 6) : [],
        source: String(b.source || 'unknown'),
      };
    };

    const energy = blockSummary(readiness.energyFlow, 'energyFlow');
    const core = blockSummary(readiness.coreLimits, 'coreLimits');
    const heating = blockSummary(readiness.heatingRod, 'heatingRod');
    const allReady = !!(energy.ready && core.ready && heating.ready);
    const sample = {
      ts: now,
      iso: new Date(now).toISOString(),
      overallReady: allReady,
      energyFlow: energy,
      coreLimits: core,
      heatingRod: heating,
      energyFlowMode: String(readiness.energyFlowMode || control.energyFlowTsMode || ''),
      blockerCount: (energy.blockers.length + core.blockers.length + heating.blockers.length),
      mismatchCount: (energy.mismatchCount + core.mismatchCount + heating.mismatchCount),
    };

    if (!Array.isArray(this._tsShadowEvaluationSamples)) this._tsShadowEvaluationSamples = [];
    const samples = this._tsShadowEvaluationSamples;
    const last = samples.length ? samples[samples.length - 1] : null;
    // Nur neue fachliche Zustände oder zeitlich sinnvolle Punkte aufnehmen, damit die Liste
    // bei schnellem UI-Refresh nicht mit identischen Zeilen geflutet wird.
    const signature = JSON.stringify({ r: sample.overallReady, e: energy.status, c: core.status, h: heating.status, m: sample.mismatchCount, b: sample.blockerCount });
    const lastSignature = last ? last.signature : '';
    if (!last || lastSignature !== signature || (now - Number(last.ts || 0)) >= 30000) {
      samples.push({ ...sample, signature });
      const cutoff = now - 30 * 60 * 1000;
      while (samples.length > 120 || (samples.length && Number(samples[0].ts || 0) < cutoff)) samples.shift();
    }

    const list = samples.slice();
    let consecutiveReady = 0;
    for (let i = list.length - 1; i >= 0; i--) {
      if (list[i] && list[i].overallReady) consecutiveReady++;
      else break;
    }
    let consecutiveBlocked = 0;
    for (let i = list.length - 1; i >= 0; i--) {
      if (list[i] && !list[i].overallReady) consecutiveBlocked++;
      else break;
    }
    const readyCount = list.filter((x) => x && x.overallReady).length;
    const mismatchCountTotal = list.reduce((sum, x) => sum + Math.max(0, Number(x && x.mismatchCount) || 0), 0);
    const firstTs = list.length ? Number(list[0].ts || 0) : 0;
    const lastTs = list.length ? Number(list[list.length - 1].ts || 0) : 0;
    const windowMinutes = firstTs && lastTs ? Math.max(0, Math.round((lastTs - firstTs) / 60000)) : 0;
    const lastSample = list.length ? list[list.length - 1] : null;
    const lastBlockers = lastSample ? []
      .concat(lastSample.energyFlow.blockers.map((x) => `Energiefluss: ${x}`))
      .concat(lastSample.coreLimits.blockers.map((x) => `Core-Limits: ${x}`))
      .concat(lastSample.heatingRod.blockers.map((x) => `Heizstab: ${x}`))
      : [];
    const status = !list.length
      ? 'collecting'
      : (consecutiveReady >= 3 ? 'stable-ready' : (lastSample && lastSample.overallReady ? 'ready-once' : 'blocked'));
    const nextAction = status === 'stable-ready'
      ? 'Shadow-Auswertung ist über mehrere Aktualisierungen stabil. Energiefluss-TS kann als nächster Schritt kontrolliert getestet werden.'
      : (status === 'ready-once'
        ? 'Aktuelle Shadow-Auswertung ist sauber. Noch weitere Aktualisierungen sammeln, bevor produktiv umgeschaltet wird.'
        : 'Blocker/Abweichungen zuerst prüfen. TypeScript darf noch nicht produktiv übernehmen.');

    return {
      version: 1,
      source: 'real-plant-shadow-evaluation-v1',
      ts: now,
      status,
      sampleCount: list.length,
      readyCount,
      blockedCount: Math.max(0, list.length - readyCount),
      readyPct: list.length ? Math.round((readyCount / list.length) * 100) : 0,
      mismatchCountTotal,
      consecutiveReady,
      consecutiveBlocked,
      windowMinutes,
      firstTs,
      lastTs,
      lastBlockers: lastBlockers.slice(0, 12),
      nextAction,
      latest: lastSample,
      samples: list.slice(-12).map((x) => ({
        ts: x.ts,
        iso: x.iso,
        overallReady: x.overallReady,
        mismatchCount: x.mismatchCount,
        blockerCount: x.blockerCount,
        energyFlow: { ready: x.energyFlow.ready, mismatchCount: x.energyFlow.mismatchCount, status: x.energyFlow.status },
        coreLimits: { ready: x.coreLimits.ready, mismatchCount: x.coreLimits.mismatchCount, status: x.coreLimits.status },
        heatingRod: { ready: x.heatingRod.ready, mismatchCount: x.heatingRod.mismatchCount, status: x.heatingRod.status },
      })),
    };
  }

  /**
   * Code-Teil: _nwBuildTsShadowRealPlantEvaluation
   *
   * Zweck:
   * Verdichtet die Shadow-Diagnose aus einer echten Kundenanlage zu einer
   * verständlichen Handlungsempfehlung. Diese Auswertung beantwortet nicht nur,
   * ob irgendwo ein JSON-Block „OK“ meldet, sondern ob wir mit dem nächsten
   * TypeScript-Schritt sicher weitergehen dürfen.
   *
   * Zusammenhang:
   * - `tsShadowReadiness` bewertet Energiefluss, Core-Limits und Heizstab einzeln.
   * - Das App-Center zeigt diese Auswertung zusätzlich als lesbare Karte.
   * - Die produktive Runtime bleibt unverändert; dieser Code entscheidet nichts
   *   für EMS, Speicher, Heizstab oder History.
   *
   * Wichtig:
   * „Energiefluss bereit“ bedeutet nur, dass der Energiefluss weiter Richtung
   * TS-Kandidatenmodus getestet werden darf. Core-Limits und Heizstab dürfen
   * trotzdem noch weiter im Shadow bleiben, wenn deren Snapshots fehlen.
   */
  _nwBuildTsShadowRealPlantEvaluation(control = {}) {
    const readiness = (control && control.tsShadowReadiness && typeof control.tsShadowReadiness === 'object')
      ? control.tsShadowReadiness
      : this._nwEvaluateEnergyFlowSwitchReadinessFromControl(control || {});

    const section = (id, label, ready, detail) => {
      const status = ready ? 'ready' : (detail && detail.status ? String(detail.status) : 'blocked');
      const blockerCount = detail && Array.isArray(detail.blockers) ? detail.blockers.length : 0;
      const warningCount = detail && Array.isArray(detail.warnings) ? detail.warnings.length : 0;
      return {
        id,
        label,
        ready: !!ready,
        status,
        summary: ready ? 'bereit' : (status === 'no-data' ? 'wartet auf Snapshot' : 'nicht bereit'),
        source: detail && detail.source ? String(detail.source) : '',
        mismatchCount: detail && Number.isFinite(Number(detail.mismatchCount)) ? Number(detail.mismatchCount) : 0,
        blockerCount,
        warningCount,
      };
    };

    const sections = [
      section('energyFlow', 'Energiefluss', readiness.readyForEnergyFlowSwitch, readiness.energyFlow),
      section('coreLimits', 'Core-Limits', readiness.readyForCoreLimitsSwitch, readiness.coreLimits),
      section('heatingRod', 'Heizstab', readiness.readyForHeatingRodSwitch, readiness.heatingRod),
    ];

    const blockers = Array.isArray(readiness.blockers) ? readiness.blockers.slice() : [];
    const warnings = Array.isArray(readiness.warnings) ? readiness.warnings.slice() : [];
    const energyReady = !!readiness.readyForEnergyFlowSwitch;
    const allReady = sections.every((x) => x.ready);
    const waiting = sections.filter((x) => !x.ready && x.status === 'no-data').map((x) => x.label);

    let overallStatus = 'blocked';
    let severity = 'warn';
    let summary = 'Energiefluss-TS ist auf dieser Anlage noch nicht freigabefähig.';
    let nextAction = 'Blocker in der Shadow-Diagnose prüfen. Produktiv bleibt JavaScript.';

    if (allReady) {
      overallStatus = 'ready-all';
      severity = 'ok';
      summary = 'Alle Shadow-Bereiche sind aktuell bereit.';
      nextAction = 'Energiefluss kann im nächsten Schritt kontrolliert im TS-Kandidatenmodus weiter getestet werden. Core-Limits und Heizstab bleiben bis zur eigenen Freigabe beobachtet.';
    } else if (energyReady) {
      overallStatus = 'energy-ready-partial';
      severity = 'info';
      summary = 'Energiefluss ist bereit; Core-Limits oder Heizstab brauchen noch Beobachtung.';
      nextAction = 'Energiefluss kann weiter Richtung TS-Kandidat geprüft werden. Core-Limits/Heizstab erst umstellen, wenn deren Shadow-Snapshots stabil OK sind.';
      if (waiting.length) warnings.push('Noch wartende Shadow-Snapshots: ' + waiting.join(', '));
    } else if (waiting.length && blockers.length === 0) {
      overallStatus = 'waiting';
      severity = 'info';
      summary = 'Die Anlage liefert noch nicht alle Shadow-Snapshots.';
      nextAction = 'Adapter einige Minuten laufen lassen oder betroffene Module einmal aktivieren, dann Diagnose erneut prüfen.';
    }

    return {
      version: 1,
      source: 'real-plant-shadow-evaluation-v1',
      ts: Date.now(),
      overallStatus,
      severity,
      summary,
      nextAction,
      energyFlowMayContinue: energyReady,
      allAreasReady: allReady,
      sections,
      blockers,
      warnings,
      recommendedNextVersion: energyReady ? '0.7.85 Energiefluss-Kandidat weiter testen' : 'Shadow-Diagnose weiter stabilisieren',
      runtimeAuthority: 'JavaScript bleibt produktiv; diese Auswertung ist nur Diagnose.',
    };
  }

  /**
   * Code-Teil: _nwResolveGridImportExportFromCache
   * Zweck: Kapselt einen lokalen Verarbeitungsschritt, damit Aufrufer nicht direkt in Detaildaten eingreifen.
   * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
   * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
   */
  _nwResolveGridImportExportFromCache() {
    const gridBuyMapped = this._nwHasMappedDatapoint('gridBuyPower');
    const gridSellMapped = this._nwHasMappedDatapoint('gridSellPower');
    const gridNetMapped = this._nwHasMappedDatapoint('gridPointPower');
    const now = Date.now();
    const maxAgeMs = this._nwLiveInputMaxAgeMs();
    const canonicalRec = this.stateCache && this.stateCache['ems.gridMeasurementFresh'];
    const canonicalAge = canonicalRec ? this._nwGetCacheAgeMs('ems.gridMeasurementFresh', now) : null;
    const canonicalKnown = !!(canonicalRec && canonicalAge !== null && canonicalAge <= Math.max(maxAgeMs, 15000));
    const readFresh = (key, mapped) => mapped ? this._nwGetNumberFromCacheFresh(key, maxAgeMs, null, now) : null;
    return resolveNvpDisplay({
      maxAgeMs,
      canonicalKnown,
      canonicalFresh: canonicalKnown && typeof canonicalRec.value === 'boolean' ? canonicalRec.value : null,
      canonicalNetW: this._nwGetNumberFromCacheFresh('ems.gridPowerRawW', maxAgeMs, null, now),
      canonicalSource: this.stateCache?.['ems.gridPowerSource']?.value,
      canonicalStatus: this.stateCache?.['ems.gridMeasurementStatus']?.value,
      gridNetRaw: readFresh('gridPointPower', gridNetMapped),
      gridBuyRaw: readFresh('gridBuyPower', gridBuyMapped),
      gridSellRaw: readFresh('gridSellPower', gridSellMapped),
      gridBuyTs: this.stateCache?.gridBuyPower?.ts,
      gridSellTs: this.stateCache?.gridSellPower?.ts,
      maxSkewMs: this.config?.diagnostics?.nvpMaxSkewMs,
      gridBuyMapped,
      gridSellMapped,
      gridNetMapped,
    });
  }

  /**
   * Code-Teil: _nwSetHistorieValue
   * Zweck: Kapselt einen lokalen Verarbeitungsschritt, damit Aufrufer nicht direkt in Detaildaten eingreifen.
   * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
   * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
   */
  _nwSetHistorieValue(localId, val, ts, tolAbs = 1) {
    try {
      const n = numericMeasurement(val);
      if (n === null) return;
      if (!this._nwHistorieLast) this._nwHistorieLast = {};
      const last = this._nwHistorieLast[localId];
      const tol = Number.isFinite(Number(tolAbs)) ? Math.max(0, Number(tolAbs)) : 0;
      if (Number.isFinite(last) && Math.abs(last - n) < tol) return;
      this._nwHistorieLast[localId] = n;
      this.setLocalStateWithCache(localId, n, ts);
    } catch (_e) {}
  }
  /**
   * Code-Teil: ensureDerivedFlowStates
   * Zweck: Verarbeitet Energiefluss-/Budgetwerte und beeinflusst Live-Anzeige sowie History.
   * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
   * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
   */
  async ensureDerivedFlowStates() {
    // Derived / calculated live states (used as fallbacks for UI, optional for mapping)
    await this.setObjectNotExistsAsync('derived', {
      type: 'channel',
      common: { name: 'Derived (berechnet)' },
      native: {},
    });

    await this.setObjectNotExistsAsync('derived.core', {
      type: 'channel',
      common: { name: 'Core (berechnet)' },
      native: {},
    });

    await this.setObjectNotExistsAsync('derived.core.building', {
      type: 'channel',
      common: { name: 'Gebäude (berechnet)' },
      native: {},
    });

    await this.setObjectNotExistsAsync('derived.core.building.loadTotalW', {
      type: 'state',
      common: {
        name: 'Gebäudeverbrauch gesamt (W, berechnet)',
        type: 'number',
        role: 'value.power',
        unit: 'W',
        read: true,
        write: false,
      },
      native: {},
    });

    await this.setObjectNotExistsAsync('derived.core.building.loadRestW', {
      type: 'state',
      common: {
        name: 'Gebäudeverbrauch Rest (W, berechnet – ohne EV/Extra-Verbraucher)',
        type: 'number',
        role: 'value.power',
        unit: 'W',
        read: true,
        write: false,
      },
      native: {},
    });

    await this.setObjectNotExistsAsync('derived.core.building.loadSource', {
      type: 'state',
      common: {
        name: 'Gebäudeverbrauch Quelle',
        type: 'string',
        role: 'text',
        read: true,
        write: false,
      },
      native: {},
    });

    // PV (berechnet) – AC/DC/Total
    await this.setObjectNotExistsAsync('derived.core.pv', {
      type: 'channel',
      common: { name: 'PV (berechnet)' },
      native: {},
    });

    await this.setObjectNotExistsAsync('derived.core.pv.acW', {
      type: 'state',
      common: {
        name: 'PV-Leistung AC (W, berechnet)',
        type: 'number',
        role: 'value.power',
        unit: 'W',
        read: true,
        write: false,
      },
      native: {},
    });

    await this.setObjectNotExistsAsync('derived.core.pv.dcW', {
      type: 'state',
      common: {
        name: 'PV-Leistung DC (W, berechnet – Speicherfarm/DC)',
        type: 'number',
        role: 'value.power',
        unit: 'W',
        read: true,
        write: false,
      },
      native: {},
    });

    await this.setObjectNotExistsAsync('derived.core.pv.totalW', {
      type: 'state',
      common: {
        name: 'PV-Leistung gesamt (W, berechnet)',
        type: 'number',
        role: 'value.power',
        unit: 'W',
        read: true,
        write: false,
      },
      native: {},
    });

    await this.setObjectNotExistsAsync('derived.core.pv.rawTotalW', {
      type: 'state', common: { name: 'PV-Leistung roh vor Plausibilitaet (W)', type: 'number', role: 'value.power', unit: 'W', read: true, write: false }, native: {},
    });
    await this.setObjectNotExistsAsync('derived.core.pv.capacityLimitW', {
      type: 'state', common: { name: 'PV-Plausibilitaetsgrenze (W)', type: 'number', role: 'value.power', unit: 'W', read: true, write: false }, native: {},
    });
    await this.setObjectNotExistsAsync('derived.core.pv.duplicateSuppressedW', {
      type: 'state', common: { name: 'Unterdrueckte PV-Doppelzaehlung (W)', type: 'number', role: 'value.power', unit: 'W', read: true, write: false }, native: {},
    });
    await this.setObjectNotExistsAsync('derived.core.pv.plausibilityCapped', {
      type: 'state', common: { name: 'PV-Plausibilitaetsgrenze aktiv', type: 'boolean', role: 'indicator', read: true, write: false }, native: {},
    });
    await this.setObjectNotExistsAsync('derived.core.pv.source', {
      type: 'state', common: { name: 'PV-Gesamtquelle', type: 'string', role: 'text', read: true, write: false }, native: {},
    });

    // Diagnose/Debug
    await this.setObjectNotExistsAsync('derived.core.building.quality', {
      type: 'state',
      common: {
        name: 'Qualität (berechnet) – OK/DEGRADED/MISSING_INPUT',
        type: 'string',
        role: 'text',
        read: true,
        write: false,
      },
