        ids.sort();
        const sig = ids.join('|');
        if (sig !== cache.cfgSig) {
          cache.cfgSig = sig;
          force = true;
        }
      } catch (_e) {}

      const now = Date.now();
      const maxAgeMs = 10 * 60 * 1000; // refresh at most every 10 min
      if (!force && cache.ts && (now - cache.ts) < maxAgeMs) return;
      cache.ts = now;

      // Query PV inverter devices from nexowatt-devices
      const objs = await this.getForeignObjectsAsync('nexowatt-devices.*.devices.*', 'channel');
      const list = [];
      for (const [cid, obj] of Object.entries(objs || {})) {
        const cat = String(obj?.native?.category || '').toUpperCase();
        if (cat !== 'PV_INVERTER') continue;

        const aliases = obj?.native?.aliases || {};

        const powerId = (typeof aliases['r.power'] === 'string' && aliases['r.power'].trim())
          ? aliases['r.power'].trim()
          : `${cid}.aliases.r.power`;

        const connectedId = (typeof aliases['comm.connected'] === 'string' && aliases['comm.connected'].trim())
          ? aliases['comm.connected'].trim()
          : `${cid}.aliases.comm.connected`;

        const offlineId = (typeof aliases['alarm.offline'] === 'string' && aliases['alarm.offline'].trim())
          ? aliases['alarm.offline'].trim()
          : `${cid}.aliases.alarm.offline`;

        const name = String(obj?.common?.name || cid).trim();
        list.push({ id: cid, name, powerId, connectedId, offlineId });
      }

            // Also include PV power datapoints configured in gridConstraints inverter lists (optional).
      // This enables PV total sum even for inverters that are not discovered via nexowatt-devices.
      try {
        const gc = this.config?.gridConstraints;
        const seenPower = new Set(list.map((d) => nwPhysicalPvSourceKey(d.powerId) || String(d.powerId || '').toLowerCase()).filter(Boolean));
        /**
         * Code-Teil: addCfg
         * Zweck: Kapselt einen lokalen Verarbeitungsschritt, damit Aufrufer nicht direkt in Detaildaten eingreifen.
         * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
         * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
         */
        const addCfg = (arr, tag) => {
          if (!Array.isArray(arr)) return;
          for (let i = 0; i < arr.length; i++) {
            const inv = arr[i] || {};
            const pid = this._nwTrimId(inv.pvPowerReadId);
            if (!pid) continue;
            const physicalKey = nwPhysicalPvSourceKey(pid) || pid.toLowerCase();
            if (seenPower.has(physicalKey)) continue;
            seenPower.add(physicalKey);
            list.push({ id: `cfg:${tag}:${i}`, name: String(inv.name || `PV ${tag} ${i + 1}`), powerId: pid, connectedId: null, offlineId: null });
          }
        };
        if (gc && typeof gc === 'object') {
          addCfg(gc.pvCurtailInvertersEvu, 'evu');
          addCfg(gc.pvCurtailInvertersZero, 'zero');
        }
      } catch (_e) {}

      const newIds = new Set();
      for (const d of list) {
        if (d.powerId) newIds.add(d.powerId);
        if (d.connectedId) newIds.add(d.connectedId);
        if (d.offlineId) newIds.add(d.offlineId);
      }

      const oldIds = cache.ids || new Set();

      // Unsubscribe removed IDs
      for (const oid of oldIds) {
        if (!newIds.has(oid)) {
          try { await this.unsubscribeForeignStatesAsync(oid); } catch (_e) {}
          try { cache.cache.delete(oid); } catch (_e) {}
        }
      }

      // Subscribe new IDs and seed cache
      for (const nid of newIds) {
        if (!oldIds.has(nid)) {
          try { await this.subscribeForeignStatesAsync(nid); } catch (_e) {}
          try {
            const st = await this.getForeignStateAsync(nid);
            if (st && st.val !== undefined) cache.cache.set(nid, { val: st.val, ts: st.ts || now });
          } catch (_e) {}
        }
      }

      cache.ids = newIds;
      cache.list = list;
    } catch (e) {
      this.log.debug(`[derivedFlow] PV inverter cache refresh failed: ${e?.message || e}`);
    }
  }
  /**
   * Code-Teil: scheduleDerivedFlowUpdate
   * Zweck: Verarbeitet Energiefluss-/Budgetwerte und beeinflusst Live-Anzeige sowie History.
   * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
   * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
   */
  scheduleDerivedFlowUpdate(reason = '') {
    if (this._nwShuttingDown) return;
    // Throttle derived calculations to avoid excessive state writes on high-frequency meters.
    const now = Date.now();
    const minMs = this._derivedFlow?.minIntervalMs ?? 250;

    // Remember latest reason (debug only)
    if (this._derivedFlow) this._derivedFlow.lastReason = reason;

    if (this._derivedFlow?.pending) return;

    const since = now - (this._derivedFlow?.lastRunMs ?? 0);
    const delay = since >= minMs ? 0 : (minMs - since);

    this._derivedFlow.pending = true;
    this._nwSetTimeout(() => {
      this._derivedFlow.pending = false;
      this._derivedFlow.lastRunMs = Date.now();
      this.updateDerivedFlowStates(this._derivedFlow.lastReason || 'scheduled')
        .catch((e) => this.log.debug(`[derivedFlow] ${e?.message || e}`));
    }, delay);
  }
  /**
   * Code-Teil: updateDerivedFlowStates
   * Zweck: Aktualisiert Runtime-Zustand, UI oder veröffentlichte Daten.
   * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
   * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
   */
  async updateDerivedFlowStates(reason = '') {
    // Building consumption can be derived from the power balance at NVP:
    // load = (PV + other production) + gridImport + batteryDischarge - gridExport - batteryCharge
    // If no direct house meter (consumptionTotal) is configured, we use this as fallback for the UI.

    const ts = Date.now();

    // Keep PV-inverter auto-cache reasonably fresh (cheap no-op when not due)
    await this._derivedRefreshPvInvertersCache(false);

    const pvPowerMapped = this._nwHasMappedDatapoint('pvPower');
    const prodTotalMapped = this._nwHasMappedDatapoint('productionTotal');
    const consumptionMapped = this._nwHasMappedDatapoint('consumptionTotal');

    // --- Grid ---
    const {
      gridBuyRaw,
      gridSellRaw,
      gridNetRaw,
      gridBuyW,
      gridSellW,
      hasGrid,
      src: gridSrc,
    } = this._nwResolveGridImportExportFromCache();

    // --- Storage ---
    // Normalize storage power centrally:
    //   batteryPower (signed) convention: -W = charge, +W = discharge
    //   settings.flowInvertBattery flips that signed value before splitting.
    // Separate charge/discharge datapoints remain supported, but stale/legacy mirrored
    // values must not make the UI or derived balance show both directions at once.
    const storageFlow = this._nwResolveBatteryFlowFromCache({ now: ts });
    const chargeW = Math.max(0, Number(storageFlow.chargeW) || 0);
    const dischargeW = Math.max(0, Number(storageFlow.dischargeW) || 0);
    const storageSrc = storageFlow.src || 'missing';
    const gridBuyRound = Math.round(gridBuyW);
    const gridSellRound = Math.round(gridSellW);

    // --- Producer slots (optional extra production) ---
    let producerSumW = 0;
    let producerCount = 0;
    for (let i = 1; i <= 5; i++) {
      const p = this._nwGetNumberFromCache(`producer${i}Power`);
      if (p !== null) {
        const n = Number(p);
        if (Number.isFinite(n)) {
          producerSumW += Math.abs(n);
          producerCount++;
        }
      }
    }

    // --- PV (AC) ---
    let pvAcRaw = null;
    let pvSource = '';
    let pvBaseSourceId = '';
    let pvBaseSourceIds = [];
    if (pvPowerMapped) {
      pvAcRaw = this._nwGetNumberFromCache('pvPower');
      pvSource = 'mapped:pvPower';
      pvBaseSourceId = String(this.config?.datapoints?.pvPower || '').trim();
      pvBaseSourceIds = pvBaseSourceId ? [pvBaseSourceId] : [];
    } else if (prodTotalMapped) {
      pvAcRaw = this._nwGetNumberFromCache('productionTotal');
      pvSource = 'mapped:productionTotal';
      pvBaseSourceId = String(this.config?.datapoints?.productionTotal || '').trim();
      pvBaseSourceIds = pvBaseSourceId ? [pvBaseSourceId] : [];
    }

    let pvAcW = 0;
    if (pvAcRaw !== null && Number.isFinite(Number(pvAcRaw))) {
      pvAcW = Math.max(0, Math.abs(Number(pvAcRaw)));
    } else {
      // Auto: sum all PV_INVERTER devices from nexowatt-devices
      const pvAuto = this._derivedFlow?.auto?.pvInverters;
      const staleSec = Number(this.config?.settings?.deviceStaleTimeoutSec);
      const staleMs = Math.max(10 * 1000, (Number.isFinite(staleSec) ? staleSec : 60) * 1000);

      let sum = 0;
      let used = 0;
      let offline = 0;

      for (const dev of (pvAuto?.list || [])) {
        const pRec = pvAuto?.cache?.get(dev.powerId);
        const cRec = pvAuto?.cache?.get(dev.connectedId);
        const oRec = pvAuto?.cache?.get(dev.offlineId);

        const connected = (cRec && cRec.val !== undefined) ? !!cRec.val : true;
        const isOffline = (oRec && oRec.val !== undefined) ? !!oRec.val : false;
        const ageOk = (pRec && Number.isFinite(Number(pRec.ts))) ? ((ts - Number(pRec.ts)) <= staleMs) : false;

        if (!connected || isOffline || !ageOk) {
          offline++;
          continue;
        }

        const v = Number(pRec?.val);
        if (!Number.isFinite(v)) continue;
        sum += Math.abs(v);
        used++;
        const sourceId = String(dev && dev.powerId || '').trim();
        if (sourceId && !pvBaseSourceIds.includes(sourceId)) pvBaseSourceIds.push(sourceId);
      }

      if (used > 0) {
        pvAcW = Math.max(0, sum);
        pvSource = 'auto:pvSources';
      } else {
        // No PV sources configured/available.
        // IMPORTANT: Do NOT fall back to producer-slots here. Producer slots are always optional and
        // must remain separate from PV (to avoid confusing PV totals when only external generators are mapped).
        pvAcW = 0;
        pvSource = 'missing';
      }
    }

    // --- PV aus Speicherfarm oder Einzel-DC-/Hybrid-Speicher -------------------
    // Die Farm liefert getrennte AC-, DC- und unbekannte WR-Anteile. Eine zentrale
    // Merge-Funktion verhindert, dass dieselbe Anlagen-PV im Energiefluss doppelt
    // erscheint. Fehlt die Anlagen-PV, dient die komplette Farm-Summe als Fallback.
    const farmMetrics = (typeof this._nwResolveStorageFarmMetricsFromCache === 'function')
      ? this._nwResolveStorageFarmMetricsFromCache({ now: ts })
      : null;
    const sfEnabled = !!(farmMetrics && farmMetrics.active);
    const storageAuthorityLive = (typeof this._nwGetStorageControlAuthority === 'function')
      ? this._nwGetStorageControlAuthority()
      : { selectedTopology: 'none', writerActive: false, reason: 'authority-unavailable' };
    const selectedStorageTopologyLive = String(storageAuthorityLive.selectedTopology || 'none');
    const singleStorageDcEnabled = !!(selectedStorageTopologyLive === 'single'
      && this.config
      && this.config.storage
      && String(this.config.storage.coupling || '').trim().toLowerCase() === 'dc');
    let pvDcW = 0;
    let pvDcSource = '';
    let pvDcIncluded = false;
    let pvFarmMerge = null;
    let pvTotalW = pvAcW;

    if (sfEnabled && typeof this._nwMergeStorageFarmPvWithBase === 'function') {
      pvFarmMerge = this._nwMergeStorageFarmPvWithBase(pvAcW, {
        now: ts,
        metrics: farmMetrics,
        baseSourceId: pvBaseSourceId,
        baseSourceIds: pvBaseSourceIds,
      });
      pvAcW = Math.max(0, Number(pvFarmMerge.acW) || 0);
      pvDcW = Math.max(0, Number(pvFarmMerge.dcW) || 0);
      pvTotalW = Math.max(0, Number(pvFarmMerge.totalW) || 0);
      pvDcIncluded = pvDcW > 0;
      pvDcSource = pvDcW > 0 ? 'farm:dc' : '';
      if (pvFarmMerge.farmFallbackUsed && pvSource === 'missing') pvSource = 'farm:pv-sources';
      else if (pvFarmMerge.farmAddedW > 0) pvSource = pvSource === 'missing' ? 'farm:pv-sources' : `${pvSource}+farm`;
    } else if (singleStorageDcEnabled) {
      const dc = this._nwGetNumberFromCache('speicher.dcPvPowerW');
      if (dc !== null && Number.isFinite(Number(dc))) {
        pvDcW = Math.max(0, Math.abs(Number(dc)));
        pvDcSource = 'storage:dc';
      }

      if (pvDcW > 0) {
        if (!pvTotalW || pvTotalW === 0) {
          pvTotalW = pvDcW;
          pvDcIncluded = true;
          if (pvSource === 'missing') pvSource = pvDcSource;
        } else {
          const relDiff = Math.abs(Math.abs(pvTotalW) - pvDcW) / Math.max(1, pvDcW);
          if (relDiff < 0.05) pvTotalW = Math.max(Math.abs(pvTotalW), pvDcW);
          else {
            pvTotalW = Math.abs(pvTotalW) + pvDcW;
            pvDcIncluded = true;
          }
        }
      }
    }

    const pvRawTotalW = pvFarmMerge && Number.isFinite(Number(pvFarmMerge.rawTotalW))
      ? Math.max(0, Number(pvFarmMerge.rawTotalW))
      : Math.max(0, pvTotalW);
    // Die Farm-Merge-Funktion hat ihre AC/DC-Anteile bereits genau einmal auf die
    // konfigurierte Anlagenleistung plausibilisiert. Ein zweiter Scale-Schritt hier
    // würde dieselben Werte nochmals verkleinern und die Historie gegenüber LIVE
    // verschieben. Einzel-/Nicht-Farm-Anlagen werden dagegen an dieser Stelle einmal
    // zentral begrenzt.
    const pvPlausibility = pvFarmMerge
      ? {
        rawW: pvRawTotalW,
        outputW: Math.max(0, Number(pvFarmMerge.totalW) || 0),
        capacityLimitW: Math.max(0, Number(pvFarmMerge.capacityLimitW) || 0),
        capped: pvFarmMerge.plausibilityCapped === true,
        suppressedW: Math.max(0, Number(pvFarmMerge.plausibilitySuppressedW) || 0),
      }
      : nwApplyPvCapacityPlausibility(pvRawTotalW, this._nwConfiguredPvCapacityW(), 0.15);
    if (!pvFarmMerge && pvPlausibility.capped) {
      const scale = pvRawTotalW > 0 ? pvPlausibility.outputW / pvRawTotalW : 1;
      pvAcW *= scale;
      pvDcW *= scale;
      pvTotalW = pvPlausibility.outputW;
      pvSource = `${pvSource}+capacity-cap`;
    }
    const pvDuplicateSuppressedW = Math.max(0,
      (Number(pvFarmMerge && pvFarmMerge.duplicateSuppressedW) || 0)
      + (Number(pvPlausibility.suppressedW) || 0),
    );

    // Total production = PV(total) + extra producers
    const productionW = pvTotalW + producerSumW;

    // --- Derived loads ---
    const rawLoadTotalW = productionW + gridBuyW + dischargeW - gridSellW - chargeW;

    // Gebäudeverbrauchs-Quelle:
    // Wenn ein direkter Gebäude-/Verbrauchs-DP gemappt ist, ist dieser Messwert für
    // LIVE, Sungrow/FENECON-Deckungslogik und Diagnose die stabilere Quelle als die
    // Bilanzgleichung aus PV + NVP + Speicher. Die Bilanz bleibt als Fallback und
    // Kontrollwert erhalten, weil Einzelwerte zeitlich versetzt eintreffen koennen.
    const directLoadMaxAgeMs = Math.max(10 * 1000, Number(this.config?.settings?.deviceStaleTimeoutSec || 60) * 1000);
    const directLoadTotalRaw = consumptionMapped
      ? this._nwGetNumberFromCacheFresh('consumptionTotal', directLoadMaxAgeMs, null, ts)
      : null;
    const directLoadTotalW = (typeof directLoadTotalRaw === 'number' && Number.isFinite(directLoadTotalRaw) && directLoadTotalRaw >= 0)
      ? Math.max(0, directLoadTotalRaw)
      : null;
    const directLoadAgeMs = consumptionMapped ? this._nwGetCacheAgeMs('consumptionTotal', ts) : null;
    let loadTotalSource = directLoadTotalW !== null ? 'mapped:consumptionTotal' : 'balance:pv+nvp+storage';

    // Some meters/adapters update asynchronously (grid/PV/battery).
    // This can temporarily yield an impossible negative power balance.
    // To avoid 0 W spikes in the VIS, we hold the last plausible value for a short time.
    let loadTotalW = directLoadTotalW !== null ? directLoadTotalW : rawLoadTotalW;

    const activityW = (Math.abs(productionW) + Math.abs(gridBuyW) + Math.abs(gridSellW) + Math.abs(chargeW) + Math.abs(dischargeW));
    const hasActivity = activityW > 200;

    // Timestamp skew between inputs (debug only)
    const tsList = [];
    /**
     * Code-Teil: pushTs
     * Zweck: Kapselt einen lokalen Verarbeitungsschritt, damit Aufrufer nicht direkt in Detaildaten eingreifen.
     * Zusammenhang: Teil von Adapterkern: Lifecycle, Webserver, API, States, EMS-Engine; Aufrufstellen und abhängige States/APIs beim Ändern mitprüfen.
     * TypeScript: Parameter, Rückgabewert und verwendete Config-/State-Objekte später explizit typisieren.
     */
    const pushTs = (k) => {
      const rec = this.stateCache && this.stateCache[k];
      const t = rec && rec.ts;
      if (typeof t === 'number' && Number.isFinite(t)) tsList.push(t);
    };
    pushTs('gridBuyPower'); pushTs('gridSellPower'); pushTs('gridPointPower');
    pushTs('storageChargePower'); pushTs('storageDischargePower'); pushTs('batteryPower');
    pushTs('pvPower'); pushTs('productionTotal');
    if (sfEnabled) {
      pushTs('storageFarm.totalPvPowerW');
      pushTs('storageFarm.totalPvAcPowerW');
      pushTs('storageFarm.totalPvDcPowerW');
      pushTs('storageFarm.totalPowerW');
      pushTs('storageFarm.totalChargePowerW');
      pushTs('storageFarm.totalDischargePowerW');
    }
    if (singleStorageDcEnabled) {
      pushTs('speicher.dcPvPowerW');
    }
    const inputSkewMs = (tsList.length >= 2) ? (Math.max(...tsList) - Math.min(...tsList)) : null;

    if (!this._derivedFlow) this._derivedFlow = {};
    if (!this._derivedFlow.good) this._derivedFlow.good = { loadTotalW: null, loadRestW: null, ts: 0 };
    const good = this._derivedFlow.good;
    const goodLoad = (typeof good.loadTotalW === 'number' && Number.isFinite(good.loadTotalW)) ? good.loadTotalW : null;
    const goodRest = (typeof good.loadRestW === 'number' && Number.isFinite(good.loadRestW)) ? good.loadRestW : null;
    const goodAgeMs = (good && typeof good.ts === 'number' && Number.isFinite(good.ts)) ? (ts - good.ts) : Infinity;

    const holdMaxAgeMs = 60 * 1000;
    let usedFallback = false;

    // Clamp to plausible range + anti-spike
    if (!Number.isFinite(loadTotalW)) loadTotalW = 0;
    if (loadTotalW < 0 || (loadTotalW === 0 && hasActivity)) {
      if (goodLoad !== null && goodAgeMs <= holdMaxAgeMs) {
        loadTotalW = goodLoad;
        loadTotalSource = `${loadTotalSource}:hold-last-good`;
        usedFallback = true;
      } else if (hasActivity) {
        // Minimal plausible base-load to avoid "0.00 kW" optics while there is clearly energy activity.
        loadTotalW = 100;
        loadTotalSource = `${loadTotalSource}:minimal-plausible`;
        usedFallback = true;
      } else {
        loadTotalW = 0;
      }
    }
    if (loadTotalW < 0) loadTotalW = 0;

    // Rest-load: subtract EV and configured extra consumers (for convenience / mapping)
    const evW = Math.max(0, Math.abs(this._nwGetNumberFromCache('evcs.totalPowerW') ?? 0));
    let consumersW = 0;
    for (let i = 1; i <= 10; i++) {
      const c = this._nwGetNumberFromCache(`consumer${i}Power`);
      if (c !== null) {
        const n = Number(c);
        if (Number.isFinite(n)) consumersW += Math.abs(n);
      }
    }

    const rawLoadRestW = loadTotalW - evW - consumersW;

    let loadRestW = loadTotalW - evW - consumersW;
    // If we had to hold/fallback the total load, prefer holding the last plausible rest-load as well.
    if (usedFallback && goodRest !== null && goodAgeMs <= holdMaxAgeMs) {
      loadRestW = goodRest;
    }
    if (!Number.isFinite(loadRestW)) loadRestW = 0;
    if (loadRestW < 0) loadRestW = 0;

    const loadTotalRound = Math.round(loadTotalW);
    const loadRestRound = Math.round(loadRestW);

    const tsShadow = this._nwRunEnergyFlowTsShadowComparison({
      ts,
      reason,
      productionW,
      pvTotalW,
      gridBuyW,
      gridSellW,
      gridNetRaw,
      storageFlow,
      chargeW,
      dischargeW,
      loadTotalW,
      loadTotalRound,
      loadRestRound,
      evW,
      consumersW,
      consumptionMapped,
      mode: this._nwGetEnergyFlowTsMode(),
      toleranceW: 120,
    });

    /**
     * Code-Teil: effectiveEnergyFlow
     *
     * Zweck:
     * Bereitet die kontrollierte produktive TS-Umschaltung vor. Standardmäßig werden
     * weiterhin die JavaScript-Werte veröffentlicht. Nur wenn `tsMigration.energyFlowMode`
     * bewusst auf `ts` steht, die Sicherheitsfreigabe gesetzt ist und der Shadow-Vergleich
     * OK meldet, dürfen TS-Werte in diesem Tick veröffentlicht werden.
     *
     * Wichtig:
     * Das schützt History und Regelung vor versehentlichen Umschaltungen. Der Status wird
     * in der Diagnose mitgeführt, damit wir später sehen, ob JS oder TS effektiv genutzt
     * wurde.
     */
    const effectiveEnergyFlow = this._nwBuildEffectiveEnergyFlowValues({
      gridBuyW: gridBuyRound,
      gridSellW: gridSellRound,
      storageChargeW: Math.round(chargeW),
      storageDischargeW: Math.round(dischargeW),
      loadTotalW: loadTotalRound,
    }, tsShadow);
    const publishGridBuyRound = Math.round(Number(effectiveEnergyFlow.gridBuyW) || 0);
    const publishGridSellRound = Math.round(Number(effectiveEnergyFlow.gridSellW) || 0);
    const publishChargeRound = Math.round(Number(effectiveEnergyFlow.storageChargeW) || 0);
    const publishDischargeRound = Math.round(Number(effectiveEnergyFlow.storageDischargeW) || 0);
    const publishLoadTotalRound = Math.round(Number(effectiveEnergyFlow.buildingLoadW) || 0);
    const publishLoadRestRound = Math.max(0, Math.round(publishLoadTotalRound - evW - consumersW));

    /**
     * Code-Teil: Energiefluss-TS-Liveteststatus veröffentlichen
     *
     * Zweck:
     * Schreibt die effektive Energieflussquelle und die TS-Schaltentscheidung in eigene
     * Diagnose-States. So sieht man beim echten Anlagentest sofort, ob die veröffentlichten
     * Werte noch aus JS oder bereits aus dem TS-Kandidaten kommen.
     *
     * Zusammenhang:
     * Der App-Center-Status liest diese States über die Diagnose-API. Die eigentlichen
     * Energieflusswerte werden oben weiterhin nur über `effectiveEnergyFlow` bestimmt;
     * dieser Block veröffentlicht ausschließlich Diagnoseinformationen.
     */
    const energyFlowSourceState = effectiveEnergyFlow.switchState && effectiveEnergyFlow.switchState.publishedSource
      ? String(effectiveEnergyFlow.switchState.publishedSource)
      : 'js-runtime';
    const energyFlowProductiveTsActive = energyFlowSourceState === 'ts-candidate' || energyFlowSourceState === 'ts-normal';
    const energyFlowLiveTestState = this._nwEnergyFlowTsLiveTestStateFromSwitch(effectiveEnergyFlow.switchState || {});
    const tsSwitchJsonText = JSON.stringify(effectiveEnergyFlow.switchState || {});
    const tsCandidateJsonText = JSON.stringify(effectiveEnergyFlow.candidate || {});
    const tsFixedSourceJsonText = JSON.stringify((effectiveEnergyFlow.switchState && effectiveEnergyFlow.switchState.fixedSourceState) || {});
    try {
      if (this._derivedFlow?.last?.energyFlowSource !== energyFlowSourceState) {
        this._derivedFlow.last.energyFlowSource = energyFlowSourceState;
        await this.setStateAsync('derived.core.building.energyFlowSource', { val: energyFlowSourceState, ack: true });
      }
      if (this._derivedFlow?.last?.tsLiveTestState !== energyFlowLiveTestState) {
        this._derivedFlow.last.tsLiveTestState = energyFlowLiveTestState;
        await this.setStateAsync('derived.core.building.tsLiveTestState', { val: energyFlowLiveTestState, ack: true });
      }
      if (this._derivedFlow?.last?.tsProductiveActive !== energyFlowProductiveTsActive) {
        this._derivedFlow.last.tsProductiveActive = energyFlowProductiveTsActive;
        await this.setStateAsync('derived.core.building.tsProductiveActive', { val: energyFlowProductiveTsActive, ack: true });
      }
    } catch (_eTsLiveState) {}

    // Update last-plausible cache from the selected building-load source.
